-- Seed catalog Bảo An Sport (nguồn: baoansport.vn, dữ liệu của chính chủ sở hữu).
-- Sinh tự động bởi scripts/build-baoansport-seed. Không sửa tay.
BEGIN;
SELECT pg_advisory_xact_lock(hashtext('dctd:seed_baoansport_catalog'));

-- 1. Cho phép bài viết loại POLICY (9 trang chính sách).
ALTER TABLE public.posts DROP CONSTRAINT IF EXISTS posts_post_type_check;
ALTER TABLE public.posts ADD CONSTRAINT posts_post_type_check CHECK (
  post_type IN ('NEWS','TRAINING_GUIDE','PRODUCT_GUIDE','ABOUT','POLICY'));

-- 2. Cho catalog cũ nghỉ, KHÔNG xoá.
--
--    Vì sao không xoá cứng: product_variants bị Restrict từ order_items, cart_items,
--    inventory_balances, inventory_movements và product_reviews. Muốn xoá sản phẩm cũ thì
--    phải xoá cả đơn hàng, thanh toán và bút toán kho demo — mà payment_transactions,
--    inventory_movements, fulfillment_status_history là sổ cái append-only, có trigger
--    chặn UPDATE/DELETE để lịch sử tiền và kho không bị sửa. Lưu trữ đạt đúng kết quả
--    kinh doanh (hàng cũ biến mất khỏi trang bán) mà không phải phá lớp bảo vệ đó.
UPDATE public.products
   SET status = 'ARCHIVED', updated_at = CURRENT_TIMESTAMP, version = version + 1
 WHERE status <> 'ARCHIVED';
UPDATE public.product_variants
   SET status = 'INACTIVE', updated_at = CURRENT_TIMESTAMP, version = version + 1
 WHERE status <> 'INACTIVE';
UPDATE public.product_prices
   SET status = 'EXPIRED', ends_at = CURRENT_TIMESTAMP, updated_at = CURRENT_TIMESTAMP,
       updated_by = 1, version = version + 1
 WHERE status <> 'EXPIRED';
UPDATE public.product_media SET status = 'INACTIVE' WHERE status <> 'INACTIVE';
UPDATE public.categories
   SET status = 'INACTIVE', updated_at = CURRENT_TIMESTAMP, version = version + 1
 WHERE status <> 'INACTIVE';
UPDATE public.brands
   SET status = 'INACTIVE', updated_at = CURRENT_TIMESTAMP, version = version + 1
 WHERE status <> 'INACTIVE';

-- 3. Danh mục cũ phải đổi slug/code để nhường chỗ cho danh mục thật trùng tên.
UPDATE public.categories SET slug = left('luu-tru-' || slug, 255),
       code = left('OLD_' || code, 32)
 WHERE slug NOT LIKE 'luu-tru-%';
UPDATE public.products SET slug = left('luu-tru-' || slug, 255),
       product_no = left('OLD-' || product_no, 32)
 WHERE slug NOT LIKE 'luu-tru-%';
-- sku là duy nhất toàn cục nên mã cũ phải nhường chỗ cho mã thật từ baoansport.
UPDATE public.product_variants SET sku = left('OLD-' || sku, 64)
 WHERE sku NOT LIKE 'OLD-%';

-- 4. Thương hiệu. Nguồn chỉ khai báo OEM cho toàn bộ sản phẩm.
VALUES ('OEM', 'OEM', 'oem', 'Hàng gia công theo đặt hàng của Bảo An Sport', 'ACTIVE',
        CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);

-- 5. Danh mục: 17 cấp cha, 44 cấp con.
SELECT v.*, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM (VALUES
  ('MAY_TAP_THE_DUC', 'Máy Tập Thể Dục', 'may-tap-the-duc', 'may-tap-the-duc', 0, 'Tìm hiểu các dòng máy tập thể dục cơ bản cho gia đình và phòng Gym tại Bảo An Sport: máy chạy bộ, xe đạp tập, máy tập bụng... Hàng chính hãng, bền đẹp, giá tốt.', 140, 'ACTIVE'),
