  ('DUNG_CU_TAP_YOGA', 'Dụng Cụ Tập Yoga', 'dung-cu-tap-yoga', 'dung-cu-tap-yoga', 0, 'Tìm hiểu các dụng cụ Yoga cơ bản hỗ trợ tập hiệu quả cho người mới như thảm, bóng, gạch, dây đai... Gợi ý địa chỉ mua dụng cụ chính hãng, giá tốt, giao hàng nhanh.', 100, 'ACTIVE'),
  ('DUNG_CU_BONG_BAN', 'Dụng Cụ Bóng Bàn', 'dung-cu-bong-ban', 'dung-cu-bong-ban', 0, 'Danh sách các dụng cụ bóng bàn cần thiết cho người chơi mới: bàn, vợt, bóng, lưới,... Tìm hiểu địa chỉ mua dụng cụ uy tín, đảm bảo chất lượng và bảo hành rõ ràng.', 20, 'ACTIVE'),
  ('DUNG_CU_VO_THUAT', 'Dụng Cụ Võ Thuật', 'dung-cu-vo-thuat', 'dung-cu-vo-thuat', 0, 'Tìm hiểu các dụng cụ võ thuật quan trọng như bao cát đấm bốc, găng tay Boxing, đích đá - đích đấm... Hướng dẫn cách chọn mua phù hợp và địa chỉ mua hàng uy tín.', 130, 'ACTIVE'),
  ('THIET_BI_PHONG_GYM', 'Thiết Bị Phòng Gym', 'thiet-bi-phong-gym', 'thiet-bi-phong-gym', 0, 'Cung cấp thiết bị phòng Gym chính hãng, gồm máy chạy bộ, xe đạp tập, giàn tạ, ghế tập... Bảo An Sport tư vấn chuyên nghiệp, lắp đặt tận nơi, bảo hành toàn quốc.', 160, 'ACTIVE'),
  ('DANH_MUC_KHAC', 'Danh Mục Khác', 'danh-muc-khac', 'danh-muc-khac', 0, 'Tổng hợp những danh mục dụng cụ thể thao khác đang bán tại Bảo An Sport. Quý khách hàng có nhu cầu mua hàng xin vui lòng gọi ngay 0939 987 456', 0, 'ACTIVE'),
  ('THIET_BI_DAY_HOC_THE_DUC', 'Thiết Bị Dạy Học Thể Dục', 'thiet-bi-day-hoc-the-duc', 'thiet-bi-day-hoc-the-duc', 0, 'Cung cấp thiết bị dạy học thể dục cho trường Tiểu học, THCS, THPT: cột nhảy cao, nệm nhảy xa, dây kéo co... Sản phẩm đầy đủ, chính hãng, phù hợp chuẩn của Bộ GD&ĐT', 150, 'ACTIVE'),
  ('DUNG_CU_BONG_DA', 'Dụng Cụ Bóng Đá', 'dung-cu-bong-da', 'dung-cu-bong-da', 0, 'Tìm hiểu các dụng cụ bóng đá cần thiết dùng cho tập luyện và thi đấu: quả bóng, giày, khung thành, găng thủ môn... Hỗ trợ chơi bóng an toàn, đúng luật, hiệu quả.', 50, 'ACTIVE'),
  ('DUNG_CU_CAU_LONG', 'Dụng Cụ Cầu Lông', 'dung-cu-cau-long', 'dung-cu-cau-long', 0, 'Tìm hiểu các dụng cụ cầu lông cần thiết cho người chơi cơ bản như vợt, quả cầu, trụ, lưới, giày... Trang bị đầy đủ để luyện tập và thi đấu hiệu quả, đúng chuẩn kỹ thuật.', 70, 'ACTIVE'),
  ('DUNG_CU_BONG_CHUYEN', 'Dụng Cụ Bóng Chuyền', 'dung-cu-bong-chuyen', 'dung-cu-bong-chuyen', 0, 'Tìm hiểu các dụng cụ bóng chuyền cần thiết cho tập luyện và thi đấu: bóng, trụ, lưới, phụ kiện. Tham khảo địa chỉ mua dụng cụ uy tín, chất lượng và giá tốt hiện nay.', 40, 'ACTIVE'),
  ('DUNG_CU_BONG_RO', 'Dụng Cụ Bóng Rổ', 'dung-cu-bong-ro', 'dung-cu-bong-ro', 0, 'Tìm hiểu các dụng cụ bóng rổ cơ bản như quả bóng rổ, trụ bóng rổ, vành rổ và lưới. Hướng dẫn chi tiết mua dụng cụ cho chơi gia đình hoặc xây dựng sân chơi.', 60, 'ACTIVE'),
  ('DUNG_CU_BOI_LOI', 'Dụng Cụ Bơi Lội', 'dung-cu-boi-loi', 'dung-cu-boi-loi', 0, 'Khám phá các dụng cụ bơi cần thiết nhất cho người lớn và trẻ em như kính, mũ, đồ bơi, phao... Gợi ý địa chỉ mua dụng cụ bơi chính hãng, giá tốt, giao hàng nhanh.', 10, 'ACTIVE'),
  ('DUNG_CU_TENNIS', 'Dụng Cụ Tennis', 'dung-cu-tennis', 'dung-cu-tennis', 0, 'Tìm hiểu các dụng cụ Tennis cần thiết như vợt, bóng, lưới, giày và phụ kiện giúp bạn luyện tập và thi đấu hiệu quả. Gợi ý địa chỉ mua dụng cụ chính hãng, giá tốt.', 110, 'ACTIVE'),
  ('DUNG_CU_BONG_CHAY', 'Dụng Cụ Bóng Chày', 'dung-cu-bong-chay', 'dung-cu-bong-chay', 0, 'Tìm hiểu các dụng cụ bóng chày cơ bản dành cho người mới bắt đầu như gậy, bóng, găng tay... Hướng dẫn cách chọn mua phù hợp và gợi ý địa chỉ bán hàng chính hãng.', 30, 'ACTIVE'),
  ('DUNG_CU_THE_THAO_NGOAI_TROI', 'Dụng Cụ Thể Thao Ngoài Trời', 'dung-cu-the-thao-ngoai-troi', 'dung-cu-the-thao-ngoai-troi', 0, 'Tìm hiểu Top 10 dụng cụ thể thao ngoài trời cơ bản lắp đặt cho công viên và khu vui chơi công cộng. Hướng dẫn cách chọn mua thiết bị phù hợp cho mọi không gian.', 120, 'ACTIVE'),
  ('DUNG_CU_PICKLEBALL', 'Dụng cụ Pickleball', 'dung-cu-pickleball', 'dung-cu-pickleball', 0, 'Cung cấp dụng cụ Pickleball chính hãng gồm vợt Pickleball, bóng Pickleball, trụ lưới và phụ kiện. Mẫu mã đa dạng, giá tốt, giao hàng toàn quốc tại Bảo An Sport.', 80, 'ACTIVE')
) AS v(code, name, slug, path, depth, description, sort_order, status);

