  ('dung-cu-tap-yoga', 'BONG_TAP_YOGA', 'Bóng Tập Yoga', 'bong-tap-yoga', 'dung-cu-tap-yoga/bong-tap-yoga', 'Tìm hiểu các mẫu bóng tập Yoga chất lượng, chống nổ và đầy đủ kích thước ở Bảo An Sport. Sản phẩm chính hãng, tư vấn tận tâm, giao hàng nhanh tại nhà toàn quốc.', 200),
  ('may-tap-the-duc', 'MAY_TAP_CO_BUNG', 'Máy Tập Bụng', 'may-tap-co-bung', 'may-tap-the-duc/may-tap-co-bung', 'Máy tập bụng đa dạng thiết kế và cơ chế vận động, phù hợp tập tại nhà, phòng Gym. Tham khảo mẫu, giá bán và kinh nghiệm chọn mua máy tại Bảo An Sport.', 330),
  ('may-tap-the-duc', 'MAY_TAP_CHAN', 'Máy Tập Chân', 'may-tap-chan', 'may-tap-the-duc/may-tap-chan', 'Cung cấp máy tập chân đa năng phù hợp dùng tại nhà cho gia đình. Sản phẩm chính hãng, thiết kế chắc chắn, tập hiệu quả. Giá tốt, giao hàng thu tiền tận nhà.', 320),
  ('dung-cu-tap-gym', 'GHE_TAP_TA', 'Ghế Tập Tạ', 'ghe-tap-ta', 'dung-cu-tap-gym/ghe-tap-ta', 'Ghế tập tạ tại nhà chính hãng, đa dạng mẫu mã, từ ghế phẳng, ghế điều chỉnh đến ghế đa năng. Tham khảo thông số, giá bán và lựa chọn mẫu phù hợp tại Bảo An Sport.', 260),
  ('dung-cu-tap-gym', 'TA_TAY_TA_DON', 'Tạ Tay - Tạ Đơn', 'ta-tay-ta-don', 'dung-cu-tap-gym/ta-tay-ta-don', 'Tạ tay, tạ đơn đa dạng trọng lượng, chất liệu và thiết kế tại Bảo An Sport, gồm tạ cố định, tạ tháo lắp và tạ điều chỉnh. Tham khảo giá, cách chọn tạ để tập gym và tập tại nhà.', 500),
