  ('dung-cu-bong-ban', 'QUA_BONG_BAN', 'Quả Bóng Bàn', 'qua-bong-ban', 'dung-cu-bong-ban/qua-bong-ban', 'Quả bóng bàn 1 sao, 2 sao, 3 sao chính hãng 729, Xiom, DHS, Double Fish... Đạt chuẩn thi đấu, độ nảy tốt, bền bỉ. Giá tốt, giao toàn quốc tại Bảo An Sport.', 450),
  ('dung-cu-bong-ban', 'PHU_KIEN_BONG_BAN', 'Phụ Kiện Bóng Bàn', 'phu-kien-bong-ban', 'dung-cu-bong-ban/phu-kien-bong-ban', 'Tìm hiểu các phụ kiện bóng bàn chính hãng ở Bảo An Sport: bao đựng vợt, keo dán vợt, bảng điểm, cọc lưới, ring chắn bóng. Đầy đủ - uy tín - giao hàng toàn quốc.', 370),
  ('dung-cu-vo-thuat', 'BAO_CAT_DAM_BOC', 'Bao Cát Đấm Bốc', 'bao-cat-dam-boc', 'dung-cu-vo-thuat/bao-cat-dam-boc', 'Bao cát đấm bốc đa dạng mẫu mã, phù hợp tập Boxing, Muay Thái, Kickboxing tại nhà và phòng tập. Tham khảo thông tin, giá bán và chọn mẫu phù hợp tại Bảo An Sport.', 180),
  ('dung-cu-vo-thuat', 'GANG_TAY_BOXING', 'Găng Tay Boxing', 'gang-tay-boxing', 'dung-cu-vo-thuat/gang-tay-boxing', 'Mua găng tay Boxing chất lượng, đa dạng size và mẫu mã cho người mới tập đến thi đấu chuyên nghiệp ở Bảo An Sport. Cam kết hàng chính hãng, giao hàng toàn quốc.', 240),
  ('dung-cu-vo-thuat', 'DICH_DAM_DICH_DA', 'Đích đá - Đích đấm', 'dich-dam-dich-da', 'dung-cu-vo-thuat/dich-dam-dich-da', 'Cung cấp đích đấm tay và đích đá chân dùng cho Boxing, MMA, Muay Thái. Thiết kế dày dặn, độ đàn hồi tốt, phù hợp cho HLV và người tập tại nhà hoặc CLB võ thuật.', 220),
  ('dung-cu-vo-thuat', 'MU_AO_GIAP_VO_THUAT', 'Mũ - Áo Giáp Võ Thuật', 'mu-ao-giap-vo-thuat', 'dung-cu-vo-thuat/mu-ao-giap-vo-thuat', 'Mua mũ, áo giáp võ thuật, giáp bụng và giáp tay - chân chính hãng tại Bảo An Sport. Sản phẩm bền đẹp, đa dạng mẫu mã, giao hàng nhanh toàn quốc, tư vấn tận tâm.', 340),
  ('dung-cu-vo-thuat', 'DUNG_CU_TAP_THE_LUC', 'Dụng Cụ Tập Thể Lực', 'dung-cu-tap-the-luc', 'dung-cu-vo-thuat/dung-cu-tap-the-luc', 'Tìm hiểu 10 dụng cụ tập thể lực tại nhà hiệu quả gồm dây đàn hồi, dây nhảy, dây lò xo, bóng tạ... ở Bảo An Sport. Sản phẩm đa dạng, chính hãng, giao hàng nhanh.', 230),
  ('dung-cu-bong-da', 'QUA_BONG_DA', 'Quả Bóng Đá', 'qua-bong-da', 'dung-cu-bong-da/qua-bong-da', 'Tìm hiểu 8 quả bóng đá Động Lực tốt nhất dùng tập luyện và thi đấu chuyên nghiệp. Xem chi tiết tại Bảo An Sport - hàng chính hãng, tư vấn chuẩn, giao toàn quốc.', 470),
  ('dung-cu-bong-da', 'LUOI_KHUNG_THANH_BONG_DA', 'Lưới - Khung Thành Bóng Đá', 'luoi-khung-thanh-bong-da', 'dung-cu-bong-da/luoi-khung-thanh-bong-da', 'Tìm hiểu Top 5 khung thành bóng đá tiêu chuẩn cho sân 5, 7, 11 người cùng hướng dẫn cách chọn mua phù hợp. Gợi ý địa chỉ bán hàng chính hãng, giao nhanh tại nhà.', 290),
  ('dung-cu-bong-da', 'PHU_KIEN_BONG_DA', 'Phụ Kiện Bóng Đá', 'phu-kien-bong-da', 'dung-cu-bong-da/phu-kien-bong-da', 'Tìm hiểu các phụ kiện bóng đá tại Bảo An Sport: găng tay, còi, nấm chiến thuật, bảng chiến thuật... Chính hãng, giao hàng toàn quốc, tư vấn chọn sản phẩm chuẩn.', 390),
  ('dung-cu-cau-long', 'TRU_LUOI_CAU_LONG', 'Trụ - Lưới Cầu Lông', 'tru-luoi-cau-long', 'dung-cu-cau-long/tru-luoi-cau-long', 'Tìm hiểu 10 mẫu trụ lưới cầu lông thi đấu & tập luyện chất lượng, phù hợp sử dụng sân trong nhà và ngoài trời. Mua trụ lưới chính hãng, giá rẻ tại Bảo An Sport.', 550),
  ('dung-cu-cau-long', 'QUA_CAU_LONG', 'Quả Cầu Lông', 'qua-cau-long', 'dung-cu-cau-long/qua-cau-long', 'Quả cầu lông chính hãng, đủ loại từ cầu lông vũ đến cầu nhựa, phù hợp luyện tập và thi đấu. Mua hàng ở Bảo An Sport - đa dạng mẫu mã, giao hàng nhanh toàn quốc.', 490),
  ('dung-cu-cau-long', 'THAM_SAN_CAU_LONG', 'Thảm Cầu Lông', 'tham-san-cau-long', 'dung-cu-cau-long/tham-san-cau-long', 'Thảm cầu lông chính hãng, chống trượt, êm chân, đạt tiêu chuẩn thi đấu chuyên nghiệp. Mua thảm ở Bảo An Sport - đa dạng lựa chọn, tư vấn kỹ, thi công toàn quốc.', 510),
  ('dung-cu-cau-long', 'PHU_KIEN_CAU_LONG', 'Phụ Kiện Cầu Lông', 'phu-kien-cau-long', 'dung-cu-cau-long/phu-kien-cau-long', 'Tìm hiểu các phụ kiện cầu lông chính hãng tại Bảo An Sport: túi đựng, quấn cán, bảng điểm, ghế trọng tài. Đa dạng mẫu mã, tư vấn chuyên sâu, giao hàng toàn quốc.', 410),
  ('dung-cu-bong-chuyen', 'QUA_BONG_CHUYEN', 'Quả Bóng Chuyền', 'qua-bong-chuyen', 'dung-cu-bong-chuyen/qua-bong-chuyen', 'Mua quả bóng chuyền chính hãng, đa dạng mẫu mã và giá tốt nhất tại Bảo An Sport. Giao hàng toàn quốc, tư vấn chọn bóng da, bóng hơi, bóng bãi biển chuẩn nhu cầu.', 460),
  ('dung-cu-bong-chuyen', 'TRU_LUOI_BONG_CHUYEN', 'Trụ - Lưới Bóng Chuyền', 'tru-luoi-bong-chuyen', 'dung-cu-bong-chuyen/tru-luoi-bong-chuyen', 'Tìm hiểu Top 6 trụ lưới bóng chuyền chất lượng tốt dùng cho tập luyện và thi đấu. Hướng dẫn cách chọn mua trụ lưới phù hợp và gợi ý địa chỉ bán hàng chính hãng.', 540),
  ('dung-cu-bong-chuyen', 'PHU_KIEN_BONG_CHUYEN', 'Phụ Kiện Bóng Chuyền', 'phu-kien-bong-chuyen', 'dung-cu-bong-chuyen/phu-kien-bong-chuyen', 'Phụ kiện bóng chuyền chính hãng, đa dạng mẫu mã gồm cọc giới hạn, bảng điểm, bảng thay người, ghế trọng tài... Mua online tại Bảo An Sport, giao hàng toàn quốc.', 380),
  ('dung-cu-bong-ro', 'QUA_BONG_RO', 'Quả Bóng Rổ', 'qua-bong-ro', 'dung-cu-bong-ro/qua-bong-ro', 'Cung cấp quả bóng rổ chính hãng dùng cho tập luyện, thi đấu và chơi giải trí. Bóng độ bền cao, cầm chắc tay, phù hợp mọi độ tuổi. Giá tốt, giao nhanh toàn quốc.', 480),
  ('dung-cu-bong-ro', 'TRU_BONG_RO', 'Trụ Bóng Rổ', 'tru-bong-ro', 'dung-cu-bong-ro/tru-bong-ro', 'Trụ bóng rổ di động, cố định cho gia đình, trường học và sân tập. Nhiều mẫu mã, đa dạng chiều cao, cấu hình và mức giá. Tham khảo sản phẩm tại Bảo An Sport.', 530),
  ('dung-cu-bong-ro', 'PHU_KIEN_BONG_RO', 'Phụ Kiện Bóng Rổ', 'phu-kien-bong-ro', 'dung-cu-bong-ro/phu-kien-bong-ro', 'Tìm hiểu các phụ kiện bóng rổ chất lượng tại Bảo An Sport: lưới bóng rổ, bảng rổ, bảng điểm, xe đựng bóng... Cam kết chính hãng, tư vấn tận tình, giao toàn quốc.', 400),
  ('dung-cu-boi-loi', 'KINH_BOI', 'Kính Bơi', 'kinh-boi', 'dung-cu-boi-loi/kinh-boi', 'Tìm hiểu các mẫu kính bơi chính hãng tại Bảo An Sport - đa dạng mẫu mã, phù hợp dùng cho trẻ em và người lớn. Tư vấn tận tình, giao hàng nhanh tại nhà toàn quốc.', 280),
  ('dung-cu-boi-loi', 'MU_BOI', 'Mũ Bơi', 'mu-boi', 'dung-cu-boi-loi/mu-boi', 'Khám phá các mẫu mũ bơi chất lượng ở Bảo An Sport - đa dạng chất liệu, phù hợp cho cả người lớn và trẻ em. Hàng chính hãng, tư vấn tận tâm, giao hàng toàn quốc.', 350),
  ('dung-cu-boi-loi', 'PHU_KIEN_BOI_LOI', 'Phụ Kiện Bơi Lội', 'phu-kien-boi-loi', 'dung-cu-boi-loi/phu-kien-boi-loi', 'Tìm hiểu các phụ kiện bơi lội tại Bảo An Sport: bịt tai bơi, dung dịch chống mờ kính, phao bơi, chân vịt. Hàng chính hãng, mẫu mã đa dạng, giao nhanh toàn quốc.', 360),
  ('dung-cu-tennis', 'TRU_LUOI_TENNIS', 'Trụ - Lưới Tennis', 'tru-luoi-tennis', 'dung-cu-tennis/tru-luoi-tennis', 'Tìm hiểu 5 mẫu trụ lưới Tennis chất lượng, bền đẹp và đạt chuẩn tập luyện, thi đấu chuyên nghiệp. Hướng dẫn cách chọn mua phù hợp và địa chỉ mua hàng chính hãng.', 570),
  ('dung-cu-tennis', 'BONG_TENNIS', 'Bóng Tennis', 'bong-tennis', 'dung-cu-tennis/bong-tennis', 'Cung cấp bóng Tennis chính hãng Dunlop, Wilson, Babolat, Prince. Phù hợp dùng tập luyện & thi đấu chuyên nghiệp. Độ nảy ổn định, sẵn hàng, giao nhanh toàn quốc.', 210),
  ('dung-cu-tennis', 'PHU_KIEN_TENNIS', 'Phụ Kiện Tennis', 'phu-kien-tennis', 'dung-cu-tennis/phu-kien-tennis', 'Chuyên phụ kiện Tennis chính hãng: ghế trọng tài, xe gạt nước sân Tennis, lưỡi cao su... Giao hàng toàn quốc, chất lượng đảm bảo thi đấu, hỗ trợ tư vấn kỹ thuật.', 430),
  ('dung-cu-tap-gym', 'GIAN_TA_DA_NANG', 'Giàn Tạ Đa Năng', 'gian-ta-da-nang', 'dung-cu-tap-gym/gian-ta-da-nang', 'Tham khảo Top 6 giàn tạ đa năng tốt nhất cho Gymer với thiết kế chắc chắn, hỗ trợ nhiều bài tập hiệu quả. Gợi ý cách chọn mua giàn tạ và địa chỉ bán hàng chính hãng.', 270),
  ('dung-cu-tap-yoga', 'PHU_KIEN_YOGA', 'Phụ Kiện Yoga', 'phu-kien-yoga', 'dung-cu-tap-yoga/phu-kien-yoga', 'Tìm hiểu các phụ kiện Yoga chính hãng tại Bảo An Sport: gạch tập, vòng tập Yoga, khăn trải thảm Yoga... Nhân viên tư vấn chuyên sâu, giao hàng tại nhà toàn quốc.', 440),
  ('dung-cu-pickleball', 'BONG_PICKLEBALL', 'Bóng Pickleball', 'bong-pickleball', 'dung-cu-pickleball/bong-pickleball', 'Tìm hiểu bóng Pickleball là gì, cấu tạo, phân loại và cách chọn bóng đạt tiêu chuẩn thi đấu. Gợi ý các mẫu bóng Pickleball tốt, chính hãng và địa chỉ mua uy tín.', 190),
  ('dung-cu-pickleball', 'TRU_LUOI_PICKLEBALL', 'Trụ lưới Pickleball', 'tru-luoi-pickleball', 'dung-cu-pickleball/tru-luoi-pickleball', 'Tìm hiểu 10 mẫu trụ lưới Pickleball chính hãng, đạt chuẩn thi đấu, dễ lắp đặt và phù hợp sân trong nhà lẫn ngoài trời. Giao hàng nhanh, giá tốt tại Bảo An Sport.', 560)
) AS v(parent_slug, code, name, slug, path, description, sort_order)
  JOIN public.categories parent ON parent.slug = v.parent_slug;

-- 6. Sản phẩm, biến thể, giá, ảnh — nạp qua bảng tạm rồi ghép bằng khoá tự nhiên.
CREATE TEMP TABLE seed_product (
  slug text PRIMARY KEY, product_no text, sku text, name text,
  short_description text, description text, price numeric, category_slug text,
  weight_grams int, specs jsonb, source_url text) ON COMMIT DROP;

CREATE TEMP TABLE seed_media (product_slug text, sort_order int, url text) ON COMMIT DROP;

                             short_description, description, status, published_at,
                             seo_json, created_by, updated_by, created_at, updated_at)
SELECT b.id, 'STANDARD', s.product_no, s.name, s.slug, s.short_description, s.description,
       'PUBLISHED', CURRENT_TIMESTAMP,
       jsonb_build_object('sourceUrl', s.source_url, 'specifications', s.specs),
       1, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
  FROM seed_product s CROSS JOIN (SELECT id FROM public.brands WHERE code = 'OEM') b;

SELECT p.id, s.sku, s.name, s.weight_grams, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
  FROM seed_product s JOIN public.products p ON p.slug = s.slug;

                                   amount, starts_at, status, created_by, updated_by, created_at, updated_at)
SELECT v.id, 'REGULAR', 'ONLINE', 'VND', s.price, CURRENT_TIMESTAMP, 'ACTIVE',
       1, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
  FROM seed_product s
  JOIN public.products p ON p.slug = s.slug
  JOIN public.product_variants v ON v.product_id = p.id;

SELECT p.id, c.id, true, 0
  FROM seed_product s
  JOIN public.products p ON p.slug = s.slug
  JOIN public.categories c ON c.slug = s.category_slug;

                                 secure_url, format, folder, alt_text, status, created_at, updated_at)
-- Một ảnh có thể xuất hiện ở nhiều sản phẩm (banner dùng chung);
-- media_assets unique theo (provider, provider_asset_id) nên chỉ tạo một bản ghi mỗi URL.
SELECT DISTINCT ON (m.url) 'EXTERNAL', m.url, m.url, 'IMAGE', m.url,
       NULLIF(lower(substring(m.url from '\.([A-Za-z0-9]+)$')), ''),
       'baoansport', left(s.name, 500), 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
  FROM seed_media m JOIN seed_product s ON s.slug = m.product_slug
 ORDER BY m.url, m.product_slug;

                                  sort_order, is_primary, status)
SELECT p.id, a.id, 'IMAGE', left(s.name, 500), m.sort_order, m.sort_order = 0, 'ACTIVE'
  FROM seed_media m
  JOIN seed_product s ON s.slug = m.product_slug
  JOIN public.products p ON p.slug = m.product_slug
  JOIN public.media_assets a ON a.public_id = m.url;

