INSERT INTO seed_product VALUES
  ('gian-ta-da-nang-hq-909s', 'BAS-1635', 'HQ-909S', 'Giàn tạ đa năng HQ-909S', 'Giàn tạ đa năng HQ-909S tích hợp nhiều bài tập cho ngực, lưng, vai, tay, chân và bụng. Thiết kế chắc chắn, kèm 70kg tạ, phù hợp tập gym tại nhà. Mua tại Bảo An Sport.', 'Giàn tạ đa năng HQ-909S tích hợp nhiều bài tập cho ngực, lưng, vai, tay, chân và bụng. Thiết kế chắc chắn, kèm 70kg tạ, phù hợp tập gym tại nhà. Mua tại Bảo An Sport.', 16000000, 'gian-ta-da-nang', 200000, '{"Mã sản phẩm": "HQ-909S", "Màu sắc": "Trắng - đen", "Chất liệu": "Thép", "Trọng lượng tạ": "70 kg", "Trọng lượng cả bộ": "200 kg", "Trọng lượng thùng": "210 kg", "Tải trọng tối đa": "250 kg", "Diện tích lắp đặt": "2750 x 2100 x 2250mm", "Số kiện đóng thùng": "6 kiện"}'::jsonb, 'https://baoansport.vn/gian-ta-da-nang/gian-ta-da-nang-hq-909s/'),
  ('ghe-tap-ta-da-nang-t059', 'BAS-1634', 'T059', 'Ghế tập tạ đa năng T059', 'Ghế tập tạ đa năng T059 hỗ trợ tập tạ, tập bụng, xà đơn, xà kép và tập chân. Thiết kế chắc chắn, điều chỉnh linh hoạt, phù hợp tập luyện tại nhà. Mua ghế ở Bảo An Sport.', 'Ghế tập tạ đa năng T059 hỗ trợ tập tạ, tập bụng, xà đơn, xà kép và tập chân. Thiết kế chắc chắn, điều chỉnh linh hoạt, phù hợp tập luyện tại nhà. Mua ghế ở Bảo An Sport.', 4100000, 'ghe-tap-ta', 30500, '{"Mã sản phẩm": "T059", "Màu sắc": "Đỏ - đen", "Chất liệu": "Thép", "Trọng lượng ghế": "30.5 Kg", "Trọng lượng thùng": "33 Kg", "Tải trọng tối đa": "120 Kg", "Diện tích lắp đặt": "230 x 206 x 97cm", "Kích thước thùng": "119 x 61 x 17cm"}'::jsonb, 'https://baoansport.vn/ghe-tap-ta/ghe-tap-ta-da-nang-t059/'),
  ('ghe-tap-ta-jl-065', 'BAS-1633', 'JL-065', 'Ghế tập tạ JL-065', 'Ghế tập tạ JL-065 được thiết kế chắc chắn khả năng chịu tải 250kg, đệm dày 6cm, điều chỉnh yên lưng 10 góc độ, ghế ngồi 3 nấc và phù hợp dùng tại nhà hoặc phòng Gym.', 'Ghế tập tạ JL-065 được thiết kế chắc chắn khả năng chịu tải 250kg, đệm dày 6cm, điều chỉnh yên lưng 10 góc độ, ghế ngồi 3 nấc và phù hợp dùng tại nhà hoặc phòng Gym.', 6800000, 'ghe-tap-ta', 42000, '{"Mã sản phẩm": "JL-065", "Màu sắc": "Đỏ - đen", "Chất liệu": "Thép", "Trọng lượng ghế": "42 kg", "Trọng lượng thùng": "45 kg", "Tải trọng tối đa": "250 kg", "Diện tích lắp đặt": "143 x 60 x 46cm", "Kích thước thùng": "150 x 52 x 26cm"}'::jsonb, 'https://baoansport.vn/ghe-tap-ta/ghe-tap-ta-jl-065/'),
  ('banh-ta-cao-su-iron-bull-phi-52', 'BAS-1632', 'BT-IronBull', 'Bánh tạ cao su Iron Bull phi 52 (65.000/Kg)', 'Bánh tạ cao su Iron Bull phi 52 chính hãng được làm từ lõi thép bên ngoài bọc cao su TPU bền bỉ, thiết kế 3 tay cầm, phù hợp sử dụng cho phòng Gym và tập luyện tại nhà.', 'Bánh tạ cao su Iron Bull phi 52 chính hãng được làm từ lõi thép bên ngoài bọc cao su TPU bền bỉ, thiết kế 3 tay cầm, phù hợp sử dụng cho phòng Gym và tập luyện tại nhà.', 65000, 'ta-tay-ta-don', 0, '{"Mã sản phẩm": "BT-IronBull", "Màu sắc": "Đen - đỏ", "Chất liệu": "Thép, cao su", "Đường kính lỗ tạ": "Phi 52", "Trọng lượng tạ": "2.5kg; 5kg; 10kg; 15kg; 20kg"}'::jsonb, 'https://baoansport.vn/ta-tay-ta-don/banh-ta-cao-su-iron-bull-phi-52/'),
  ('ta-tay-iron-bull', 'BAS-1631', 'IronBull', 'Tạ tay Iron Bull (70.000/Kg)', 'Tạ tay Iron Bull chính hãng được làm từ thép bọc cao su TPU, tay cầm mạ crom chống trơn trượt, đa dạng trọng lượng từ 2.5-30Kg và phù hợp dùng tại nhà hay phòng Gym.', 'Tạ tay Iron Bull chính hãng được làm từ thép bọc cao su TPU, tay cầm mạ crom chống trơn trượt, đa dạng trọng lượng từ 2.5-30Kg và phù hợp dùng tại nhà hay phòng Gym.', 70000, 'ta-tay-ta-don', 2500, '{"Mã sản phẩm": "IronBull", "Màu sắc": "Đen - đỏ", "Chất liệu": "Thép, cao su", "Tay cầm": "Mạ crom", "Trọng lượng": "2.5kg đến 30kg"}'::jsonb, 'https://baoansport.vn/ta-tay-ta-don/ta-tay-iron-bull/'),
  ('xe-dung-bong-pickleball-301358', 'BAS-1630', '301538', 'Xe đựng bóng Pickleball 301538', 'Xe đựng bóng Pickleball 301358 chính hãng Vifa Sport được làm từ thép sơn tĩnh điện, sức chứa 100-120 bóng, có bánh xe di chuyển và phù hợp cho sân tập, thi đấu.', 'Xe đựng bóng Pickleball 301358 chính hãng Vifa Sport được làm từ thép sơn tĩnh điện, sức chứa 100-120 bóng, có bánh xe di chuyển và phù hợp cho sân tập, thi đấu.', 1850000, 'tru-luoi-pickleball', 0, '{"Mã sản phẩm": "301538", "Màu sắc": "Trắng", "Chất liệu": "Thép Ø21, Ø8, Ø6", "Trọng lượng": "Đang cập nhật", "Kích thước lắp đặt": "65 x 52 x 100cm"}'::jsonb, 'https://baoansport.vn/tru-luoi-pickleball/xe-dung-bong-pickleball-301358/'),
  ('ghe-trong-tai-pickleball-302359-p', 'BAS-1629', '302359-P', 'Ghế trọng tài Pickleball 302359-P', 'Ghế trọng tài Pickleball 302359-P của Vifa Sport được làm từ khung thép sơn tĩnh điện chắc chắn, mặt bàn Compact bền đẹp và thích hợp cho sân thi đấu Pickleball.', 'Ghế trọng tài Pickleball 302359-P của Vifa Sport được làm từ khung thép sơn tĩnh điện chắc chắn, mặt bàn Compact bền đẹp và thích hợp cho sân thi đấu Pickleball.', 2950000, 'tru-luoi-pickleball', 10200, '{"Mã sản phẩm": "302359-P", "Màu sắc": "Trắng", "Chất liệu": "Thép, Compact", "Trọng lượng": "10.2 Kg", "Tải trọng tối đa": "120 Kg", "Kích thước": "650 x 650 x 974mm"}'::jsonb, 'https://baoansport.vn/tru-luoi-pickleball/ghe-trong-tai-pickleball-302359-p/'),
  ('gian-ta-da-nang-hq-700s', 'BAS-1628', 'HQ-700S', 'Giàn tạ đa năng HQ-700S', 'Giàn tạ đa năng HQ-700S được thiết kế chắc chắn, hỗ trợ nhiều bài tập toàn thân hiệu quả và phù hợp dùng tập tại nhà cho Gymer. Giá tốt, bền bỉ, dễ sử dụng.', 'Giàn tạ đa năng HQ-700S được thiết kế chắc chắn, hỗ trợ nhiều bài tập toàn thân hiệu quả và phù hợp dùng tập tại nhà cho Gymer. Giá tốt, bền bỉ, dễ sử dụng.', 10800000, 'gian-ta-da-nang', 164000, '{"Mã sản phẩm": "HQ-700S", "Màu sắc": "Đen", "Chất liệu": "Thép", "Trọng lượng tạ": "72 kg", "Trọng lượng cả bộ": "164 kg", "Trọng lượng thùng": "172 kg", "Tải trọng tối đa": "200 kg", "Diện tích lắp đặt": "190 x 210 x 110 cm", "Số kiện đóng thùng": "4 kiện"}'::jsonb, 'https://baoansport.vn/gian-ta-da-nang/gian-ta-da-nang-hq-700s/'),
  ('ta-tay-luc-giac-kingbox', 'BAS-1627', 'TTLGK', 'Tạ tay lục giác Kingbox (60.000/Kg)', 'Tạ tay lục giác Kingbox bọc cao su được thiết kế chống lăn, tay cầm chắc chắn, phù hợp tập tại nhà và phòng Gym. Tạ có nhiều mức tạ, độ bền cao, giá tốt.', 'Tạ tay lục giác Kingbox bọc cao su được thiết kế chống lăn, tay cầm chắc chắn, phù hợp tập tại nhà và phòng Gym. Tạ có nhiều mức tạ, độ bền cao, giá tốt.', 60000, 'ta-tay-ta-don', 30000, '{"Mã sản phẩm": "TTLGK", "Màu sắc": "Đen", "Chất liệu": "Gang, cao su", "Tay cầm": "Thép mạ kẽm", "Trọng lượng": "2.5 - 30Kg"}'::jsonb, 'https://baoansport.vn/ta-tay-ta-don/ta-tay-luc-giac-kingbox/'),
  ('ghe-tap-ta-da-nang-ms-435', 'BAS-1626', 'MS-435', 'Ghế tập tạ đa năng MS-435', 'Ghế tập tạ đa năng MS-435 được thiết kế chắc chắn, hỗ trợ tập ngực, tay, bụng và chân hiệu quả. Sản phẩm phù hợp dùng tập Gym tại nhà, tiết kiệm chi phí.', 'Ghế tập tạ đa năng MS-435 được thiết kế chắc chắn, hỗ trợ tập ngực, tay, bụng và chân hiệu quả. Sản phẩm phù hợp dùng tập Gym tại nhà, tiết kiệm chi phí.', 5200000, 'ghe-tap-ta', 38000, '{"Mã sản phẩm": "MS-435", "Màu sắc": "Đen đỏ", "Chất liệu": "Thép hộp", "Trọng lượng ghế": "38 kg", "Trọng lượng thùng": "40 kg", "Tải trọng tối đa": "300 kg", "Diện tích lắp đặt": "140 x 161 x 170cm", "Kích thước thùng": "130 x 40 x 22.5cm"}'::jsonb, 'https://baoansport.vn/ghe-tap-ta/ghe-tap-ta-da-nang-ms-435/'),
  ('khung-tap-xa-da-nang-kingbox-kb-780', 'BAS-1625', 'KB-780', 'Khung tập xà đa năng Kingbox KB-780', 'Khung tập xà đa năng Kingbox KB-780 là thiết bị tập luyện thân trên chuyên nghiệp với kết cấu thép hộp dày và chịu tải đến 300 kg, cho phép điều chỉnh chiều cao dễ dàng.', 'Khung tập xà đa năng Kingbox KB-780 là thiết bị tập luyện thân trên chuyên nghiệp với kết cấu thép hộp dày và chịu tải đến 300 kg, cho phép điều chỉnh chiều cao dễ dàng.', 3850000, 'xa-don-xa-kep', 38000, '{"Mã sản phẩm": "KB-780", "Màu sắc": "Đen đỏ", "Chất liệu": "Thép hộp", "Trọng lượng xà": "35 kg", "Trọng lượng thùng": "38 kg", "Tải trọng tối đa": "300 kg", "Diện tích lắp đặt": "125 x 100 x 220cm", "Kích thước thùng 1": "117 x 23 x 20cm", "Kích thước thùng 2": "113 x 31 x 14cm"}'::jsonb, 'https://baoansport.vn/xa-don-xa-kep/khung-tap-xa-da-nang-kingbox-kb-780/'),
  ('khung-tap-xa-da-nang-kingbox-kb-103', 'BAS-1624', 'KB-103', 'Khung tập xà đa năng Kingbox KB-103', 'Khung tập xà đa năng Kingbox KB-103 là thiết bị tập luyện tại nhà được thiết kế chắc chắn, chịu tải đến 150kg và cho phép điều chỉnh chiều cao dễ dàng từ 155 tới 215cm.', 'Khung tập xà đa năng Kingbox KB-103 là thiết bị tập luyện tại nhà được thiết kế chắc chắn, chịu tải đến 150kg và cho phép điều chỉnh chiều cao dễ dàng từ 155 tới 215cm.', 1700000, 'xa-don-xa-kep', 17000, '{"Mã sản phẩm": "KB-103", "Màu sắc": "Đen xám", "Chất liệu": "Thép hộp", "Trọng lượng xà": "16 kg", "Trọng lượng thùng": "17 kg", "Tải trọng tối đa": "150 kg", "Diện tích lắp đặt": "114 x 113 x 215cm", "Kích thước đóng gói": "118 x 28 x 18cm"}'::jsonb, 'https://baoansport.vn/xa-don-xa-kep/khung-tap-xa-da-nang-kingbox-kb-103/'),
  ('khung-tap-xa-don-kingbox-kb-102', 'BAS-1623', 'KB-102', 'Khung tập xà đơn Kingbox KB-102', 'Khung tập xà đơn Kingbox KB-102 làm từ thép hộp 4×4cm dày 1.2mm, chịu tải tới 150kg và cho phép điều chỉnh chiều cao từ 155cm đến 215cm, phù hợp nhiều đối tượng.', 'Khung tập xà đơn Kingbox KB-102 làm từ thép hộp 4×4cm dày 1.2mm, chịu tải tới 150kg và cho phép điều chỉnh chiều cao từ 155cm đến 215cm, phù hợp nhiều đối tượng.', 1500000, 'xa-don-xa-kep', 16000, '{"Mã sản phẩm": "KB-102", "Màu sắc": "Đen xám", "Chất liệu": "Thép hộp", "Trọng lượng xà": "15 kg", "Trọng lượng thùng": "16 kg", "Tải trọng tối đa": "150 kg", "Diện tích lắp đặt": "114 x 113 x 215cm", "Kích thước đóng gói": "118 x 28 x 14cm"}'::jsonb, 'https://baoansport.vn/xa-don-xa-kep/khung-tap-xa-don-kingbox-kb-102/'),
  ('tru-pickleball-thi-dau-tt-805', 'BAS-1622', 'TT-805', 'Trụ Pickleball thi đấu TT-805', 'Trụ Pickleball thi đấu TT-805 làm từ khung thép sơn tĩnh điện, có tay quay căng lưới và bánh xe di chuyển. Sản phẩm phù hợp cho sân tập, sân thi đấu phong trào, trường học.', 'Trụ Pickleball thi đấu TT-805 làm từ khung thép sơn tĩnh điện, có tay quay căng lưới và bánh xe di chuyển. Sản phẩm phù hợp cho sân tập, sân thi đấu phong trào, trường học.', 4850000, 'tru-luoi-pickleball', 35000, '{"Mã sản phẩm": "TT-805", "Màu sắc": "Đen", "Chất liệu": "Thép hộp", "Trọng lượng": "35 kg", "Kích thước": "6832 x 754 x 904mm", "Căng lưới": "Bằng tay quay", "Bánh xe": "Có", "Lưới đi kèm": "Đã bao gồm"}'::jsonb, 'https://baoansport.vn/tru-luoi-pickleball/tru-pickleball-thi-dau-tt-805/'),
  ('ban-bong-ban-double-fish-df-201c', 'BAS-1621', 'DF-201C', 'Bàn bóng bàn Double Fish DF 201C', 'Bàn bóng bàn Double Fish DF 201C sở hữu mặt MDF 18mm cho độ nảy đều, khung chắc chắn, thiết kế gấp gọn tiện lợi. Phù hợp dùng cho gia đình, văn phòng, trường học.', 'Bàn bóng bàn Double Fish DF 201C sở hữu mặt MDF 18mm cho độ nảy đều, khung chắc chắn, thiết kế gấp gọn tiện lợi. Phù hợp dùng cho gia đình, văn phòng, trường học.', 8900000, 'ban-bong-ban', 93000, '{"Mã sản phẩm": "DF-201C", "Màu sắc": "Đen - xanh", "Chất liệu": "Gỗ MDF, thép", "Độ dày mặt bàn": "18mm", "Kích thước bàn": "1525 x 2740 x 760mm", "Kích thước thùng": "1610 x 1440 x 150mm", "Trọng lượng bàn": "93 kg", "Trọng lượng thùng": "103 kg", "Cọc lưới đi kèm": "Có"}'::jsonb, 'https://baoansport.vn/ban-bong-ban/ban-bong-ban-double-fish-df-201c/'),
  ('luoi-pickleball-vifasport-325048', 'BAS-1620', '325048', 'Lưới Pickleball VifaSport 325048', 'Lưới Pickleball VifaSport 325048 được làm từ chất liệu sợi TPE 2.5 mm bền bỉ, ô lưới M48 và thiết kế chống thụng. Sản phẩm phù hợp cho cả tập luyện và thi đấu Pickleball.', 'Lưới Pickleball VifaSport 325048 được làm từ chất liệu sợi TPE 2.5 mm bền bỉ, ô lưới M48 và thiết kế chống thụng. Sản phẩm phù hợp cho cả tập luyện và thi đấu Pickleball.', 1400000, 'tru-luoi-pickleball', 0, '{"Mã sản phẩm": "325048", "Màu sắc": "Đen", "Chất liệu": "Sợi TPE 2.5mm", "Ô lưới": "M48", "Biên trên": "Băng Polyester", "Kích thước": "0.86 x 6.7m", "Dây căng": "Cáp thép Ø5mm dài 7.4m"}'::jsonb, 'https://baoansport.vn/tru-luoi-pickleball/luoi-pickleball-vifasport-325048/'),
  ('xe-dap-tap-the-duc-new-life-span', 'BAS-1619', 'New-Life-Span', 'Xe đạp tập thể dục New Life Span', 'Xe đạp tập thể dục New Life Span sở hữu thiết kế yên tựa lưng thoải mái, khung thép chắc chắn và bánh đà vận hành êm. Sản phẩm phù hợp dùng tập tại nhà cho gia đình.', 'Xe đạp tập thể dục New Life Span sở hữu thiết kế yên tựa lưng thoải mái, khung thép chắc chắn và bánh đà vận hành êm. Sản phẩm phù hợp dùng tập tại nhà cho gia đình.', 3600000, 'xe-dap-tap-the-duc', 19900, '{"Mã sản phẩm": "New-Life-Span", "Màu sắc": "Xám - cam", "Chất liệu": "Thép, nhựa", "Trọng lượng xe": "19.9 kg", "Trọng lượng thùng": "22.1 kg", "Tải trọng tối đa": "120 kg", "Kích thước lắp đặt": "95 x 52 x 121cm", "Kích thước thùng": "100 x 21.5 x 59cm", "Yên xe": "Có", "Chuyển động": "Dây xích + bánh đà", "Kháng lực": "Có", "Đo nhịp tim": "Có"}'::jsonb, 'https://baoansport.vn/xe-dap-tap-the-duc/xe-dap-tap-the-duc-new-life-span/'),
  ('ghe-tap-ta-g02', 'BAS-1618', 'G02', 'Ghế tập tạ G02', 'Ghế tập tạ G02 thiết kế khung thép chắc chắn, đệm ghế dày, hỗ trợ tập đẩy ngực với tạ đòn an toàn. Phù hợp tập Gym tại nhà và phòng tập nhỏ, phân phối tại Bảo An Sport.', 'Ghế tập tạ G02 thiết kế khung thép chắc chắn, đệm ghế dày, hỗ trợ tập đẩy ngực với tạ đòn an toàn. Phù hợp tập Gym tại nhà và phòng tập nhỏ, phân phối tại Bảo An Sport.', 5900000, 'ghe-tap-ta', 37000, '{"Mã sản phẩm": "G02", "Màu sắc": "Xám - đỏ", "Chất liệu": "Thép, nệm mút", "Trọng lượng ghế": "37 kg", "Trọng lượng thùng": "40 kg", "Tải trọng tối đa": "350 kg", "Kích thước lắp đặt": "150 x 156 x 120cm", "Kích thước thùng 1": "124 x 57 x 20.5cm", "Kích thước thùng 2": "90 x 50 x 17.5cm"}'::jsonb, 'https://baoansport.vn/ghe-tap-ta/ghe-tap-ta-g02/'),
  ('ban-bong-ban-harito-tt-278', 'BAS-1617', 'TT-278', 'Bàn bóng bàn Harito TT-278', 'Bàn bóng bàn Harito TT-278 có độ nảy chuẩn, chân chắc chắn, dễ gấp gọn và di chuyển. Phù hợp câu lạc bộ, trường học và gia đình, phân phối chính hãng ở Bảo An Sport.', 'Bàn bóng bàn Harito TT-278 có độ nảy chuẩn, chân chắc chắn, dễ gấp gọn và di chuyển. Phù hợp câu lạc bộ, trường học và gia đình, phân phối chính hãng ở Bảo An Sport.', 8900000, 'ban-bong-ban', 100000, '{"Mã sản phẩm": "TT-278", "Màu sắc": "Xanh", "Chất liệu": "Gỗ MDF, thép", "Độ dày mặt bàn": "18mm", "Kích thước bàn": "1525 x 2740 x 760mm", "Kích thước thùng": "1610 x 1440 x 150mm", "Trọng lượng bàn": "100kg", "Trọng lượng thùng": "102kg", "Cọc lưới đi kèm": "Có"}'::jsonb, 'https://baoansport.vn/ban-bong-ban/ban-bong-ban-harito-tt-278/'),
  ('tru-bong-ro-s206', 'BAS-1616', 'S206', 'Trụ bóng rổ S206', 'Mua trụ bóng rổ S206 chính hãng ở Bảo An Sport - thiết kế di động, điều chỉnh độ cao linh hoạt, khung thép chắc chắn. Giao hàng tại nhà toàn quốc, giá tốt nhất.', 'Mua trụ bóng rổ S206 chính hãng ở Bảo An Sport - thiết kế di động, điều chỉnh độ cao linh hoạt, khung thép chắc chắn. Giao hàng tại nhà toàn quốc, giá tốt nhất.', 5800000, 'tru-bong-ro', 0, '{"Mã sản phẩm": "S206", "Màu sắc": "Đen", "Chiều cao rổ": "Từ 2m45 đến 3m05", "Đường kính rổ": "45 cm", "Kích thước bảng": "112 × 72 cm", "Kích thước đế trụ": "90 × 60 × 15 cm", "Kích thước thùng": "112 × 25 × 77cm", "Trọng lượng trụ": "28 kg", "Trọng lượng đóng thùng": "30 kg", "Bánh xe di chuyển": "Có"}'::jsonb, 'https://baoansport.vn/tru-bong-ro/tru-bong-ro-s206/'),
  ('ta-tay-thao-lap-ma-niken', 'BAS-1615', 'TTTLMN', 'Tạ tay tháo lắp mạ Niken', 'Tạ tay tháo lắp mạ Niken chính hãng tại Bảo An Sport – có 3 mức 20kg, 30kg và 40kg. Thiết kế bền đẹp, dễ dàng tháo lắp, giao hàng toàn quốc & bảo hành 12 tháng.', 'Tạ tay tháo lắp mạ Niken chính hãng tại Bảo An Sport – có 3 mức 20kg, 30kg và 40kg. Thiết kế bền đẹp, dễ dàng tháo lắp, giao hàng toàn quốc & bảo hành 12 tháng.', 1300000, 'ta-tay-ta-don', 20000, '{"Mã sản phẩm": "TTTLMN", "Màu sắc": "Xám bạc", "Chất liệu": "Thép, gang mạ niken", "Trọng lượng": "20kg, 30kg và 40kg", "Loại tạ": "Tháo lắp", "Hộp đựng đi kèm": "Có"}'::jsonb, 'https://baoansport.vn/ta-tay-ta-don/ta-tay-thao-lap-ma-niken/'),
  ('vot-bong-ban-stiga-tube-5-sao', 'BAS-1614', 'Tube', 'Vợt bóng bàn Stiga Tube 5 sao', 'Vợt bóng bàn Stiga Tube 5 sao thiết kế 5 lớp gỗ kết hợp 2 lớp carbon, tốc độ nhanh - xoáy mạnh - kiểm soát ổn định. Mua vợt chính hãng, giá tốt tại Bảo An Sport.', 'Vợt bóng bàn Stiga Tube 5 sao thiết kế 5 lớp gỗ kết hợp 2 lớp carbon, tốc độ nhanh - xoáy mạnh - kiểm soát ổn định. Mua vợt chính hãng, giá tốt tại Bảo An Sport.', 1200000, 'vot-bong-ban', 0, '{"Mã sản phẩm": "Tube", "Màu sắc": "Đỏ, đen", "Chất liệu": "Gỗ + sợi carbon + cao su + bọt biển", "Trọng lượng": "320 ± 6 gram", "Kích thước mặt vợt": "160 x 152 mm", "Độ dày vợt": "13.5 ± 0.2 mm", "Điều khiển": "7", "Tốc độ": "8", "Bộ vợt gồm": "1 vợt + 1 bóng + băng tay thấm mồ hôi + hộp đựng"}'::jsonb, 'https://baoansport.vn/vot-bong-ban/vot-bong-ban-stiga-tube-5-sao/'),
  ('vot-bong-ban-stiga-crystal-4-sao', 'BAS-1613', 'Crystal', 'Vợt bóng bàn Stiga Crystal 4 sao', 'Vợt bóng bàn Stiga Crystal 4 sao nổi bật với thiết kế 5 lớp gỗ + 2 lớp carbon, tốc độ mạnh mẽ, độ xoáy ổn định và kiểm soát tốt. Mua chính hãng tại Bảo An Sport.', 'Vợt bóng bàn Stiga Crystal 4 sao nổi bật với thiết kế 5 lớp gỗ + 2 lớp carbon, tốc độ mạnh mẽ, độ xoáy ổn định và kiểm soát tốt. Mua chính hãng tại Bảo An Sport.', 1100000, 'vot-bong-ban', 0, '{"Mã sản phẩm": "Crystal", "Màu sắc": "Đỏ, đen", "Chất liệu": "Gỗ + sợi carbon + cao su + bọt biển", "Trọng lượng": "320 ± 6 gram", "Kích thước mặt vợt": "160 x 152 mm", "Độ dày vợt": "13.5 ± 0.2 mm", "Điều khiển": "6", "Tốc độ": "8", "Bộ vợt gồm": "1 vợt + 1 bóng + băng tay thấm mồ hôi + hộp đựng"}'::jsonb, 'https://baoansport.vn/vot-bong-ban/vot-bong-ban-stiga-crystal-4-sao/'),
  ('vot-bong-ban-stiga-bounce-3-sao', 'BAS-1612', 'Bounce', 'Vợt bóng bàn Stiga Bounce 3 sao', 'Mua vợt bóng bàn Stiga Bounce 3 sao chính hãng tại Bảo An Sport. Thiết kế 5 lớp gỗ và cao su bám xoáy tốt, dễ dùng cho người mới. Giá tốt, giao toàn quốc.', 'Mua vợt bóng bàn Stiga Bounce 3 sao chính hãng tại Bảo An Sport. Thiết kế 5 lớp gỗ và cao su bám xoáy tốt, dễ dùng cho người mới. Giá tốt, giao toàn quốc.', 1000000, 'vot-bong-ban', 0, '{"Mã sản phẩm": "Bounce", "Màu sắc": "Đỏ, đen", "Chất liệu": "5 lớp gỗ + cao su + bọt biển", "Trọng lượng": "328 ± 6 gram", "Điều khiển": "6", "Tốc độ": "7", "Bộ vợt gồm": "1 vợt + 1 bóng + băng tay thấm mồ hôi + hộp đựng"}'::jsonb, 'https://baoansport.vn/vot-bong-ban/vot-bong-ban-stiga-bounce-3-sao/'),
  ('ban-bong-ban-vnsport-mdf-09', 'BAS-1611', 'MDF-09', 'Bàn bóng bàn VnSport MDF-09', 'Bàn bóng bàn VnSport MDF-09 có mặt gỗ MDF cao cấp, khung thép chắc chắn và phù hợp luyện tập, thi đấu. Mua bàn ở Bảo An Sport, giá tốt - giao nhanh.', 'Bàn bóng bàn VnSport MDF-09 có mặt gỗ MDF cao cấp, khung thép chắc chắn và phù hợp luyện tập, thi đấu. Mua bàn ở Bảo An Sport, giá tốt - giao nhanh.', 7950000, 'ban-bong-ban', 108000, '{"Mã sản phẩm": "MDF-09", "Màu sắc": "Đen", "Chất liệu": "Thép, gỗ MDF", "Độ dày mặt bàn": "25mm", "Kích thước lắp đặt": "2740 x 1525 x 760 mm", "Kích thước vận chuyển": "1600 x 1470 x 120 mm", "Trọng lượng bàn": "108 kg", "Gập gọn": "Có", "Bánh xe di chuyển": "Có", "Khuyến mại": "Cọc lưới + bóng + vợt"}'::jsonb, 'https://baoansport.vn/ban-bong-ban/ban-bong-ban-vnsport-mdf-09/'),
  ('ghe-tap-bung-da-nang-dds-bs1108', 'BAS-1610', 'BS1108', 'Ghế tập bụng đa năng DDS BS1108', 'Ghế tập bụng đa năng DDS BS1108 thiết kế chắc chắn, an toàn, hỗ trợ gập bụng hiệu quả tại nhà. Hàng chính hãng, giá tốt, bảo hành đầy đủ ở Bảo An Sport.', 'Ghế tập bụng đa năng DDS BS1108 thiết kế chắc chắn, an toàn, hỗ trợ gập bụng hiệu quả tại nhà. Hàng chính hãng, giá tốt, bảo hành đầy đủ ở Bảo An Sport.', 1450000, 'ghe-tap-bung', 9500, '{"Mã sản phẩm": "BS1108", "Màu sắc": "Đen - đỏ", "Chất liệu": "Thép, mút da", "Trọng lượng ghế": "9.5 kg", "Trọng lượng đóng gói": "11.1 kg", "Kích thước lắp đặt": "150 × 41 × 80cm", "Kích thước đóng thùng": "135 × 19 × 35cm"}'::jsonb, 'https://baoansport.vn/ghe-tap-bung/ghe-tap-bung-da-nang-dds-bs1108/'),
  ('luoi-pickleball-thi-dau-330048c', 'BAS-1609', '330048C', 'Lưới Pickleball thi đấu 330048C', 'Lưới Pickleball thi đấu 330048C của Vifa Sport kích thước chuẩn 6.7 × 0.9m, sợi TPE siêu bền, biên gia cố chắc chắn, dùng cho sân trong nhà và ngoài trời.', 'Lưới Pickleball thi đấu 330048C của Vifa Sport kích thước chuẩn 6.7 × 0.9m, sợi TPE siêu bền, biên gia cố chắc chắn, dùng cho sân trong nhà và ngoài trời.', 1500000, 'tru-luoi-pickleball', 0, '{"Mã sản phẩm": "330048C", "Màu sắc": "Đen", "Chất liệu": "Sợi TPE 3.0mm", "Ô lưới": "M48", "Biên trên": "Băng Polyester", "Kích thước": "0.9 × 6.7m", "Dây căng": "Cáp thép Ø5mm dài 7.4m"}'::jsonb, 'https://baoansport.vn/tru-luoi-pickleball/luoi-pickleball-thi-dau-330048c/'),
  ('tru-pickleball-di-dong-303904p', 'BAS-1608', '303904‑P', 'Trụ Pickleball di động 303904‑P', 'Trụ Pickleball di động 303904‑P chính hãng Vifa Sport làm từ khung thép chắc chắn, thiết kế tháo lắp nhanh, có bánh xe, đặt được cả trong nhà lẫn ngoài trời.', 'Trụ Pickleball di động 303904‑P chính hãng Vifa Sport làm từ khung thép chắc chắn, thiết kế tháo lắp nhanh, có bánh xe, đặt được cả trong nhà lẫn ngoài trời.', 5200000, 'tru-luoi-pickleball', 35000, '{"Mã sản phẩm": "303904‑P", "Màu sắc": "Đen", "Chất liệu": "Thép hộp", "Trọng lượng": "35 kg", "Kích thước": "6860 × 750 × 914 mm", "Căng lưới": "Bằng tay quay", "Bánh xe": "Có", "Lưới đi kèm": "Chưa bao gồm"}'::jsonb, 'https://baoansport.vn/tru-luoi-pickleball/tru-pickleball-di-dong-303904p/'),
  ('khung-ganh-ta-da-nang-hq-k11', 'BAS-1607', 'HQ-K11', 'Khung gánh tạ đa năng HQ-K11', 'Khung gánh tạ đa năng HQ-K11 thiết kế chắc chắn, hỗ trợ nhiều bài tập, phù hợp người mới đến Gymer chuyên nghiệp. Chính hãng, giá tốt tại Bảo An Sport.', 'Khung gánh tạ đa năng HQ-K11 thiết kế chắc chắn, hỗ trợ nhiều bài tập, phù hợp người mới đến Gymer chuyên nghiệp. Chính hãng, giá tốt tại Bảo An Sport.', 22000000, 'gian-ta-da-nang', 194500, '{"Mã sản phẩm": "HQ-K11", "Màu sắc": "Đen, cam", "Chất liệu": "Thép, mút, da PU", "Trọng lượng cả bộ": "194.5 kg", "Trọng lượng tạ (2 bên)": "120 kg", "Tải trọng tập tối đa": "500 kg", "Kích thước lắp đặt": "220 × 140 × 210cm", "Số kiện đóng gói": "9 kiện", "Ghế tập đi kèm": "Có", "Đòn tạ đi kèm": "1 (lắp vào khung)"}'::jsonb, 'https://baoansport.vn/gian-ta-da-nang/khung-ganh-ta-da-nang-hq-k11/'),
  ('ghe-tap-bung-da-nang-dds-1127f', 'BAS-1606', 'DDS‑1127F', 'Ghế tập bụng đa năng DDS‑1127F', 'Ghế tập bụng đa năng DDS‑1127F thiết kế khung thép chắc chắc, đệm êm, tích hợp dây kéo tay, phù hợp tập tại nhà cho người mới và người rèn luyện thể lực.', 'Ghế tập bụng đa năng DDS‑1127F thiết kế khung thép chắc chắc, đệm êm, tích hợp dây kéo tay, phù hợp tập tại nhà cho người mới và người rèn luyện thể lực.', 1400000, 'ghe-tap-bung', 8800, '{"Mã sản phẩm": "DDS‑1127F", "Màu sắc": "Đen - nâu", "Chất liệu": "Thép, mút da", "Trọng lượng ghế": "8.8 kg", "Trọng lượng đóng gói": "11.3 kg", "Tải trọng tối đa": "100 kg", "Kích thước lắp đặt": "140 × 55 × 60cm", "Kích thước đóng thùng": "139.5 × 37.5 × 17.5cm"}'::jsonb, 'https://baoansport.vn/ghe-tap-bung/ghe-tap-bung-da-nang-dds-1127f/'),
  ('may-chay-bo-sakura-hq-v7-plus', 'BAS-1605', 'HQ-V7-Plus', 'Máy chạy bộ Sakura HQ-V7 Plus', 'Máy chạy bộ Sakura HQ-V7 Plus là mẫu máy đơn năng có thiết kế gọn đẹp, động cơ 3.0HP mạnh mẽ, khung thép chắc chắn, thích hợp sử dụng cho gia đình.', 'Máy chạy bộ Sakura HQ-V7 Plus là mẫu máy đơn năng có thiết kế gọn đẹp, động cơ 3.0HP mạnh mẽ, khung thép chắc chắn, thích hợp sử dụng cho gia đình.', 34500000, 'may-chay-bo', 158000, '{"Mã sản phẩm": "HQ-V7-Plus", "Màu sắc": "Đen - xám", "Điện áp": "220V, 50-60Hz", "Động cơ": "AC", "Công suất": "3.0Hp đạt đỉnh 6.0Hp", "Tốc độ": "0.8 - 20 km/h", "Nâng độ dốc": "0 đến 18%", "Trọng lượng máy": "158 kg", "Trọng lượng thùng": "172 kg", "Tải trọng tối đa": "160 kg", "Kích thước bàn chạy": "1600 × 590 mm", "Kích thước lắp đặt": "2200 × 820 × 1500mm", "Màn hình": "LED", "Thảm chạy": "Diamond Running Belt", "Giảm chấn": "Đệm cao su", "Khóa an toàn": "Có", "Gập gọn": "Không", "Bánh xe di chuyển": "Có", "Cổng kết nối/sạc": "USB", "Âm thanh": "Loa Hi-Fi"}'::jsonb, 'https://baoansport.vn/may-chay-bo/may-chay-bo-sakura-hq-v7-plus/'),
  ('may-chay-bo-mofit-senior-6900', 'BAS-1604', 'Senior-6900', 'Máy chạy bộ Mofit Senior 6900', 'Máy chạy bộ Mofit Senior 6900 thiết kế hiện đại, khung chắc chắn, động cơ mạnh mẽ, nhiều tính năng thông minh. Phù hợp phòng Gym hoặc tập luyện tại nhà.', 'Máy chạy bộ Mofit Senior 6900 thiết kế hiện đại, khung chắc chắn, động cơ mạnh mẽ, nhiều tính năng thông minh. Phù hợp phòng Gym hoặc tập luyện tại nhà.', 46500000, 'may-chay-bo', 192000, '{"Mã sản phẩm": "Senior-6900", "Màu sắc": "Đen - xám", "Điện áp": "Điện áp", "Động cơ": "AC", "Công suất": "Đạt đỉnh 7.0HP", "Tốc độ": "0.8 - 22 km/h", "Nâng độ dốc": "3 đến 18%", "Trọng lượng máy": "192 kg", "Trọng lượng thùng": "219 kg", "Tải trọng tối đa": "180 kg", "Kích thước bàn chạy": "1630 × 600 mm", "Kích thước lắp đặt": "2210 × 1020 × 1630mm", "Màn hình": "LED", "Thảm chạy": "Diamond Running Belt", "Giảm chấn": "Đệm cao su", "Khóa an toàn": "Có", "Gập gọn": "Không", "Bánh xe di chuyển": "Có"}'::jsonb, 'https://baoansport.vn/may-chay-bo/may-chay-bo-mofit-senior-6900/'),
  ('may-ban-bong-ban-yt-xiaoru-niu-no1', 'BAS-1603', 'Xiaoru-Niu-No-1', 'Máy bắn bóng bàn Y&T Xiaoru Niu No 1', 'Máy bắn bóng bàn Y&T Xiaoru Niu No 1 thiết kế gọn nhẹ, điều chỉnh dễ dàng với 9 kiểu xoáy, tốc độ 25-90 bóng/phút, thích hợp luyện tập cá nhân, câu lạc bộ.', 'Máy bắn bóng bàn Y&T Xiaoru Niu No 1 thiết kế gọn nhẹ, điều chỉnh dễ dàng với 9 kiểu xoáy, tốc độ 25-90 bóng/phút, thích hợp luyện tập cá nhân, câu lạc bộ.', 14500000, 'may-ban-bong-ban', 9360, '{"Mã sản phẩm": "Xiaoru-Niu-No-1", "Màu sắc": "Trắng - đen", "Trọng lượng máy": "9.36 kg", "Kích thước lắp đặt": "38 × 42.5 × 110cm", "Kích thước thùng": "84 × 46.5 × 38cm", "Chế độ xoáy": "9 chế độ", "Tần số phát bóng": "25-90 bóng/phút", "Tốc độ bắn bóng": "4-50 m/giây", "Góc bắn điều chỉnh": "0-40 độ"}'::jsonb, 'https://baoansport.vn/may-ban-bong-ban/may-ban-bong-ban-yt-xiaoru-niu-no1/'),
  ('gach-cao-su-epdm', 'BAS-1602', 'EPDM', 'Gạch cao su EPDM', 'Gạch cao su EPDM thiết kế chống trơn trượt, độ đàn hồi cao, giảm chấn hiệu quả cho phòng Gym, khu vui chơi và sân thể thao. Thi công dễ, sử dụng bền lâu.', 'Gạch cao su EPDM thiết kế chống trơn trượt, độ đàn hồi cao, giảm chấn hiệu quả cho phòng Gym, khu vui chơi và sân thể thao. Thi công dễ, sử dụng bền lâu.', 520000, 'thiet-bi-phong-gym', 0, '{"Mã sản phẩm": "EPDM", "Màu sắc": "Chấm trắng, vàng, cam", "Chất liệu": "Cao su, EPDM", "Kích thước": "50 × 50 cm hoặc 1 × 1 m", "Độ dày": "15mm, 25mm, 30mm, 35mm"}'::jsonb, 'https://baoansport.vn/thiet-bi-phong-gym/gach-cao-su-epdm/'),
  ('xe-dap-phuc-hoi-chuc-nang-tokado-tk-8601r', 'BAS-1601', 'TK-8601R', 'Xe đạp phục hồi chức năng Tokado TK-8601R', 'Xe đạp phục hồi chức năng Tokado TK-8601R thiết kế ghế tựa, điều chỉnh kháng lực, phù hợp cho người già, người yếu sức hoặc phục hồi sau chấn thương.', 'Xe đạp phục hồi chức năng Tokado TK-8601R thiết kế ghế tựa, điều chỉnh kháng lực, phù hợp cho người già, người yếu sức hoặc phục hồi sau chấn thương.', 6300000, 'xe-dap-tap-the-duc', 33000, '{"Mã sản phẩm": "TK-8601R", "Màu sắc": "Xám bạc - đen", "Chất liệu": "Thép, nhựa", "Trọng lượng bánh đà": "3 kg", "Trọng lượng xe": "33 kg", "Trọng lượng thùng": "37 kg", "Tải trọng tối đa": "120 kg", "Kích thước lắp đặt": "133 × 67 × 122cm", "Kích thước thùng": "90 × 38 × 65cm", "Yên xe tựa lưng": "Có", "Chuyển động": "Dây curoa + bánh đà", "Kháng lực": "8 mức", "Đo nhịp tim": "Có"}'::jsonb, 'https://baoansport.vn/xe-dap-tap-the-duc/xe-dap-phuc-hoi-chuc-nang-tokado-tk-8601r/'),
  ('bong-pickleball-zocker-five-star', 'BAS-1600', 'Five-Star', 'Bóng Pickleball Zocker Five Star', 'Bóng Pickleball Zocker Five Star được làm từ chất liệu nhựa PE, đường bay ổn định, độ nảy chuẩn và đạt tiêu chuẩn thi đấu. Mua bóng chính hãng tại Bảo An Sport.', 'Bóng Pickleball Zocker Five Star được làm từ chất liệu nhựa PE, đường bay ổn định, độ nảy chuẩn và đạt tiêu chuẩn thi đấu. Mua bóng chính hãng tại Bảo An Sport.', 145000, 'bong-pickleball', 0, '{"Mã sản phẩm": "Five-Star", "Màu sắc": "Xanh neon", "Chất liệu": "Nhựa PU", "Trọng lượng": "26 gram", "Đường kính": "74 mm", "Số lỗ khoan": "40 lỗ"}'::jsonb, 'https://baoansport.vn/bong-pickleball/bong-pickleball-zocker-five-star/'),
  ('bong-pickleball-ama-pro-40', 'BAS-1599', 'Pro-40', 'Bóng Pickleball AMA Pro-40', 'Bóng Pickleball AMA Pro-40 làm từ nhựa PE, thiết kế 40 lỗ chuẩn ngoài trời, bay ổn định và chịu lực tốt. Mua bóng chính hãng giá chỉ 55.000 ₫/quả ở Bảo An Sport.', 'Bóng Pickleball AMA Pro-40 làm từ nhựa PE, thiết kế 40 lỗ chuẩn ngoài trời, bay ổn định và chịu lực tốt. Mua bóng chính hãng giá chỉ 55.000 ₫/quả ở Bảo An Sport.', 55000, 'bong-pickleball', 0, '{"Mã sản phẩm": "Pro-40", "Màu sắc": "Xanh neon", "Chất liệu": "Nhựa PU", "Trọng lượng": "25-26 gram", "Đường kính": "73-74 mm", "Số lỗ khoan": "40 lỗ"}'::jsonb, 'https://baoansport.vn/bong-pickleball/bong-pickleball-ama-pro-40/'),
  ('bong-pickleball-zocker-five-star-gen-2', 'BAS-1598', 'Five-Star-Gen-2', 'Bóng Pickleball Zocker Five Star Gen 2', 'Bóng Pickleball Zocker Five Star Gen 2 thiết kế đạt tiêu chuẩn thi đấu, độ bền cao, bay ổn định và phù hợp chơi ngoài trời. Đặt mua bóng giá tốt ở Bảo An Sport.', 'Bóng Pickleball Zocker Five Star Gen 2 thiết kế đạt tiêu chuẩn thi đấu, độ bền cao, bay ổn định và phù hợp chơi ngoài trời. Đặt mua bóng giá tốt ở Bảo An Sport.', 185000, 'bong-pickleball', 0, '{"Mã sản phẩm": "Five-Star-Gen-2", "Màu sắc": "Xanh neon", "Chất liệu": "Nhựa PP", "Trọng lượng": "26 gram", "Đường kính": "74 mm", "Số lỗ khoan": "40 lỗ"}'::jsonb, 'https://baoansport.vn/bong-pickleball/bong-pickleball-zocker-five-star-gen-2/'),
  ('bong-pickleball-kamito-xforce', 'BAS-1597', 'X‑Force', 'Bóng Pickleball Kamito X‑Force', 'Bóng Pickleball Kamito X‑Force làm từ nhựa PE cao cấp, 40 lỗ khoan tự động, đạt tiêu chuẩn thi đấu. Bóng dùng cho sân ngoài trời, mua chính hãng ở Bảo An Sport.', 'Bóng Pickleball Kamito X‑Force làm từ nhựa PE cao cấp, 40 lỗ khoan tự động, đạt tiêu chuẩn thi đấu. Bóng dùng cho sân ngoài trời, mua chính hãng ở Bảo An Sport.', 180000, 'bong-pickleball', 0, '{"Mã sản phẩm": "X‑Force", "Màu sắc": "Xanh neon", "Chất liệu": "Nhựa PE", "Trọng lượng": "26 gram", "Đường kính": "74 mm", "Số lỗ khoan": "40 lỗ"}'::jsonb, 'https://baoansport.vn/bong-pickleball/bong-pickleball-kamito-xforce/'),
  ('bong-pickleball-franklin-x-40', 'BAS-1596', 'X-40', 'Bóng Pickleball Franklin X-40', 'Bóng Pickleball Franklin X-40 làm từ chất liệu nhựa PE, 40 lỗ khoan chuẩn, đường kính 74mm và nặng 26 gram. Bóng phù hợp dùng cho thi đấu ở sân chơi ngoài trời.', 'Bóng Pickleball Franklin X-40 làm từ chất liệu nhựa PE, 40 lỗ khoan chuẩn, đường kính 74mm và nặng 26 gram. Bóng phù hợp dùng cho thi đấu ở sân chơi ngoài trời.', 70000, 'bong-pickleball', 0, '{"Mã sản phẩm": "X-40", "Màu sắc": "Xanh neon", "Chất liệu": "Nhựa PE", "Trọng lượng": "26 gram", "Đường kính": "74 mm", "Số lỗ khoan": "40 lỗ"}'::jsonb, 'https://baoansport.vn/bong-pickleball/bong-pickleball-franklin-x-40/'),
