  ('tru-luoi-pickleball-di-dong-xuki', 'BAS-1592', 'TPXK', 'Trụ lưới Pickleball di động Xuki', 'Trụ lưới Pickleball di động Xuki thiết kế chắc chắn, dễ lắp ráp và phù hợp sân tập luyện, phong trào. Mua trụ chính hãng tại Bảo An Sport - Giao hàng toàn quốc.', 'Trụ lưới Pickleball di động Xuki thiết kế chắc chắn, dễ lắp ráp và phù hợp sân tập luyện, phong trào. Mua trụ chính hãng tại Bảo An Sport - Giao hàng toàn quốc.', 4800000, 'tru-luoi-pickleball', 37000, '{"Mã sản phẩm": "TPXK", "Màu sắc": "Đen", "Chất liệu": "Thép hộp", "Trọng lượng": "37 Kg", "Kích thước": "6834 × 750 × 914mm", "Căng lưới": "Bằng tay quay", "Bánh xe": "Có", "Lưới đi kèm": "Đã bao gồm"}'::jsonb, 'https://baoansport.vn/tru-luoi-pickleball/tru-luoi-pickleball-di-dong-xuki/'),
  ('tru-pickleball-di-dong-303901-p', 'BAS-1591', '303901-P', 'Trụ Pickleball di động 303901-P', 'Trụ Pickleball di động 303901-P được làm chắc chắn, có tay quay căng lưới và thiết kế giúp bóng lăn qua dễ dàng. Chính hãng Vifa Sport, giao hàng nhanh tại nhà.', 'Trụ Pickleball di động 303901-P được làm chắc chắn, có tay quay căng lưới và thiết kế giúp bóng lăn qua dễ dàng. Chính hãng Vifa Sport, giao hàng nhanh tại nhà.', 2950000, 'tru-luoi-pickleball', 22000, '{"Mã sản phẩm": "303901-P", "Màu sắc": "Đen", "Chất liệu": "Thép hộp", "Trọng lượng": "22 Kg", "Kích thước": "6790 × 700 × 914mm", "Căng lưới": "Bằng tay quay", "Bánh xe": "Không", "Lưới đi kèm": "Chưa bao gồm"}'::jsonb, 'https://baoansport.vn/tru-luoi-pickleball/tru-pickleball-di-dong-303901-p/'),
  ('tru-pickleball-thi-dau-303705-p', 'BAS-1590', '303705-P', 'Trụ Pickleball thi đấu 303705-P', 'Trụ Pickleball 303705-P thiết kế cố định, làm bằng thép sơn tĩnh điện, tích hợp tay quay căng lưới, đạt chuẩn thi đấu ngoài trời. Mua chính hãng ở Bảo An Sport.', 'Trụ Pickleball 303705-P thiết kế cố định, làm bằng thép sơn tĩnh điện, tích hợp tay quay căng lưới, đạt chuẩn thi đấu ngoài trời. Mua chính hãng ở Bảo An Sport.', 2430000, 'tru-luoi-pickleball', 18000, '{"Mã sản phẩm": "303705-P", "Màu sắc": "Đen", "Chất liệu": "Thép hộp", "Trọng lượng": "18 Kg", "Kích thước": "6860 × 80 × 914mm", "Căng lưới": "Bằng tay quay", "Bánh xe": "Không", "Lưới đi kèm": "Chưa bao gồm"}'::jsonb, 'https://baoansport.vn/tru-luoi-pickleball/tru-pickleball-thi-dau-303705-p/'),
  ('tru-pickleball-thi-dau-303704-p', 'BAS-1589', '303704-P', 'Trụ Pickleball thi đấu 303704-P', 'Trụ Pickleball thi đấu 303704-P thiết kế di động, làm từ thép mạ kẽm cao cấp, phù hợp cho sân thi đấu chuyên nghiệp. Chính hãng Vifa Sport, giá tốt, giao nhanh.', 'Trụ Pickleball thi đấu 303704-P thiết kế di động, làm từ thép mạ kẽm cao cấp, phù hợp cho sân thi đấu chuyên nghiệp. Chính hãng Vifa Sport, giá tốt, giao nhanh.', 5200000, 'tru-luoi-pickleball', 35000, '{"Mã sản phẩm": "303704-P", "Màu sắc": "Đen", "Chất liệu": "Thép hộp", "Trọng lượng": "35 Kg", "Kích thước": "6868 × 750 × 914 mm", "Căng lưới": "Bằng tay quay", "Bánh xe": "Có", "Lưới đi kèm": "Chưa bao gồm"}'::jsonb, 'https://baoansport.vn/tru-luoi-pickleball/tru-pickleball-thi-dau-303704-p/'),
  ('tru-pickleball-di-dong-303703p', 'BAS-1588', '303703‑P', 'Trụ Pickleball di động 303703‑P', 'Trụ Pickleball di động 303703‑P làm từ thép hộp sơn tĩnh điện, có kèm lưới, dễ lắp đặt và phù hợp luyện tập. Mua chính hãng ở Bảo An Sport - giao hàng toàn quốc.', 'Trụ Pickleball di động 303703‑P làm từ thép hộp sơn tĩnh điện, có kèm lưới, dễ lắp đặt và phù hợp luyện tập. Mua chính hãng ở Bảo An Sport - giao hàng toàn quốc.', 1500000, 'tru-luoi-pickleball', 6000, '{"Mã sản phẩm": "303703‑P", "Màu sắc": "Đen", "Chất liệu": "Thép hộp", "Trọng lượng": "6 Kg", "Kích thước": "4550 × 600 × 914mm", "Căng lưới": "Bằng tay", "Bánh xe": "Không có", "Lưới đi kèm": "Có"}'::jsonb, 'https://baoansport.vn/tru-luoi-pickleball/tru-pickleball-di-dong-303703p/'),
  ('tru-pickleball-303702-p', 'BAS-1587', '303702-P', 'Trụ Pickleball 303702-P', 'Trụ Pickleball 303702-P di động chính hãng Vifa Sport làm bằng thép hộp vuông 30×30 mm, dễ tháo lắp và di chuyển, phù hợp cho sân tập luyện hoặc sân phong trào.', 'Trụ Pickleball 303702-P di động chính hãng Vifa Sport làm bằng thép hộp vuông 30×30 mm, dễ tháo lắp và di chuyển, phù hợp cho sân tập luyện hoặc sân phong trào.', 2050000, 'tru-luoi-pickleball', 15000, '{"Mã sản phẩm": "303702-P", "Màu sắc": "Đen", "Chất liệu": "Thép hộp", "Trọng lượng": "15 Kg", "Kích thước": "6890 x 800 x 914mm", "Căng lưới": "Tay quay", "Bánh xe": "Không có", "Lưới đi kèm": "Chưa bao gồm"}'::jsonb, 'https://baoansport.vn/tru-luoi-pickleball/tru-pickleball-303702-p/'),
  ('tru-pickleball-di-dong-303701-p', 'BAS-1586', '303701-P', 'Trụ Pickleball di động 303701-P', 'Trụ Pickleball 303701‑P thiết kế dạng di động, sử dụng thép hộp 40×40 mm sơn tĩnh điện, dễ tháo lắp di chuyển. Phù hợp cho sân gia đình, trường học, khu dân cư.', 'Trụ Pickleball 303701‑P thiết kế dạng di động, sử dụng thép hộp 40×40 mm sơn tĩnh điện, dễ tháo lắp di chuyển. Phù hợp cho sân gia đình, trường học, khu dân cư.', 2950000, 'tru-luoi-pickleball', 20000, '{"Mã sản phẩm": "303701-P", "Màu sắc": "Đen", "Chất liệu": "Thép hộp", "Trọng lượng": "20 Kg", "Kích thước": "6780 x 700 x 914mm", "Căng lưới": "Tay quay", "Bánh xe": "Không có", "Lưới đi kèm": "Chưa bao gồm"}'::jsonb, 'https://baoansport.vn/tru-luoi-pickleball/tru-pickleball-di-dong-303701-p/'),
  ('giay-da-cau-de-kep-cao-cap', 'BAS-1585', 'GDCDK', 'Giày đá cầu đế kếp cao cấp', 'Mua giày đá cầu đế kếp cao cấp tại Bảo An Sport. Thiết kế hình mỏ vịt ôm chân, chất liệu da lộn, đế kếp bám sân tốt. Giao hàng nhanh, đổi trả trong 3 ngày.', 'Mua giày đá cầu đế kếp cao cấp tại Bảo An Sport. Thiết kế hình mỏ vịt ôm chân, chất liệu da lộn, đế kếp bám sân tốt. Giao hàng nhanh, đổi trả trong 3 ngày.', 650000, 'thiet-bi-day-hoc-the-duc', 0, '{"Mã sản phẩm": "GDCDK", "Màu sắc": "Đen", "Chất liệu": "Da lộn", "Loại đế": "Đế kếp", "Size": "39-44", "Trọng lượng": "750 gram"}'::jsonb, 'https://baoansport.vn/thiet-bi-day-hoc-the-duc/giay-da-cau-de-kep-cao-cap/'),
  ('xe-dap-tap-the-duc-tokado-tk-1000', 'BAS-1584', 'TK-1000', 'Xe đạp tập thể dục Tokado TK-1000', 'Xe đạp tập thể dục Tokado TK-1000 thuộc dòng xe liên hoàn, hỗ trợ vận động chân tay hiệu quả, phù hợp dùng cho người già, người tập phục hồi chức năng.', 'Xe đạp tập thể dục Tokado TK-1000 thuộc dòng xe liên hoàn, hỗ trợ vận động chân tay hiệu quả, phù hợp dùng cho người già, người tập phục hồi chức năng.', 3200000, 'xe-dap-tap-the-duc', 17000, '{"Mã sản phẩm": "TK-1000", "Màu sắc": "Xám - đen - cam", "Chất liệu": "Thép, nhựa", "Trọng lượng xe": "17kg", "Trọng lượng thùng": "19kg", "Tải trọng tối đa": "100kg", "Kích thước lắp đặt": "100 x 53 x 124cm", "Kích thước thùng": "91 x 18.5 x 61.5cm", "Yên xe": "Có", "Chuyển động": "Xích + bánh đà", "Kháng lực": "Nhiều mức", "Đo nhịp tim": "Có"}'::jsonb, 'https://baoansport.vn/xe-dap-tap-the-duc/xe-dap-tap-the-duc-tokado-tk-1000/'),
  ('gang-tay-boxing-bn', 'BAS-1377', 'GTBBN', 'Găng tay Boxing BN', 'Găng tay Boxing BN được thiết kế đẹp mắt, may chắc chắn từ da PU cao cấp, bên trong lót mouse hấp thụ lực và sử dụng công nghệ thoáng khí chống ướt.', 'Găng tay Boxing BN được thiết kế đẹp mắt, may chắc chắn từ da PU cao cấp, bên trong lót mouse hấp thụ lực và sử dụng công nghệ thoáng khí chống ướt.', 450000, 'gang-tay-boxing', 0, '{"Mã sản phẩm": "GTBBN", "Màu sắc": "Nhiều màu", "Chất liệu": "Da PU, EVA", "Trọng lượng": "10oz, 12oz", "Kích thước": "Đang cập nhật", "Kích thước đóng gói": "36 x 18 x 16 cm"}'::jsonb, 'https://baoansport.vn/gang-tay-boxing/gang-tay-boxing-bn/'),
  ('gia-de-ta-bowflex', 'BAS-1376', 'GDTB', 'Giá để tạ Bowflex', 'Giá để tạ Bowflex chính hãng được thiết kế chắc chắn, kích thước nhỏ gọn và có chức năng dùng để làm giá đỡ cho tạ tay Bowflex 552 hoặc Bowflex 1090.', 'Giá để tạ Bowflex chính hãng được thiết kế chắc chắn, kích thước nhỏ gọn và có chức năng dùng để làm giá đỡ cho tạ tay Bowflex 552 hoặc Bowflex 1090.', 2100000, 'ta-tay-ta-don', 15000, '{"Mã sản phẩm": "GDTB", "Màu sắc": "Xám", "Chất liệu": "Thép", "Trọng lượng": "15 kg", "Trọng lượng thùng": "17 kg", "Tải trọng tối đa": "150 kg", "Kích thước thùng": "56 x 56 x 12cm", "Kích thước lắp đặt": "66 x 55 x 58cm"}'::jsonb, 'https://baoansport.vn/ta-tay-ta-don/gia-de-ta-bowflex/'),
  ('ghe-day-ta-impulse-it7014', 'BAS-1379', 'IT7014', 'Ghế đẩy tạ Impulse IT7014', 'Ghế đẩy tạ Impulse IT7014 được thiết kế theo tiêu chuẩn châu Âu, hỗ trợ nằm đẩy tạ giúp tập cơ ngực hiệu quả và chuyên dùng để lắp cho các phòng Gym.', 'Ghế đẩy tạ Impulse IT7014 được thiết kế theo tiêu chuẩn châu Âu, hỗ trợ nằm đẩy tạ giúp tập cơ ngực hiệu quả và chuyên dùng để lắp cho các phòng Gym.', 13900000, 'thiet-bi-phong-gym', 82000, '{"Mã sản phẩm": "IT7014", "Màu sắc": "Xám bạc", "Chất liệu": "Thép, nệm da", "Trọng lượng ghế": "82 kg", "Tải trọng tối đa": "300 kg", "Kích thước lắp đặt": "165,7 x 165,8 x 137,3 cm"}'::jsonb, 'https://baoansport.vn/thiet-bi-phong-gym/ghe-day-ta-impulse-it7014/'),
  ('ghe-tap-dieu-chinh-impulse-it7011', 'BAS-1381', 'IT7011', 'Ghế tập điều chỉnh Impulse IT7011', 'Ghế tập điều chỉnh Impulse IT7011 được làm chắc chắn từ khung thép dày, yên ghế bọc nệm da cao cấp và chuyên dùng để lắp đặt cho các phòng tập Gym.', 'Ghế tập điều chỉnh Impulse IT7011 được làm chắc chắn từ khung thép dày, yên ghế bọc nệm da cao cấp và chuyên dùng để lắp đặt cho các phòng tập Gym.', 8500000, 'thiet-bi-phong-gym', 37000, '{"Mã sản phẩm": "IT7011", "Màu sắc": "Xám bạc", "Chất liệu": "Thép, nệm da", "Trọng lượng ghế": "37 kg", "Tải trọng tối đa": "180 kg", "Kích thước lắp đặt": "1212 x 750 x 465 mm"}'::jsonb, 'https://baoansport.vn/thiet-bi-phong-gym/ghe-tap-dieu-chinh-impulse-it7011/'),
