  ('xa-don-vifa-sport-vifa-711213', 'BAS-1374', 'VIFA-711213', 'Xà đơn Vifa Sport VIFA-711213', 'Xà đơn Vifa Sport VIFA-711213 được sản xuất bởi thương hiệu Việt Pháp, hỗ trợ ba người tập cùng lúc và chuyên dùng để lắp đặt cho công viên ngoài trời.', 'Xà đơn Vifa Sport VIFA-711213 được sản xuất bởi thương hiệu Việt Pháp, hỗ trợ ba người tập cùng lúc và chuyên dùng để lắp đặt cho công viên ngoài trời.', 16000000, 'dung-cu-the-thao-ngoai-troi', 61000, '{"Mã sản phẩm": "VIFA-711213", "Màu sắc": "Xanh - xám", "Chất liệu": "Thép, nhựa", "Trọng lượng máy": "61 kg", "Tải trọng tối đa": "180 kg", "Diện tích phù hợp": "2400 x 2400mm", "Kích thước lắp đặt": "1820 x 1820 x 2280mm (±3%)"}'::jsonb, 'https://baoansport.vn/dung-cu-the-thao-ngoai-troi/xa-don-vifa-sport-vifa-711213/'),
  ('ghe-tap-bung-impulse-it7013', 'BAS-1380', 'IT7013', 'Ghế tập bụng Impulse IT7013', 'Ghế tập bụng Impulse IT7013 thiết kế chắc chắn, hỗ trợ gập bụng hiệu quả và an toàn cho cột sống. Mua tại Bảo An Sport cam kết chính hãng, giá tốt nhất.', 'Ghế tập bụng Impulse IT7013 thiết kế chắc chắn, hỗ trợ gập bụng hiệu quả và an toàn cho cột sống. Mua tại Bảo An Sport cam kết chính hãng, giá tốt nhất.', 9600000, 'thiet-bi-phong-gym', 42500, '{"Mã sản phẩm": "IT7013", "Màu sắc": "Xám bạc", "Chất liệu": "Thép, nệm da", "Trọng lượng ghế": "42,5 kg", "Tải trọng tối đa": "300 kg", "Kích thước lắp đặt": "1738 x 725 x 899 mm"}'::jsonb, 'https://baoansport.vn/thiet-bi-phong-gym/ghe-tap-bung-impulse-it7013/'),
