  ('xa-kep-vifa-sport-vifa-711222', 'BAS-1373', 'VIFA-711222', 'Xà kép Vifa Sport VIFA-711222', 'Xà kép Vifa Sport VIFA-711222 được sản xuất bởi thương hiệu Việt Pháp, hỗ trợ hai người cùng tập một lúc và phù hợp dùng để lắp cho công viên ngoài trời.', 'Xà kép Vifa Sport VIFA-711222 được sản xuất bởi thương hiệu Việt Pháp, hỗ trợ hai người cùng tập một lúc và phù hợp dùng để lắp cho công viên ngoài trời.', 12500000, 'dung-cu-the-thao-ngoai-troi', 62000, '{"Mã sản phẩm": "VIFA-711222", "Màu sắc": "Xanh - xám", "Chất liệu": "Thép, nhựa", "Trọng lượng máy": "62 kg", "Tải trọng tối đa": "180 kg", "Diện tích phù hợp": "1200 x 2800mm", "Kích thước lắp đặt": "2020 x 640 x 1430mm (±3%)"}'::jsonb, 'https://baoansport.vn/dung-cu-the-thao-ngoai-troi/xa-kep-vifa-sport-vifa-711222/'),
  ('may-tap-xoay-eo-vifa-sport-vifa-711333', 'BAS-1371', 'VIFA-711333', 'Máy tập xoay eo Vifa Sport VIFA-711333', 'Máy tập xoay eo Vifa Sport VIFA-711333 được sản xuất bởi thương hiệu Việt Pháp, hỗ trợ ba người tập cùng lúc và phù hợp dùng để lắp đặt cho công viên.', 'Máy tập xoay eo Vifa Sport VIFA-711333 được sản xuất bởi thương hiệu Việt Pháp, hỗ trợ ba người tập cùng lúc và phù hợp dùng để lắp đặt cho công viên.', 20000000, 'dung-cu-the-thao-ngoai-troi', 47000, '{"Mã sản phẩm": "VIFA-711333", "Màu sắc": "Xanh - xám", "Chất liệu": "Thép, nhựa", "Trọng lượng máy": "47 kg", "Tải trọng tối đa": "180 kg", "Diện tích phù hợp": "Đường kính 2.1m", "Kích thước lắp đặt": "1580 x 1300mm (±3%)"}'::jsonb, 'https://baoansport.vn/dung-cu-the-thao-ngoai-troi/may-tap-xoay-eo-vifa-sport-vifa-711333/'),
  ('dich-do-ban-tay-bn', 'BAS-1356', 'DDBTBN', 'Đích đỡ bàn tay BN', 'Đích đỡ bàn tay BN chính hãng được thiết kế đẹp mắt, có khả năng chịu lực đánh mạnh khi tập luyện và phù hợp sử dụng để rèn luyện các bộ môn võ thuật.', 'Đích đỡ bàn tay BN chính hãng được thiết kế đẹp mắt, có khả năng chịu lực đánh mạnh khi tập luyện và phù hợp sử dụng để rèn luyện các bộ môn võ thuật.', 350000, 'dich-dam-dich-da', 0, '{"Mã sản phẩm": "DDBTBN", "Màu sắc": "Nhiều màu", "Chất liệu": "PU, mút xốp", "Kích thước": "25 x 18.5 x 4 cm", "Trọng lượng": "600 gram"}'::jsonb, 'https://baoansport.vn/dich-dam-dich-da/dich-do-ban-tay-bn/'),
  ('dich-da-cao-cap-bn', 'BAS-1357', 'DDCCBN', 'Đích đá cao cấp BN', 'Đích đá cao cấp BN được thiết kế đẹp mắt, có chức năng rèn luyện kỹ thuật đấm đá và phù hợp dùng để tập nhiều môn võ như Boxing, MMA, Muay Thái,...', 'Đích đá cao cấp BN được thiết kế đẹp mắt, có chức năng rèn luyện kỹ thuật đấm đá và phù hợp dùng để tập nhiều môn võ như Boxing, MMA, Muay Thái,...', 650000, 'dich-dam-dich-da', 0, '{"Mã sản phẩm": "DDCCBN", "Màu sắc": "Nhiều màu", "Chất liệu": "PU Leather, EVA Foam, Recycle Cotton và PE Foam", "Kích thước": "35 x 21 x 8 cm", "Trọng lượng": "800 gram"}'::jsonb, 'https://baoansport.vn/dich-dam-dich-da/dich-da-cao-cap-bn/'),
  ('may-tap-cheo-thuyen-vifa-sport-vifa-711602', 'BAS-1358', 'VIFA-711602', 'Máy tập chèo thuyền Vifa Sport VIFA-711602', 'Máy tập chèo thuyền Vifa Sport VIFA-711602 được thiết kế chắc chắn, hỗ trợ các bài tập vận động toàn thân hiệu quả và phù hợp để lắp đặt cho công viên.', 'Máy tập chèo thuyền Vifa Sport VIFA-711602 được thiết kế chắc chắn, hỗ trợ các bài tập vận động toàn thân hiệu quả và phù hợp để lắp đặt cho công viên.', 20000000, 'dung-cu-the-thao-ngoai-troi', 0, '{"Mã sản phẩm": "VIFA-711602", "Màu sắc": "Xanh - xám", "Chất liệu": "Thép, nhựa", "Trọng lượng máy": "Đang cập nhật", "Tải trọng tối đa": "180 kg", "Diện tích phù hợp": "1500 x 2200mm", "Kích thước lắp đặt": "1310 x 790 x 1030mm (±3%)"}'::jsonb, 'https://baoansport.vn/dung-cu-the-thao-ngoai-troi/may-tap-cheo-thuyen-vifa-sport-vifa-711602/'),
  ('giap-bung-cao-cap-bn', 'BAS-1360', 'GBBN', 'Giáp bụng cao cấp BN', 'Giáp bụng cao cấp BN được may chắc chắn từ chất liệu da PU, bên trong đệm xốp EVA dày dặn và có chức năng bảo vệ bụng khi tập luyện, thi đấu võ thuật.', 'Giáp bụng cao cấp BN được may chắc chắn từ chất liệu da PU, bên trong đệm xốp EVA dày dặn và có chức năng bảo vệ bụng khi tập luyện, thi đấu võ thuật.', 1150000, 'mu-ao-giap-vo-thuat', 1000, '{"Mã sản phẩm": "GBBN", "Màu sắc": "Cà phê, xám", "Chất liệu": "Da PU, EVA", "Trọng lượng": "1kg", "Size": "Free size"}'::jsonb, 'https://baoansport.vn/mu-ao-giap-vo-thuat/giap-bung-cao-cap-bn/'),
  ('giap-chan-bn', 'BAS-1361', 'GCBN', 'Giáp chân BN', 'Giáp chân BN được may chắc chắn từ chất liệu da PU cao cấp, trong lõi đệm bằng EVA Form và có tác dụng giúp bảo vệ ống chân, bàn chân khi thi đấu võ.', 'Giáp chân BN được may chắc chắn từ chất liệu da PU cao cấp, trong lõi đệm bằng EVA Form và có tác dụng giúp bảo vệ ống chân, bàn chân khi thi đấu võ.', 520000, 'mu-ao-giap-vo-thuat', 0, '{"Mã sản phẩm": "GCBN", "Màu sắc": "Cam, đỏ, trắng, xanh", "Chất liệu": "Da PU, EVA", "Trọng lượng": "500 gram", "Size": "M, L"}'::jsonb, 'https://baoansport.vn/mu-ao-giap-vo-thuat/giap-chan-bn/'),
  ('bao-ho-ha-bo-kuki-bn', 'BAS-1362', 'Kuki-BN', 'Bảo hộ hạ bộ Kuki BN', 'Bảo hộ hạ bộ Kuki BN được may chắc chắn bằng chất liệu da PU, bên trong lót EVA dày dặn và có chức năng bảo vệ hạ bộ khi tập luyện, thi đấu đối kháng.', 'Bảo hộ hạ bộ Kuki BN được may chắc chắn bằng chất liệu da PU, bên trong lót EVA dày dặn và có chức năng bảo vệ hạ bộ khi tập luyện, thi đấu đối kháng.', 350000, 'mu-ao-giap-vo-thuat', 0, '{"Mã sản phẩm": "Kuki-BN", "Màu sắc": "Đen, đỏ", "Chất liệu": "Da PU, EVA", "Trọng lượng": "300 gram", "Size": "S, L"}'::jsonb, 'https://baoansport.vn/mu-ao-giap-vo-thuat/bao-ho-ha-bo-kuki-bn/'),
  ('giap-dui-bn', 'BAS-1363', 'GDBN', 'Giáp đùi BN', 'Giáp đùi BN được thiết kế đẹp mắt, may chắc chắn từ chất liệu da PU và bên trong đệm EVA Foam, Recycle Cotton kết hợp với PE Foam chất lượng cao.', 'Giáp đùi BN được thiết kế đẹp mắt, may chắc chắn từ chất liệu da PU và bên trong đệm EVA Foam, Recycle Cotton kết hợp với PE Foam chất lượng cao.', 1450000, 'mu-ao-giap-vo-thuat', 0, '{"Mã sản phẩm": "GDBN", "Màu sắc": "Cam + đen, xanh + đen", "Chất liệu": "Da PU, EVA Foam, Recycle Cotton, PE Foam", "Trọng lượng": "1500 gram", "Size": "Free size"}'::jsonb, 'https://baoansport.vn/mu-ao-giap-vo-thuat/giap-dui-bn/'),
  ('thiet-bi-tap-toan-than-vifa-sport-vifa-711601', 'BAS-1364', 'VIFA-711601', 'Thiết bị tập toàn thân Vifa Sport VIFA-711601', 'Thiết bị tập toàn thân Vifa Sport VIFA-711601 được thiết kế hoàn toàn từ khung thép dày, sơn tĩnh điện cao cấp và phù hợp với điều kiện khí hậu Việt Nam.', 'Thiết bị tập toàn thân Vifa Sport VIFA-711601 được thiết kế hoàn toàn từ khung thép dày, sơn tĩnh điện cao cấp và phù hợp với điều kiện khí hậu Việt Nam.', 13800000, 'dung-cu-the-thao-ngoai-troi', 0, '{"Mã sản phẩm": "VIFA-711601", "Màu sắc": "Xanh - xám", "Chất liệu": "Thép, nhựa", "Trọng lượng máy": "Đang cập nhật", "Tải trọng tối đa": "180 kg", "Diện tích phù hợp": "1500 x 2000mm", "Kích thước lắp đặt": "1130 x 610 x 1320 mm (±3%)"}'::jsonb, 'https://baoansport.vn/dung-cu-the-thao-ngoai-troi/thiet-bi-tap-toan-than-vifa-sport-vifa-711601/'),
  ('xe-dap-tap-vifa-sport-vifa-711531', 'BAS-1365', 'VIFA-711531', 'Xe đạp tập Vifa Sport VIFA-711531', 'Xe đạp tập Vifa Sport VIFA-711531 được thiết kế chắc chắn, hỗ trợ tập thể lực hiệu quả và chuyên dùng để lắp cho công viên hay sân tập thể thao ngoài trời.', 'Xe đạp tập Vifa Sport VIFA-711531 được thiết kế chắc chắn, hỗ trợ tập thể lực hiệu quả và chuyên dùng để lắp cho công viên hay sân tập thể thao ngoài trời.', 17000000, 'dung-cu-the-thao-ngoai-troi', 53000, '{"Mã sản phẩm": "VIFA-711531", "Màu sắc": "Xanh - xám", "Chất liệu": "Thép, nhựa", "Trọng lượng máy": "53kg", "Tải trọng tối đa": "180 kg", "Diện tích phù hợp": "1200 x 1600mm", "Kích thước lắp đặt": "1060 x 660 x 1060mm (±3%)"}'::jsonb, 'https://baoansport.vn/dung-cu-the-thao-ngoai-troi/xe-dap-tap-vifa-sport-vifa-711531/'),
  ('xe-dap-tap-vifa-sport-vifa-711521', 'BAS-1366', 'VIFA-711521', 'Xe đạp tập Vifa Sport VIFA-711521', 'Xe đạp tập Vifa Sport VIFA-711521 chính hãng được thiết kế chắc chắn, hỗ trợ tập luyện sức khỏe hiệu quả và phù hợp để lắp đặt cho công viên ngoài trời.', 'Xe đạp tập Vifa Sport VIFA-711521 chính hãng được thiết kế chắc chắn, hỗ trợ tập luyện sức khỏe hiệu quả và phù hợp để lắp đặt cho công viên ngoài trời.', 15000000, 'dung-cu-the-thao-ngoai-troi', 45000, '{"Mã sản phẩm": "VIFA-711521", "Màu sắc": "Xanh - xám", "Chất liệu": "Thép, nhựa", "Trọng lượng máy": "45 kg", "Tải trọng tối đa": "180 kg", "Diện tích phù hợp": "1100 x 1700mm", "Kích thước lắp đặt": "1000 x 540 x 1170mm (±3%)"}'::jsonb, 'https://baoansport.vn/dung-cu-the-thao-ngoai-troi/xe-dap-tap-vifa-sport-vifa-711521/'),
  ('may-di-bo-lac-tay-vifa-sport-vifa-711511', 'BAS-1367', 'VIFA-711511', 'Máy đi bộ lắc tay Vifa Sport VIFA-711511', 'Máy đi bộ lắc tay Vifa Sport VIFA-711511 chính hãng được chế tạo hoàn toàn bằng thép dày, sơn tĩnh điện cao cấp và hỗ trợ tập vận động toàn thân hiệu quả.', 'Máy đi bộ lắc tay Vifa Sport VIFA-711511 chính hãng được chế tạo hoàn toàn bằng thép dày, sơn tĩnh điện cao cấp và hỗ trợ tập vận động toàn thân hiệu quả.', 20400000, 'dung-cu-the-thao-ngoai-troi', 45000, '{"Mã sản phẩm": "VIFA-711511", "Màu sắc": "Xanh - xám", "Chất liệu": "Thép, nhựa", "Trọng lượng máy": "45 kg", "Tải trọng tối đa": "180 kg", "Diện tích phù hợp": "1100 x 2200mm", "Kích thước lắp đặt": "1210 x 620 x 1430mm (±3%)"}'::jsonb, 'https://baoansport.vn/dung-cu-the-thao-ngoai-troi/may-di-bo-lac-tay-vifa-sport-vifa-711511/'),
  ('may-di-bo-tren-khong-vifa-sport-vifa-711411', 'BAS-1368', 'VIFA-711411', 'Máy đi bộ trên không Vifa Sport VIFA-711411', 'Máy đi bộ trên không Vifa Sport VIFA-711411 được chế tạo từ thép sơn tĩnh điện, phù hợp với khí hậu ở Việt Nam và chuyên dùng để lắp đặt cho công viên.', 'Máy đi bộ trên không Vifa Sport VIFA-711411 được chế tạo từ thép sơn tĩnh điện, phù hợp với khí hậu ở Việt Nam và chuyên dùng để lắp đặt cho công viên.', 15500000, 'dung-cu-the-thao-ngoai-troi', 47000, '{"Mã sản phẩm": "VIFA-711411", "Màu sắc": "Xanh - xám", "Chất liệu": "Thép, nhựa", "Trọng lượng máy": "47 kg", "Tải trọng tối đa": "180 kg", "Diện tích phù hợp": "1600 x 2000mm", "Kích thước lắp đặt": "1060 x 520 x 1480mm (±3%)"}'::jsonb, 'https://baoansport.vn/dung-cu-the-thao-ngoai-troi/may-di-bo-tren-khong-vifa-sport-vifa-711411/'),
  ('thiet-bi-tap-dap-chan-vifa-sport-vifa-711412', 'BAS-1369', 'VIFA-711412', 'Thiết bị tập đạp chân Vifa Sport VIFA-711412', 'Thiết bị tập đạp chân Vifa Sport VIFA-711412 được thiết kế chắc chắn, hỗ trợ 2 người tập cùng lúc và chuyên dùng để lắp đặt cho các công viên ngoài trời.', 'Thiết bị tập đạp chân Vifa Sport VIFA-711412 được thiết kế chắc chắn, hỗ trợ 2 người tập cùng lúc và chuyên dùng để lắp đặt cho các công viên ngoài trời.', 17000000, 'dung-cu-the-thao-ngoai-troi', 74000, '{"Mã sản phẩm": "VIFA-711412", "Màu sắc": "Xanh - xám", "Chất liệu": "Thép, nhựa", "Trọng lượng máy": "74 kg", "Tải trọng tối đa": "180 kg", "Diện tích phù hợp": "1000 x 3000mm", "Kích thước lắp đặt": "1860 x 450 x 1490mm (±3%)"}'::jsonb, 'https://baoansport.vn/dung-cu-the-thao-ngoai-troi/thiet-bi-tap-dap-chan-vifa-sport-vifa-711412/'),
  ('dung-cu-tap-lung-eo-vifa-sport-vifa-711322', 'BAS-1370', 'VIFA-711322', 'Dụng cụ tập lưng eo Vifa Sport VIFA-711322', 'Dụng cụ tập lưng eo Vifa Sport VIFA-711322 được sản xuất theo tiêu chuẩn châu Âu, hỗ trợ 2 người tập cùng lúc và phù hợp dùng để lắp đặt cho công viên.', 'Dụng cụ tập lưng eo Vifa Sport VIFA-711322 được sản xuất theo tiêu chuẩn châu Âu, hỗ trợ 2 người tập cùng lúc và phù hợp dùng để lắp đặt cho công viên.', 18500000, 'dung-cu-the-thao-ngoai-troi', 52000, '{"Mã sản phẩm": "VIFA-711322", "Màu sắc": "Xanh - xám", "Chất liệu": "Thép, nhựa", "Trọng lượng máy": "52 kg", "Tải trọng tối đa": "180 kg", "Diện tích phù hợp": "1800 x 2000mm", "Kích thước lắp đặt": "1200 x 790 x 1260mm (±3%)"}'::jsonb, 'https://baoansport.vn/dung-cu-the-thao-ngoai-troi/dung-cu-tap-lung-eo-vifa-sport-vifa-711322/'),
  ('dung-cu-tap-tay-vai-doi-vifa-sport-vifa-711142', 'BAS-1355', 'VIFA-711142', 'Dụng cụ tập tay vai đôi Vifa Sport VIFA-711142', 'Dụng cụ tập tay vai đôi Vifa Sport VIFA-711142 được thiết kế từ thép sơn tĩnh điện, phù hợp với khí hậu Việt Nam và chuyên dùng để lắp đặt cho công viên.', 'Dụng cụ tập tay vai đôi Vifa Sport VIFA-711142 được thiết kế từ thép sơn tĩnh điện, phù hợp với khí hậu Việt Nam và chuyên dùng để lắp đặt cho công viên.', 16400000, 'dung-cu-the-thao-ngoai-troi', 0, '{"Mã sản phẩm": "VIFA-711142", "Màu sắc": "Xanh - xám", "Chất liệu": "Thép, nhựa", "Trọng lượng máy": "Đang cập nhật", "Tải trọng tối đa": "180 kg", "Diện tích phù hợp": "1600 x 2000mm", "Kích thước lắp đặt": "1400 x 1040 x 1500mm (±3%)"}'::jsonb, 'https://baoansport.vn/dung-cu-the-thao-ngoai-troi/dung-cu-tap-tay-vai-doi-vifa-sport-vifa-711142/'),
  ('khung-tap-xa-kep-ke-bung-impulse-it7010', 'BAS-1382', 'IT7010', 'Khung tập xà kép, ke bụng Impulse IT7010', 'Khung tập xà kép, ke bụng Impulse IT7010 được thiết kế chắc chắn, có khả năng chịu tải trọng người tập lớn và chuyên dùng để lắp đặt cho các phòng Gym.', 'Khung tập xà kép, ke bụng Impulse IT7010 được thiết kế chắc chắn, có khả năng chịu tải trọng người tập lớn và chuyên dùng để lắp đặt cho các phòng Gym.', 10500000, 'thiet-bi-phong-gym', 0, '{"Mã sản phẩm": "IT7010", "Màu sắc": "Xám bạc", "Chất liệu": "Thép, nệm da", "Trọng lượng khung": "53 kg", "Tải trọng tối đa": "180 kg", "Kích thước lắp đặt": "1120 x 780 x 1550 mm"}'::jsonb, 'https://baoansport.vn/thiet-bi-phong-gym/khung-tap-xa-kep-ke-bung-impulse-it7010/'),
  ('ghe-bang-tap-ta-impulse-it7009', 'BAS-1383', 'IT7009', 'Ghế băng tập tạ Impulse IT7009', 'Ghế băng tập tạ Impulse IT7009 được thiết kế chắc chắn, yên ghế bọc da cao cấp và có chức năng dùng tập khởi động hoặc thực hiện các bài tập với tạ tay.', 'Ghế băng tập tạ Impulse IT7009 được thiết kế chắc chắn, yên ghế bọc da cao cấp và có chức năng dùng tập khởi động hoặc thực hiện các bài tập với tạ tay.', 6600000, 'thiet-bi-phong-gym', 27500, '{"Mã sản phẩm": "IT7009", "Màu sắc": "Xám bạc", "Chất liệu": "Thép, nệm da", "Trọng lượng ghế": "27,5 kg", "Tải trọng tối đa": "180 kg", "Kích thước lắp đặt": "1200 x 749 x 426 mm"}'::jsonb, 'https://baoansport.vn/thiet-bi-phong-gym/ghe-bang-tap-ta-impulse-it7009/'),
  ('don-ta-2m2-phi-50', 'BAS-1406', 'DT2M2P50', 'Đòn tạ 2m2 phi 50', 'Đòn tạ 2m2 phi 50 nhập khẩu thiết kế đạt tiêu chuẩn Olympic, chuyên dùng đẩy tạ hoặc gánh tạ và phù hợp sử dụng cho các phòng tập Gym chuyên nghiệp.', 'Đòn tạ 2m2 phi 50 nhập khẩu thiết kế đạt tiêu chuẩn Olympic, chuyên dùng đẩy tạ hoặc gánh tạ và phù hợp sử dụng cho các phòng tập Gym chuyên nghiệp.', 1200000, 'ta-tay-ta-don', 20000, '{"Mã sản phẩm": "DT2M2P50", "Màu sắc": "Xám bạc", "Chất liệu": "Thép", "Chiều dài": "2m2", "Trọng lượng": "20 kg", "Tải trọng tối đa": "300 kg", "Kẹp tạ": "Có"}'::jsonb, 'https://baoansport.vn/ta-tay-ta-don/don-ta-2m2-phi-50/'),
  ('hop-cau-long-vina-star', 'BAS-1407', 'HCLVS', 'Hộp cầu lông Vina Star', 'Hộp cầu lông Vina Star chính hãng được sản xuất tại Việt Nam, gồm 12 quả cầu đạt chuẩn thi đấu chuyên nghiệp và phù hợp để chơi trong nhà lẫn ngoài trời.', 'Hộp cầu lông Vina Star chính hãng được sản xuất tại Việt Nam, gồm 12 quả cầu đạt chuẩn thi đấu chuyên nghiệp và phù hợp để chơi trong nhà lẫn ngoài trời.', 340000, 'qua-cau-long', 0, '{"Mã sản phẩm": "HCLVS", "Màu sắc": "Trắng sứ", "Chất liệu": "Xốp, lông vũ", "Quy cách đóng hộp": "12 quả"}'::jsonb, 'https://baoansport.vn/qua-cau-long/hop-cau-long-vina-star/'),
  ('bong-yoga-adidas-adbl-14246or', 'BAS-1409', '14246OR', 'Bóng tập Yoga Adidas ADBL 14246OR', 'Bóng tập Yoga Adidas ADBL 14246OR chính hãng làm từ chất liệu cao su cao cấp, có độ đàn hồi cao và khả năng chống nổ tuyệt đối khi sử dụng tập luyện.', 'Bóng tập Yoga Adidas ADBL 14246OR chính hãng làm từ chất liệu cao su cao cấp, có độ đàn hồi cao và khả năng chống nổ tuyệt đối khi sử dụng tập luyện.', 1150000, 'bong-tap-yoga', 1000, '{"Mã sản phẩm": "14246OR", "Màu sắc": "Cam đỏ - đen", "Chất liệu": "Cao su", "Đường kính": "65cm", "Trọng lượng": "1 kg", "Tải trọng tối đa": "110 kg", "Kích thước hộp": "40 x 30 x 20cm"}'::jsonb, 'https://baoansport.vn/bong-tap-yoga/bong-yoga-adidas-adbl-14246or/'),
  ('khung-ganh-ta-da-nang-k1', 'BAS-1410', 'K1', 'Khung gánh tạ đa năng K1', 'Khung gánh tạ đa năng K1 được thiết kế chắc chắn, trang bị trên 30 bài tập hiệu quả cho các nhóm cơ và phù hợp sử dụng để tập luyện tại nhà cho Gymer.', 'Khung gánh tạ đa năng K1 được thiết kế chắc chắn, trang bị trên 30 bài tập hiệu quả cho các nhóm cơ và phù hợp sử dụng để tập luyện tại nhà cho Gymer.', 15500000, 'gian-ta-da-nang', 194000, '{"Mã sản phẩm": "K1", "Màu sắc": "Đen cam", "Chất liệu": "Thép, nệm da", "Trọng lượng tạ": "33 kg", "Trọng lượng cả bộ": "194 kg", "Tải trọng tối đa": "300 kg", "Diện tích lắp đặt": "220 x 150 x 220 cm", "Kích thước thùng": "5 kiện"}'::jsonb, 'https://baoansport.vn/gian-ta-da-nang/khung-ganh-ta-da-nang-k1/'),
  ('gia-de-ta-chu-a-10-doi', 'BAS-1411', 'GDT10D', 'Giá để tạ chữ A 10 đôi', 'Giá để tạ chữ A 10 đôi được thiết kế chắc chắn từ thép hộp dày, sơn tĩnh điện chống rỉ, có khả năng chịu lực cực tốt và có chức năng dùng để xếp gọn tạ tay.', 'Giá để tạ chữ A 10 đôi được thiết kế chắc chắn từ thép hộp dày, sơn tĩnh điện chống rỉ, có khả năng chịu lực cực tốt và có chức năng dùng để xếp gọn tạ tay.', 2500000, 'ta-tay-ta-don', 0, '{"Mã sản phẩm": "GDT10D", "Màu sắc": "Đen", "Chất liệu": "Thép, nhựa", "Trọng lượng giá": "10 kg", "Tải trọng tối đa": "200 kg", "Kích thước lắp đặt": "59 x 39 x 126cm", "Kích thước thùng": "Đang cập nhật"}'::jsonb, 'https://baoansport.vn/ta-tay-ta-don/gia-de-ta-chu-a-10-doi/'),
  ('xa-don-xa-kep-da-nang-mk-680', 'BAS-1413', 'MK-680', 'Xà đơn xà kép đa năng MK-680', 'Xà đơn xà kép đa năng MK-680 chính hãng Miking được thiết kế chắc chắn, hỗ trợ nhiều bài tập thể hình hiệu quả, phù hợp sử dụng để tập luyện cho Gymer.', 'Xà đơn xà kép đa năng MK-680 chính hãng Miking được thiết kế chắc chắn, hỗ trợ nhiều bài tập thể hình hiệu quả, phù hợp sử dụng để tập luyện cho Gymer.', 4500000, 'xa-don-xa-kep', 40000, '{"Mã sản phẩm": "MK-680", "Màu sắc": "Vàng đen", "Chất liệu": "Thép, nhựa, mút da", "Trọng lượng xà": "38 kg", "Trọng lượng thùng": "40 kg", "Tải trọng tối đa": "180 kg", "Kích thước lắp đặt": "103 x 104 x 208 cm", "Kích thước thùng": "105 x 38 x 15cm và 115 x 38 x 20cm"}'::jsonb, 'https://baoansport.vn/xa-don-xa-kep/xa-don-xa-kep-da-nang-mk-680/'),
  ('xa-don-xa-kep-da-nang-ex-30', 'BAS-1414', 'EX30', 'Xà đơn xà kép đa năng EX30', 'Xà đơn xà kép đa năng EX30 được thiết kế chắc chắn từ khung thép dày, tải trọng tối đa lên đến 100kg và độ cao điều chỉnh dễ dàng từ 170cm đến 240cm.', 'Xà đơn xà kép đa năng EX30 được thiết kế chắc chắn từ khung thép dày, tải trọng tối đa lên đến 100kg và độ cao điều chỉnh dễ dàng từ 170cm đến 240cm.', 2950000, 'xa-don-xa-kep', 24000, '{"Mã sản phẩm": "EX30", "Màu sắc": "Vàng đen", "Chất liệu": "Thép, nhựa, mút da", "Trọng lượng xà": "23 kg", "Trọng lượng thùng": "24 kg", "Tải trọng tối đa": "100 kg", "Độ rộng xà kép": "52 cm", "Độ rộng xà đơn": "95 cm", "Độ cao xà kép": "126 cm", "Kích thước lắp đặt": "100 x 82 x 240cm", "Kích thước thùng": "138 x 81 x 11cm"}'::jsonb, 'https://baoansport.vn/xa-don-xa-kep/xa-don-xa-kep-da-nang-ex-30/'),
  ('vong-lac-eo-bang-ong-thep', 'BAS-1415', 'VLEOT', 'Vòng lắc eo bằng ống thép', 'Vòng lắc eo bằng ống thép được thiết kế thông minh, có thể tháo rời dễ dàng sau khi sử dụng xong và phù hợp dùng cho bài tập lắc vòng tại nhà cho cá nhân.', 'Vòng lắc eo bằng ống thép được thiết kế thông minh, có thể tháo rời dễ dàng sau khi sử dụng xong và phù hợp dùng cho bài tập lắc vòng tại nhà cho cá nhân.', 275000, 'phu-kien-tap-gym', 0, '{"Mã sản phẩm": "VLEOT", "Màu sắc": "Hồng xanh", "Chất liệu": "Thép, mút xốp", "Trọng lượng vòng": "1 kg", "Trọng lượng cả hộp": "1.4 kg", "Đường kính vòng": "95 cm", "Số mảnh ghép": "6", "Kích thước hộp": "50 x 18 x 8cm"}'::jsonb, 'https://baoansport.vn/phu-kien-tap-gym/vong-lac-eo-bang-ong-thep/'),
  ('qua-bong-ban-729-3-sao-40', 'BAS-1418', 'QBB729', 'Quả bóng bàn 729 3 sao 40+', 'Quả bóng bàn 729 3 sao 40+ chính hãng được làm từ chất liệu cao cấp, sử dụng công nghệ mới không mối nối, tròn đều và cho độ nảy cực chuẩn khi đánh.', 'Quả bóng bàn 729 3 sao 40+ chính hãng được làm từ chất liệu cao cấp, sử dụng công nghệ mới không mối nối, tròn đều và cho độ nảy cực chuẩn khi đánh.', 150000, 'qua-bong-ban', 0, '{"Mã sản phẩm": "QBB729", "Màu sắc": "Trắng", "Chất liệu": "Nhựa dẻo", "Đường kính": "40mm", "Trọng lượng bóng": "~2,8 gram", "Trọng lượng hộp": "20 gram", "Kích thước hộp": "12 x 9 x 4.5cm", "Quy cách đóng hộp": "6 quả"}'::jsonb, 'https://baoansport.vn/qua-bong-ban/qua-bong-ban-729-3-sao-40/'),
  ('qua-bong-ban-xiom-v-40', 'BAS-1419', 'V-40+', 'Quả bóng bàn Xiom V 40+', 'Quả bóng bàn Xiom V 40+ được sản xuất từ chất liệu nhựa cao cấp, sử dụng công nghệ mới không mối hàn nối, quả bóng tròn đều và cho độ nảy cực chuẩn.', 'Quả bóng bàn Xiom V 40+ được sản xuất từ chất liệu nhựa cao cấp, sử dụng công nghệ mới không mối hàn nối, quả bóng tròn đều và cho độ nảy cực chuẩn.', 150000, 'qua-bong-ban', 0, '{"Mã sản phẩm": "V-40+", "Màu sắc": "Trắng", "Chất liệu": "Nhựa dẻo", "Đường kính": "40 - 40.6mm", "Trọng lượng bóng": "2.67 - 2.77gram", "Trọng lượng hộp": "25 gram", "Kích thước hộp": "12 x 8.5 x 4.5cm", "Quy cách đóng hộp": "6 quả"}'::jsonb, 'https://baoansport.vn/qua-bong-ban/qua-bong-ban-xiom-v-40/'),
  ('xe-dap-tap-the-duc-tokado-tk800', 'BAS-1422', 'TK800', 'Xe đạp tập thể dục Tokado TK800', 'Xe đạp tập thể dục Tokado TK800 chính hãng được thiết kế đẹp mắt, khung máy chắc chắn, vận hành êm ái và hỗ trợ tập vận động cả chân lẫn tay hiệu quả.', 'Xe đạp tập thể dục Tokado TK800 chính hãng được thiết kế đẹp mắt, khung máy chắc chắn, vận hành êm ái và hỗ trợ tập vận động cả chân lẫn tay hiệu quả.', 3600000, 'xe-dap-tap-the-duc', 17500, '{"Mã sản phẩm": "TK800", "Màu sắc": "Cam - xám - đen", "Chất liệu": "Thép, nhựa", "Trọng lượng xe": "17.5 kg", "Trọng lượng đóng thùng": "19.5 kg", "Tải trọng tối đa": "110 kg", "Đường kính bánh đà": "48 cm", "Kích thước lắp đặt": "100 x 60 x 114 cm", "Kích thước thùng": "93 x 20,5 x 66 cm", "Yên xe": "Có", "Chuyển động": "Xích + bánh đà", "Kháng lực": "Nhiều mức", "Đo nhịp tim": "Có"}'::jsonb, 'https://baoansport.vn/xe-dap-tap-the-duc/xe-dap-tap-the-duc-tokado-tk800/'),
  ('xe-dap-tap-the-duc-tokado-tk-1900', 'BAS-1423', 'TK-1900', 'Xe đạp tập thể dục Tokado TK-1900', 'Xe đạp tập thể dục Tokado TK-1900 thuộc dòng xe toàn thân, hỗ trợ cả tư thế đứng lẫn ngồi đạp xe và phù hợp sử dụng để rèn luyện sức khỏe cho gia đình.', 'Xe đạp tập thể dục Tokado TK-1900 thuộc dòng xe toàn thân, hỗ trợ cả tư thế đứng lẫn ngồi đạp xe và phù hợp sử dụng để rèn luyện sức khỏe cho gia đình.', 9500000, 'xe-dap-tap-the-duc', 54500, '{"Mã sản phẩm": "TK-1900", "Màu sắc": "Xám - đen", "Chất liệu": "Thép, nhựa", "Trọng lượng xe": "54.5 kg", "Trọng lượng thùng": "61 kg", "Tải trọng tối đa": "130 kg", "Kích thước lắp đặt": "160 x 65 x 175 cm", "Kích thước thùng": "135 x 43 x 71 cm", "Yên xe": "Có", "Chuyển động": "Dây curoa + bánh đà", "Kháng lực": "10 mức", "Đo nhịp tim": "Có"}'::jsonb, 'https://baoansport.vn/xe-dap-tap-the-duc/xe-dap-tap-the-duc-tokado-tk-1900/'),
  ('buc-nhay-aerobic-840', 'BAS-1424', '840', 'Bục nhảy Aerobic 840', 'Bục nhảy Aerobic 840 cao cấp được làm từ chất liệu nhựa PP kết hợp với nhựa ABS, thiết kế dạng tháo rời và có thể dễ dàng điều chỉnh độ cao khi sử dụng.', 'Bục nhảy Aerobic 840 cao cấp được làm từ chất liệu nhựa PP kết hợp với nhựa ABS, thiết kế dạng tháo rời và có thể dễ dàng điều chỉnh độ cao khi sử dụng.', 1500000, 'phu-kien-yoga', 8000, '{"Mã sản phẩm": "840", "Màu sắc": "Đen - tím - xanh", "Chất liệu": "Nhựa PP, nhựa ABS", "Trọng lượng": "8 kg", "Trọng lượng cả hộp": "9 kg", "Tải trọng tối đa": "100 kg", "Kích thước đặt": "110 x 40 x 20 cm"}'::jsonb, 'https://baoansport.vn/phu-kien-yoga/buc-nhay-aerobic-840/'),
  ('don-ta-1m8-phi-50', 'BAS-1405', 'DT1M8P50', 'Đòn tạ 1m8 phi 50', 'Đòn tạ 1m8 phi 50 được nhập khẩu nguyên chiếc từ Trung Quốc, đạt tiêu chuẩn Olympic và phù hợp để sử dụng cho các phòng tập thể hình chuyên nghiệp.', 'Đòn tạ 1m8 phi 50 được nhập khẩu nguyên chiếc từ Trung Quốc, đạt tiêu chuẩn Olympic và phù hợp để sử dụng cho các phòng tập thể hình chuyên nghiệp.', 1000000, 'ta-tay-ta-don', 11000, '{"Mã sản phẩm": "DT1M8P50", "Màu sắc": "Xám bạc", "Chất liệu": "Thép", "Chiều dài": "1m5", "Trọng lượng": "11 kg", "Tải trọng tối đa": "300 kg", "Kẹp tạ": "Có"}'::jsonb, 'https://baoansport.vn/ta-tay-ta-don/don-ta-1m8-phi-50/'),
  ('don-ta-1m5-phi-50', 'BAS-1404', 'DT1M5P50', 'Đòn tạ 1m5 phi 50', 'Đòn tạ 1m5 phi 50 nhập khẩu làm từ chất liệu thép không rỉ, bề mặt vật liệu mạ inox kết hợp với niken sáng bóng và đạt tiêu chuẩn Olympic cho phòng Gym.', 'Đòn tạ 1m5 phi 50 nhập khẩu làm từ chất liệu thép không rỉ, bề mặt vật liệu mạ inox kết hợp với niken sáng bóng và đạt tiêu chuẩn Olympic cho phòng Gym.', 900000, 'ta-tay-ta-don', 8000, '{"Mã sản phẩm": "DT1M5P50", "Màu sắc": "Xám bạc", "Chất liệu": "Thép", "Chiều dài": "1m5", "Trọng lượng": "8 kg", "Tải trọng tối đa": "250 kg", "Kẹp tạ": "Có"}'::jsonb, 'https://baoansport.vn/ta-tay-ta-don/don-ta-1m5-phi-50/'),
  ('ghe-tap-lung-bung-impulse-it7007', 'BAS-1384', 'IT7007', 'Ghế tập lưng bụng Impulse IT7007', 'Ghế tập lưng bụng Impulse IT7007 được thiết kế chắc chắn, có khả năng điều chỉnh độ nghiêng và phù hợp dùng để lắp đặt cho phòng Gym chuyên nghiệp.', 'Ghế tập lưng bụng Impulse IT7007 được thiết kế chắc chắn, có khả năng điều chỉnh độ nghiêng và phù hợp dùng để lắp đặt cho phòng Gym chuyên nghiệp.', 9500000, 'thiet-bi-phong-gym', 43500, '{"Mã sản phẩm": "IT7007", "Màu sắc": "Xám bạc", "Chất liệu": "Thép, nệm da", "Trọng lượng ghế": "43,5 kg", "Tải trọng tối đa": "180 kg", "Kích thước lắp đặt": "1312 x 749 x 814 mm"}'::jsonb, 'https://baoansport.vn/thiet-bi-phong-gym/ghe-tap-lung-bung-impulse-it7007/'),
  ('ghe-tap-nang-chan-impulse-it7005', 'BAS-1385', 'IT7005', 'Ghế tập nâng chân Impulse IT7005', 'Ghế tập nâng chân Impulse IT7005 được thiết kế chắc chắn, hỗ trợ tập bắp chuối hiệu quả và phù hợp sử dụng để lắp đặt cho phòng tập Gym chuyên nghiệp.', 'Ghế tập nâng chân Impulse IT7005 được thiết kế chắc chắn, hỗ trợ tập bắp chuối hiệu quả và phù hợp sử dụng để lắp đặt cho phòng tập Gym chuyên nghiệp.', 8200000, 'thiet-bi-phong-gym', 50000, '{"Mã sản phẩm": "IT7005", "Màu sắc": "Xám bạc", "Chất liệu": "Thép, nệm da", "Trọng lượng ghế": "50 kg", "Tải trọng tối đa": "180 kg", "Kích thước lắp đặt": "1356 x 751 x 831 mm"}'::jsonb, 'https://baoansport.vn/thiet-bi-phong-gym/ghe-tap-nang-chan-impulse-it7005/'),
  ('ghe-tap-tay-truoc-impulse-it7002', 'BAS-1386', 'IT7002', 'Ghế tập tay trước Impulse IT7002', 'Ghế tập tay trước Impulse IT7002 được thiết kế chắc chắn, hỗ trợ tập cơ bắp tay trước hiệu quả và thích hợp sử dụng tại các phòng tập Gym chuyên nghiệp.', 'Ghế tập tay trước Impulse IT7002 được thiết kế chắc chắn, hỗ trợ tập cơ bắp tay trước hiệu quả và thích hợp sử dụng tại các phòng tập Gym chuyên nghiệp.', 6000000, 'thiet-bi-phong-gym', 44000, '{"Mã sản phẩm": "IT7002", "Màu sắc": "Xám bạc", "Chất liệu": "Thép, nệm da", "Trọng lượng ghế": "44 kg", "Tải trọng tối đa": "180 kg", "Kích thước lắp đặt": "1010 x 810 x 880 mm"}'::jsonb, 'https://baoansport.vn/thiet-bi-phong-gym/ghe-tap-tay-truoc-impulse-it7002/'),
  ('gian-ta-da-nang-bp-806', 'BAS-1387', 'BP-806', 'Giàn tạ đa năng BP-806', 'Giàn tạ đa năng BP-806 được thiết kế chắc chắn, tích hợp hơn 30 bài tập thể hình cho toàn bộ các nhóm cơ trên cơ thể và hỗ trợ bốn người tập cùng một lúc.', 'Giàn tạ đa năng BP-806 được thiết kế chắc chắn, tích hợp hơn 30 bài tập thể hình cho toàn bộ các nhóm cơ trên cơ thể và hỗ trợ bốn người tập cùng một lúc.', 14650000, 'gian-ta-da-nang', 225000, '{"Mã sản phẩm": "BP-806", "Màu sắc": "Đen - xám - đỏ", "Chất liệu": "Thép, nệm da", "Trọng lượng tạ": "73 kg", "Trọng lượng bao đấm": "25 kg", "Trọng lượng cả bộ": "225 kg", "Tải trọng tối đa": "180 kg", "Kích thước lắp đặt": "1940 x 1700 x 2200 mm", "Số kiện vận chuyển": "7 kiện"}'::jsonb, 'https://baoansport.vn/gian-ta-da-nang/gian-ta-da-nang-bp-806/'),
  ('gian-ta-da-nang-hq-908s', 'BAS-1388', 'HQ-908S', 'Giàn tạ đa năng HQ-908S', 'Giàn tạ đa năng HQ-908S thiết kế đạt chuẩn phòng Gym, tích hợp hơn 50 bài tập thể hình từ cơ bản đến nâng cao và hỗ trợ 3 người tập cùng một thời điểm.', 'Giàn tạ đa năng HQ-908S thiết kế đạt chuẩn phòng Gym, tích hợp hơn 50 bài tập thể hình từ cơ bản đến nâng cao và hỗ trợ 3 người tập cùng một thời điểm.', 14900000, 'gian-ta-da-nang', 210000, '{"Mã sản phẩm": "HQ-908S", "Màu sắc": "Đen - xám - đỏ", "Chất liệu": "Thép, nệm da", "Trọng lượng tạ": "73 kg", "Trọng lượng cả bộ": "210 kg", "Tải trọng tối đa": "180 kg", "Kích thước lắp đặt": "1900 x 2000 x 2300 mm", "Số kiện vận chuyển": "5 kiện"}'::jsonb, 'https://baoansport.vn/gian-ta-da-nang/gian-ta-da-nang-hq-908s/'),
  ('thiet-bi-tap-phuc-hoi-chuc-nang-3-in-1', 'BAS-1391', 'TBTPHCN', 'Thiết bị tập phục hồi chức năng 3 in 1', 'Thiết bị tập phục hồi chức năng 3 in 1 được thiết kế nhỏ gọn, hỗ trợ tập vận động chân tay hiệu quả và phù hợp dùng tập cho bệnh nhân bị tai nạn, tai biến.', 'Thiết bị tập phục hồi chức năng 3 in 1 được thiết kế nhỏ gọn, hỗ trợ tập vận động chân tay hiệu quả và phù hợp dùng tập cho bệnh nhân bị tai nạn, tai biến.', 2450000, 'xe-dap-tap-the-duc', 0, '{"Mã sản phẩm": "TBTPHCN", "Màu sắc": "Xám - xanh", "Chất liệu": "Thép, nhựa", "Trọng lượng thiết bị": "19 kg", "Tải trọng tối đa": "100 kg", "Kích thước lắp đặt": "142 x 54 x 160 cm"}'::jsonb, 'https://baoansport.vn/xe-dap-tap-the-duc/thiet-bi-tap-phuc-hoi-chuc-nang-3-in-1/'),
  ('mu-bao-ho-dau-bn-fight', 'BAS-1394', 'BN-Fight', 'Mũ bảo hộ đầu BN Fight', 'Mũ bảo hộ đầu BN Fight được thiết kế đẹp mắt, may chắc chắn từ chất liệu PU cao cấp và có tác dụng giúp đảm bảo an toàn cho võ sĩ khi thi đấu võ thuật.', 'Mũ bảo hộ đầu BN Fight được thiết kế đẹp mắt, may chắc chắn từ chất liệu PU cao cấp và có tác dụng giúp đảm bảo an toàn cho võ sĩ khi thi đấu võ thuật.', 550000, 'mu-ao-giap-vo-thuat', 0, '{"Mã sản phẩm": "BN-Fight", "Màu sắc": "Cam - đen, đỏ - đen, xanh - đen", "Chất liệu": "Da PU, EVA, vải", "Trọng lượng": "800 gram", "Size": "S, L, XL"}'::jsonb, 'https://baoansport.vn/mu-ao-giap-vo-thuat/mu-bao-ho-dau-bn-fight/'),
  ('gang-tay-boxing-tre-em-bn', 'BAS-1395', 'GBTEBN', 'Găng tay Boxing trẻ em BN', 'Găng tay Boxing trẻ em BN được thiết kế đẹp, may chắc chắn từ chất liệu da PU, có kích thước 6oz và phù hợp sử dụng cho trẻ em độ tuổi từ 5 đến 10 tuổi.', 'Găng tay Boxing trẻ em BN được thiết kế đẹp, may chắc chắn từ chất liệu da PU, có kích thước 6oz và phù hợp sử dụng cho trẻ em độ tuổi từ 5 đến 10 tuổi.', 375000, 'gang-tay-boxing', 0, '{"Mã sản phẩm": "GBTEBN", "Màu sắc": "Đỏ, xanh, trắng", "Chất liệu": "Da PU, EVA", "Trọng lượng": "6oz", "Độ tuổi phù hợp": "5 đến 10 tuổi"}'::jsonb, 'https://baoansport.vn/gang-tay-boxing/gang-tay-boxing-tre-em-bn/'),
  ('xa-don-vifa-sport-vifa-711214', 'BAS-1375', 'VIFA-711214', 'Xà đơn Vifa Sport VIFA-711214', 'Xà đơn Vifa Sport VIFA-711214 được thiết kế theo tiêu chuẩn Châu Âu, hỗ trợ hai người tập cùng lúc và phù hợp để rèn luyện cho cả người lớn lẫn trẻ em.', 'Xà đơn Vifa Sport VIFA-711214 được thiết kế theo tiêu chuẩn Châu Âu, hỗ trợ hai người tập cùng lúc và phù hợp để rèn luyện cho cả người lớn lẫn trẻ em.', 11800000, 'dung-cu-the-thao-ngoai-troi', 69000, '{"Mã sản phẩm": "VIFA-711214", "Màu sắc": "Xanh - xám", "Chất liệu": "Thép, nhựa", "Trọng lượng máy": "69 kg", "Tải trọng tối đa": "180 kg", "Diện tích phù hợp": "2000 x 3800mm", "Kích thước lắp đặt": "3020 x 220 x 2280mm (±3%)"}'::jsonb, 'https://baoansport.vn/dung-cu-the-thao-ngoai-troi/xa-don-vifa-sport-vifa-711214/'),
  ('xe-dap-tap-phuc-hoi-chuc-nang-bc-85023', 'BAS-1399', 'BC-85023', 'Xe đạp tập phục hồi chức năng BC-85023', 'Xe đạp tập phục hồi chức năng BC-85023 được thiết kế chắc chắn, yên ngồi có thêm phần tựa lưng và có chức năng hỗ trợ tập vận động chân tay hiệu quả.', 'Xe đạp tập phục hồi chức năng BC-85023 được thiết kế chắc chắn, yên ngồi có thêm phần tựa lưng và có chức năng hỗ trợ tập vận động chân tay hiệu quả.', 7400000, 'xe-dap-tap-the-duc', 37000, '{"Mã sản phẩm": "BC-85023", "Màu sắc": "Ghi xám", "Chất liệu": "Thép, nhựa", "Trọng lượng bánh đà": "7 kg", "Trọng lượng xe": "37 kg", "Trọng lượng thùng": "45 kg", "Tải trọng tối đa": "130 kg", "Kích thước lắp đặt": "140 x 50 x 136 cm", "Kích thước thùng": "123.5 x 32 x 74 cm", "Yên xe": "Có", "Chuyển động": "Dây curoa + bánh đà", "Kháng lực": "14 mức", "Đo nhịp tim": "Có"}'::jsonb, 'https://baoansport.vn/xe-dap-tap-the-duc/xe-dap-tap-phuc-hoi-chuc-nang-bc-85023/'),
  ('day-nhay-the-duc-loi-cap-kem-ta', 'BAS-1400', 'DNTDLC', 'Dây nhảy thể dục lõi cáp kèm tạ', 'Dây nhảy thể dục lõi cáp kèm tạ được làm từ chất liệu cao cấp, tay cầm có thể điều chỉnh trọng lượng dễ dàng và tích hợp bi xoay chống xoắn dây khi nhảy.', 'Dây nhảy thể dục lõi cáp kèm tạ được làm từ chất liệu cao cấp, tay cầm có thể điều chỉnh trọng lượng dễ dàng và tích hợp bi xoay chống xoắn dây khi nhảy.', 100000, 'dung-cu-tap-the-luc', 0, '{"Mã sản phẩm": "DNTDLC", "Màu sắc": "Đen - đỏ", "Chất liệu": "Thép, nhựa", "Chiều dài dây": "2.8m", "Chiều dài tay cầm": "16cm", "Trọng lượng dây": "400 gram"}'::jsonb, 'https://baoansport.vn/dung-cu-tap-the-luc/day-nhay-the-duc-loi-cap-kem-ta/'),
  ('don-ta-chu-z-phi-50', 'BAS-1402', 'DTCZ50', 'Đòn tạ chữ Z phi 50', 'Đòn tạ chữ Z phi 50 nhập khẩu được làm từ chất liệu thép đặc chống rỉ, mạ Inox kết hợp với Niken bền đẹp, sáng bóng và trang bị kẹp khóa tạ ở cả hai đầu.', 'Đòn tạ chữ Z phi 50 nhập khẩu được làm từ chất liệu thép đặc chống rỉ, mạ Inox kết hợp với Niken bền đẹp, sáng bóng và trang bị kẹp khóa tạ ở cả hai đầu.', 900000, 'ta-tay-ta-don', 6500, '{"Mã sản phẩm": "DTCZ50", "Màu sắc": "Xám bạc", "Chất liệu": "Thép", "Chiều dài": "1m2", "Trọng lượng": "6,5 kg", "Tải trọng tối đa": "250 kg", "Khóa tạ": "Có"}'::jsonb, 'https://baoansport.vn/ta-tay-ta-don/don-ta-chu-z-phi-50/'),
