  ('buc-nhay-aerobic-royal-740', 'BAS-1425', 'Royal-740', 'Bục tập Aerobic Royal 740', 'Bục tập Aerobic Royal 740 được làm chắc chắn từ chất liệu nhựa ABS, có khả năng chịu tải trọng người tập đến 100kg và có thể điều chỉnh độ cao dễ dàng.', 'Bục tập Aerobic Royal 740 được làm chắc chắn từ chất liệu nhựa ABS, có khả năng chịu tải trọng người tập đến 100kg và có thể điều chỉnh độ cao dễ dàng.', 850000, 'phu-kien-yoga', 3500, '{"Mã sản phẩm": "Royal-740", "Màu sắc": "Đen - tím", "Chất liệu": "Nhựa ABS", "Trọng lượng": "3.5 kg", "Trọng lượng cả hộp": "4 kg", "Tải trọng tối đa": "100 kg", "Kích thước lắp đặt": "70 x 25 x 22 cm"}'::jsonb, 'https://baoansport.vn/phu-kien-yoga/buc-nhay-aerobic-royal-740/'),
  ('tham-san-cau-long-tinsue', 'BAS-1260', 'TCLT', 'Thảm sân cầu lông Tinsue', 'Thảm sân cầu lông Tinsue chính hãng được sản xuất từ chất liệu EVA + PVC cao cấp, có khả năng chống trơn trượt cực tốt, đạt tiêu chuẩn thi đấu Quốc tế.', 'Thảm sân cầu lông Tinsue chính hãng được sản xuất từ chất liệu EVA + PVC cao cấp, có khả năng chống trơn trượt cực tốt, đạt tiêu chuẩn thi đấu Quốc tế.', 32000000, 'tham-san-cau-long', 0, '{"Mã sản phẩm": "TCLT", "Màu sắc": "Xanh", "Chất liệu": "EVA + PVC", "Kích thước sân": "15.4 x 7.1m"}'::jsonb, 'https://baoansport.vn/tham-san-cau-long/tham-san-cau-long-tinsue/'),
  ('tru-bong-ro-s021a', 'BAS-1301', 'S021A', 'Trụ bóng rổ S021A', 'Trụ bóng rổ S021A của SBA305 được làm chắc chắn, có chức năng điều chỉnh độ cao và phù hợp sử dụng để chơi bóng rổ ở nhà hoặc dùng cho trường học.', 'Trụ bóng rổ S021A của SBA305 được làm chắc chắn, có chức năng điều chỉnh độ cao và phù hợp sử dụng để chơi bóng rổ ở nhà hoặc dùng cho trường học.', 5200000, 'tru-bong-ro', 0, '{"Mã sản phẩm": "S021A", "Màu sắc": "Đen + trắng", "Chiều cao rổ": "305cm", "Đường kính rổ": "45cm", "Kích thước bảng rổ": "1100 x 750mm", "Kích thước đế trụ": "1150 x 750 x 200mm", "Trọng lượng trụ": "28kg", "Trọng lượng cả thùng": "30kg", "Diện tích lắp đặt": "Đang cập nhật", "Bánh xe di chuyển": "Có"}'::jsonb, 'https://baoansport.vn/tru-bong-ro/tru-bong-ro-s021a/'),
  ('tru-bong-ro-s021', 'BAS-1302', 'S021', 'Trụ bóng rổ S021', 'Trụ bóng rổ S021 nhập khẩu từ Trung Quốc được thiết kế chắc chắn, có thể điều chỉnh độ cao dễ dàng khi sử dụng và phù hợp chơi tại nhà hoặc trường học.', 'Trụ bóng rổ S021 nhập khẩu từ Trung Quốc được thiết kế chắc chắn, có thể điều chỉnh độ cao dễ dàng khi sử dụng và phù hợp chơi tại nhà hoặc trường học.', 5900000, 'tru-bong-ro', 0, '{"Mã sản phẩm": "S021", "Màu sắc": "Đen + trắng", "Chiều cao rổ": "305cm", "Đường kính rổ": "45cm", "Kích thước bảng rổ": "1100 x 750mm", "Kích thước đế trụ": "1150 x 750 x 200mm", "Trọng lượng trụ": "30kg", "Trọng lượng cả thùng": "32kg", "Diện tích lắp đặt": "Đang cập nhật", "Bánh xe di chuyển": "Có"}'::jsonb, 'https://baoansport.vn/tru-bong-ro/tru-bong-ro-s021/'),
  ('ghe-tap-ta-don-xuki', 'BAS-1303', 'GTDXK', 'Ghế tập tạ đơn Xuki', 'Ghế tập tạ đơn Xuki được thiết kế chắc chắn, hỗ trợ các chức năng cơ bản gồm đẩy ngực, hít đất, tập xà kép và phù hợp sử dụng để tập tại nhà cho Gymer.', 'Ghế tập tạ đơn Xuki được thiết kế chắc chắn, hỗ trợ các chức năng cơ bản gồm đẩy ngực, hít đất, tập xà kép và phù hợp sử dụng để tập tại nhà cho Gymer.', 1350000, 'ghe-tap-ta', 18000, '{"Mã sản phẩm": "GTDXK", "Màu sắc": "Xám - đỏ", "Chất liệu": "Thép, mút da", "Trọng lượng": "18 kg", "Tải trọng tối đa": "160 kg", "Kích thước lắp đặt": "125 x 68 x 85 cm"}'::jsonb, 'https://baoansport.vn/ghe-tap-ta/ghe-tap-ta-don-xuki/'),
  ('ban-bong-ban-mini', 'BAS-1306', 'JL20850', 'Bàn bóng bàn Mini', 'Bàn bóng bàn Mini tại Bảo An Sport - mặt bàn MDF 12 mm chống lóa, khung thép chắc có thể gập gọn, đi kèm cọc lưới. Giá chỉ 3.4 triệu, có sẵn giao hàng nhanh.', 'Bàn bóng bàn Mini tại Bảo An Sport - mặt bàn MDF 12 mm chống lóa, khung thép chắc có thể gập gọn, đi kèm cọc lưới. Giá chỉ 3.4 triệu, có sẵn giao hàng nhanh.', 3400000, 'ban-bong-ban', 23500, '{"Mã sản phẩm": "JL20850", "Màu sắc": "Xanh - xám", "Chất liệu": "Thép, gỗ MDF", "Độ dày mặt bàn": "12mm", "Kích thước lắp đặt": "1820 x 910 x 760 mm", "Kích thước thùng": "940 x 940 x 82 mm", "Trọng lượng bàn": "23.5 kg", "Trọng lượng thùng": "26.5 kg", "Gập gọn": "Có", "Bánh xe di chuyển": "Không", "Cọc lưới đi kèm": "Có"}'::jsonb, 'https://baoansport.vn/ban-bong-ban/ban-bong-ban-mini/'),
  ('ban-bong-ban-kamito-6825', 'BAS-1307', '6825', 'Bàn bóng bàn Kamito 6825', 'Bàn bóng bàn Kamito 6825 chính hãng có mặt bàn làm từ gỗ MDF cao cấp dày 25mm, chân bàn chắc chắn và phù hợp dùng để chơi tại các CLB bóng bàn.', 'Bàn bóng bàn Kamito 6825 chính hãng có mặt bàn làm từ gỗ MDF cao cấp dày 25mm, chân bàn chắc chắn và phù hợp dùng để chơi tại các CLB bóng bàn.', 10500000, 'ban-bong-ban', 113000, '{"Mã sản phẩm": "6825", "Màu sắc": "Xanh  - đen", "Chất liệu": "Thép, gỗ MDF", "Độ dày mặt bàn": "25mm", "Kích thước lắp đặt": "2740 x 1525 x 760 mm", "Kích thước thùng": "Đang cập nhật", "Trọng lượng bàn": "113 kg", "Trọng lượng thùng": "117kg", "Gập gọn": "Có", "Bánh xe di chuyển": "Có", "Cọc lưới đi kèm": "Có"}'::jsonb, 'https://baoansport.vn/ban-bong-ban/ban-bong-ban-kamito-6825/'),
  ('ban-bong-ban-kamito-6818', 'BAS-1308', '6818', 'Bàn bóng bàn Kamito 6818', 'Bàn bóng bàn Kamito 6818 có mặt bàn làm từ gỗ MDF dày 18mm, chân bàn chắc chắn có thể gập gọn và phù hợp dùng chơi bóng bàn tại nhà hoặc cơ quan.', 'Bàn bóng bàn Kamito 6818 có mặt bàn làm từ gỗ MDF dày 18mm, chân bàn chắc chắn có thể gập gọn và phù hợp dùng chơi bóng bàn tại nhà hoặc cơ quan.', 7200000, 'ban-bong-ban', 85000, '{"Mã sản phẩm": "6818", "Màu sắc": "Xanh - trắng - đen", "Chất liệu": "Thép, gỗ MDF", "Độ dày mặt bàn": "18mm", "Kích thước lắp đặt": "2740 x 1525 x 760 mm", "Kích thước thùng": "1600 x 1470 x 120 mm", "Đường kính bánh xe": "75 mm", "Trọng lượng bàn": "85 kg", "Trọng lượng thùng": "88 kg", "Gập gọn": "Có", "Bánh xe di chuyển": "Có", "Cọc lưới đi kèm": "Có"}'::jsonb, 'https://baoansport.vn/ban-bong-ban/ban-bong-ban-kamito-6818/'),
  ('ban-bong-ban-vinasport-mdf-04', 'BAS-1310', 'MDF-04', 'Bàn bóng bàn VinaSport MDF 04', 'Bàn bóng bàn VinaSport MDF 04 được thiết kế chắc chắn, mặt bàn dày 25mm cho độ nảy chuẩn và phù hợp để chơi bóng bàn tại nhà, cơ quan, trường học.', 'Bàn bóng bàn VinaSport MDF 04 được thiết kế chắc chắn, mặt bàn dày 25mm cho độ nảy chuẩn và phù hợp để chơi bóng bàn tại nhà, cơ quan, trường học.', 4650000, 'ban-bong-ban', 0, '{"Mã sản phẩm": "MDF-04", "Màu sắc": "Xanh - trắng", "Chất liệu": "Thép, gỗ MDF", "Độ dày mặt bàn": "25mm", "Kích thước lắp đặt": "2740 x 1525 x 760 mm", "Kích thước vận chuyển": "1600 x 1470 x 115 mm", "Trọng lượng bàn": "Đang cập nhật", "Gập gọn": "Có", "Bánh xe di chuyển": "Có", "Khuyến mại": "Cọc lưới + hộp bóng"}'::jsonb, 'https://baoansport.vn/ban-bong-ban/ban-bong-ban-vinasport-mdf-04/'),
  ('ban-bong-ban-vinasport-mdf-03', 'BAS-1311', 'MDF-03', 'Bàn bóng bàn VinaSport MDF-03', 'Bàn bóng bàn VinaSport MDF-03 (MDF 18mm) thiết kế có chân bàn chắn chắn, mặt bàn cho độ nảy chính xác và phù hợp dùng chơi ở nhà hay trường học.', 'Bàn bóng bàn VinaSport MDF-03 (MDF 18mm) thiết kế có chân bàn chắn chắn, mặt bàn cho độ nảy chính xác và phù hợp dùng chơi ở nhà hay trường học.', 4250000, 'ban-bong-ban', 0, '{"Mã sản phẩm": "MDF-03", "Màu sắc": "Xanh - trắng", "Chất liệu": "Thép, gỗ MDF", "Độ dày mặt bàn": "18mm", "Kích thước lắp đặt": "2740 x 1525 x 760 mm", "Kích thước vận chuyển": "1600 x 1470 x 110 mm", "Trọng lượng bàn": "Đang cập nhật", "Gập gọn": "Có", "Bánh xe di chuyển": "Có", "Khuyến mại": "Cọc lưới, hộp bóng"}'::jsonb, 'https://baoansport.vn/ban-bong-ban/ban-bong-ban-vinasport-mdf-03/'),
  ('ban-bong-ban-vinasport-mdf-02', 'BAS-1312', 'MDF-02', 'Bàn bóng bàn VinaSport MDF-02', 'Bàn bóng bàn VinaSport MDF-02 thiết kế đạt tiêu chuẩn tập luyện, chân bàn chắc chắn, mặt bàn cho độ nảy chuẩn và phù hợp sử dụng để chơi cho gia đình', 'Bàn bóng bàn VinaSport MDF-02 thiết kế đạt tiêu chuẩn tập luyện, chân bàn chắc chắn, mặt bàn cho độ nảy chuẩn và phù hợp sử dụng để chơi cho gia đình', 4150000, 'ban-bong-ban', 0, '{"Mã sản phẩm": "MDF-02", "Màu sắc": "Xanh - đen", "Chất liệu": "Thép, gỗ MDF", "Độ dày mặt bàn": "25mm", "Kích thước lắp đặt": "2740 x 1525 x 760 mm", "Kích thước vận chuyển": "1600 x 1470 x 120 mm", "Trọng lượng bàn": "Đang cập nhật", "Gập gọn": "Có", "Bánh xe di chuyển": "Có", "Khuyến mại": "Cọc lưới, hộp bóng"}'::jsonb, 'https://baoansport.vn/ban-bong-ban/ban-bong-ban-vinasport-mdf-02/'),
  ('xe-dap-tap-the-duc-aguri-aga-206pa', 'BAS-1314', 'AGA-206PA', 'Xe đạp tập thể dục Aguri AGA-206PA', 'Xe đạp tập thể dục Aguri AGA-206PA được thiết kế đẹp mắt, kiểu dáng nhỏ gọn, hỗ trợ tập vận động cả tay lẫn chân hiệu quả và phù hợp dùng cho gia đình', 'Xe đạp tập thể dục Aguri AGA-206PA được thiết kế đẹp mắt, kiểu dáng nhỏ gọn, hỗ trợ tập vận động cả tay lẫn chân hiệu quả và phù hợp dùng cho gia đình', 3350000, 'xe-dap-tap-the-duc', 17500, '{"Mã sản phẩm": "AGA-206PA", "Màu sắc": "Cam - đen - ghi xám", "Chất liệu": "Thép, nhựa", "Trọng lượng xe": "17.5 kg", "Trọng lượng thùng": "20.5 kg", "Tải trọng tối đa": "100 kg", "Kích thước lắp đặt": "1120 x 620 x 1180 mm", "Kích thước thùng": "910 x 210 x 598 mm", "Yên xe": "Có", "Chuyển động": "Xích + bánh đà", "Kháng lực": "Nhiều mức", "Đo nhịp tim": "Có"}'::jsonb, 'https://baoansport.vn/xe-dap-tap-the-duc/xe-dap-tap-the-duc-aguri-aga-206pa/'),
  ('ghe-tap-gym-da-nang-dds-1201', 'BAS-1316', 'DDS-1201', 'Ghế tập Gym đa năng DDS-1201', 'Ghế tập Gym đa năng DDS-1201 được thiết kế nhỏ gọn, có thể điều chỉnh độ dốc dễ dàng khi sử dụng và tích hợp nhiều bài tập thể hình hiệu quả cho Gymer.', 'Ghế tập Gym đa năng DDS-1201 được thiết kế nhỏ gọn, có thể điều chỉnh độ dốc dễ dàng khi sử dụng và tích hợp nhiều bài tập thể hình hiệu quả cho Gymer.', 2200000, 'ghe-tap-ta', 13700, '{"Mã sản phẩm": "DDS-1201", "Màu sắc": "Đen - xám - đỏ", "Chất liệu": "Thép, mút da", "Trọng lượng ghế": "13.7 kg", "Trọng lượng thùng": "15.2 kg", "Tải trọng tối đa": "180 kg", "Kích thước yên ghế": "110 x 33 x 7 cm", "Diện tích lắp đặt": "110 x 110 x 46 cm", "Kích thước thùng": "1180 x 41 x 31.5 cm"}'::jsonb, 'https://baoansport.vn/ghe-tap-ta/ghe-tap-gym-da-nang-dds-1201/'),
  ('gian-ta-da-nang-hq-708', 'BAS-1317', 'HQ-708', 'Giàn tạ đa năng HQ-708', 'Giàn tạ đa năng HQ-708 được thiết kế chắc chắn, tích hợp gần 30 bài tập thể hình cho các nhóm cơ và phù hợp sử dụng cho gia đình hoặc phòng Gym mini.', 'Giàn tạ đa năng HQ-708 được thiết kế chắc chắn, tích hợp gần 30 bài tập thể hình cho các nhóm cơ và phù hợp sử dụng cho gia đình hoặc phòng Gym mini.', 9500000, 'gian-ta-da-nang', 155000, '{"Mã sản phẩm": "HQ-708", "Màu sắc": "Đen - xám - đỏ", "Chất liệu": "Thép, nệm da", "Trọng lượng tạ": "73 kg", "Trọng lượng cả bộ": "155 kg", "Trọng lượng thùng": "160 kg", "Kích thước lắp đặt": "1980 x 1050 x 2200 mm", "Số kiện vận chuyển": "4 kiện/bộ"}'::jsonb, 'https://baoansport.vn/gian-ta-da-nang/gian-ta-da-nang-hq-708/'),
  ('ghe-tap-gym-da-nang-miking-ps-031', 'BAS-1318', 'PS-031', 'Ghế tập Gym đa năng Miking PS-031', 'Ghế tập Gym đa năng Miking PS-031 được thiết kế chắc chắn, hỗ trợ rất nhiều bài tập thể hình hiệu quả và phù hợp sử dụng để tập luyện tại nhà cho Gymer.', 'Ghế tập Gym đa năng Miking PS-031 được thiết kế chắc chắn, hỗ trợ rất nhiều bài tập thể hình hiệu quả và phù hợp sử dụng để tập luyện tại nhà cho Gymer.', 2150000, 'ghe-tap-ta', 17000, '{"Mã sản phẩm": "PS-031", "Màu sắc": "Đen - đỏ", "Chất liệu": "Thép, mút da", "Trọng lượng ghế": "17 kg", "Trọng lượng thùng": "18.5 kg", "Tải trọng tối đa": "150 kg", "Kích thước yên ghế": "96 x 26cm", "Diện tích lắp đặt": "158 x 48 x 49cm", "Kích thước thùng": "127.5 x 47 x 15cm"}'::jsonb, 'https://baoansport.vn/ghe-tap-ta/ghe-tap-gym-da-nang-miking-ps-031/'),
  ('khung-ganh-ta-da-nang-k8', 'BAS-1319', 'K8', 'Khung gánh tạ đa năng K8', 'Khung gánh tạ đa năng K8 được thiết kế chắc chắn, hỗ trợ nhiều bài tập hiệu quả và phù hợp dùng tập tại nhà cho Gymer hoặc lắp đặt cho phòng Gym mini.', 'Khung gánh tạ đa năng K8 được thiết kế chắc chắn, hỗ trợ nhiều bài tập hiệu quả và phù hợp dùng tập tại nhà cho Gymer hoặc lắp đặt cho phòng Gym mini.', 12000000, 'gian-ta-da-nang', 106000, '{"Mã sản phẩm": "K8", "Màu sắc": "Đen - cam", "Chất liệu": "Thép, nệm da", "Trọng lượng cả bộ": "106 kg", "Trọng lượng thùng": "Đang cập nhật", "Tải trọng tối đa": "250 kg", "Kích thước lắp đặt": "1360 x 2100 x 2150 mm", "Số kiện vận chuyển": "2 kiện/bộ", "Kích thước kiện 1": "1630 x 500 x 220 mm", "Kích thước kiện 2": "2125 x 460 x 140 mm"}'::jsonb, 'https://baoansport.vn/gian-ta-da-nang/khung-ganh-ta-da-nang-k8/'),
  ('may-chay-bo-sakura-hq-v2c', 'BAS-1300', 'HQ-V2C', 'Máy chạy bộ Sakura HQ-V2C', 'Máy chạy bộ Sakura HQ-V2C được thiết kế đa năng, sử dụng động cơ DC có công suất 3.0Hp và phù hợp sử dụng để tập luyện thể dục ở nhà cho gia đình', 'Máy chạy bộ Sakura HQ-V2C được thiết kế đa năng, sử dụng động cơ DC có công suất 3.0Hp và phù hợp sử dụng để tập luyện thể dục ở nhà cho gia đình', 20000000, 'may-chay-bo', 90000, '{"Mã sản phẩm": "HQ-V2C", "Màu sắc": "Đen - trắng - đỏ", "Điện áp": "220V, 50-60Hz", "Động cơ": "DC", "Công suất": "3.0Hp", "Tốc độ": "1.0 - 16 km/h", "Nâng độ dốc": "0 đến 15%", "Trọng lượng máy": "90 kg", "Trọng lượng thùng": "96 kg và 6 kg", "Tải trọng tối đa": "130 kg", "Kích thước bàn chạy": "136 x 47.5 cm", "Kích thước lắp đặt": "180 x 80 x 142 cm", "Kích thước gập gọn": "125 x 80 x 145 cm", "Kích thước thùng 1": "179.5 x 81 x 36.5 cm", "Kích thước thùng 2": "41 x 27 x 18 cm", "Màn hình": "LED", "Thảm chạy": "Diamond Running Belt", "Giảm chấn": "Đệm cao su", "Khóa an toàn": "Có", "Gập gọn": "Có", "Bánh xe di chuyển": "Có", "Cổng kết nối/sạc": "USB", "Âm thanh": "Loa Hi-Fi"}'::jsonb, 'https://baoansport.vn/may-chay-bo/may-chay-bo-sakura-hq-v2c/'),
  ('coc-ky-thuat-bong-da-no606', 'BAS-1298', 'NO606', 'Cọc kỹ thuật bóng đá NO606', 'Cọc kỹ thuật bóng đá NO606 thiết kế tự đứng, làm bằng nhựa dẻo chịu lực tốt và chuyên dùng để luyện kỹ thuật dắt bóng qua người, chạy chỗ trong bóng đá.', 'Cọc kỹ thuật bóng đá NO606 thiết kế tự đứng, làm bằng nhựa dẻo chịu lực tốt và chuyên dùng để luyện kỹ thuật dắt bóng qua người, chạy chỗ trong bóng đá.', 240000, 'phu-kien-bong-da', 0, '{"Mã sản phẩm": "NO606", "Màu sắc": "Vàng cam", "Chất liệu": "Nhựa", "Chiều cao": "160cm", "Trọng lượng": "900 gram"}'::jsonb, 'https://baoansport.vn/phu-kien-bong-da/coc-ky-thuat-bong-da-no606/'),
  ('xe-dap-tap-the-duc-spin-bike-jn55', 'BAS-1263', 'JN-D01', 'Xe đạp tập thể dục Spin Bike JN55', 'Xe đạp tập thể dục Spin Bike JN55 chính hãng Tokado được thiết kế chắc chắn, hỗ trợ tập thể lực + giảm cân hiệu quả và phù hợp dùng tại nhà cho gia đình', 'Xe đạp tập thể dục Spin Bike JN55 chính hãng Tokado được thiết kế chắc chắn, hỗ trợ tập thể lực + giảm cân hiệu quả và phù hợp dùng tại nhà cho gia đình', 4850000, 'xe-dap-tap-the-duc', 27000, '{"Mã sản phẩm": "JN-D01", "Màu sắc": "Đen - vàng", "Chất liệu": "Thép, nhựa", "Trọng lượng bánh đà": "8 kg", "Trọng lượng xe": "27 kg", "Trọng lượng thùng": "31 kg", "Tải trọng tối đa": "120 kg", "Kích thước lắp đặt": "105 x 50 x 117 cm", "Kích thước thùng": "104 x 23 x 92 cm", "Yên xe": "Có", "Chuyển động": "Dây curoa + bánh đà", "Kháng lực": "Nhiều mức", "Đo nhịp tim": "Có"}'::jsonb, 'https://baoansport.vn/xe-dap-tap-the-duc/xe-dap-tap-the-duc-spin-bike-jn55/'),
  ('xe-dap-tap-the-duc-tokado-tk007', 'BAS-1265', 'TK007', 'Xe đạp tập thể dục Tokado TK007', 'Xe đạp tập thể dục Tokado TK007 chính hãng được thiết kế đẹp, hỗ trợ tập thể lực, tập giảm cân hiệu quả và phù hợp sử dụng cho gia đình hoặc phòng Gym', 'Xe đạp tập thể dục Tokado TK007 chính hãng được thiết kế đẹp, hỗ trợ tập thể lực, tập giảm cân hiệu quả và phù hợp sử dụng cho gia đình hoặc phòng Gym', 6900000, 'xe-dap-tap-the-duc', 41000, '{"Mã sản phẩm": "TK007", "Màu sắc": "Đen - xám - vàng", "Chất liệu": "Thép, nhựa", "Trọng lượng bánh đà": "13 kg", "Trọng lượng xe": "41 kg", "Trọng lượng thùng": "46 kg", "Tải trọng tối đa": "135 kg", "Kích thước lắp đặt": "107 x 55 x 120 cm", "Kích thước thùng": "101.5 x 24.5 x 86 cm", "Yên xe": "Có", "Chuyển động": "Dây curoa + bánh đà", "Kháng lực": "Nhiều mức", "Đo nhịp tim": "Có"}'::jsonb, 'https://baoansport.vn/xe-dap-tap-the-duc/xe-dap-tap-the-duc-tokado-tk007/'),
  ('xe-dap-tap-the-duc-tokado-tk900', 'BAS-1270', 'TK900', 'Xe đạp tập thể dục Tokado TK900', 'Xe đạp tập thể dục Tokado TK900 được thiết kế dạng cố định + khung xe chắc chắn, hỗ trợ tập thể lực tại nhà hiệu quả và phù hợp sử dụng cho gia đình', 'Xe đạp tập thể dục Tokado TK900 được thiết kế dạng cố định + khung xe chắc chắn, hỗ trợ tập thể lực tại nhà hiệu quả và phù hợp sử dụng cho gia đình', 3750000, 'xe-dap-tap-the-duc', 21800, '{"Mã sản phẩm": "TK900", "Màu sắc": "Đen - xám - đỏ", "Chất liệu": "Thép, nhựa", "Trọng lượng bánh đà": "4 kg", "Trọng lượng xe": "21.8 kg", "Trọng lượng thùng": "24.1 kg", "Tải trọng tối đa": "120 kg", "Kích thước lắp đặt": "75 x 52 x 136 cm", "Kích thước thùng": "80 x 30 x 60 cm", "Yên xe": "Có", "Chuyển động": "Dây curoa + bánh đà", "Kháng lực": "8 mức", "Đo nhịp tim": "Có"}'::jsonb, 'https://baoansport.vn/xe-dap-tap-the-duc/xe-dap-tap-the-duc-tokado-tk900/'),
  ('xe-dap-tap-lien-hoan-life-span', 'BAS-1274', '4090', 'Xe đạp tập liên hoàn Life Span', 'Xe đạp tập liên hoàn Life Span chính hãng được thiết kế nhỏ gọn, hỗ trợ tập vận động toàn thân hiệu quả và phù hợp dùng để tập tại nhà cho người cao tuổi.', 'Xe đạp tập liên hoàn Life Span chính hãng được thiết kế nhỏ gọn, hỗ trợ tập vận động toàn thân hiệu quả và phù hợp dùng để tập tại nhà cho người cao tuổi.', 3050000, 'xe-dap-tap-the-duc', 16500, '{"Mã sản phẩm": "4090", "Màu sắc": "Đen - xám, đen - vàng", "Chất liệu": "Thép, nhựa", "Trọng lượng xe": "16.5 kg", "Trọng lượng thùng": "18.5 kg", "Tải trọng tối đa": "110 kg", "Kích thước lắp đặt": "102 x 60 x 115 cm", "Kích thước thùng": "89 x 20.5 x 59 cm", "Yên xe": "Có", "Chuyển động": "Xích + bánh đà", "Kháng lực": "Nhiều mức", "Đo nhịp tim": "Có"}'::jsonb, 'https://baoansport.vn/xe-dap-tap-the-duc/xe-dap-tap-lien-hoan-life-span/'),
  ('may-tap-phuc-hoi-chuc-nang-mini-bike', 'BAS-1275', 'WE3', 'Máy tập phục hồi chức năng Mini Bike', 'Máy tập phục hồi chức năng Mini Bike được thiết kế nhỏ gọn, chạy bằng điện và sử dụng để tập đạp xe vận động cho người già hoặc dùng tập vật lý trị liệu', 'Máy tập phục hồi chức năng Mini Bike được thiết kế nhỏ gọn, chạy bằng điện và sử dụng để tập đạp xe vận động cho người già hoặc dùng tập vật lý trị liệu', 1850000, 'xe-dap-tap-the-duc', 5000, '{"Mã sản phẩm": "WE3", "Màu sắc": "Xanh - trắng", "Chất liệu": "Thép, nhựa", "Điện áp": "220V/50Hz", "Công suất": "70W", "Tốc độ điều chỉnh": "12 mức độ", "Tốc độ đạp xe": "35 - 80 vòng/phút", "Trọng lượng": "5 kg", "Trọng lượng hộp": "5.5 kg", "Tải trọng tối đa": "50 kg", "Kích thước lắp đặt": "48 x 38 x 29 cm", "Kích thước thùng": "42 x 29 x 21 cm"}'::jsonb, 'https://baoansport.vn/xe-dap-tap-the-duc/may-tap-phuc-hoi-chuc-nang-mini-bike/'),
  ('ghe-tap-ta-da-nang-xuki', 'BAS-1276', 'GTXK', 'Ghế tập tạ đa năng Xuki', 'Ghế tập tạ đa năng Xuki hỗ trợ nhiều bài tập: đẩy ngực, kéo xô, ép ngực, tập chân,... Thiết kế chắc chắn, tải trọng lớn, giá từ 1.900.000đ. Giao hàng toàn quốc.', 'Ghế tập tạ đa năng Xuki hỗ trợ nhiều bài tập: đẩy ngực, kéo xô, ép ngực, tập chân,... Thiết kế chắc chắn, tải trọng lớn, giá từ 1.900.000đ. Giao hàng toàn quốc.', 1900000, 'ghe-tap-ta', 30000, '{"Mã sản phẩm": "GTXK", "Màu sắc": "Xám - đỏ", "Chất liệu": "Thép, mút da", "Trọng lượng": "30 kg", "Tải trọng tối đa": "180 kg", "Kích thước lắp đặt": "145 x 135 x 205 cm", "Kích thước thùng": "Đang cập nhật"}'::jsonb, 'https://baoansport.vn/ghe-tap-ta/ghe-tap-ta-da-nang-xuki/'),
  ('ta-tay-v-tap', 'BAS-1550', 'TT-VTAP', 'Tạ tay V-TAP (65.000/Kg)', 'Tạ tay V-TAP được đúc đặc từ gang, bên ngoài bọc cao su cao cấp, tay cầm chắc chắn và phù hợp sử dụng cho cá nhân hoặc phòng Gym chuyên nghiệp.', 'Tạ tay V-TAP được đúc đặc từ gang, bên ngoài bọc cao su cao cấp, tay cầm chắc chắn và phù hợp sử dụng cho cá nhân hoặc phòng Gym chuyên nghiệp.', 65000, 'ta-tay-ta-don', 0, '{"Mã sản phẩm": "TT-VTAP", "Màu sắc": "Đỏ đen", "Chất liệu": "Gang, cao su", "Trọng lượng tạ": "2.5kg đến 25kg"}'::jsonb, 'https://baoansport.vn/ta-tay-ta-don/ta-tay-v-tap/'),
  ('ghe-tap-ta-da-nang-xuki-2022', 'BAS-1277', 'XK2022', 'Ghế tập tạ đa năng Xuki 2022', 'Ghế tập tạ đa năng Xuki 2022 hỗ trợ tập đẩy tạ, kéo xô, ép ngực, tập xà đơn, tập xà kép, tập cơ chân hiệu quả và phù hợp sử dụng để tập tại nhà cho Gymer.', 'Ghế tập tạ đa năng Xuki 2022 hỗ trợ tập đẩy tạ, kéo xô, ép ngực, tập xà đơn, tập xà kép, tập cơ chân hiệu quả và phù hợp sử dụng để tập tại nhà cho Gymer.', 3900000, 'ghe-tap-ta', 52000, '{"Mã sản phẩm": "XK2022", "Màu sắc": "Xám - đỏ", "Chất liệu": "Thép, mút da", "Trọng lượng": "52 kg", "Tải trọng tối đa": "200 kg", "Kích thước lắp đặt": "210 x 150 x 230 cm", "Kích thước thùng": "Đang cập nhật"}'::jsonb, 'https://baoansport.vn/ghe-tap-ta/ghe-tap-ta-da-nang-xuki-2022/'),
  ('dich-da-kangrui-kt338', 'BAS-1278', 'KT338', 'Đích đá Kangrui KT338', 'Đích đá Kangrui KT338 được may bền đẹp từ da tổng hợp PU, bên trong lót xốp EVA có độ đàn hồi cao và phù hợp sử dụng để tập luyện cho Clb võ thuật.', 'Đích đá Kangrui KT338 được may bền đẹp từ da tổng hợp PU, bên trong lót xốp EVA có độ đàn hồi cao và phù hợp sử dụng để tập luyện cho Clb võ thuật.', 580000, 'dich-dam-dich-da', 0, '{"Mã sản phẩm": "KT338", "Màu sắc": "Xanh - đen, đỏ - đen", "Chất liệu": "Da PU, EVA", "Kích thước": "45 x 25 x 10 cm", "Trọng lượng": "560 gram"}'::jsonb, 'https://baoansport.vn/dich-dam-dich-da/dich-da-kangrui-kt338/'),
  ('may-chay-bo-phong-gym-sakura-v9', 'BAS-1283', 'V9', 'Máy chạy bộ phòng Gym Sakura V9', 'Máy chạy bộ phòng Gym Sakura V9 có trọng lượng nặng 217 kg, trang bị động cơ AC công suất 4.5Hp đỉnh 7.0Hp và phù hợp dùng cho phòng tập cao cấp.', 'Máy chạy bộ phòng Gym Sakura V9 có trọng lượng nặng 217 kg, trang bị động cơ AC công suất 4.5Hp đỉnh 7.0Hp và phù hợp dùng cho phòng tập cao cấp.', 42500000, 'may-chay-bo', 217500, '{"Mã sản phẩm": "V9", "Màu sắc": "Đen - xám", "Điện áp": "220V, 50-60Hz", "Động cơ": "AC", "Công suất": "4.5Hp đạt đỉnh 7.0Hp", "Tốc độ": "0.8 - 20 km/h", "Nâng độ dốc": "0 đến 21%", "Trọng lượng máy": "217.5 kg", "Trọng lượng thùng": "205.9 kg và 36.3 kg", "Tải trọng tối đa": "180 kg", "Kích thước bàn chạy": "155 x 58.5 cm", "Kích thước lắp đặt": "208.3 x 98.2 x 162 cm", "Kích thước thùng 1": "219 x 104.4 x 46 cm", "Kích thước thùng 2": "107.5 x 104.8 x 41 cm", "Màn hình": "LED", "Thảm chạy": "Diamond Running Belt", "Giảm chấn": "Đệm cao su", "Khóa an toàn": "Có", "Gập gọn": "Không", "Bánh xe di chuyển": "Có", "Quạt làm mát": "Có"}'::jsonb, 'https://baoansport.vn/may-chay-bo/may-chay-bo-phong-gym-sakura-v9/'),
  ('may-chay-bo-impulse-pt300', 'BAS-1284', 'PT300H', 'Máy chạy bộ Impulse PT300H', 'Máy chạy bộ Impulse PT300H chính hãng được thiết kế chắc chắn, sử dụng motor AC có công suất 3.0 đạt đỉnh 5.0Hp và phù hợp dùng cho phòng tập Gym.', 'Máy chạy bộ Impulse PT300H chính hãng được thiết kế chắc chắn, sử dụng motor AC có công suất 3.0 đạt đỉnh 5.0Hp và phù hợp dùng cho phòng tập Gym.', 48500000, 'may-chay-bo', 198000, '{"Mã sản phẩm": "PT300H", "Màu sắc": "Đen - xám", "Điện áp": "220V, 50-60Hz", "Động cơ": "AC", "Công suất": "3.0Hp đạt đỉnh 5.0Hp", "Tốc độ": "0.6 - 20 km/h", "Nâng độ dốc": "0 đến 15%", "Trọng lượng máy": "198 kg", "Trọng lượng thùng": "240 kg", "Tải trọng tối đa": "160 kg", "Kích thước bàn chạy": "152 x 55 cm", "Kích thước lắp đặt": "213 × 93 × 143 cm", "Kích thước thùng 1": "226 x 93 x 55 cm", "Kích thước thùng 2": "126 x 105 x 32 cm", "Màn hình": "LED", "Thảm chạy": "Diamond Running Belt", "Giảm chấn": "Impulse Soft®", "Khóa an toàn": "Có", "Gập gọn": "Không", "Bánh xe di chuyển": "Có"}'::jsonb, 'https://baoansport.vn/may-chay-bo/may-chay-bo-impulse-pt300/'),
  ('may-chay-bo-mofit-enjoy-305', 'BAS-1289', 'Enjoy-305', 'Máy chạy bộ Mofit Enjoy 305', 'Máy chạy bộ Mofit Enjoy 305 được thiết kế đẹp mắt, kích thước nhỏ gọn, sử dụng motor công suất 2.5Hp và chuyên dùng để tập thể dục tại nhà cho gia đình', 'Máy chạy bộ Mofit Enjoy 305 được thiết kế đẹp mắt, kích thước nhỏ gọn, sử dụng motor công suất 2.5Hp và chuyên dùng để tập thể dục tại nhà cho gia đình', 10000000, 'may-chay-bo', 49000, '{"Mã sản phẩm": "Enjoy-305", "Màu sắc": "Trắng - đen - xanh", "Điện áp": "220V, 50-60Hz", "Động cơ": "DC", "Công suất": "2.5Hp đạt đỉnh 3.5Hp", "Tốc độ": "1.0 - 14.8 km/h", "Nâng độ dốc": "0 đến 15%", "Trọng lượng máy": "49 kg", "Trọng lượng thùng": "57 kg", "Tải trọng tối đa": "100 kg", "Kích thước bàn chạy": "116 x 43 cm", "Kích thước lắp đặt": "150.7 x 74 x 129.5 cm", "Kích thước gập gọn": "Đang cập nhật", "Kích thước thùng": "Đang cập nhật", "Màn hình": "LCD", "Thảm chạy": "Diamond Running Belt", "Giảm chấn": "Đệm cao su", "Khóa an toàn": "Có", "Gập gọn": "Có", "Bánh xe di chuyển": "Có", "Cổng kết nối/sạc": "USB", "USB": "Loa Hi-Fi"}'::jsonb, 'https://baoansport.vn/may-chay-bo/may-chay-bo-mofit-enjoy-305/'),
  ('may-chay-bo-sakura-hq-v6', 'BAS-1296', 'HQ-V6', 'Máy chạy bộ Sakura HQ-V6', 'Máy chạy bộ Sakura HQ-V6 được thiết kế đơn năng, khung máy chắc chắn, sử dụng motor DC công suất 4.0HP và phù hợp dùng tập thể dục cho gia đình.', 'Máy chạy bộ Sakura HQ-V6 được thiết kế đơn năng, khung máy chắc chắn, sử dụng motor DC công suất 4.0HP và phù hợp dùng tập thể dục cho gia đình.', 21500000, 'may-chay-bo', 105000, '{"Mã sản phẩm": "HQ-V6", "Màu sắc": "Xám - đen", "Điện áp": "220V, 50-60Hz", "Động cơ": "DC", "Công suất": "4.0Hp", "Tốc độ": "1.0 - 20 km/h", "Nâng độ dốc": "0 đến 20 %", "Trọng lượng máy": "105 kg", "Trọng lượng thùng": "115 kg", "Tải trọng tối đa": "135 kg", "Kích thước bàn chạy": "146 x 52 cm", "Kích thước lắp đặt": "190 x 85 x 145 cm", "Kích thước gập gọn": "120 x 85 x 153 cm", "Kích thước thùng": "191 x 88 x 37.5 cm", "Màn hình": "LED", "Thảm chạy": "Diamond Running Belt", "Giảm chấn": "Đệm cao su", "Khóa an toàn": "Có", "Gập gọn": "Có", "Bánh xe di chuyển": "Có", "Cổng kết nối/sạc": "USB", "Âm thanh": "Loa Hi-Fi"}'::jsonb, 'https://baoansport.vn/may-chay-bo/may-chay-bo-sakura-hq-v6/'),
  ('may-chay-bo-sakura-hq-v6c', 'BAS-1297', 'HQ-V6C', 'Máy chạy bộ Sakura HQ-V6C', 'Máy chạy bộ Sakura HQ-V6C được thiết kế đa năng, sử dụng động cơ DC có công suất 4.0Hp mạnh mẽ và phù hợp dùng để tập luyện tại nhà cho gia đình', 'Máy chạy bộ Sakura HQ-V6C được thiết kế đa năng, sử dụng động cơ DC có công suất 4.0Hp mạnh mẽ và phù hợp dùng để tập luyện tại nhà cho gia đình', 22500000, 'may-chay-bo', 110000, '{"Mã sản phẩm": "HQ-V6C", "Màu sắc": "Xám - đen", "Điện áp": "220V, 50-60Hz", "Động cơ": "DC", "Công suất": "4.0Hp", "Tốc độ": "1.0 - 20 km/h", "Nâng độ dốc": "0 đến 20 %", "Trọng lượng máy": "110 kg", "Trọng lượng thùng": "115 kg và 6 kg", "Tải trọng tối đa": "135 kg", "Kích thước bàn chạy": "146 x 52 cm", "Kích thước lắp đặt": "195 x 85 x 145 cm", "Kích thước gập gọn": "120 x 85 x 153 cm", "Kích thước thùng 1": "191 x 88 x 37.5 cm", "Kích thước thùng 2": "41 x 27 x 18 cm", "Màn hình": "LED", "Thảm chạy": "Diamond Running Belt", "Giảm chấn": "Đệm cao su", "Khóa an toàn": "Có", "Gập gọn": "Có", "Bánh xe di chuyển": "Có", "Cổng kết nối/sạc": "USB", "Âm thanh": "Loa Hi-Fi"}'::jsonb, 'https://baoansport.vn/may-chay-bo/may-chay-bo-sakura-hq-v6c/'),
  ('ghe-tap-gym-da-nang-dds-1205', 'BAS-1320', 'DDS-1205', 'Ghế tập Gym đa năng DDS-1205', 'Ghế tập Gym đa năng DDS-1205 được thiết kế chắc chắn, hỗ trợ nhiều bài tập hiệu quả và phù hợp dùng cho các bạn đang có mục tiêu tập thể hình tại nhà.', 'Ghế tập Gym đa năng DDS-1205 được thiết kế chắc chắn, hỗ trợ nhiều bài tập hiệu quả và phù hợp dùng cho các bạn đang có mục tiêu tập thể hình tại nhà.', 3350000, 'ghe-tap-ta', 20000, '{"Mã sản phẩm": "DDS-1205", "Màu sắc": "Đen - xám - đỏ", "Chất liệu": "Thép, mút da", "Trọng lượng ghế": "20 kg", "Trọng lượng thùng": "23 kg", "Tải trọng tối đa": "180 kg", "Kích thước yên ghế": "Đang cập nhật", "Diện tích lắp đặt": "155 x 50 x 106 cm", "Kích thước thùng": "128 x 36.5 x 29.5 cm"}'::jsonb, 'https://baoansport.vn/ghe-tap-ta/ghe-tap-gym-da-nang-dds-1205/'),
  ('xe-dap-phuc-hoi-chuc-nang-bc-51053', 'BAS-1323', 'BC-51053', 'Xe đạp phục hồi chức năng BC-51053', 'Xe đạp phục hồi chức năng BC-51053 chính hãng LongStyle được thiết kế chắc chắn, ghế ngồi có tựa lưng và hỗ trợ tập vận động cả tay lẫn chân hiệu quả', 'Xe đạp phục hồi chức năng BC-51053 chính hãng LongStyle được thiết kế chắc chắn, ghế ngồi có tựa lưng và hỗ trợ tập vận động cả tay lẫn chân hiệu quả', 6200000, 'xe-dap-tap-the-duc', 33000, '{"Mã sản phẩm": "BC-51053", "Màu sắc": "Ghi xám", "Chất liệu": "Thép, nhựa", "Trọng lượng bánh đà": "7 kg", "Trọng lượng xe": "33 kg", "Trọng lượng thùng": "36 kg", "Tải trọng tối đa": "120 kg", "Kích thước lắp đặt": "102 x 61 x 126 cm", "Kích thước thùng": "99 x 70 x 31 cm", "Yên xe": "Có", "Chuyển động": "Dây curoa + bánh đà", "Kháng lực": "14 mức", "Đo nhịp tim": "Có"}'::jsonb, 'https://baoansport.vn/xe-dap-tap-the-duc/xe-dap-phuc-hoi-chuc-nang-bc-51053/'),
  ('vong-lac-eo-bang-nhua', 'BAS-1341', 'VLEBN', 'Vòng lắc eo bằng nhựa', 'Vòng lắc eo bằng nhựa Hula Hoop được làm từ chất liệu nhựa ABS, gồm 8 miếng rời ghép lại với nhau và phù hợp dùng để tập lắc vòng tại nhà cho nam nữ.', 'Vòng lắc eo bằng nhựa Hula Hoop được làm từ chất liệu nhựa ABS, gồm 8 miếng rời ghép lại với nhau và phù hợp dùng để tập lắc vòng tại nhà cho nam nữ.', 250000, 'phu-kien-tap-gym', 0, '{"Mã sản phẩm": "VLEBN", "Màu sắc": "Nhiều màu", "Chất liệu": "Nhựa ABS", "Trọng lượng vòng": "1.1 kg", "Đường kính vòng": "98cm", "Số lượng mảnh ghép": "8", "Kích thước hộp đựng": "42 x 24 x 7cm"}'::jsonb, 'https://baoansport.vn/phu-kien-tap-gym/vong-lac-eo-bang-nhua/'),
  ('ban-bong-ban-vnsport-mdf-08', 'BAS-1343', 'MDF-08', 'Bàn bóng bàn VnSport MDF-08', 'Bàn bóng bàn VnSport MDF-08 được thiết kế chắc chắn, mặt bàn có độ nảy chính xác ở tất cả mọi vị trí và đạt tiêu chuẩn thi đấu bóng bàn chuyên nghiệp.', 'Bàn bóng bàn VnSport MDF-08 được thiết kế chắc chắn, mặt bàn có độ nảy chính xác ở tất cả mọi vị trí và đạt tiêu chuẩn thi đấu bóng bàn chuyên nghiệp.', 7600000, 'ban-bong-ban', 0, '{"Mã sản phẩm": "MDF-08", "Màu sắc": "Xanh - trắng", "Chất liệu": "Thép, gỗ MDF", "Độ dày mặt bàn": "25mm", "Kích thước lắp đặt": "2740 x 1525 x 760 mm", "Kích thước vận chuyển": "Đang cập nhật", "Trọng lượng bàn": "Đang cập nhật", "Gập gọn": "Có", "Bánh xe di chuyển": "Có", "Khuyến mại": "Cọc lưới + bóng + vợt"}'::jsonb, 'https://baoansport.vn/ban-bong-ban/ban-bong-ban-vnsport-mdf-08/'),
  ('day-nhay-the-duc-fed-xm0105', 'BAS-1408', 'XM0105', 'Dây nhảy thể dục FED XM0105', 'Dây nhảy thể dục FED XM0105 được thiết kế đẹp mắt, phần tay cầm có trục bi giúp không bị xoắn dây khi nhảy và có thể điều chỉnh chiều dài dây dễ dàng.', 'Dây nhảy thể dục FED XM0105 được thiết kế đẹp mắt, phần tay cầm có trục bi giúp không bị xoắn dây khi nhảy và có thể điều chỉnh chiều dài dây dễ dàng.', 350000, 'dung-cu-tap-the-luc', 0, '{"Mã sản phẩm": "XM0105", "Màu sắc": "Đen - cam hoặc Đen", "Chất liệu": "Thép, nhôm, PVC", "Kích thước tay cầm": "163.5 x 16 mm", "Kích thước dây nhảy": "3m x 2.5mm", "Trọng lượng": "200 gram", "Kích thước hộp": "16.5 x 15 x 4 cm"}'::jsonb, 'https://baoansport.vn/dung-cu-tap-the-luc/day-nhay-the-duc-fed-xm0105/'),
  ('ban-bong-ban-vnsport-mdf-07', 'BAS-1344', 'MDF-07', 'Bàn bóng bàn VnSport MDF-07', 'Bàn bóng bàn VnSport MDF-07 có mặt bàn nhập khẩu chính hãng từ Trung Quốc, chân bàn sản xuất tại Việt Nam và đạt tiêu chuẩn tập luyện chuyên nghiệp.', 'Bàn bóng bàn VnSport MDF-07 có mặt bàn nhập khẩu chính hãng từ Trung Quốc, chân bàn sản xuất tại Việt Nam và đạt tiêu chuẩn tập luyện chuyên nghiệp.', 6500000, 'ban-bong-ban', 0, '{"Mã sản phẩm": "MDF-07", "Màu sắc": "Xanh - trắng", "Chất liệu": "Thép, gỗ MDF", "Độ dày mặt bàn": "18mm", "Kích thước lắp đặt": "2740 x 1525 x 760 mm", "Kích thước vận chuyển": "Đang cập nhật", "Trọng lượng bàn": "Đang cập nhật", "Gập gọn": "Có", "Bánh xe di chuyển": "Có", "Khuyến mại": "Cọc lưới + bóng + vợt"}'::jsonb, 'https://baoansport.vn/ban-bong-ban/ban-bong-ban-vnsport-mdf-07/'),
  ('bo-ta-tay-da-nang-fed', 'BAS-1396', 'FED', 'Bộ tạ tay đa năng FED', 'Bộ tạ tay đa năng FED được làm từ chất liệu gang mạ Niken bọc cao su, có 2 mức cân nặng gồm 20kg; 30kg và có thể tháo lắp tạ đơn hoặc tạ đòn dễ dàng.', 'Bộ tạ tay đa năng FED được làm từ chất liệu gang mạ Niken bọc cao su, có 2 mức cân nặng gồm 20kg; 30kg và có thể tháo lắp tạ đơn hoặc tạ đòn dễ dàng.', 2500000, 'ta-tay-ta-don', 20000, '{"Mã sản phẩm": "FED", "Màu sắc": "Đen, cam", "Chất liệu": "Gang mạ niken, cao su, nhựa ABS", "Trọng lượng": "20kg, 30kg", "Loại tạ": "Tháo lắp", "Hộp đựng": "Có", "Găng tay đi kèm": "Có"}'::jsonb, 'https://baoansport.vn/ta-tay-ta-don/bo-ta-tay-da-nang-fed/'),
  ('ban-bong-ban-kamito-premium', 'BAS-1346', 'Premium', 'Bàn bóng bàn Kamito Premium', 'Bàn bóng bàn Kamito Premium đạt tiêu chuẩn thi đấu Quốc tế, có mặt gỗ MDF 25mm chống lóa, khung thép chắc chắn, gập gọn dễ dàng, bền đẹp vượt trội.', 'Bàn bóng bàn Kamito Premium đạt tiêu chuẩn thi đấu Quốc tế, có mặt gỗ MDF 25mm chống lóa, khung thép chắc chắn, gập gọn dễ dàng, bền đẹp vượt trội.', 13000000, 'ban-bong-ban', 125000, '{"Mã sản phẩm": "Premium", "Màu sắc": "Xanh - xám", "Chất liệu": "Thép, gỗ MDF cao cấp", "Độ dày mặt bàn": "25mm", "Kích thước lắp đặt": "2740 x 1525 x 760 mm", "Kích thước vận chuyển": "Đang cập nhật", "Trọng lượng bàn": "125kg", "Gập gọn": "Có", "Bánh xe di chuyển": "Có", "Khuyến mại": "Cọc lưới + bóng"}'::jsonb, 'https://baoansport.vn/ban-bong-ban/ban-bong-ban-kamito-premium/'),
  ('bo-ta-da-nang-4-in-1', 'BAS-1347', 'BTDN', 'Bộ tạ đa năng 4 in 1', 'Bộ tạ đa năng 4 in 1 được chế tạo thông minh, có thể điều chỉnh thành tạ đơn; tạ đòn; tạ ấm hoặc dụng cụ hít đất và phù hợp sử dụng để tập thể hình tại nhà.', 'Bộ tạ đa năng 4 in 1 được chế tạo thông minh, có thể điều chỉnh thành tạ đơn; tạ đòn; tạ ấm hoặc dụng cụ hít đất và phù hợp sử dụng để tập thể hình tại nhà.', 1700000, 'ta-tay-ta-don', 20000, '{"Mã sản phẩm": "BTDN", "Màu sắc": "Đen - cam", "Trọng lượng": "20kg", "Loại tạ": "Tháo lắp", "Chất liệu": "Xi măng, sắt, thép, nhựa ABS, mút"}'::jsonb, 'https://baoansport.vn/ta-tay-ta-don/bo-ta-da-nang-4-in-1/'),
  ('xe-dap-phuc-hoi-chuc-nang-bc-51023', 'BAS-1348', 'BC-51023', 'Xe đạp phục hồi chức năng BC-51023', 'Xe đạp phục hồi chức năng BC-51023 được thiết kế chắc chắn, ghế ngồi có thêm yên tựa lưng và có chức năng hỗ trợ tập vận động cả chân lẫn tay hiệu quả.', 'Xe đạp phục hồi chức năng BC-51023 được thiết kế chắc chắn, ghế ngồi có thêm yên tựa lưng và có chức năng hỗ trợ tập vận động cả chân lẫn tay hiệu quả.', 5600000, 'xe-dap-tap-the-duc', 31500, '{"Mã sản phẩm": "BC-51023", "Màu sắc": "Ghi xám", "Chất liệu": "Thép, nhựa", "Trọng lượng bánh đà": "6 kg", "Trọng lượng xe": "31.5 kg", "Trọng lượng thùng": "35 kg", "Tải trọng tối đa": "120 kg", "Kích thước lắp đặt": "130 x 58 x 104 cm", "Kích thước thùng": "101 x 28.5 x 59 cm", "Yên xe": "Có", "Chuyển động": "Dây curoa + bánh đà", "Kháng lực": "8 mức", "Đo nhịp tim": "Có"}'::jsonb, 'https://baoansport.vn/xe-dap-tap-the-duc/xe-dap-phuc-hoi-chuc-nang-bc-51023/'),
  ('gang-tay-boxing-kangrui-kb348', 'BAS-1349', 'KB348', 'Găng tay Boxing Kangrui KB348', 'Găng tay Boxing Kangrui KB348 được thiết kế đẹp mắt, may chắc chắn từ chất liệu da PU kết hợp với lớp lót EVA và phù hợp dùng cho tập luyện võ thuật.', 'Găng tay Boxing Kangrui KB348 được thiết kế đẹp mắt, may chắc chắn từ chất liệu da PU kết hợp với lớp lót EVA và phù hợp dùng cho tập luyện võ thuật.', 650000, 'gang-tay-boxing', 0, '{"Mã sản phẩm": "KB348", "Màu sắc": "Đỏ - đen - vàng đồng và Xanh + xám + đen", "Chất liệu": "Da PU, EVA", "Trọng lượng": "10oz, 12oz", "Kích thước": "Đang cập nhật"}'::jsonb, 'https://baoansport.vn/gang-tay-boxing/gang-tay-boxing-kangrui-kb348/'),
  ('ta-dia-cao-su-phi-52', 'BAS-1350', 'TDP52', 'Tạ đĩa cao su phi 52 (60.000/Kg)', 'Tạ đĩa cao su phi 52 chính hãng được đúc đặc từ chất liệu thép, bên ngoài bọc cao su cao cấp cực dày, đường kính lỗ tạ phi 52 và có giá bán 60.000 đồng/kg.', 'Tạ đĩa cao su phi 52 chính hãng được đúc đặc từ chất liệu thép, bên ngoài bọc cao su cao cấp cực dày, đường kính lỗ tạ phi 52 và có giá bán 60.000 đồng/kg.', 60000, 'ta-tay-ta-don', 0, '{"Mã sản phẩm": "TDP52", "Màu sắc": "Đen - đỏ", "Chất liệu": "Thép, cao su", "Đường kính lỗ tạ": "Phi 52", "Trọng lượng tạ": "2.5kg; 5kg; 10kg; 15kg; 20kg"}'::jsonb, 'https://baoansport.vn/ta-tay-ta-don/ta-dia-cao-su-phi-52/'),
  ('bao-dam-boxing-fairtex-viet-nam', 'BAS-1351', 'BDFairtex', 'Bao đấm Boxing Fairtex Việt Nam', 'Mua bao đấm Boxing Fairtex Việt Nam chính hãng tại Bảo An Sport. Chất liệu da PU cao cấp, ruột EVA chắc chắn, chịu lực tốt, phù hợp tập Boxing, MMA.', 'Mua bao đấm Boxing Fairtex Việt Nam chính hãng tại Bảo An Sport. Chất liệu da PU cao cấp, ruột EVA chắc chắn, chịu lực tốt, phù hợp tập Boxing, MMA.', 2000000, 'bao-cat-dam-boc', 54000, '{"Mã sản phẩm": "BDFairtex", "Màu sắc": "Đen, đỏ", "Chất liệu": "Da PU, EVA, vải vụn", "Chiều cao": "1m2, 1m5, 1m6, 1m8", "Đường kính": "36 - 38cm", "Trọng lượng": "35 - 54kg"}'::jsonb, 'https://baoansport.vn/bao-cat-dam-boc/bao-dam-boxing-fairtex-viet-nam/'),
  ('ban-bong-ban-mofit-mplus-18', 'BAS-1461', 'MPlus-18', 'Bàn bóng bàn Mofit MPlus 18', 'Bàn bóng bàn Mofit MPlus 18 được nhập khẩu chính hãng từ Trung Quốc, mặt bàn làm từ gỗ MDF dày 18mm cho độ nảy chuẩn và chân thiết kế chắc chắn.', 'Bàn bóng bàn Mofit MPlus 18 được nhập khẩu chính hãng từ Trung Quốc, mặt bàn làm từ gỗ MDF dày 18mm cho độ nảy chuẩn và chân thiết kế chắc chắn.', 7650000, 'ban-bong-ban', 85000, '{"Mã sản phẩm": "MPlus-18", "Màu sắc": "Xanh - đen - xám", "Chất liệu": "Thép, gỗ MDF", "Độ dày mặt bàn": "18mm", "Kích thước lắp đặt": "2740 x 1525 x 760mm", "Kích thước đóng gói": "1600 x 1470 x 140mm", "Trọng lượng bàn": "85 kg", "Trọng lượng thùng": "88 kg", "Gập gọn": "Có", "Bánh xe di chuyển": "Có", "Cọc lưới đi kèm": "Có"}'::jsonb, 'https://baoansport.vn/ban-bong-ban/ban-bong-ban-mofit-mplus-18/'),
  ('thiet-bi-tap-keo-tay-vifa-sport-vifa-711112', 'BAS-1352', 'VIFA-711112', 'Thiết bị tập kéo tay Vifa Sport VIFA-711112', 'Thiết bị tập kéo tay Vifa Sport VIFA-711112 sản xuất hoàn toàn bằng thép, sử dụng sơn tĩnh điện ngoài trời cao cấp và hỗ trợ tập thể dục toàn thân hiệu quả.', 'Thiết bị tập kéo tay Vifa Sport VIFA-711112 sản xuất hoàn toàn bằng thép, sử dụng sơn tĩnh điện ngoài trời cao cấp và hỗ trợ tập thể dục toàn thân hiệu quả.', 37500000, 'dung-cu-the-thao-ngoai-troi', 124000, '{"Mã sản phẩm": "VIFA-711112", "Màu sắc": "Xanh - xám", "Chất liệu": "Thép, nhựa", "Trọng lượng máy": "124 kg", "Tải trọng tối đa": "105 kg", "Diện tích phù hợp": "1300 x 2800mm", "Kích thước lắp đặt": "2050 x 720 x 1970mm"}'::jsonb, 'https://baoansport.vn/dung-cu-the-thao-ngoai-troi/thiet-bi-tap-keo-tay-vifa-sport-vifa-711112/'),
  ('thiet-bi-tap-day-tay-vifa-sport-vifa-711122', 'BAS-1353', 'VIFA-711122', 'Thiết bị tập đẩy tay Vifa Sport VIFA-711122', 'Thiết bị tập đẩy tay Vifa Sport VIFA-711122 thiết kế theo tiêu chuẩn châu Âu, hỗ trợ tập cơ tay hiệu quả và chuyên dùng để lắp đặt cho công viên ngoài trời.', 'Thiết bị tập đẩy tay Vifa Sport VIFA-711122 thiết kế theo tiêu chuẩn châu Âu, hỗ trợ tập cơ tay hiệu quả và chuyên dùng để lắp đặt cho công viên ngoài trời.', 43000000, 'dung-cu-the-thao-ngoai-troi', 156000, '{"Mã sản phẩm": "VIFA-711122", "Màu sắc": "Xanh - xám", "Chất liệu": "Thép, nhựa", "Trọng lượng máy": "156 kg", "Tải trọng tối đa": "105 kg", "Diện tích phù hợp": "1300 x 3000mm", "Kích thước lắp đặt": "2000 x 740 x 2050mm"}'::jsonb, 'https://baoansport.vn/dung-cu-the-thao-ngoai-troi/thiet-bi-tap-day-tay-vifa-sport-vifa-711122/'),
  ('xa-don-gan-cua-2022', 'BAS-1340', 'XDGC2022', 'Xà đơn gắn cửa 2022', 'Xà đơn gắn cửa 2022 là mẫu xà đơn treo tường mới nhất hiện nay, tích hợp nhiều cải tiến vượt trội, đảm bảo chắc chắn và an toàn tuyệt đối cho người dùng.', 'Xà đơn gắn cửa 2022 là mẫu xà đơn treo tường mới nhất hiện nay, tích hợp nhiều cải tiến vượt trội, đảm bảo chắc chắn và an toàn tuyệt đối cho người dùng.', 350000, 'xa-don-xa-kep', 0, '{"Mã sản phẩm": "XDGC2022", "Màu sắc": "Đen - đỏ", "Chất liệu": "Thép, PVC, EVA", "Trọng lượng xà": "2.1 - 3.1kg", "Tải trọng tối đa": "180 kg", "Kích thước": "Có 3 kích thước"}'::jsonb, 'https://baoansport.vn/xa-don-xa-kep/xa-don-gan-cua-2022/'),
  ('dia-xoay-eo-nhua-thanh-xuan', 'BAS-1339', 'DXENTX', 'Đĩa xoay eo nhựa Thanh Xuân', 'Đĩa xoay eo nhựa Thanh Xuân được thiết kế nhỏ gọn, chuyển động trơn tru, khả năng chịu tải tốt và hỗ trợ các bài tập giúp giảm mỡ vòng eo tại nhà hiệu quả.', 'Đĩa xoay eo nhựa Thanh Xuân được thiết kế nhỏ gọn, chuyển động trơn tru, khả năng chịu tải tốt và hỗ trợ các bài tập giúp giảm mỡ vòng eo tại nhà hiệu quả.', 140000, 'phu-kien-tap-gym', 0, '{"Mã sản phẩm": "DXENTX", "Màu sắc": "Xanh, đen", "Chất liệu": "Nhựa, sắt", "Trọng lượng": "700 gram", "Tải trọng tối đa": "80 kg", "Kích thước đĩa xoay": "25.5 x 3cm", "Kích thước hộp đựng": "26 x 26 x 3.5cm"}'::jsonb, 'https://baoansport.vn/phu-kien-tap-gym/dia-xoay-eo-nhua-thanh-xuan/'),
  ('xa-don-treo-tuong-2021', 'BAS-1325', 'XD2021', 'Xà đơn treo tường 2021', 'Xà đơn treo tường 2021 được thiết kế chắc chắn, có khóa chống xoay và phù hợp dùng để tập tại nhà. Mua xà đơn gắn cửa 2021 giá rẻ ở Bảo An Sport.', 'Xà đơn treo tường 2021 được thiết kế chắc chắn, có khóa chống xoay và phù hợp dùng để tập tại nhà. Mua xà đơn gắn cửa 2021 giá rẻ ở Bảo An Sport.', 320000, 'xa-don-xa-kep', 0, '{"Mã sản phẩm": "XD2021", "Màu sắc": "Đen - đỏ", "Chất liệu": "Thép, nhựa, EVA", "Trọng lượng xà": "2 - 3kg", "Tải trọng tối đa": "150 kg", "Kích thước": "Có 3 kích thước"}'::jsonb, 'https://baoansport.vn/xa-don-xa-kep/xa-don-treo-tuong-2021/'),
  ('bo-ta-da-nang-dieu-chinh', 'BAS-1326', 'BTDNDC', 'Bộ tạ tay đa năng điều chỉnh', 'Bộ tạ tay đa năng điều chỉnh thiết kế có thể tháo lắp dễ dàng thành tạ tay hoặc tạ đòn; có các mức 20kg, 30kg, 40kg và phù hợp dùng tập tại nhà cho Gymer', 'Bộ tạ tay đa năng điều chỉnh thiết kế có thể tháo lắp dễ dàng thành tạ tay hoặc tạ đòn; có các mức 20kg, 30kg, 40kg và phù hợp dùng tập tại nhà cho Gymer', 550000, 'ta-tay-ta-don', 40000, '{"Mã sản phẩm": "BTDNDC", "Màu sắc": "Đen - vàng", "Chất liệu": "Bê tông, nhựa ABS", "Loại tạ": "Tháo lắp", "Trọng lượng": "20, 30, 40kg"}'::jsonb, 'https://baoansport.vn/ta-tay-ta-don/bo-ta-da-nang-dieu-chinh/'),
  ('giay-da-cau-thi-dau-nhap-khau', 'BAS-1544', 'GDCNK', 'Giày đá cầu thi đấu nhập khẩu', 'Giày đá cầu thi đấu được nhập khẩu từ Trung Quốc, may chắc chắn từ chất liệu da lộn đế cao su và có size từ 35 đến 44 dùng cho cả người lớn lẫn trẻ em.', 'Giày đá cầu thi đấu được nhập khẩu từ Trung Quốc, may chắc chắn từ chất liệu da lộn đế cao su và có size từ 35 đến 44 dùng cho cả người lớn lẫn trẻ em.', 350000, 'thiet-bi-day-hoc-the-duc', 0, '{"Mã sản phẩm": "GDCNK", "Màu sắc": "Đen trắng", "Chất liệu": "Da lộn, vải, cao su", "Size": "Từ 35 đến 44", "Trọng lượng": "≈ 350 gram"}'::jsonb, 'https://baoansport.vn/thiet-bi-day-hoc-the-duc/giay-da-cau-thi-dau-nhap-khau/'),
  ('may-chay-bo-sakura-s33', 'BAS-1327', 'S33', 'Máy chạy bộ Sakura S33', 'Máy chạy bộ Sakura S33 được thiết kế đa năng, sử dụng động cơ DC có công suất 2.5Hp và hỗ trợ tập chạy bộ, gập bụng, massage giúp giảm cân hiệu quả.', 'Máy chạy bộ Sakura S33 được thiết kế đa năng, sử dụng động cơ DC có công suất 2.5Hp và hỗ trợ tập chạy bộ, gập bụng, massage giúp giảm cân hiệu quả.', 13500000, 'may-chay-bo', 73000, '{"Mã sản phẩm": "S33", "Màu sắc": "Đen - xám - cam", "Điện áp": "220V, 50-60Hz", "Động cơ": "DC", "Công suất": "2.5Hp", "Tốc độ": "1.0 - 16 km/h", "Nâng độ dốc": "0 đến 15%", "Trọng lượng máy": "73 kg", "Trọng lượng thùng": "80 kg", "Tải trọng tối đa": "110 kg", "Độ rộng bàn chạy": "48 cm", "Kích thước lắp đặt": "188 x 80 x 140 cm", "Kích thước gập gọn": "110 x 80 x 160 cm", "Kích thước thùng": "178 x 77 x 33 cm", "Màn hình": "LCD", "Thảm chạy": "Diamond Running Belt", "Giảm chấn": "Đệm cao su", "Khóa an toàn": "Có", "Gập gọn": "Có", "Bánh xe di chuyển": "Có", "Âm thanh": "Loa Hi-Fi"}'::jsonb, 'https://baoansport.vn/may-chay-bo/may-chay-bo-sakura-s33/'),
  ('xe-dap-tap-the-duc-doufit-eb-09', 'BAS-1328', 'EB-09', 'Xe đạp tập thể dục Doufit EB-09', 'Xe đạp tập thể dục Doufit EB-09 cao cấp được thiết kế đẹp mắt, hỗ trợ các bài tập đạp xe tại nhà giúp giảm cân nhanh và phù hợp sử dụng cho hộ gia đình.', 'Xe đạp tập thể dục Doufit EB-09 cao cấp được thiết kế đẹp mắt, hỗ trợ các bài tập đạp xe tại nhà giúp giảm cân nhanh và phù hợp sử dụng cho hộ gia đình.', 4800000, 'xe-dap-tap-the-duc', 26000, '{"Mã sản phẩm": "EB-09", "Màu sắc": "Đen - vàng", "Chất liệu": "Thép, nhựa", "Trọng lượng bánh đà": "8 kg", "Trọng lượng xe": "26 kg", "Trọng lượng thùng": "30 kg", "Tải trọng tối đa": "120 kg", "Kích thước lắp đặt": "95 x 54 x 120 cm", "Kích thước thùng": "92 x 23 x 104 cm", "Yên xe": "Có", "Chuyển động": "Dây curoa + bánh đà", "Kháng lực": "Nhiều mức", "Đo nhịp tim": "Có"}'::jsonb, 'https://baoansport.vn/xe-dap-tap-the-duc/xe-dap-tap-the-duc-doufit-eb-09/'),
  ('tru-bong-chuyen-di-dong-td-02', 'BAS-1329', 'TD-02', 'Trụ bóng chuyền di động TD-02', 'Trụ bóng chuyền di động TD-02 được thiết kế chắc chắn, có chức năng điều chỉnh độ cao lưới dễ dàng khi lắp đặt và phù hợp dùng cho cơ quan, trường học.', 'Trụ bóng chuyền di động TD-02 được thiết kế chắc chắn, có chức năng điều chỉnh độ cao lưới dễ dàng khi lắp đặt và phù hợp dùng cho cơ quan, trường học.', 7800000, 'tru-luoi-bong-chuyen', 0, '{"Mã sản phẩm": "TD-02", "Màu sắc": "Trắng", "Chất liệu": "Thép", "Chiều cao điều chỉnh": "2m25 và 2m44", "Đối trọng": "40 kg/cục", "Số lượng đối trọng": "4", "Kích thước lắp đặt": "60 x 84 x 244 cm", "Kiểu trụ": "Di động", "Tay quay căng lưới": "Có", "Bánh xe di chuyển": "Có"}'::jsonb, 'https://baoansport.vn/tru-luoi-bong-chuyen/tru-bong-chuyen-di-dong-td-02/'),
  ('ghe-tap-vai-impulse-it7031', 'BAS-1331', 'IT7031', 'Ghế tập vai Impulse IT7031', 'Ghế tập vai Impulse IT7031 chính hãng được thiết kế chắc chắn, hỗ trợ các bài tập giúp phát triển cơ vai hiệu quả và phù hợp dùng cho phòng Gym cao cấp.', 'Ghế tập vai Impulse IT7031 chính hãng được thiết kế chắc chắn, hỗ trợ các bài tập giúp phát triển cơ vai hiệu quả và phù hợp dùng cho phòng Gym cao cấp.', 12000000, 'thiet-bi-phong-gym', 86500, '{"Mã sản phẩm": "IT7031", "Màu sắc": "Xám bạc", "Chất liệu": "Thép, nệm da", "Trọng lượng ghế": "86.5 kg", "Tải trọng tối đa": "300 kg", "Kích thước lắp đặt": "1349 x 1126 x 1651 mm", "Kích thước thùng": "Đang cập nhật"}'::jsonb, 'https://baoansport.vn/thiet-bi-phong-gym/ghe-tap-vai-impulse-it7031/'),
  ('ghe-nam-day-nguc-duoi-impulse-it7016', 'BAS-1332', 'IT7016', 'Ghế nằm đẩy ngực dưới Impulse IT7016', 'Ghế nằm đẩy ngực dưới Impulse IT7016 được thiết kế chắc chắn, hỗ trợ bài tập giúp phát triển cơ ngực hiệu quả và chuyên dùng để lắp đặt cho phòng Gym.', 'Ghế nằm đẩy ngực dưới Impulse IT7016 được thiết kế chắc chắn, hỗ trợ bài tập giúp phát triển cơ ngực hiệu quả và chuyên dùng để lắp đặt cho phòng Gym.', 16200000, 'thiet-bi-phong-gym', 72000, '{"Mã sản phẩm": "IT7016", "Màu sắc": "Xám bạc", "Chất liệu": "Thép, nệm da", "Trọng lượng ghế": "72 kg", "Tải trọng tối đa": "300 kg", "Kích thước lắp đặt": "2103 x 1658 x 1370 mm", "Kích thước thùng": "Đang cập nhật"}'::jsonb, 'https://baoansport.vn/thiet-bi-phong-gym/ghe-nam-day-nguc-duoi-impulse-it7016/'),
  ('ban-bong-ban-vnsport-mdf-05-18mm', 'BAS-1333', 'MDF-05', 'Bàn bóng bàn VnSport MDF-05 18mm', 'Bàn bóng bàn VnSport MDF-05 18mm chính hãng được thiết kế chắc chắn, mặt bàn cho độ nảy chuẩn và chân bàn có chức năng xếp gọn sau khi chơi xong.', 'Bàn bóng bàn VnSport MDF-05 18mm chính hãng được thiết kế chắc chắn, mặt bàn cho độ nảy chuẩn và chân bàn có chức năng xếp gọn sau khi chơi xong.', 5000000, 'ban-bong-ban', 0, '{"Mã sản phẩm": "MDF-05", "Màu sắc": "Xanh - trắng - đen", "Chất liệu": "Thép, gỗ MDF", "Độ dày mặt bàn": "18mm", "Kích thước lắp đặt": "2740 x 1525 x 760 mm", "Kích thước vận chuyển": "1600 x 1470 x 120 mm", "Trọng lượng bàn": "Đang cập nhật", "Gập gọn": "Có", "Bánh xe di chuyển": "Có", "Khuyến mại": "Cọc lưới + bóng + vợt"}'::jsonb, 'https://baoansport.vn/ban-bong-ban/ban-bong-ban-vnsport-mdf-05-18mm/'),
  ('ban-bong-ban-vnsport-mdf-06-25mm', 'BAS-1334', 'MDF-06', 'Bàn bóng bàn VnSport MDF-06 25mm', 'Bàn bóng bàn VnSport MDF-06 25mm được thiết kế chắc chắn, cho độ nảy bóng chuẩn đều ở tất cả mọi vị trí và có khả năng gập gọn lại sau khi chơi xong.', 'Bàn bóng bàn VnSport MDF-06 25mm được thiết kế chắc chắn, cho độ nảy bóng chuẩn đều ở tất cả mọi vị trí và có khả năng gập gọn lại sau khi chơi xong.', 5500000, 'ban-bong-ban', 0, '{"Mã sản phẩm": "MDF-06", "Màu sắc": "Xanh - trắng - đen", "Chất liệu": "Thép, gỗ MDF", "Độ dày mặt bàn": "25mm", "Kích thước lắp đặt": "2740 x 1525 x 760 mm", "Kích thước vận chuyển": "1600 x 1470 x 130 mm", "Trọng lượng bàn": "Đang cập nhật", "Gập gọn": "Có", "Bánh xe di chuyển": "Có", "Khuyến mại": "Cọc lưới + bóng + vợt"}'::jsonb, 'https://baoansport.vn/ban-bong-ban/ban-bong-ban-vnsport-mdf-06-25mm/'),
  ('ban-bong-ban-vinasport-mdf-01', 'BAS-1313', 'MDF-01', 'Bàn bóng bàn VinaSport MDF-01', 'Bàn bóng bàn VinaSport MDF-01 được thiết kế chắc chắn, mặt bàn độ nảy chính xác, đạt tiêu chuẩn tập luyện và phù hợp dùng cho gia đình hoặc chung cư', 'Bàn bóng bàn VinaSport MDF-01 được thiết kế chắc chắn, mặt bàn độ nảy chính xác, đạt tiêu chuẩn tập luyện và phù hợp dùng cho gia đình hoặc chung cư', 3850000, 'ban-bong-ban', 0, '{"Mã sản phẩm": "MDF-01", "Màu sắc": "Xanh - đen", "Chất liệu": "Thép, gỗ MDF", "Độ dày mặt bàn": "18mm", "Kích thước lắp đặt": "2740 x 1525 x 760 mm", "Kích thước vận chuyển": "1600 x 1470 x 110 mm", "Trọng lượng bàn": "Đang cập nhật", "Gập gọn": "Có", "Bánh xe di chuyển": "Có", "Khuyến mại": "Cọc lưới, hộp bóng"}'::jsonb, 'https://baoansport.vn/ban-bong-ban/ban-bong-ban-vinasport-mdf-01/'),
  ('don-tay-tay-35cm-cao-cap', 'BAS-1335', 'DTTCC', 'Đòn tạ tay 35cm cao cấp', 'Đòn tạ tay 35cm cao cấp được làm từ chất liệu thép chống rỉ mạ inox, phần tay cầm bọc cao su giúp cầm nắm chắc hơn và hai đầu có khóa tạ dạng ren vặn.', 'Đòn tạ tay 35cm cao cấp được làm từ chất liệu thép chống rỉ mạ inox, phần tay cầm bọc cao su giúp cầm nắm chắc hơn và hai đầu có khóa tạ dạng ren vặn.', 150000, 'ta-tay-ta-don', 1800, '{"Mã sản phẩm": "DTTCC", "Màu sắc": "Bạc - xanh - đen", "Chất liệu": "Thép, cao su", "Chiều dài": "35 cm", "Trọng lượng": "1.8 kg"}'::jsonb, 'https://baoansport.vn/ta-tay-ta-don/don-tay-tay-35cm-cao-cap/'),
  ('bao-dam-qua-tao-mma-everlast', 'BAS-1336', 'BDQT', 'Bao đấm quả táo MMA Everlast', 'Bao đấm quả táo MMA Everlast được may chắc chắn từ chất liệu da xịn, bên trong nhồi bằng EVA kết hợp với vải vụn và có xích treo đi kèm rất tiện dụng.', 'Bao đấm quả táo MMA Everlast được may chắc chắn từ chất liệu da xịn, bên trong nhồi bằng EVA kết hợp với vải vụn và có xích treo đi kèm rất tiện dụng.', 1850000, 'bao-cat-dam-boc', 24000, '{"Mã sản phẩm": "BDQT", "Màu sắc": "Đen", "Chất liệu": "Da, EVA, vải vụn", "Chiều cao": "100 cm", "Đường kính": "44 cm", "Trọng lượng": "23-24 kg"}'::jsonb, 'https://baoansport.vn/bao-cat-dam-boc/bao-dam-qua-tao-mma-everlast/'),
  ('dia-xoay-eo-sat-thanh-xuan', 'BAS-1338', 'XESTX', 'Đĩa xoay eo sắt Thanh Xuân', 'Đĩa xoay eo sắt Thanh Xuân được thiết kế chắc chắn, chuyển động trơn tru, khả năng chịu lực tốt và có chức năng hỗ trợ tập giảm mỡ bụng tại nhà hiệu quả.', 'Đĩa xoay eo sắt Thanh Xuân được thiết kế chắc chắn, chuyển động trơn tru, khả năng chịu lực tốt và có chức năng hỗ trợ tập giảm mỡ bụng tại nhà hiệu quả.', 220000, 'phu-kien-tap-gym', 1400, '{"Mã sản phẩm": "XESTX", "Màu sắc": "Xanh, tím", "Chất liệu": "Sắt, cao su", "Trọng lượng": "1.4 kg", "Tải trọng tối đa": "120 kg", "Kích thước đĩa xoay": "28 x 2.5cm", "Kích thước hộp đựng": "28.5 x 28.5 x 3cm"}'::jsonb, 'https://baoansport.vn/phu-kien-tap-gym/dia-xoay-eo-sat-thanh-xuan/'),
  ('dung-cu-tap-tay-vai-don-vifa-sport-vifa-711132', 'BAS-1354', 'VIFA-711132', 'Dụng cụ tập tay vai đơn Vifa Sport VIFA-711132', 'Dụng cụ tập tay vai đơn Vifa Sport VIFA-711132 được thiết kế chắc chắn, hỗ trợ hai người tập cùng một thời điểm và có chức năng tập cơ tay, vai hiệu quả.', 'Dụng cụ tập tay vai đơn Vifa Sport VIFA-711132 được thiết kế chắc chắn, hỗ trợ hai người tập cùng một thời điểm và có chức năng tập cơ tay, vai hiệu quả.', 13900000, 'dung-cu-the-thao-ngoai-troi', 0, '{"Mã sản phẩm": "VIFA-711132", "Màu sắc": "Xanh - xám", "Chất liệu": "Thép, nhựa", "Trọng lượng máy": "Đang cập nhật", "Diện tích phù hợp": "1500 x 1500mm", "Kích thước lắp đặt": "930 x 830 x 1820mm (±3%)"}'::jsonb, 'https://baoansport.vn/dung-cu-the-thao-ngoai-troi/dung-cu-tap-tay-vai-don-vifa-sport-vifa-711132/'),
  ('vot-bong-ban-729-2060-carbon', 'BAS-1507', '2060-Carbon', 'Vợt bóng bàn 729 2060 Carbon', 'Vợt bóng bàn 729 2060 Carbon có cốt làm từ gỗ tự nhiên kết hợp với carbon, mặt vợt mềm dễ kiểm soát bóng khi chơi và phù hợp sử dụng cho chơi căn bản.', 'Vợt bóng bàn 729 2060 Carbon có cốt làm từ gỗ tự nhiên kết hợp với carbon, mặt vợt mềm dễ kiểm soát bóng khi chơi và phù hợp sử dụng cho chơi căn bản.', 350000, 'vot-bong-ban', 0, '{"Mã sản phẩm": "2060-Carbon", "Màu sắc": "Đỏ - đen", "Chất liệu": "Gỗ, mút cao su", "Độ dày mặt vợt": "14mm", "Kích thước mặt": "15.5 x 15cm", "Chiều dài cán vợt": "10cm", "Trọng lượng vợt": "250 gram", "Túi đựng vợt": "Có", "Bóng đi kèm": "Có"}'::jsonb, 'https://baoansport.vn/vot-bong-ban/vot-bong-ban-729-2060-carbon/'),
  ('xa-don-tre-em', 'BAS-1526', 'XDTE', 'Xà đơn trẻ em', 'Xà đơn trẻ em được làm chắc chắn từ thép ống phi 27, thiết kế chân choãi rộng, dễ dàng điều chỉnh độ cao khi tập và phù hợp dùng cho bé từ 3 đến 10 tuổi.', 'Xà đơn trẻ em được làm chắc chắn từ thép ống phi 27, thiết kế chân choãi rộng, dễ dàng điều chỉnh độ cao khi tập và phù hợp dùng cho bé từ 3 đến 10 tuổi.', 1250000, 'xa-don-xa-kep', 8500, '{"Mã sản phẩm": "XDTE", "Màu sắc": "Xanh - xám", "Chất liệu": "Thép, mút", "Trọng lượng xà": "7.5kg", "Trọng lượng thùng": "8.5kg", "Tải trọng tập tối đa": "60kg", "Chiều cao điều chỉnh": "70 đến 130cm", "Kích thước lắp đặt": "100 x 147cm", "Kích thước thùng": "105 x 30 x 13cm"}'::jsonb, 'https://baoansport.vn/xa-don-xa-kep/xa-don-tre-em/'),
  ('dung-cu-hit-dat-perfect-push-up', 'BAS-1527', 'Perfect-Push-Up', 'Dụng cụ hít đất Perfect Push Up', 'Dụng cụ hít đất Perfect Push Up được làm chắc chắn từ nhựa ABS, có khả năng xoay cổ tay khi tập và phù hợp sử dụng cho các bài tập chống đẩy tại nhà.', 'Dụng cụ hít đất Perfect Push Up được làm chắc chắn từ nhựa ABS, có khả năng xoay cổ tay khi tập và phù hợp sử dụng cho các bài tập chống đẩy tại nhà.', 350000, 'phu-kien-tap-gym', 1600, '{"Mã sản phẩm": "Perfect-Push-Up", "Màu sắc": "Đen đỏ", "Chất liệu": "Nhựa ABS, Inox", "Trọng lượng": "1.6kg", "Trọng lượng hộp": "1.8kg", "Tải trọng tập tối đa": "120kg", "Kích thước 1 bên": "20 x 11cm", "Kích thước hộp": "32 x 12 x 20cm"}'::jsonb, 'https://baoansport.vn/phu-kien-tap-gym/dung-cu-hit-dat-perfect-push-up/'),
  ('khung-ganh-ta-da-nang-tk-03', 'BAS-1528', 'KB-783', 'Khung gánh tạ đa năng TK-03 (KB-783)', 'Khung gánh tạ đa năng TK-03 (KB-783) thiết kế chắc chắn, điều chỉnh độ cao dễ dàng và hỗ trợ nhiều bài tập gồm Squat, tập xà đơn, tập xà kép, nằm đẩy ngực.', 'Khung gánh tạ đa năng TK-03 (KB-783) thiết kế chắc chắn, điều chỉnh độ cao dễ dàng và hỗ trợ nhiều bài tập gồm Squat, tập xà đơn, tập xà kép, nằm đẩy ngực.', 2250000, 'ghe-tap-ta', 21000, '{"Mã sản phẩm": "KB-783", "Màu sắc": "Đen đỏ", "Chất liệu": "Thép, nhựa PVC", "Trọng lượng": "21kg", "Trọng lượng thùng": "22.5kg", "Tải trọng tối đa": "200kg", "Kích thước thùng": "122 x 23 x 33cm", "Kích thước lắp đặt": "119 x 113 x 231cm", "Chiều cao xà tối đa": "226cm"}'::jsonb, 'https://baoansport.vn/ghe-tap-ta/khung-ganh-ta-da-nang-tk-03/'),
  ('kim-bop-tay-dieu-chinh-100kg', 'BAS-1530', 'KBTDC', 'Kìm bóp tay điều chỉnh 10-100Kg', 'Kìm bóp tay điều chỉnh 10-100kg được làm chắc chắn, lực bóp khi tập có thể điều chỉnh dễ dàng từ 10 đến 100kg và trang bị thêm đồng hồ hiển thị số lần tập.', 'Kìm bóp tay điều chỉnh 10-100kg được làm chắc chắn, lực bóp khi tập có thể điều chỉnh dễ dàng từ 10 đến 100kg và trang bị thêm đồng hồ hiển thị số lần tập.', 130000, 'dung-cu-tap-the-luc', 0, '{"Mã sản phẩm": "KBTDC", "Màu sắc": "Đen, xanh dương, xanh rêu", "Chất liệu": "Thép, nhựa", "Trọng lượng": "300 gram", "Lực đàn hồi": "10-100kg", "Kích thước": "16 x 14.5cm", "Kích thước hộp": "18 x 14 x 3cm"}'::jsonb, 'https://baoansport.vn/dung-cu-tap-the-luc/kim-bop-tay-dieu-chinh-100kg/'),
  ('ghe-bang-tap-ta-kingbox-ac-5001', 'BAS-1531', 'AC-5001', 'Ghế băng tập tạ KingBox AC-5001', 'Ghế băng tập tạ Kingbox AC-5001 được thiết kế nhỏ gọn, có khả năng gấp gọn dễ dàng sau khi tập xong và phù hợp dùng để tập tại nhà cho anh em Gymer.', 'Ghế băng tập tạ Kingbox AC-5001 được thiết kế nhỏ gọn, có khả năng gấp gọn dễ dàng sau khi tập xong và phù hợp dùng để tập tại nhà cho anh em Gymer.', 650000, 'ghe-tap-ta', 7500, '{"Mã sản phẩm": "AC-5001", "Màu sắc": "Đen đỏ", "Chất liệu": "Thép, da PU", "Trọng lượng": "7.5kg", "Tải trọng tối đa": "150kg", "Kích thước lắp đặt": "108 x 29 x 42cm", "Kích thước đóng gói": "108 x 32 x 14cm"}'::jsonb, 'https://baoansport.vn/ghe-tap-ta/ghe-bang-tap-ta-kingbox-ac-5001/'),
  ('ban-bong-ban-rainbow-harito-1000', 'BAS-1532', 'RH1000', 'Bàn bóng bàn Rainbow Harito 1000', 'Bàn bóng bàn Rainbow Harito 1000 được thiết kế đẹp mắt, đạt tiêu chuẩn của liên đoàn bóng bàn thế giới ITTF và phù hợp dùng cho thi đấu chuyên nghiệp.', 'Bàn bóng bàn Rainbow Harito 1000 được thiết kế đẹp mắt, đạt tiêu chuẩn của liên đoàn bóng bàn thế giới ITTF và phù hợp dùng cho thi đấu chuyên nghiệp.', 23500000, 'ban-bong-ban', 137000, '{"Mã sản phẩm": "RH1000", "Chất liệu": "Gỗ MDF, thép", "Độ dày mặt bàn": "25mm", "Kích thước lắp đặt": "2740 x 1525 x 760mm", "Trọng lượng bàn": "137kg", "Trọng lượng đóng thùng": "145kg", "Cọc lưới đi kèm": "Có", "Khả năng gập gọn": "Không"}'::jsonb, 'https://baoansport.vn/ban-bong-ban/ban-bong-ban-rainbow-harito-1000/'),
  ('xe-dap-tap-the-duc-pro-580r', 'BAS-1533', 'Pro-580R', 'Xe đạp tập thể dục Pro-580R', 'Xe đạp tập thể dục Pro-580R được thiết kế chắc chắn, ghế ngồi có yên tựa lưng, chuyển động bằng dây curoa cực êm và hỗ trợ tập cả tay lẫn chân hiệu quả.', 'Xe đạp tập thể dục Pro-580R được thiết kế chắc chắn, ghế ngồi có yên tựa lưng, chuyển động bằng dây curoa cực êm và hỗ trợ tập cả tay lẫn chân hiệu quả.', 5800000, 'xe-dap-tap-the-duc', 31500, '{"Mã sản phẩm": "Pro-580R", "Màu sắc": "Xám - đen", "Chất liệu": "Thép, nhựa", "Trọng lượng bánh đà": "3 kg", "Trọng lượng xe": "31.5 kg", "Trọng lượng thùng": "35 kg", "Tải trọng tối đa": "100 kg", "Kích thước lắp đặt": "139 x 67 x 115cm", "Kích thước thùng": "142 x 25 x 58cm", "Yên xe tựa lưng": "Có", "Chuyển động": "Dây curoa + bánh đà", "Kháng lực": "8 mức", "Đo nhịp tim": "Có"}'::jsonb, 'https://baoansport.vn/xe-dap-tap-the-duc/xe-dap-tap-the-duc-pro-580r/'),
  ('ghe-tap-ta-dds-7002', 'BAS-1534', 'DDS-7302', 'Ghế tập tạ DDS-7002 (DDS-7302)', 'Ghế tập tạ DDS-7002 (DDS-7302) thiết kế chắc chắn, khoảng đỡ đòn tạ rộng, yên ghế điều chỉnh dễ dàng và hỗ trợ rất nhiều bài tập thể hình hiệu quả cho Gymer.', 'Ghế tập tạ DDS-7002 (DDS-7302) thiết kế chắc chắn, khoảng đỡ đòn tạ rộng, yên ghế điều chỉnh dễ dàng và hỗ trợ rất nhiều bài tập thể hình hiệu quả cho Gymer.', 5050000, 'ghe-tap-ta', 35300, '{"Mã sản phẩm": "DDS-7302", "Màu sắc": "Đen, vàng nâu", "Chất liệu": "Thép, mút da", "Trọng lượng ghế": "35,3kg", "Trọng lượng thùng": "39kg", "Tải trọng tối đa": "250kg", "Kích thước lắp đặt": "170 x 105 x 138cm", "Kích thước thùng": "113 x 73,5 x 22,5cm"}'::jsonb, 'https://baoansport.vn/ghe-tap-ta/ghe-tap-ta-dds-7002/'),
  ('kim-bop-tay-dieu-chinh-10-120kg', 'BAS-1536', 'KBT120', 'Kìm bóp tay điều chỉnh 10-120Kg', 'Kìm bóp tay điều chỉnh 10-120Kg được làm từ chất liệu lõi thép bọc nhựa, lò xo có độ đàn hồi cao và trang bị núm xoay điều chỉnh lực bóp từ 10 đến 120kg.', 'Kìm bóp tay điều chỉnh 10-120Kg được làm từ chất liệu lõi thép bọc nhựa, lò xo có độ đàn hồi cao và trang bị núm xoay điều chỉnh lực bóp từ 10 đến 120kg.', 120000, 'dung-cu-tap-the-luc', 0, '{"Mã sản phẩm": "KBT120", "Màu sắc": "Đen; xanh lá; đen cam", "Chất liệu": "Thép, nhựa", "Lực đàn hồi": "10-120Kg", "Kích thước hộp": "15 x 12 x 3cm"}'::jsonb, 'https://baoansport.vn/dung-cu-tap-the-luc/kim-bop-tay-dieu-chinh-10-120kg/'),
  ('vot-bong-ban-729-very-6-sao', 'BAS-1537', 'Very-6-sao', 'Vợt bóng bàn 729 Very 6 sao', 'Vợt bóng bàn 729 Very 6 sao (6 Star) chính hãng có tay cầm chắc chắn, mút mềm, dễ kiểm soát khi chơi và phù hợp sử dụng với lối đánh công thủ toàn diện.', 'Vợt bóng bàn 729 Very 6 sao (6 Star) chính hãng có tay cầm chắc chắn, mút mềm, dễ kiểm soát khi chơi và phù hợp sử dụng với lối đánh công thủ toàn diện.', 480000, 'vot-bong-ban', 0, '{"Mã sản phẩm": "Very-6-sao", "Màu sắc": "Đen - đỏ", "Chất liệu": "Gỗ, carbon, mút cao su", "Độ dày mặt vợt": "2.1mm", "Kích thước mặt": "15.5 x 15cm", "Chiều dài cán vợt": "10cm", "Túi đựng vợt": "Có", "Bóng đi kèm": "2 quả"}'::jsonb, 'https://baoansport.vn/vot-bong-ban/vot-bong-ban-729-very-6-sao/'),
  ('vot-bong-ban-729-very-9-sao', 'BAS-1538', 'Very-9-sao', 'Vợt bóng bàn 729 Very 9 sao', 'Vợt bóng bàn 729 Very 9 sao (9 Star) thuộc dòng vợt dán sẵn của thương hiệu 729, dễ dàng điều khiển khi đánh và phù hợp với người chơi công thủ toàn diện.', 'Vợt bóng bàn 729 Very 9 sao (9 Star) thuộc dòng vợt dán sẵn của thương hiệu 729, dễ dàng điều khiển khi đánh và phù hợp với người chơi công thủ toàn diện.', 1150000, 'vot-bong-ban', 0, '{"Mã sản phẩm": "Very-9-sao", "Màu sắc": "Đen - đỏ", "Chất liệu": "Gỗ, carbon, mút cao su", "Độ dày mặt vợt": "2.1mm", "Kích thước mặt": "15.5 x 15cm", "Chiều dài cán vợt": "10cm", "Túi đựng vợt": "Có", "Bóng đi kèm": "Không"}'::jsonb, 'https://baoansport.vn/vot-bong-ban/vot-bong-ban-729-very-9-sao/'),
  ('gian-ta-da-nang-jl-k12', 'BAS-1541', 'JL-K12', 'Giàn tạ đa năng JL-K12', 'Giàn tạ đa năng JL-K12 được thiết kế chắc chắn, trang bị ghế tập tạ đi kèm và hỗ trợ nhiều bài tập Gym hiệu quả như gánh tạ, đẩy ngực, tập xà đơn, xà kép,...', 'Giàn tạ đa năng JL-K12 được thiết kế chắc chắn, trang bị ghế tập tạ đi kèm và hỗ trợ nhiều bài tập Gym hiệu quả như gánh tạ, đẩy ngực, tập xà đơn, xà kép,...', 22000000, 'gian-ta-da-nang', 255000, '{"Mã sản phẩm": "JL-K12", "Màu sắc": "Đen, cam", "Chất liệu": "Thép, mút, da PU", "Trọng lượng cả bộ": "255kg", "Trọng lượng tạ 2 bên": "90kg", "Tải trọng tập tối đa": "500kg", "Kích thước lắp đặt": "220 x 183 x 215cm", "Kích thước hộp": "Đang cập nhật", "Ghế tập đi kèm": "Có", "Đòn tạ đi kèm": "1 (lắp vào khung gánh)"}'::jsonb, 'https://baoansport.vn/gian-ta-da-nang/gian-ta-da-nang-jl-k12/'),
  ('xe-dap-tap-the-duc-zasami-kz-6511', 'BAS-1542', 'KZ-6511', 'Xe đạp tập thể dục Zasami KZ-6511', 'Xe đạp tập thể dục Zasami KZ-6511 thiết kế đẹp mắt, yên có thể điều chỉnh cao thấp - trước sau và hỗ trợ tập vận động toàn thân cả chân lẫn tay hiệu quả.', 'Xe đạp tập thể dục Zasami KZ-6511 thiết kế đẹp mắt, yên có thể điều chỉnh cao thấp - trước sau và hỗ trợ tập vận động toàn thân cả chân lẫn tay hiệu quả.', 3000000, 'xe-dap-tap-the-duc', 17500, '{"Mã sản phẩm": "KZ-6511", "Màu sắc": "Xám xanh", "Chất liệu": "Thép, nhựa", "Trọng lượng xe": "17.5kg", "Trọng lượng thùng": "20.5kg", "Tải trọng tối đa": "90kg", "Kích thước lắp đặt": "100 x 46 x 116cm", "Kích thước thùng": "138 x 37 x 58.5cm", "Yên xe": "Có", "Chuyển động": "Dây xích", "Đo nhịp tim": "Đo nhịp tim"}'::jsonb, 'https://baoansport.vn/xe-dap-tap-the-duc/xe-dap-tap-the-duc-zasami-kz-6511/'),
  ('luoi-bong-chuyen-thi-dau-412010', 'BAS-1525', '412010', 'Lưới bóng chuyền thi đấu 412010', 'Lưới bóng chuyền thi đấu 412010 của Vifa Sport được đan bằng tay từ sợi CPE 1.9mm, có khả năng chống tia UV và phù hợp dùng trong nhà lẫn ngoài trời.', 'Lưới bóng chuyền thi đấu 412010 của Vifa Sport được đan bằng tay từ sợi CPE 1.9mm, có khả năng chống tia UV và phù hợp dùng trong nhà lẫn ngoài trời.', 660000, 'tru-luoi-bong-chuyen', 0, '{"Mã sản phẩm": "412010", "Màu sắc": "Đen - trắng", "Chất liệu": "Sợi CPE, PVC", "Kích thước ô lưới": "100 x 100mm", "Tỷ trọng sợi": "1.8 gram/m", "Đường kính sợi": "1.9mm", "Trọng lượng lưới": "Đang cập nhật"}'::jsonb, 'https://baoansport.vn/tru-luoi-bong-chuyen/luoi-bong-chuyen-thi-dau-412010/'),
  ('vot-bong-ban-729-4star', 'BAS-1524', '4Star', 'Vợt bóng bàn 729 4Star', 'Vợt bóng bàn 729 4Star được dán sẵn mút có tính đàn hồi cao, phù hợp dùng cho lối đánh tấn công và tay cầm thiết kế vừa vặn, dễ dàng điều khiển khi chơi.', 'Vợt bóng bàn 729 4Star được dán sẵn mút có tính đàn hồi cao, phù hợp dùng cho lối đánh tấn công và tay cầm thiết kế vừa vặn, dễ dàng điều khiển khi chơi.', 300000, 'vot-bong-ban', 0, '{"Mã sản phẩm": "4Star", "Màu sắc": "Đỏ - đen", "Chất liệu": "Gỗ, mút cao su", "Độ dày cốt vợt": "7mm", "Kích thước mặt": "15.5 x 15cm", "Chiều dài cán vợt": "10cm", "Trọng lượng vợt": "250 gram", "Túi đựng vợt": "Có", "Bóng đi kèm": "Không"}'::jsonb, 'https://baoansport.vn/vot-bong-ban/vot-bong-ban-729-4star/'),
  ('vot-bong-ban-729-3star', 'BAS-1523', '3Star', 'Vợt bóng bàn 729 3Star', 'Vợt bóng bàn 729 3Star chính hãng được dán sẵn mút vợt có độ đàn hồi cao, dễ dàng kiểm soát bóng khi chơi, phần tay cầm thiết kế vừa, cầm rất thoải mái.', 'Vợt bóng bàn 729 3Star chính hãng được dán sẵn mút vợt có độ đàn hồi cao, dễ dàng kiểm soát bóng khi chơi, phần tay cầm thiết kế vừa, cầm rất thoải mái.', 280000, 'vot-bong-ban', 0, '{"Mã sản phẩm": "3Star", "Màu sắc": "Đỏ - đen", "Chất liệu": "Gỗ, mút cao su", "Độ dày cốt vợt": "5.5mm", "Kích thước mặt": "15.5 x 15cm", "Chiều dài cán vợt": "10cm", "Trọng lượng vợt": "250 gram", "Túi đựng vợt": "Có", "Bóng đi kèm": "Không"}'::jsonb, 'https://baoansport.vn/vot-bong-ban/vot-bong-ban-729-3star/'),
  ('vot-bong-ban-729-1star', 'BAS-1508', '729-1Star', 'Vợt bóng bàn 729 1Star', 'Vợt bóng bàn 729 1Star có cốt được làm từ gỗ tự nhiên dày 5.5mm, mặt vợt sử dụng mút cao su có độ đàn hồi cao và tay cầm thiết kế vừa vặn, dễ cầm nắm.', 'Vợt bóng bàn 729 1Star có cốt được làm từ gỗ tự nhiên dày 5.5mm, mặt vợt sử dụng mút cao su có độ đàn hồi cao và tay cầm thiết kế vừa vặn, dễ cầm nắm.', 200000, 'vot-bong-ban', 0, '{"Mã sản phẩm": "729-1Star", "Màu sắc": "Đỏ - đen", "Chất liệu": "Gỗ, mút cao su", "Độ dày mặt vợt": "13mm", "Kích thước mặt": "15.5 x 15cm", "Chiều dài cán vợt": "10cm", "Trọng lượng vợt": "≈250 gram", "Túi đựng vợt": "Có", "Bóng đi kèm": "Không"}'::jsonb, 'https://baoansport.vn/vot-bong-ban/vot-bong-ban-729-1star/'),
