  ('may-ban-bong-ban-yt-v989g', 'BAS-1510', 'V-989G', 'Máy bắn bóng bàn Y&T V-989G', 'Máy bắn bóng bàn Y&T V-989G được thiết kế thông minh, trang bị nhiều chế độ bắn bóng cho người tập và có khả năng điều chỉnh tốc độ, độ xoáy dễ dàng.', 'Máy bắn bóng bàn Y&T V-989G được thiết kế thông minh, trang bị nhiều chế độ bắn bóng cho người tập và có khả năng điều chỉnh tốc độ, độ xoáy dễ dàng.', 23000000, 'may-ban-bong-ban', 0, '{"Mã sản phẩm": "V-989G", "Màu sắc": "Nâu - đen", "Nguồn điện": "220V-50Hz", "Góc điều chỉnh bắn": "180 độ", "Số bóng bắn ra ít nhất": "25 quả/phút", "Số bóng bắn ra nhiều nhất": "95 quả/phút", "Tốc độ bóng chậm nhất": "4 m/s (14.4 km/h)", "Tốc độ bóng nhanh nhất": "50 m/s (180 km/h)", "Trọng lượng máy bắn": "15.3 kg", "Trọng lượng đóng thùng": "23.6 kg", "Kích thước đặt máy": "52 x 37 x 105cm", "Kích thước đóng thùng": "110 x 57 x 53cm", "Điều khiển từ xa": "Có", "Lưới thu bóng": "Có", "Bóng đi kèm": "Có"}'::jsonb, 'https://baoansport.vn/may-ban-bong-ban/may-ban-bong-ban-yt-v989g/'),
  ('may-ban-bong-ban-yt-v989e2', 'BAS-1511', 'V-989E2', 'Máy bắn bóng bàn Y&T V-989E2', 'Máy bắn bóng bàn Y&T V-989E2 được thiết kế thông minh, khả năng bắn bóng chính xác và có thể điều chỉnh tốc độ bắn lẫn độ xoáy bóng vô cùng dễ dàng.', 'Máy bắn bóng bàn Y&T V-989E2 được thiết kế thông minh, khả năng bắn bóng chính xác và có thể điều chỉnh tốc độ bắn lẫn độ xoáy bóng vô cùng dễ dàng.', 21000000, 'may-ban-bong-ban', 0, '{"Mã sản phẩm": "V-989E2", "Màu sắc": "Nâu - đen", "Nguồn điện": "220V-50Hz", "Góc điều chỉnh bắn": "0-40 độ", "Số bóng bắn ra ít nhất": "25 quả/phút", "Số bóng bắn ra nhiều nhất": "95 quả/phút", "Tốc độ bóng chậm nhất": "4 m/s (14.4 km/h)", "Tốc độ bóng nhanh nhất": "50 m/s (180 km/h)", "Trọng lượng máy bắn": "13.3 kg", "Trọng lượng đóng thùng": "21.3 kg", "Kích thước đặt máy": "52 x 37 x 105cm", "Kích thước đóng thùng": "110 x 53 x 43.5cm", "Điều khiển từ xa": "Có", "Lưới thu bóng": "Có", "Bóng đi kèm": "Có"}'::jsonb, 'https://baoansport.vn/may-ban-bong-ban/may-ban-bong-ban-yt-v989e2/'),
  ('may-ban-bong-ban-yt-v-989h2', 'BAS-1512', 'V-989H2', 'Máy bắn bóng bàn Y&T V-989H2', 'Máy bắn bóng bàn Y&T V-989H2 nâng cấp từ bản V-989H cũ, trang bị chức năng bắn bóng thông minh và có thể điều khiển bằng giọng nói vô cùng hiện đại.', 'Máy bắn bóng bàn Y&T V-989H2 nâng cấp từ bản V-989H cũ, trang bị chức năng bắn bóng thông minh và có thể điều khiển bằng giọng nói vô cùng hiện đại.', 30000000, 'may-ban-bong-ban', 0, '{"Mã sản phẩm": "V-989H2", "Màu sắc": "Nâu - đen", "Nguồn điện": "220V-50Hz", "Góc điều chỉnh bắn": "0-40 độ", "Số bóng bắn ra ít nhất": "25 quả/phút", "Số bóng bắn ra nhiều nhất": "95 quả/phút", "Tốc độ bóng chậm nhất": "4 m/s (14.4 km/h)", "Tốc độ bóng nhanh nhất": "50 m/s (180 km/h)", "Trọng lượng máy bắn": "15 kg", "Trọng lượng đóng thùng": "23.3 kg", "Kích thước đặt máy": "52 x 37 x 105cm", "Kích thước đóng thùng": "110 x 57 x 43.5cm", "Điều khiển từ xa": "Có", "Lưới thu bóng": "Có", "Bóng đi kèm": "Có"}'::jsonb, 'https://baoansport.vn/may-ban-bong-ban/may-ban-bong-ban-yt-v-989h2/'),
  ('qua-bong-nem-paledas', 'BAS-1514', 'Paledas', 'Quả bóng ném Paledas', 'Quả bóng ném Paledas được làm từ chất liệu da kết hợp với cao su non, cho khả năng giữ hơi tốt, đạt tiêu chuẩn thi đấu của Liên đoàn bóng ném Việt Nam.', 'Quả bóng ném Paledas được làm từ chất liệu da kết hợp với cao su non, cho khả năng giữ hơi tốt, đạt tiêu chuẩn thi đấu của Liên đoàn bóng ném Việt Nam.', 320000, 'thiet-bi-day-hoc-the-duc', 0, '{"Mã sản phẩm": "Paledas", "Màu sắc": "Vàng, xanh", "Chất liệu": "Da, cao su", "Size bóng": "Số 2, số 3", "Trọng lượng bóng": "Đang cập nhật"}'::jsonb, 'https://baoansport.vn/thiet-bi-day-hoc-the-duc/qua-bong-nem-paledas/'),
  ('khung-thanh-bong-da-mini-f181', 'BAS-1515', 'F181', 'Khung thành bóng đá Mini F181', 'Khung thành bóng đá Mini F181 được làm từ ống thép phi 32, sẵn lưới đi kèm, với kích thước 90 x 60 x 60cm và có khả năng gập gọn lại khi không sử dụng.', 'Khung thành bóng đá Mini F181 được làm từ ống thép phi 32, sẵn lưới đi kèm, với kích thước 90 x 60 x 60cm và có khả năng gập gọn lại khi không sử dụng.', 900000, 'luoi-khung-thanh-bong-da', 5500, '{"Mã sản phẩm": "F181", "Màu sắc": "Đen", "Chất liệu": "Thép, PE", "Trọng lượng": "5.5 kg", "Trọng lượng thùng": "6.0 kg", "Kích thước lắp": "90 x 60 x 60cm", "Kích thước thùng": "64 x 25 x 7cm"}'::jsonb, 'https://baoansport.vn/luoi-khung-thanh-bong-da/khung-thanh-bong-da-mini-f181/'),
  ('khung-thanh-bong-da-mini-g68', 'BAS-1516', 'G68', 'Khung thành bóng đá Mini G68', 'Khung thành bóng đá Mini G68 được hàn cố định từ ống thép phi 34 dày 1.4mm, bề mặt vật liệu mạ kẽm, có sẵn lưới đi kèm và kích thước 90 x 60 x 52cm.', 'Khung thành bóng đá Mini G68 được hàn cố định từ ống thép phi 34 dày 1.4mm, bề mặt vật liệu mạ kẽm, có sẵn lưới đi kèm và kích thước 90 x 60 x 52cm.', 750000, 'luoi-khung-thanh-bong-da', 6000, '{"Mã sản phẩm": "G68", "Màu sắc": "Trắng", "Chất liệu": "Thép, sợi tổng hợp", "Trọng lượng": "6 kg", "Kích thước khung": "90 x 60 x 52cm"}'::jsonb, 'https://baoansport.vn/luoi-khung-thanh-bong-da/khung-thanh-bong-da-mini-g68/'),
  ('coc-gioi-han-bong-chuyen-401463', 'BAS-1517', '401463', 'Cọc giới hạn bóng chuyền 401463', 'Cọc giới hạn bóng chuyền 401463 chính hãng Vifa Sport được làm từ chất liệu hợp kim nhôm, thiết bị giảm sốc bằng inox và gắn vào lưới bằng khóa nhựa.', 'Cọc giới hạn bóng chuyền 401463 chính hãng Vifa Sport được làm từ chất liệu hợp kim nhôm, thiết bị giảm sốc bằng inox và gắn vào lưới bằng khóa nhựa.', 1400000, 'phu-kien-bong-chuyen', 2000, '{"Mã sản phẩm": "401463", "Màu sắc": "Đỏ - trắng", "Chất liệu": "Hợp kim nhôm, nhựa", "Đường kính": "10mm", "Chiều dài": "1830mm", "Trọng lượng": "2 kg"}'::jsonb, 'https://baoansport.vn/phu-kien-bong-chuyen/coc-gioi-han-bong-chuyen-401463/'),
  ('nong-tru-bong-chuyen-402442no', 'BAS-1518', '402442NO', 'Nòng trụ bóng chuyền 402442NO', 'Nòng trụ bóng chuyền 402442NO chính hãng Vifa Sport làm từ ống thép Ø95, bề mặt vật liệu mạ kẽm nhúng nóng, chuyên dùng để thi công sân bóng chuyền.', 'Nòng trụ bóng chuyền 402442NO chính hãng Vifa Sport làm từ ống thép Ø95, bề mặt vật liệu mạ kẽm nhúng nóng, chuyên dùng để thi công sân bóng chuyền.', 620000, 'tru-luoi-bong-chuyen', 5000, '{"Mã sản phẩm": "402442NO", "Màu sắc": "Xám", "Chất liệu": "Thép", "Đường kính": "950mm", "Chiều cao": "460mm", "Trọng lượng": "5 kg"}'::jsonb, 'https://baoansport.vn/tru-luoi-bong-chuyen/nong-tru-bong-chuyen-402442no/'),
  ('qua-cau-long-555', 'BAS-1519', '555', 'Quả cầu lông 555', 'Quả cầu lông 555 giá rẻ có tán cầu được làm từ lông vũ, đế cầu làm bằng nút bần xốp, đóng gói 10 quả/hộp và phù hợp sử dụng để tập luyện cầu lông cơ bản.', 'Quả cầu lông 555 giá rẻ có tán cầu được làm từ lông vũ, đế cầu làm bằng nút bần xốp, đóng gói 10 quả/hộp và phù hợp sử dụng để tập luyện cầu lông cơ bản.', 120000, 'qua-cau-long', 0, '{"Mã sản phẩm": "555", "Màu sắc": "Trắng", "Chất liệu": "Lông vũ, xốp", "Quy cách đóng gói": "10 quả/hộp"}'::jsonb, 'https://baoansport.vn/qua-cau-long/qua-cau-long-555/');
INSERT INTO seed_product VALUES
  ('may-tap-tang-chieu-cao-06d', 'BAS-1521', '06D', 'Máy tập tăng chiều cao 06D', 'Máy tập tăng chiều cao 06D thiết kế chắc chắn, phù hợp sử dụng để tập tăng chiều cao cho trẻ trong độ tuổi dậy thì và chữa bệnh cột sống cho người lớn tuổi.', 'Máy tập tăng chiều cao 06D thiết kế chắc chắn, phù hợp sử dụng để tập tăng chiều cao cho trẻ trong độ tuổi dậy thì và chữa bệnh cột sống cho người lớn tuổi.', 4200000, 'may-tap-chan', 27500, '{"Mã sản phẩm": "06D", "Màu sắc": "Xám - đen", "Chất liệu": "Thép, nệm mút", "Trọng lượng máy": "27.5 kg", "Trọng lượng thùng": "30 kg", "Tải trọng tối đa": "150 kg", "Kích thước lắp đặt": "146 x 78 x 159cm", "Kích thước thùng": "127 x 61,5 x 19,5cm", "Chiều cao người tập tối thiểu": "140cm", "Chiều cao người tập tối đa": "198cm"}'::jsonb, 'https://baoansport.vn/may-tap-chan/may-tap-tang-chieu-cao-06d/'),
  ('vot-bong-ban-729-2star', 'BAS-1522', '2Star', 'Vợt bóng bàn 729 2Star', 'Vợt bóng bàn 729 2Star chính hãng được dán sẵn mút có tính đàn hồi cao, dễ dàng kiểm soát bóng khi chơi và phù hợp dùng cho người chơi bóng bàn cơ bản.', 'Vợt bóng bàn 729 2Star chính hãng được dán sẵn mút có tính đàn hồi cao, dễ dàng kiểm soát bóng khi chơi và phù hợp dùng cho người chơi bóng bàn cơ bản.', 240000, 'vot-bong-ban', 0, '{"Mã sản phẩm": "2Star", "Màu sắc": "Đỏ - đen", "Chất liệu": "Gỗ, mút cao su", "Độ dày cốt vợt": "5.5mm", "Kích thước mặt": "15.5 x 15cm", "Chiều dài cán vợt": "10cm", "Trọng lượng vợt": "250 gram", "Túi đựng vợt": "Có", "Bóng đi kèm": "Không"}'::jsonb, 'https://baoansport.vn/vot-bong-ban/vot-bong-ban-729-2star/'),
  ('ta-binh-voi-kingbox', 'BAS-1543', 'TBVK', 'Tạ bình vôi Kingbox (65.000/Kg)', 'Tạ bình vôi Kingbox (tạ ấm) được làm từ chất liệu gang đúc nguyên khối, bên ngoài bọc cao su dày và tay cầm thiết kế vừa vặn, dễ cầm nắm khi tập luyện.', 'Tạ bình vôi Kingbox (tạ ấm) được làm từ chất liệu gang đúc nguyên khối, bên ngoài bọc cao su dày và tay cầm thiết kế vừa vặn, dễ cầm nắm khi tập luyện.', 65000, 'ta-tay-ta-don', 12000, '{"Mã sản phẩm": "TBVK", "Màu sắc": "Đỏ đen, xanh đen", "Chất liệu": "Gang, cao su", "Trọng lượng": "2, 4, 6, 8, 10, 12kg", "Kích thước tạ": "Nhiều kích thước", "Đường kính tay cầm": "2.5cm"}'::jsonb, 'https://baoansport.vn/ta-tay-ta-don/ta-binh-voi-kingbox/'),
  ('giay-da-cau-2-lop', 'BAS-1545', 'GDC2L', 'Giày đá cầu 2 lớp', 'Giày đá cầu 2 lớp được may chắc chắn từ chất liệu da lộn, trong lót vải, đế bằng cao su và có kích cỡ từ 36 đến 44, phù hợp dùng cho người lớn lẫn trẻ em.', 'Giày đá cầu 2 lớp được may chắc chắn từ chất liệu da lộn, trong lót vải, đế bằng cao su và có kích cỡ từ 36 đến 44, phù hợp dùng cho người lớn lẫn trẻ em.', 350000, 'thiet-bi-day-hoc-the-duc', 0, '{"Mã sản phẩm": "GDC2L", "Màu sắc": "Đen xám", "Chất liệu": "Da lộn, vải, cao su", "Size": "Từ 36 đến 44", "Trọng lượng": "≈ 400 gram"}'::jsonb, 'https://baoansport.vn/thiet-bi-day-hoc-the-duc/giay-da-cau-2-lop/'),
  ('ta-binh-voi-gold-sport', 'BAS-1546', 'TBVGS', 'Tạ bình vôi Gold Sport (75.000/Kg)', 'Tạ bình vôi Gold Sport được đúc đặc từ chất liệu thép, bên ngoài bọc cao su, có các mức gồm 4; 6; 8; 10kg và phù hợp dùng cho phòng Gym chuyên nghiệp.', 'Tạ bình vôi Gold Sport được đúc đặc từ chất liệu thép, bên ngoài bọc cao su, có các mức gồm 4; 6; 8; 10kg và phù hợp dùng cho phòng Gym chuyên nghiệp.', 75000, 'ta-tay-ta-don', 10000, '{"Mã sản phẩm": "TBVGS", "Màu sắc": "Đen, xám", "Chất liệu": "thép, cao su", "Trọng lượng": "4, 6, 8, 10Kg", "Đường kính tay cầm": "2.7cm"}'::jsonb, 'https://baoansport.vn/ta-tay-ta-don/ta-binh-voi-gold-sport/'),
  ('banh-ta-gang-phi-52', 'BAS-1567', 'TGP52', 'Bánh tạ gang phi 52 (30.000/Kg)', 'Mua bánh tạ gang phi 52 chuẩn Olympic, chất liệu gang đúc đặc siêu bền, đa dạng trọng lượng từ 2.5kg đến 25kg. Giao hàng tại nhà toàn quốc - Giá cực tốt!', 'Mua bánh tạ gang phi 52 chuẩn Olympic, chất liệu gang đúc đặc siêu bền, đa dạng trọng lượng từ 2.5kg đến 25kg. Giao hàng tại nhà toàn quốc - Giá cực tốt!', 30000, 'ta-tay-ta-don', 20000, '{"Mã sản phẩm": "TGP52", "Màu sắc": "Đen", "Chất liệu": "Gang", "Trọng lượng": "3, 5, 10, 15 và 20kg", "Đường kính tạ": "Đang cập nhật"}'::jsonb, 'https://baoansport.vn/ta-tay-ta-don/banh-ta-gang-phi-52/'),
  ('may-tap-bung-t200', 'BAS-1569', 'T200', 'Máy tập bụng T200', 'Mua máy tập bụng T200 chính hãng tại Bảo An Sport. Thiết kế nhỏ gọn, chịu lực tốt, điều chỉnh linh hoạt, hỗ trợ tập bụng hiệu quả. Giao hàng toàn quốc!', 'Mua máy tập bụng T200 chính hãng tại Bảo An Sport. Thiết kế nhỏ gọn, chịu lực tốt, điều chỉnh linh hoạt, hỗ trợ tập bụng hiệu quả. Giao hàng toàn quốc!', 1400000, 'may-tap-co-bung', 10000, '{"Mã sản phẩm": "T200", "Màu sắc": "Đen, hồng", "Chất liệu": "Thép, mút, ABS", "Trọng lượng máy": "10kg", "Tải trọng tối đa": "150kg", "Kích thước sử dụng": "105 x 41 x 110cm", "Kích thước gập gọn": "95 x 41 x 20cm", "Kích thước thùng": "95 x 24 x 22cm"}'::jsonb, 'https://baoansport.vn/may-tap-co-bung/may-tap-bung-t200/'),
  ('gian-ta-da-nang-jl-k10', 'BAS-1570', 'JL-K10', 'Giàn tạ đa năng JL-K10', 'Giàn tạ đa năng JL-K10 tích hợp đẩy ngực, kéo xô, squat, tập xà đơn,... Thiết kế chắc chắn, kèm ghế tập tạ. Phù hợp tập toàn thân tại nhà, tiết kiệm diện tích.', 'Giàn tạ đa năng JL-K10 tích hợp đẩy ngực, kéo xô, squat, tập xà đơn,... Thiết kế chắc chắn, kèm ghế tập tạ. Phù hợp tập toàn thân tại nhà, tiết kiệm diện tích.', 18000000, 'gian-ta-da-nang', 258000, '{"Mã sản phẩm": "JL-K10", "Màu sắc": "Đen, cam", "Chất liệu": "Thép", "Trọng lượng máy": "144kg", "Trọng lượng cả bộ": "258kg", "Trọng lượng thùng": "269kg", "Tải trọng tối đa": "300kg", "Kích thước lắp đặt": "220 x 183 x 215cm", "Số kiện vận chuyển": "5 kiện", "Kích thước thùng": "197 x 45 x 15cm; 133 x 44 x 25cm; 42 x 21 x 32cm (3 kiện)"}'::jsonb, 'https://baoansport.vn/gian-ta-da-nang/gian-ta-da-nang-jl-k10/'),
  ('tru-bong-ro-s033', 'BAS-1571', 'S033', 'Trụ bóng rổ S033', 'Trụ bóng rổ S033 thiết kế chắc chắn từ khung thép sơn tĩnh điện, bảng kính cường lực, điều chỉnh độ cao linh hoạt. Giao hàng tận nơi, bảo hành chính hãng.', 'Trụ bóng rổ S033 thiết kế chắc chắn từ khung thép sơn tĩnh điện, bảng kính cường lực, điều chỉnh độ cao linh hoạt. Giao hàng tận nơi, bảo hành chính hãng.', 18500000, 'tru-bong-ro', 0, '{"Mã sản phẩm": "S033", "Màu sắc": "Đen, đỏ", "Chất liệu": "Thép, kính cường lực", "Trọng lượng trụ": "230kg", "Chiều cao rổ": "Từ 1m7 đến 3m05", "Đường kính rổ": "45cm", "Kích thước bảng": "180 x 105 x 1cm", "Kích thước đế trụ": "180 x 90 x 40cm"}'::jsonb, 'https://baoansport.vn/tru-bong-ro/tru-bong-ro-s033/'),
  ('ghe-bang-tap-ta-kingbox-yb-01', 'BAS-1572', 'YB-01', 'Ghế băng tập tạ Kingbox YB-01', 'Ghế băng tập tạ Kingbox YB-01 được làm từ khung thép 4x4cm dày 1.4mm, chịu lực 300kg. Đệm êm, nhỏ gọn, phù hợp tập tại nhà. Giá tốt, giao toàn quốc !', 'Ghế băng tập tạ Kingbox YB-01 được làm từ khung thép 4x4cm dày 1.4mm, chịu lực 300kg. Đệm êm, nhỏ gọn, phù hợp tập tại nhà. Giá tốt, giao toàn quốc !', 970000, 'ghe-tap-ta', 11000, '{"Mã sản phẩm": "YB-01", "Màu sắc": "Đen, đỏ", "Chất liệu": "Thép, mút, da PU", "Trọng lượng ghế": "11kg", "Trọng lượng thùng": "12kg", "Tải trọng tối đa": "300kg", "Kích thước ghế": "110 x 35 x 46cm", "Kích thước đóng gói": "108 x 38 x 16cm"}'::jsonb, 'https://baoansport.vn/ghe-tap-ta/ghe-bang-tap-ta-kingbox-yb-01/'),
  ('gia-de-ta-6-doi-kingbox-jl001', 'BAS-1573', 'JL001', 'Giá để tạ 6 đôi Kingbox JL001', 'Giá để tạ 6 đôi Kingbox JL001 thiết kế chắc chắn từ khung thép dày 2mm, có 2 tầng và chứa 6 cặp tạ tay. Sản phẩm phù hợp cho phòng Gym và tập tại nhà.', 'Giá để tạ 6 đôi Kingbox JL001 thiết kế chắc chắn từ khung thép dày 2mm, có 2 tầng và chứa 6 cặp tạ tay. Sản phẩm phù hợp cho phòng Gym và tập tại nhà.', 4250000, 'ta-tay-ta-don', 42000, '{"Mã sản phẩm": "JL001", "Màu sắc": "Đen, xám", "Chất liệu": "Thép", "Trọng lượng giá": "40kg", "Trọng lượng thùng": "42kg", "Tải trọng tối đa": "1000kg", "Kích thước lắp đặt": "135 x 75 x 76cm", "Kích thước đóng gói": "77 x 76 x 12cm và 137 x 25 x 5cm"}'::jsonb, 'https://baoansport.vn/ta-tay-ta-don/gia-de-ta-6-doi-kingbox-jl001/'),
  ('ghe-tap-ta-da-nang-kingbox-jl018', 'BAS-1574', 'V-ZTS04', 'Ghế tập tạ đa năng Kingbox JL018 (V-ZTS04)', 'Ghế tập tạ đa năng Kingbox JL018 (V-ZTS04) thiết kế siêu chắc, chịu tải 300kg, điều chỉnh độ dốc dễ dàng. Hỗ trợ nhiều bài tập, giải pháp tối ưu cho Gymer tập tại nhà!', 'Ghế tập tạ đa năng Kingbox JL018 (V-ZTS04) thiết kế siêu chắc, chịu tải 300kg, điều chỉnh độ dốc dễ dàng. Hỗ trợ nhiều bài tập, giải pháp tối ưu cho Gymer tập tại nhà!', 3500000, 'ghe-tap-ta', 23000, '{"Mã sản phẩm": "V-ZTS04", "Màu sắc": "Đen", "Chất liệu": "Thép", "Trọng lượng ghế": "23kg", "Trọng lượng thùng": "25kg", "Tải trọng tối đa": "300kg", "Kích thước ghế": "120 x 74 x 47cm", "Kích thước đóng gói": "120 x 43 x 22cm"}'::jsonb, 'https://baoansport.vn/ghe-tap-ta/ghe-tap-ta-da-nang-kingbox-jl018/'),
  ('tru-bong-ro-hoc-sinh-s003', 'BAS-1575', 'S003', 'Trụ bóng rổ học sinh S003', 'Mua trụ bóng rổ học sinh S003 chính hãng, thiết kế chắc chắn, chiều cao điều chỉnh từ 2.1m đến 2.6m phù hợp dùng cho trẻ em. Giao hàng toàn quốc, giá tốt!', 'Mua trụ bóng rổ học sinh S003 chính hãng, thiết kế chắc chắn, chiều cao điều chỉnh từ 2.1m đến 2.6m phù hợp dùng cho trẻ em. Giao hàng toàn quốc, giá tốt!', 2650000, 'tru-bong-ro', 0, '{"Mã sản phẩm": "S003", "Màu sắc": "Đỏ - đen", "Chiều cao rổ": "2m1 đến 2m6", "Đường kính rổ": "45cm", "Kích thước bảng": "90 x 60cm", "Kích thước đối trọng": "90 x 60 x 17cm", "Kích thước lắp đặt": "135 x 90 x 310cm", "Bánh xe di chuyển": "Có"}'::jsonb, 'https://baoansport.vn/tru-bong-ro/tru-bong-ro-hoc-sinh-s003/'),
  ('gia-de-ta-10-doi-kingbox-jl002', 'BAS-1576', 'JL002', 'Giá để tạ 10 đôi Kingbox JL002', 'Giá để tạ 10 đôi Kingbox JL002 thiết kế chắc chắn, chịu tải 1000kg, giúp sắp xếp tạ gọn gàng chuyên nghiệp. Mua tại Bảo An Sport, giao hàng toàn quốc!', 'Giá để tạ 10 đôi Kingbox JL002 thiết kế chắc chắn, chịu tải 1000kg, giúp sắp xếp tạ gọn gàng chuyên nghiệp. Mua tại Bảo An Sport, giao hàng toàn quốc!', 4750000, 'ta-tay-ta-don', 54000, '{"Mã sản phẩm": "JL002", "Màu sắc": "Đen, xám", "Chất liệu": "Thép", "Trọng lượng giá": "52kg", "Trọng lượng thùng": "54kg", "Tải trọng tối đa": "1000kg", "Kích thước lắp": "2276 x  750 x 763mm", "Kích thước đóng gói": "Đang cập nhật"}'::jsonb, 'https://baoansport.vn/ta-tay-ta-don/gia-de-ta-10-doi-kingbox-jl002/'),
  ('ghe-tap-ta-hq-7008', 'BAS-1578', 'HQ-7008', 'Ghế tập tạ HQ-7008', 'Ghế tập tạ HQ-7008 được thiết kế đa năng, chắc chắn, nhỏ gọn và phù hợp để tập luyện tại nhà. Giao hàng toàn quốc, bảo hành uy tín tại Bảo An Sport.', 'Ghế tập tạ HQ-7008 được thiết kế đa năng, chắc chắn, nhỏ gọn và phù hợp để tập luyện tại nhà. Giao hàng toàn quốc, bảo hành uy tín tại Bảo An Sport.', 5000000, 'ghe-tap-ta', 32000, '{"Mã sản phẩm": "HQ-7008", "Màu sắc": "Đen, xám", "Chất liệu": "Thép", "Trọng lượng ghế": "32kg", "Trọng lượng thùng": "34kg", "Tải trọng tối đa": "300kg", "Kích thước lắp": "132 x 62 x 93cm", "Kích thước đóng gói": "Đang cập nhật"}'::jsonb, 'https://baoansport.vn/ghe-tap-ta/ghe-tap-ta-hq-7008/'),
  ('ghe-tap-lung-bung-hq-7007', 'BAS-1579', 'HQ-7007', 'Ghế tập lưng bụng HQ-7007', 'Ghế tập lưng bụng HQ-7007 hỗ trợ tập cơ bụng, cơ lưng chuyên sâu. Thiết kế chắc chắn, phù hợp dùng cho Gymer tập tại nhà. Giá tốt tại Bảo An Sport!', 'Ghế tập lưng bụng HQ-7007 hỗ trợ tập cơ bụng, cơ lưng chuyên sâu. Thiết kế chắc chắn, phù hợp dùng cho Gymer tập tại nhà. Giá tốt tại Bảo An Sport!', 5000000, 'ghe-tap-bung', 32000, '{"Mã sản phẩm": "HQ-7007", "Màu sắc": "Đen, xám", "Chất liệu": "Thép", "Trọng lượng ghế": "32kg", "Trọng lượng thùng": "34kg", "Tải trọng tối đa": "300kg", "Kích thước lắp": "124 x 96 x 70cm", "Kích thước đóng gói": "116 x 60 x 21cm"}'::jsonb, 'https://baoansport.vn/ghe-tap-bung/ghe-tap-lung-bung-hq-7007/'),
  ('ta-tay-boc-cao-su-kingbox', 'BAS-1580', 'TTCSKb', 'Tạ tay bọc cao su Kingbox (60.000/Kg)', 'Mua tạ tay bọc cao su Kingbox chính hãng, chất liệu bền đẹp, thiết kế chống lăn, nhiều trọng lượng. Giao hàng toàn quốc, bảo hành 12 tháng. Đặt mua ngay!', 'Mua tạ tay bọc cao su Kingbox chính hãng, chất liệu bền đẹp, thiết kế chống lăn, nhiều trọng lượng. Giao hàng toàn quốc, bảo hành 12 tháng. Đặt mua ngay!', 60000, 'ta-tay-ta-don', 0, '{"Mã sản phẩm": "TTCSKb", "Màu sắc": "Xanh, đỏ", "Chất liệu": "Gang bọc cao su", "Trọng lượng tạ": "1-6kg", "Kích thước tạ": "Đang cập nhật"}'::jsonb, 'https://baoansport.vn/ta-tay-ta-don/ta-tay-boc-cao-su-kingbox/'),
  ('may-ban-bong-ban-yt-v981', 'BAS-1581', 'V-981', 'Máy bắn bóng bàn Y&T V-981', 'Mua máy bắn bóng bàn Y&T V-981 chính hãng tại Bảo An Sport. Thiết kế nhỏ gọn, 8 chế độ xoáy, điều khiển dễ dàng. Giao toàn quốc, bảo hành 1 năm.', 'Mua máy bắn bóng bàn Y&T V-981 chính hãng tại Bảo An Sport. Thiết kế nhỏ gọn, 8 chế độ xoáy, điều khiển dễ dàng. Giao toàn quốc, bảo hành 1 năm.', 8000000, 'may-ban-bong-ban', 4400, '{"Mã sản phẩm": "V-981", "Màu sắc": "Đen, nâu đồng", "Trọng lượng máy": "4.4kg", "Kích thước lắp đặt": "30,5 x 24,5 x 56,5cm", "Kích thước thùng": "81,5 x 39 x 40,5cm", "Chế độ xoáy": "8 chế độ", "Tần số phát bóng": "25-80 bóng/phút", "Tốc độ bắn bóng": "3-30 m/giây", "Góc bắn điều chỉnh": "0-40 độ"}'::jsonb, 'https://baoansport.vn/may-ban-bong-ban/may-ban-bong-ban-yt-v981/'),
  ('don-ta-tay-phi-50', 'BAS-1568', 'DTTP50', 'Đòn tạ tay phi 50', 'Mua đòn tạ tay phi 50 chất lượng, tương thích tạ lỗ phi 52 chuẩn Olympic. Thiết kế chắc chắn, xoay mượt, tay cầm chống trượt. Giá tốt, giao hàng toàn quốc.', 'Mua đòn tạ tay phi 50 chất lượng, tương thích tạ lỗ phi 52 chuẩn Olympic. Thiết kế chắc chắn, xoay mượt, tay cầm chống trượt. Giá tốt, giao hàng toàn quốc.', 400000, 'ta-tay-ta-don', 0, '{"Mã sản phẩm": "DTTP50", "Màu sắc": "Ghi xám", "Chất liệu": "Thép mạ inox", "Chiều dài": "50cm", "Đường kính lắp tạ": "50mm", "Đường kính tay cầm": "25mm", "Trọng lượng đòn": "4 kg/tay"}'::jsonb, 'https://baoansport.vn/ta-tay-ta-don/don-ta-tay-phi-50/'),
  ('ta-tay-v-tap-v-du', 'BAS-1566', 'V-DU', 'Tạ tay V-TAP V-DU (70.000/Kg)', 'Tạ tay V-TAP V-DU được làm từ gang bọc cao su, thiết kế chống lăn, có mức tạ từ 2.5 đến 25kg. Sản phẩm phù hợp cho phòng Gym và luyện tập chuyên nghiệp.', 'Tạ tay V-TAP V-DU được làm từ gang bọc cao su, thiết kế chống lăn, có mức tạ từ 2.5 đến 25kg. Sản phẩm phù hợp cho phòng Gym và luyện tập chuyên nghiệp.', 70000, 'ta-tay-ta-don', 25000, '{"Mã sản phẩm": "V-DU", "Màu sắc": "Đen", "Chất liệu": "Gang, cao su", "Tay cầm": "Thép mạ kẽm", "Trọng lượng": "2.5 - 25Kg"}'::jsonb, 'https://baoansport.vn/ta-tay-ta-don/ta-tay-v-tap-v-du/'),
  ('ban-bong-ban-mofit-mp-99g', 'BAS-1565', 'MP99G', 'Bàn bóng bàn Mofit MP99G', 'Mua bàn bóng bàn Mofit MP99G chính hãng tại Bảo An Sport. Mặt bàn chuẩn thi đấu, chân chắc chắn, dễ gấp gọn. Giá tốt, giao hàng tại nhà toàn quốc.', 'Mua bàn bóng bàn Mofit MP99G chính hãng tại Bảo An Sport. Mặt bàn chuẩn thi đấu, chân chắc chắn, dễ gấp gọn. Giá tốt, giao hàng tại nhà toàn quốc.', 11500000, 'ban-bong-ban', 120000, '{"Mã sản phẩm": "MP99G", "Màu sắc": "Nâu đồng, xanh", "Chất liệu": "Gỗ MDF, thép", "Độ dày mặt bàn": "25mm", "Đường kính bánh xe": "100mm", "Trọng lượng bàn": "120Kg", "Trọng lượng thùng": "123Kg", "Kích thước bàn": "2740 x 1525 x 760mm", "Kích thước đóng gói": "1600 x 1480 x 170mm"}'::jsonb, 'https://baoansport.vn/ban-bong-ban/ban-bong-ban-mofit-mp-99g/'),
  ('gian-ta-da-nang-m-918p', 'BAS-1549', 'M-918P', 'Giàn tạ đa năng M-918P', 'Giàn tạ đa năng M-918P được thiết kế đẹp mắt, chắc chắn và hỗ trợ hơn 30 bài tập khác nhau cho Gymer như đẩy ngực, kéo xô, gánh tạ, tập chân, đấm bốc.', 'Giàn tạ đa năng M-918P được thiết kế đẹp mắt, chắc chắn và hỗ trợ hơn 30 bài tập khác nhau cho Gymer như đẩy ngực, kéo xô, gánh tạ, tập chân, đấm bốc.', 15500000, 'gian-ta-da-nang', 172000, '{"Mã sản phẩm": "M-918P", "Màu sắc": "Đen nâu", "Chất liệu": "Thép, nhựa, da PU", "Trọng lượng tạ": "73 kg", "Trọng lượng cả bộ": "172 kg", "Trọng lượng thùng": "187 kg", "Tải trọng tối đa": "300 kg", "Diện tích lắp đặt": "170 x 100 x 205cm", "Số kiện đóng thùng": "5 kiện"}'::jsonb, 'https://baoansport.vn/gian-ta-da-nang/gian-ta-da-nang-m-918p/'),
  ('ban-bong-ban-double-fish-235g-gold', 'BAS-1551', '235G', 'Bàn bóng bàn Double Fish 235G Gold', 'Bàn bóng bàn Double Fish 235G Gold được thiết kế đẹp, mặt bàn có độ nảy chuẩn, chân bàn chắc chắn và đạt chuẩn thi đấu của liên đoàn bóng bàn thế giới.', 'Bàn bóng bàn Double Fish 235G Gold được thiết kế đẹp, mặt bàn có độ nảy chuẩn, chân bàn chắc chắn và đạt chuẩn thi đấu của liên đoàn bóng bàn thế giới.', 19500000, 'ban-bong-ban', 0, '{"Mã sản phẩm": "235G", "Màu sắc": "Xanh sẫm, vàng", "Chất liệu": "Gỗ MDF, thép", "Độ dày mặt bàn": "25mm", "Kích thước bàn": "1525 x 2740 x 760mm", "Trọng lượng mặt bàn": "94kg", "Trọng lượng chân bàn": "28kg", "Cọc lưới đi kèm": "Có"}'::jsonb, 'https://baoansport.vn/ban-bong-ban/ban-bong-ban-double-fish-235g-gold/'),
  ('dich-da-kangrui-kt340', 'BAS-1553', 'KT340', 'Đích đá Kangrui KT340', 'Mua đích đá Kangrui KT340 dùng để tập võ thuật, Boxing ở Bảo An Sport. Cam kết chính hãng, giá rẻ, giao hàng tại nhà. Hotline đặt hàng 0939987456.', 'Mua đích đá Kangrui KT340 dùng để tập võ thuật, Boxing ở Bảo An Sport. Cam kết chính hãng, giá rẻ, giao hàng tại nhà. Hotline đặt hàng 0939987456.', 650000, 'dich-dam-dich-da', 1600, '{"Mã sản phẩm": "KT340", "Màu sắc": "Đỏ + đen", "Chất liệu": "Da PU, EVA", "Trọng lượng": "1.6kg", "Kích thước": "60 x 40 x 10cm"}'::jsonb, 'https://baoansport.vn/dich-dam-dich-da/dich-da-kangrui-kt340/'),
  ('gia-de-ta-tay-2-tang-6-doi-kingbox', 'BAS-1554', 'GD-206', 'Giá để tạ tay 2 tầng 6 đôi KingBox', 'Mua giá để tạ tay 2 tầng 6 đôi KingBox cho gia đình và phòng tập Gym tại Bảo An Sport. Mẫu mã đẹp, nhập khẩu chính hãng, giá rẻ, giao hàng tận nhà.', 'Mua giá để tạ tay 2 tầng 6 đôi KingBox cho gia đình và phòng tập Gym tại Bảo An Sport. Mẫu mã đẹp, nhập khẩu chính hãng, giá rẻ, giao hàng tận nhà.', 3150000, 'ta-tay-ta-don', 30000, '{"Mã sản phẩm": "GD-206", "Màu sắc": "Đen", "Chất liệu": "Thép", "Trọng lượng": "30kg", "Tải trọng": "300kg", "Sức chứa": "12 quả", "Kích thước": "125 x 78 x 57cm", "Kích thước thùng": "Kiện 1: 126 x 28 x 15cm Kiện 2: 85 x 67 x 16cm"}'::jsonb, 'https://baoansport.vn/ta-tay-ta-don/gia-de-ta-tay-2-tang-6-doi-kingbox/'),
  ('ban-bong-ban-double-fish-325', 'BAS-1555', 'DF-325', 'Bàn bóng bàn Double Fish 325', 'Đặt mua bàn bóng bàn Double Fish 325 chính hãng Song Ngư ở Bảo An Sport. Giá rẻ, vận chuyển, lắp đặt tại nhà. Khuyến mãi hộp bóng, vợt bóng bàn.', 'Đặt mua bàn bóng bàn Double Fish 325 chính hãng Song Ngư ở Bảo An Sport. Giá rẻ, vận chuyển, lắp đặt tại nhà. Khuyến mãi hộp bóng, vợt bóng bàn.', 23500000, 'ban-bong-ban', 108000, '{"Mã sản phẩm": "DF-325", "Màu sắc": "Xanh, đen", "Chất liệu": "Gỗ MDF, thép", "Độ dày mặt bàn": "25mm", "Kích thước bàn": "1525 x 2740 x 760mm", "Kích thước thùng": "1650 x 1460 x 240mm", "Trọng lượng bàn": "108kg", "Trọng lượng thùng": "120kg", "Cọc lưới đi kèm": "Có"}'::jsonb, 'https://baoansport.vn/ban-bong-ban/ban-bong-ban-double-fish-325/'),
  ('ghe-tap-ta-da-nang-bp-010', 'BAS-1556', 'BP-010', 'Ghế tập tạ đa năng BP-010', 'Ghế tập tạ đa năng BP-010 được thiết kế chắc chắn, yên có khả năng điều chỉnh độ dốc dễ dàng và phù hợp sử dụng tập thể hình tại nhà cho anh em Gymer.', 'Ghế tập tạ đa năng BP-010 được thiết kế chắc chắn, yên có khả năng điều chỉnh độ dốc dễ dàng và phù hợp sử dụng tập thể hình tại nhà cho anh em Gymer.', 2800000, 'ghe-tap-ta', 22000, '{"Mã sản phẩm": "BP-010", "Màu sắc": "Đen", "Chất liệu": "Thép", "Trọng lượng ghế": "22kg", "Trọng lượng thùng": "24kg", "Tải trọng tối đa": "250kg", "Kích thước lắp đặt": "160 x 60 x 50cm", "Kích thước thùng": "100 x 41 x 23cm"}'::jsonb, 'https://baoansport.vn/ghe-tap-ta/ghe-tap-ta-da-nang-bp-010/'),
  ('gang-tay-mma-bn', 'BAS-1557', 'MMA-BN', 'Găng tay MMA BN', 'Găng tay MMA BN được thiết kế dạng hở ngón, may chắc chắn từ chất liệu da PU bên trong lót EVA cực êm và phù hợp sử dụng để tập Muay Thai, MMA.', 'Găng tay MMA BN được thiết kế dạng hở ngón, may chắc chắn từ chất liệu da PU bên trong lót EVA cực êm và phù hợp sử dụng để tập Muay Thai, MMA.', 400000, 'gang-tay-boxing', 0, '{"Mã sản phẩm": "MMA-BN", "Màu sắc": "Đen, đỏ, xám, trắng, xanh", "Chất liệu": "Da PU, EVA", "Trọng lượng": "300 gram", "Size": "M, L"}'::jsonb, 'https://baoansport.vn/gang-tay-boxing/gang-tay-mma-bn/'),
  ('ghe-bang-tap-ta-kingbox-ac-5002', 'BAS-1558', 'AC-5002', 'Ghế băng tập tạ Kingbox AC-5002', 'Ghế băng tập tạ Kingbox AC-5002 thiết kế chắc chắn từ thép hộp vuông 40 x 40mm, nệm ghế dày 5cm và chịu được tải trọng người tập tối đa lên đến 300kg.', 'Ghế băng tập tạ Kingbox AC-5002 thiết kế chắc chắn từ thép hộp vuông 40 x 40mm, nệm ghế dày 5cm và chịu được tải trọng người tập tối đa lên đến 300kg.', 900000, 'ghe-tap-ta', 9500, '{"Mã sản phẩm": "AC-5002", "Màu sắc": "đen", "Chất liệu": "thép, nệm da", "Trọng lượng ghế": "9.5kg", "Trọng lượng thùng": "11kg", "Tải trọng tối đa": "300kg", "Kích thước lắp đặt": "108 x 44 x 41cm", "Kích thước thùng": "108 x 38 x 16cm"}'::jsonb, 'https://baoansport.vn/ghe-tap-ta/ghe-bang-tap-ta-kingbox-ac-5002/'),
  ('khung-tap-xa-don-cs002-01', 'BAS-1559', 'CS002-01', 'Khung tập xà đơn CS002-01', 'Khung tập xà đơn CS002-01 được làm chắc chắn từ thép hộp 40 x 40mm dày 1.2mm, chịu tải trọng tối đa 200kg và chiều cao điều chỉnh từ 150 đến 215cm.', 'Khung tập xà đơn CS002-01 được làm chắc chắn từ thép hộp 40 x 40mm dày 1.2mm, chịu tải trọng tối đa 200kg và chiều cao điều chỉnh từ 150 đến 215cm.', 1200000, 'xa-don-xa-kep', 0, '{"Mã sản phẩm": "CS002-01", "Màu sắc": "Vàng, đen", "Trọng lượng bộ xà": "14kg", "Tải trọng tối đa": "200kg", "Diện tích lắp đặt": "116 x 100 x 215cm", "Kích thước đóng gói": "109 x 39 x 11cm"}'::jsonb, 'https://baoansport.vn/xa-don-xa-kep/khung-tap-xa-don-cs002-01/'),
  ('gian-ta-da-nang-kingbox-jl021', 'BAS-1561', 'JL021', 'Giàn tạ đa năng Kingbox JL021', 'Giàn tạ đa năng Kingbox JL021 được thiết kế dạng chữ V giúp tiết kiệm diện tích lắp đặt, hỗ trợ nhiều bài tập hiệu quả và phù hợp cho phòng Gym gia đình.', 'Giàn tạ đa năng Kingbox JL021 được thiết kế dạng chữ V giúp tiết kiệm diện tích lắp đặt, hỗ trợ nhiều bài tập hiệu quả và phù hợp cho phòng Gym gia đình.', 12500000, 'gian-ta-da-nang', 246000, '{"Mã sản phẩm": "JL021", "Màu sắc": "Đen", "Chất liệu": "Thép, mút, nhựa", "Trọng lượng tạ": "140kg", "Trọng lượng cả bộ": "246kg", "Tải trọng tập tối đa": "200kg", "Kích thước lắp đặt": "1170 x 1600 x 2200mm", "Kích thước hộp": "Đang cập nhật"}'::jsonb, 'https://baoansport.vn/gian-ta-da-nang/gian-ta-da-nang-kingbox-jl021/'),
  ('xe-dap-tap-phuc-hoi-chuc-nang-bc81013', 'BAS-1562', 'BC81013', 'Xe đạp tập phục hồi chức năng BC81013', 'Xe đạp tập phục hồi chức năng BC81013 thiết kế chắc chắn, hỗ trợ tập vận động tay chân hiệu quả và phù hợp sử dụng để rèn luyện sức khỏe cho người già.', 'Xe đạp tập phục hồi chức năng BC81013 thiết kế chắc chắn, hỗ trợ tập vận động tay chân hiệu quả và phù hợp sử dụng để rèn luyện sức khỏe cho người già.', 7000000, 'xe-dap-tap-the-duc', 35500, '{"Mã sản phẩm": "BC81013", "Màu sắc": "Ghi - đen", "Chất liệu": "Thép, nhựa", "Trọng lượng bánh đà": "5kg", "Trọng lượng xe": "35.5kg", "Trọng lượng thùng": "39.5kg", "Tải trọng tối đa": "100kg", "Kích thước lắp đặt": "123 x 69 x 126cm", "Kích thước thùng": "98.5 x 37.5 x 59cm", "Yên xe tựa lưng": "Có", "Chuyển động": "Dây curoa + bánh đà", "Kháng lực": "14 mức", "Đo nhịp tim": "Có"}'::jsonb, 'https://baoansport.vn/xe-dap-tap-the-duc/xe-dap-tap-phuc-hoi-chuc-nang-bc81013/'),
  ('vo-nem-nhay-cao', 'BAS-1563', 'VNNC', 'Vỏ bạt phủ nệm nhảy cao', 'Vỏ bạt phủ nệm nhảy cao được may chắc chắn từ chất liệu vải PVC chống thấm, đường may hai lớp và có đầy đủ kích thước theo yêu cầu của khách hàng.', 'Vỏ bạt phủ nệm nhảy cao được may chắc chắn từ chất liệu vải PVC chống thấm, đường may hai lớp và có đầy đủ kích thước theo yêu cầu của khách hàng.', 600000, 'thiet-bi-day-hoc-the-duc', 0, '{"Mã sản phẩm": "VNNC", "Màu sắc": "Xanh", "Chất liệu": "Vải PVC", "Kích thước": "Theo yêu cầu"}'::jsonb, 'https://baoansport.vn/thiet-bi-day-hoc-the-duc/vo-nem-nhay-cao/'),
  ('ghe-tap-ta-da-nang-kingbox-8023', 'BAS-1564', 'V-8023', 'Ghế tập tạ đa năng Kingbox 8023', 'Ghế tập tạ đa năng Kingbox 8023 thiết kế chắc chắn, có khả năng gấp gọn dễ dàng sau khi tập và phù hợp sử dụng cho anh em có nhu cầu tập Gym tại nhà.', 'Ghế tập tạ đa năng Kingbox 8023 thiết kế chắc chắn, có khả năng gấp gọn dễ dàng sau khi tập và phù hợp sử dụng cho anh em có nhu cầu tập Gym tại nhà.', 1500000, 'ghe-tap-ta', 11000, '{"Mã sản phẩm": "V-8023", "Màu sắc": "Đen", "Chất liệu": "Thép, da PU", "Trọng lượng ghế": "11kg", "Trọng lượng hộp": "12kg", "Tải trọng tập tối đa": "200kg", "Kích thước lắp đặt": "130 x 32 x 80cm", "Kích thước hộp": "81 x 35 x 20cm"}'::jsonb, 'https://baoansport.vn/ghe-tap-ta/ghe-tap-ta-da-nang-kingbox-8023/'),
  ('phu-kien-lap-ta-am-nhua', 'BAS-1454', 'PKTAN', 'Phụ kiện lắp tạ ấm nhựa', 'Phụ kiện lắp tạ ấm nhựa được làm từ chất liệu lõi thép, bên ngoài bọc nhựa PE và dùng để kết hợp bộ tạ bê tông ghép thành tạ bình hoặc sử dụng tập hít đất.', 'Phụ kiện lắp tạ ấm nhựa được làm từ chất liệu lõi thép, bên ngoài bọc nhựa PE và dùng để kết hợp bộ tạ bê tông ghép thành tạ bình hoặc sử dụng tập hít đất.', 200000, 'ta-tay-ta-don', 1000, '{"Mã sản phẩm": "PKTAN", "Màu sắc": "Đen, vàng", "Chất liệu": "Thép, nhựa PE", "Trọng lượng": "1 kg", "Trọng lượng hộp": "1.2 kg", "Kích thước": "Đang cập nhật", "Kích thước hộp": "25 x 15 x 18 cm"}'::jsonb, 'https://baoansport.vn/ta-tay-ta-don/phu-kien-lap-ta-am-nhua/'),
  ('qua-bong-ban-729-3star', 'BAS-1506', 'BB-729-3Star', 'Quả bóng bàn 729 3Star', 'Quả bóng bàn 729 3Star chính hãng được làm từ nhựa cao cấp, đường kính 40mm, trọng lượng dao động từ 2.67 đến 2.77gram và đóng hộp 6 quả bóng/hộp.', 'Quả bóng bàn 729 3Star chính hãng được làm từ nhựa cao cấp, đường kính 40mm, trọng lượng dao động từ 2.67 đến 2.77gram và đóng hộp 6 quả bóng/hộp.', 110000, 'qua-bong-ban', 0, '{"Mã sản phẩm": "BB-729-3Star", "Màu sắc": "Trắng", "Chất liệu": "Nhựa", "Đường kính bóng": "40mm", "Trọng lượng bóng": "2.67-2.77gram", "Quy cách đóng hộp": "6 quả/hộp"}'::jsonb, 'https://baoansport.vn/qua-bong-ban/qua-bong-ban-729-3star/'),
  ('vong-tap-yoga-abs', 'BAS-1426', 'VTYA', 'Vòng tập Yoga ABS', 'Vòng tập Yoga ABS được làm từ chất liệu nhựa ABS cao cấp có độ bền cao, bên ngoài bọc một lớp cao su TPE độ dày 6mm và có đường kính bằng 35cm.', 'Vòng tập Yoga ABS được làm từ chất liệu nhựa ABS cao cấp có độ bền cao, bên ngoài bọc một lớp cao su TPE độ dày 6mm và có đường kính bằng 35cm.', 320000, 'phu-kien-yoga', 1300, '{"Mã sản phẩm": "VTYA", "Màu sắc": "Nhiều màu", "Chất liệu": "Nhựa ABS, TPE", "Trọng lượng": "1.3 kg", "Trọng lượng cả hộp": "1.5 kg", "Tải trọng tối đa": "100 kg", "Kích thước vòng": "33 x 15 cm"}'::jsonb, 'https://baoansport.vn/phu-kien-yoga/vong-tap-yoga-abs/'),
  ('ban-bong-ban-double-fish-203m', 'BAS-1448', '203M', 'Bàn bóng bàn Double Fish 203M', 'Bàn bóng bàn Double Fish 203M chính hãng được thiết kế chắc chắn, mặt bàn làm từ gỗ MDF cao cấp dày 25mm cho độ nảy chuẩn và chân có thể gập gọn.', 'Bàn bóng bàn Double Fish 203M chính hãng được thiết kế chắc chắn, mặt bàn làm từ gỗ MDF cao cấp dày 25mm cho độ nảy chuẩn và chân có thể gập gọn.', 12500000, 'ban-bong-ban', 0, '{"Mã sản phẩm": "203M", "Màu sắc": "Xanh - trắng xám", "Chất liệu mặt bàn": "Gỗ MDF cao cấp", "Độ dày mặt bàn": "25mm", "Trọng lượng mặt": "98 kg", "Trọng lượng chân": "17 kg", "Trọng lượng đóng thùng": "125 kg", "Kích thước lắp đặt": "2740 x 1525 x 760mm", "Bánh xe di chuyển": "Có", "Chức năng gập gọn": "Có"}'::jsonb, 'https://baoansport.vn/ban-bong-ban/ban-bong-ban-double-fish-203m/'),
  ('bao-tai-nhay-bao-bo', 'BAS-1450', 'BNBB', 'Bao tải nhảy bao bố', 'Bao tải nhảy bao bố được làm từ chất liệu sợi đay, đường may chắc chắn, chuyên dùng để sử dụng cho trò chơi nhảy bao bố ở trường học, công ty, cơ quan,...', 'Bao tải nhảy bao bố được làm từ chất liệu sợi đay, đường may chắc chắn, chuyên dùng để sử dụng cho trò chơi nhảy bao bố ở trường học, công ty, cơ quan,...', 120000, 'thiet-bi-day-hoc-the-duc', 0, '{"Mã sản phẩm": "BNBB", "Màu sắc": "Nâu", "Chất liệu": "Sợi đay", "Trọng lượng bao": "1 kg", "Chiều rộng bao": "70 - 75cm", "Chiều cao bao": "100 - 110cm"}'::jsonb, 'https://baoansport.vn/thiet-bi-day-hoc-the-duc/bao-tai-nhay-bao-bo/'),
  ('giay-da-cau-cao-cap-3-lop', 'BAS-1451', 'GDCCC3L', 'Giày đá cầu cao cấp 3 lớp', 'Giày đá cầu cao cấp 3 lớp được thiết kế chuẩn phom hình mỏ vịt, tăng khả năng tiếp xúc cầu khi chơi và phù hợp cho cả đá cầu phủi, cầu lưới chuyên nghiệp.', 'Giày đá cầu cao cấp 3 lớp được thiết kế chuẩn phom hình mỏ vịt, tăng khả năng tiếp xúc cầu khi chơi và phù hợp cho cả đá cầu phủi, cầu lưới chuyên nghiệp.', 450000, 'thiet-bi-day-hoc-the-duc', 0, '{"Mã sản phẩm": "GDCCC3L", "Màu sắc": "Nhiều màu", "Chất liệu": "Da, cao su", "Size": "36 đến 44", "Trọng lượng": "500 - 600 gram"}'::jsonb, 'https://baoansport.vn/thiet-bi-day-hoc-the-duc/giay-da-cau-cao-cap-3-lop/'),
  ('phu-kien-lap-ta-am-fed', 'BAS-1453', 'PKTA', 'Phụ kiện lắp tạ ấm Fed', 'Phụ kiện lắp tạ ấm Fed được làm từ chất liệu thép sơn tĩnh điện kết hợp với nhựa ABS và có chức năng dùng lắp ghép thành tạ bình hoặc sử dụng tập hít đất.', 'Phụ kiện lắp tạ ấm Fed được làm từ chất liệu thép sơn tĩnh điện kết hợp với nhựa ABS và có chức năng dùng lắp ghép thành tạ bình hoặc sử dụng tập hít đất.', 450000, 'ta-tay-ta-don', 1800, '{"Mã sản phẩm": "PKTA", "Màu sắc": "Đen, cam", "Chất liệu": "Thép, nhựa ABS", "Trọng lượng": "1.8 kg", "Trọng lượng hộp": "2 kg", "Kích thước lắp đặt": "25 x 20 cm", "Kích thước thùng": "25 x 21 x 16 cm"}'::jsonb, 'https://baoansport.vn/ta-tay-ta-don/phu-kien-lap-ta-am-fed/'),
  ('xa-don-treo-tuong-da-nang-8-in-1', 'BAS-1455', 'XD8I1', 'Xà đơn treo tường đa năng 8 in 1', 'Xà đơn treo tường đa năng 8 in 1 được làm chắc chắn từ thép ống dày, có khả năng chịu lực tốt và phù hợp sử dụng cho người tập thể dục, thể hình tại nhà.', 'Xà đơn treo tường đa năng 8 in 1 được làm chắc chắn từ thép ống dày, có khả năng chịu lực tốt và phù hợp sử dụng cho người tập thể dục, thể hình tại nhà.', 1100000, 'xa-don-xa-kep', 0, '{"Mã sản phẩm": "XD8I1", "Màu sắc": "Đen", "Chất liệu": "Thép, mút", "Trọng lượng xà": "9 kg", "Trọng lượng đóng gói": "10 kg", "Tải trọng tối đa": "150 kg", "Kích thước lắp đặt": "93 x 73 x 47 cm"}'::jsonb, 'https://baoansport.vn/xa-don-xa-kep/xa-don-treo-tuong-da-nang-8-in-1/'),
  ('vot-bong-ban-729-very-3-star', 'BAS-1456', 'Very-3-Star', 'Vợt bóng bàn 729 Very 3 Star', 'Vợt bóng bàn 729 Very 3 Star (3 sao) thuộc dòng vợt dán sẵn của 729, cốt vợt làm bằng gỗ tự nhiên giúp tạo độ xoáy tốt và mặt vợt mềm dễ kiểm soát bóng.', 'Vợt bóng bàn 729 Very 3 Star (3 sao) thuộc dòng vợt dán sẵn của 729, cốt vợt làm bằng gỗ tự nhiên giúp tạo độ xoáy tốt và mặt vợt mềm dễ kiểm soát bóng.', 350000, 'vot-bong-ban', 0, '{"Mã sản phẩm": "Very-3-Star", "Màu sắc": "Đỏ - đen", "Chất liệu": "Gỗ, mút cao su", "Độ dày mặt vợt": "2.1mm", "Kích thước mặt vợt": "16 x 15cm", "Chiều dài cán vợt": "10cm", "Bao đựng vợt": "Có", "Bóng tặng kèm": "2 quả"}'::jsonb, 'https://baoansport.vn/vot-bong-ban/vot-bong-ban-729-very-3-star/'),
  ('bo-dung-cu-hit-dat-14-in-1', 'BAS-1457', 'HD14I1', 'Bộ dụng cụ hít đất chống đẩy 14 in 1', 'Bộ dụng cụ hít đất chống đẩy 14 in 1 làm từ chất liệu nhựa cao cấp, có khả năng chịu tải trọng người tập lên đến 100kg và hỗ trợ 14 tư thế bài tập khác nhau.', 'Bộ dụng cụ hít đất chống đẩy 14 in 1 làm từ chất liệu nhựa cao cấp, có khả năng chịu tải trọng người tập lên đến 100kg và hỗ trợ 14 tư thế bài tập khác nhau.', 200000, 'phu-kien-tap-gym', 1000, '{"Mã sản phẩm": "HD14I1", "Màu sắc": "Đen", "Chất liệu": "Nhựa ABS", "Trọng lượng": "1kg", "Tải trọng tối đa": "100kg", "Kích thước bàn tập": "63 x 18.5 x 2cm", "Kích thước gập gọn": "31.5 x 18.5 x 4cm", "Kích thước hộp": "32 x 19 x 8cm"}'::jsonb, 'https://baoansport.vn/phu-kien-tap-gym/bo-dung-cu-hit-dat-14-in-1/'),
  ('bo-dung-cu-tap-the-luc-3-in-1', 'BAS-1459', 'DCTL3I1', 'Bộ dụng cụ tập thể lực 3 in 1', 'Bộ dụng cụ tập thể lực 3 in 1 được thiết kế chắc chắn, trang bị các bài tập cơ bản gồm hít đất; gập bụng; kéo dây đàn hồi và phù hợp sử dụng để tập tại nhà.', 'Bộ dụng cụ tập thể lực 3 in 1 được thiết kế chắc chắn, trang bị các bài tập cơ bản gồm hít đất; gập bụng; kéo dây đàn hồi và phù hợp sử dụng để tập tại nhà.', 400000, 'phu-kien-tap-gym', 2000, '{"Mã sản phẩm": "DCTL3I1", "Màu sắc": "Đen", "Chất liệu": "Nhựa ABS", "Trọng lượng": "2 kg", "Tải trọng tối đa": "150 kg", "Kích thước bàn tập": "60 x 25 x 18cm", "Kích thước hộp": "62 x 28 x 8cm"}'::jsonb, 'https://baoansport.vn/phu-kien-tap-gym/bo-dung-cu-tap-the-luc-3-in-1/'),
  ('tru-bong-ro-801818', 'BAS-1460', '801818', 'Trụ bóng rổ Vifa Sport 801818', 'Trụ bóng rổ Vifa Sport 801818 được thiết kế chắc chắn, chiều cao vành rổ điều chỉnh từ 2m6 đến 3m05 và phù hợp để chơi bóng rổ tại nhà hoặc trường học.', 'Trụ bóng rổ Vifa Sport 801818 được thiết kế chắc chắn, chiều cao vành rổ điều chỉnh từ 2m6 đến 3m05 và phù hợp để chơi bóng rổ tại nhà hoặc trường học.', 5700000, 'tru-bong-ro', 0, '{"Mã sản phẩm": "801818", "Màu sắc": "Đen", "Chất liệu": "Thép, nhựa LLDPE", "Chiều cao rổ": "2m6; 2m8; 3m05", "Đường kính rổ": "45cm", "Kích thước bảng": "1115 x 750mm", "Kích thước đế": "1150 x 720 x 200mm", "Kích thước lắp đặt": "1980 x 1115 x 3960mm", "Trọng lượng trụ": "35 kg", "Trọng lượng cả thùng": "38kg", "Bánh xe di chuyển": "Có"}'::jsonb, 'https://baoansport.vn/tru-bong-ro/tru-bong-ro-801818/'),
  ('tru-bong-ro-co-dinh-tt-503', 'BAS-1462', 'TT-503', 'Trụ bóng rổ cố định TT-503', 'Trụ bóng rổ cố định TT-503 thiết kế có khung chính làm từ thép hộp 150 x 150mm, sử dụng bảng rổ làm bằng Composite và lắp đặt chôn cố định xuống nền.', 'Trụ bóng rổ cố định TT-503 thiết kế có khung chính làm từ thép hộp 150 x 150mm, sử dụng bảng rổ làm bằng Composite và lắp đặt chôn cố định xuống nền.', 12500000, 'tru-bong-ro', 0, '{"Mã sản phẩm": "TT-503", "Màu sắc": "Xanh - trắng", "Chất liệu": "Thép hộp, composite", "Chiều cao rổ": "305cm", "Đường kính rổ": "45cm", "Kích thước bảng": "1800 x 1050 x 25 mm", "Chất liệu bảng": "Composite", "Chất liệu lưới": "TPP 6.0mm", "Trọng lượng trụ": "140kg", "Kích thước lắp đặt": "Đang cập nhật"}'::jsonb, 'https://baoansport.vn/tru-bong-ro/tru-bong-ro-co-dinh-tt-503/'),
  ('tru-bong-ro-co-dinh-tt-103', 'BAS-1463', 'TT-103', 'Trụ bóng rổ cố định TT-103', 'Trụ bóng rổ cố định TT-103 được thiết kế chắc chắn, thân chính làm từ thép hộp 150 x 150mm, sử dụng bảng kính cường lực và lắp đặt cố định xuống nền', 'Trụ bóng rổ cố định TT-103 được thiết kế chắc chắn, thân chính làm từ thép hộp 150 x 150mm, sử dụng bảng kính cường lực và lắp đặt cố định xuống nền', 14500000, 'tru-bong-ro', 0, '{"Mã sản phẩm": "TT-103", "Màu sắc": "Xanh, trắng", "Chất liệu": "Thép, kính cường lực", "Chiều cao rổ": "305cm", "Đường kính rổ": "45cm", "Kích thước bảng": "1200 x 900 x 10mm và 1800 x 1050 x 10mm", "Chất liệu bảng": "Kính cường lực", "Chất liệu lưới": "TPP 6.0mm", "Trọng lượng trụ": "Đang cập nhật", "Kích thước lắp đặt": "Đang cập nhật"}'::jsonb, 'https://baoansport.vn/tru-bong-ro/tru-bong-ro-co-dinh-tt-103/'),
  ('gian-ta-da-nang-m-888p', 'BAS-1464', 'M-888P', 'Giàn tạ đa năng M-888P', 'Giàn tạ đa năng M-888P (HQ-368) được thiết kế siêu chắc chắn, hỗ trợ đầy đủ bài tập cho các nhóm cơ và phù hợp dùng để tập luyện thể hình cho nam nữ', 'Giàn tạ đa năng M-888P (HQ-368) được thiết kế siêu chắc chắn, hỗ trợ đầy đủ bài tập cho các nhóm cơ và phù hợp dùng để tập luyện thể hình cho nam nữ', 32000000, 'gian-ta-da-nang', 360000, '{"Mã sản phẩm": "M-888P", "Màu sắc": "Đen - xám", "Chất liệu": "Thép, nệm da", "Trọng lượng tạ": "132 kg", "Trọng lượng cả bộ": "360 kg", "Trọng lượng thùng": "Đang cập nhật", "Tải trọng tối đa": "700 kg", "Kích thước lắp đặt": "220 x 180 x 220cm", "Kích thước thùng": "Đang cập nhật"}'::jsonb, 'https://baoansport.vn/gian-ta-da-nang/gian-ta-da-nang-m-888p/'),
  ('xoay-eo-phong-tap-gym', 'BAS-1465', 'XEPT', 'Xoay eo cho phòng tập Gym', 'Xoay eo cho phòng tập Gym được làm chắc chắn từ thép hộp 50 x 100m dày 2.0mm, đĩa xoay chuyển động bằng trục bi và phù hợp dùng cho các phòng tập.', 'Xoay eo cho phòng tập Gym được làm chắc chắn từ thép hộp 50 x 100m dày 2.0mm, đĩa xoay chuyển động bằng trục bi và phù hợp dùng cho các phòng tập.', 2250000, 'may-tap-co-bung', 18500, '{"Mã sản phẩm": "XEPT", "Màu sắc": "Trắng hoặc xám", "Chất liệu": "Thép", "Trọng lượng máy": "18.5 kg", "Tải trọng tối đa": "150 kg", "Kích thước lắp đặt": "82 x 75 x 114cm", "Đường kính bàn xoay": "45cm"}'::jsonb, 'https://baoansport.vn/may-tap-co-bung/xoay-eo-phong-tap-gym/'),
  ('dia-xoay-eo-co-day-dan-hoi', 'BAS-1447', 'DXCDDH', 'Đĩa xoay eo có dây đàn hồi', 'Đĩa xoay eo có dây đàn hồi được làm từ nhựa cao cấp, chuyển động trơn tru bởi hệ thống bi nằm ở trong và tích hợp thêm dây kháng lực giúp giữ thăng bằng.', 'Đĩa xoay eo có dây đàn hồi được làm từ nhựa cao cấp, chuyển động trơn tru bởi hệ thống bi nằm ở trong và tích hợp thêm dây kháng lực giúp giữ thăng bằng.', 150000, 'phu-kien-tap-gym', 0, '{"Mã sản phẩm": "DXCDDH", "Màu sắc": "Hồng + trắng, Tím + trắng", "Chất liệu": "Nhựa, dây đàn hồi", "Trọng lượng": "900 gram", "Trọng lượng hộp": "1 kg", "Tải trọng tối đa": "100 kg", "Kích thước đĩa xoay": "26 x 3cm", "Kích thước hộp": "28 x 28 x 4cm"}'::jsonb, 'https://baoansport.vn/phu-kien-tap-gym/dia-xoay-eo-co-day-dan-hoi/'),
  ('ghe-tap-lung-bung-m-001', 'BAS-1446', 'M-001', 'Ghế tập lưng bụng M-001', 'Ghế tập lưng bụng M-001 được thiết kế chắc chắn, có thể điều chỉnh độ dốc khi dùng và có chức năng hỗ trợ các bài tập chuyên sâu cho nhóm cơ lưng bụng.', 'Ghế tập lưng bụng M-001 được thiết kế chắc chắn, có thể điều chỉnh độ dốc khi dùng và có chức năng hỗ trợ các bài tập chuyên sâu cho nhóm cơ lưng bụng.', 2400000, 'ghe-tap-bung', 10500, '{"Mã sản phẩm": "M-001", "Màu sắc": "Ghi xám - Đen cam", "Chất liệu": "Thép, mút da", "Trọng lượng": "10.5 kg", "Trọng lượng thùng": "12 kg", "Tải trọng tối đa": "120 kg", "Kích thước thùng": "106 x 43 x 15cm", "Kích thước gập gọn": "93 x 47cm", "Kích thước lắp đặt": "104 x 47 x 93cm"}'::jsonb, 'https://baoansport.vn/ghe-tap-bung/ghe-tap-lung-bung-m-001/'),
  ('luoi-cau-long-victor-c-7004', 'BAS-1445', 'C-7004', 'Lưới cầu lông Victor C-7004', 'Lưới cầu lông Victor C-7004 làm từ 100% chất liệu Polyester, mắt lưới to đều, có dây căng đi kèm và đạt tiêu chuẩn thi đấu của liên đoàn cầu lông Thế giới.', 'Lưới cầu lông Victor C-7004 làm từ 100% chất liệu Polyester, mắt lưới to đều, có dây căng đi kèm và đạt tiêu chuẩn thi đấu của liên đoàn cầu lông Thế giới.', 180000, 'tru-luoi-cau-long', 0, '{"Mã sản phẩm": "C-7004", "Màu sắc": "Đỏ - trắng", "Chất liệu": "Polyester", "Kích thước mắt lưới": "14mm", "Kích thước lưới": "604 x 76 cm", "Trọng lượng": "500 gram", "Hộp đựng": "Có"}'::jsonb, 'https://baoansport.vn/tru-luoi-cau-long/luoi-cau-long-victor-c-7004/'),
  ('xe-dap-tap-the-duc-pro-x709', 'BAS-1427', 'Pro-X709', 'Xe đạp tập thể dục Pro-X709', 'Xe đạp tập thể dục Pro-X709 hãng Pro Fitness được thiết kế chắc chắn, hỗ trợ đạp xe tại nhà giúp giảm cân và nâng cao sức khỏe hiệu quả cho cả gia đình.', 'Xe đạp tập thể dục Pro-X709 hãng Pro Fitness được thiết kế chắc chắn, hỗ trợ đạp xe tại nhà giúp giảm cân và nâng cao sức khỏe hiệu quả cho cả gia đình.', 3200000, 'xe-dap-tap-the-duc', 28000, '{"Mã sản phẩm": "Pro-X709", "Màu sắc": "Đen - đỏ", "Chất liệu": "Thép, nhựa", "Trọng lượng bánh đà": "8 kg", "Trọng lượng xe": "28 kg", "Trọng lượng thùng": "30 kg", "Tải trọng tối đa": "120 kg", "Kích thước lắp đặt": "105 x 50 x 102 cm", "Kích thước thùng": "102 x 23.5 x 79 cm", "Yên xe": "Có", "Chuyển động": "Dây curoa + bánh đà", "Kháng lực": "Nhiều mức", "Đo nhịp tim": "Có"}'::jsonb, 'https://baoansport.vn/xe-dap-tap-the-duc/xe-dap-tap-the-duc-pro-x709/'),
  ('tham-tap-yoga-adidas-admt-12235', 'BAS-1429', 'ADMT-12235', 'Thảm tập Yoga Adidas ADMT-12235', 'Thảm tập Yoga Adidas ADMT-12235 chính hãng được làm từ chất liệu cao su NBR cao cấp, độ dày tới 1cm và bề mặt có khả năng chống trơn trượt cực tốt.', 'Thảm tập Yoga Adidas ADMT-12235 chính hãng được làm từ chất liệu cao su NBR cao cấp, độ dày tới 1cm và bề mặt có khả năng chống trơn trượt cực tốt.', 1350000, 'tham-tap-yoga', 1100, '{"Mã sản phẩm": "ADMT-12235", "Màu sắc": "Đen - đỏ", "Chất liệu": "Cao su NBR", "Độ dày thảm": "10mm", "Kích thước": "183 x 61 cm", "Trọng lượng": "1.1 kg", "Phụ kiện đi kèm": "Dây đeo"}'::jsonb, 'https://baoansport.vn/tham-tap-yoga/tham-tap-yoga-adidas-admt-12235/'),
  ('dung-dich-chong-mo-kinh-boi-view', 'BAS-1431', 'View-Anti-Fog', 'Dung dịch chống mờ kính bơi View', 'Dung dịch chống mờ kính bơi View là sản phẩm chuyên dụng, có tác dụng giúp tránh tình trạng hơi nước đọng vào mắt kính và để giúp nhìn rõ hơn khi đi bơi.', 'Dung dịch chống mờ kính bơi View là sản phẩm chuyên dụng, có tác dụng giúp tránh tình trạng hơi nước đọng vào mắt kính và để giúp nhìn rõ hơn khi đi bơi.', 180000, 'phu-kien-boi-loi', 0, '{"Mã sản phẩm": "View-Anti-Fog", "Dạng": "Dung dịch", "Dung tích": "15ml", "Túi đựng": "Có"}'::jsonb, 'https://baoansport.vn/phu-kien-boi-loi/dung-dich-chong-mo-kinh-boi-view/'),
  ('gang-tay-boxing-tre-em-kangrui', 'BAS-1432', 'GBXTE', 'Găng tay Boxing trẻ em Kangrui', 'Găng tay Boxing trẻ em Kangrui được may chắc chắn từ chất liệu da PU, bên trong đệm lót EVA, kích thước 6oz và phù hợp dùng cho trẻ từ 5 đến 12 tuổi.', 'Găng tay Boxing trẻ em Kangrui được may chắc chắn từ chất liệu da PU, bên trong đệm lót EVA, kích thước 6oz và phù hợp dùng cho trẻ từ 5 đến 12 tuổi.', 320000, 'gang-tay-boxing', 0, '{"Mã sản phẩm": "GBXTE", "Màu sắc": "Đỏ", "Chất liệu": "PU, EVA", "PU, EVA": "6oz", "Độ tuổi phù hợp": "5 đến 12 tuổi"}'::jsonb, 'https://baoansport.vn/gang-tay-boxing/gang-tay-boxing-tre-em-kangrui/'),
  ('mu-boi-whale-3d', 'BAS-1433', 'CAP-1800', 'Mũ bơi Whale 3D', 'Mũ bơi Whale 3D được làm từ 100% chất liệu Silicon cao cấp, đảm bảo an toàn cho sức khỏe người dùng và có chức năng chống nước tràn vào tóc khi bơi.', 'Mũ bơi Whale 3D được làm từ 100% chất liệu Silicon cao cấp, đảm bảo an toàn cho sức khỏe người dùng và có chức năng chống nước tràn vào tóc khi bơi.', 190000, 'mu-boi', 0, '{"Mã sản phẩm": "CAP-1800", "Màu sắc": "Nhiều màu", "Chất liệu": "Silicon", "Kích thước": "170 x 148mm", "Hộp đựng": "Có"}'::jsonb, 'https://baoansport.vn/mu-boi/mu-boi-whale-3d/'),
  ('mu-boi-silicone-gai', 'BAS-1434', 'MBSG', 'Mũ bơi Silicone gai', 'Mũ bơi Silicone gai được làm từ 100% chất liệu Silicone, thiết kế dạng gai giúp nâng cao khả năng giữ ấm cho đầu và phù hợp sử dụng để bơi cho người lớn.', 'Mũ bơi Silicone gai được làm từ 100% chất liệu Silicone, thiết kế dạng gai giúp nâng cao khả năng giữ ấm cho đầu và phù hợp sử dụng để bơi cho người lớn.', 140000, 'mu-boi', 0, '{"Mã sản phẩm": "MBSG", "Màu sắc": "Xám, hồng, cam, xanh, đen", "Chất liệu": "Silicon", "Kích thước": "21 x 18cm", "Túi đựng": "Có"}'::jsonb, 'https://baoansport.vn/mu-boi/mu-boi-silicone-gai/'),
  ('dai-lung-tap-gym-fed-yd-01', 'BAS-1435', 'YD-01', 'Đai lưng tập Gym FED YD-01', 'Đai lưng tập Gym FED-YD-01 làm từ da bò cao cấp, hỗ trợ lưng - bụng, cố định cột sống khi tập Squat và Deadlift. Có 3 size linh hoạt, an toàn và chắc chắn.', 'Đai lưng tập Gym FED-YD-01 làm từ da bò cao cấp, hỗ trợ lưng - bụng, cố định cột sống khi tập Squat và Deadlift. Có 3 size linh hoạt, an toàn và chắc chắn.', 580000, 'phu-kien-tap-gym', 0, '{"Mã sản phẩm": "YD-01", "Màu sắc": "Cam, đen", "Chất liệu": "Da bò", "Size": "M, L, XL", "Trọng lượng": "650-750 gram"}'::jsonb, 'https://baoansport.vn/phu-kien-tap-gym/dai-lung-tap-gym-fed-yd-01/'),
  ('may-chay-bo-pro-fitness-pf-113da', 'BAS-1437', 'PF-113DA', 'Máy chạy bộ Pro Fitness PF-113DA', 'Máy chạy bộ Pro Fitness PF-113DA New được thiết kế đa năng, trang bị động cơ DC có công suất tối đa lên đến 2.5Hp và phù hợp sử dụng cho gia đình.', 'Máy chạy bộ Pro Fitness PF-113DA New được thiết kế đa năng, trang bị động cơ DC có công suất tối đa lên đến 2.5Hp và phù hợp sử dụng cho gia đình.', 12400000, 'may-chay-bo', 67000, '{"Mã sản phẩm": "PF-113DA", "Màu sắc": "Đen - xám", "Điện áp": "220V, 50-60Hz", "Động cơ": "DC", "Công suất": "2.5Hp", "Tốc độ": "0.8 - 16 km/h", "Nâng độ dốc": "0 đến 15%", "Trọng lượng máy": "67 kg", "Trọng lượng thùng": "77 kg", "Tải trọng tối đa": "120 kg", "Kích thước bàn chạy": "125 x 46 cm", "Kích thước lắp đặt": "168 x 74 x 130 cm", "Kích thước gập gọn": "72 x 74 x 140 cm", "Kích thước thùng": "169 x 76 x 32.5 cm", "Màn hình": "LCD", "Thảm chạy": "Diamond Running Belt", "Giảm chấn": "Đệm cao su, lò xo", "Khóa an toàn": "Có", "Gập gọn": "Có", "Bánh xe di chuyển": "Có", "Cổng kết nối/sạc": "USB", "Âm thanh": "Loa Hi-Fi"}'::jsonb, 'https://baoansport.vn/may-chay-bo/may-chay-bo-pro-fitness-pf-113da/'),
  ('may-chay-bo-pro-fitness-pf-117d', 'BAS-1438', 'PF-117D', 'Máy chạy bộ Pro Fitness PF-117D', 'Máy chạy bộ Pro Fitness PF-117D được thiết kế chắc chắn, trang bị động cơ DC khủng với công suất tối đa lên đến 4.5Hp và phù hợp sử dụng cho gia đình.', 'Máy chạy bộ Pro Fitness PF-117D được thiết kế chắc chắn, trang bị động cơ DC khủng với công suất tối đa lên đến 4.5Hp và phù hợp sử dụng cho gia đình.', 20500000, 'may-chay-bo', 105000, '{"Mã sản phẩm": "PF-117D", "Màu sắc": "Đen - xám", "Điện áp": "220V, 50-60Hz", "Động cơ": "DC", "Công suất": "4.5Hp", "Tốc độ": "1 - 20 km/h", "Nâng độ dốc": "0 đến 15%", "Trọng lượng máy": "105 kg", "Trọng lượng thùng": "115 kg", "Tải trọng tối đa": "150 kg", "Kích thước bàn chạy": "140 x 52 cm", "Kích thước lắp đặt": "187 x 78 x 149 cm", "Kích thước gập gọn": "97 x 78 x 151 cm", "Kích thước thùng": "198 x 90 x 41 cm", "Màn hình": "Cảm ứng", "Thảm chạy": "Diamond Running Belt", "Giảm chấn": "Đệm cao su, lò xo", "Khóa an toàn": "Có", "Gập gọn": "Có", "Bánh xe di chuyển": "Có", "Cổng kết nối/sạc": "USB", "Âm thanh": "Loa Hi-Fi"}'::jsonb, 'https://baoansport.vn/may-chay-bo/may-chay-bo-pro-fitness-pf-117d/'),
  ('may-chay-bo-phong-gym-sakura-v8', 'BAS-1439', 'V8', 'Máy chạy bộ phòng Gym Sakura V8', 'Máy chạy bộ phòng Gym Sakura V8 được thiết kế với khung máy cứng cáp, trang bị động cơ AC 3.0Hp đạt đỉnh 6.0Hp, kích thước bàn chạy rộng tới 58cm.', 'Máy chạy bộ phòng Gym Sakura V8 được thiết kế với khung máy cứng cáp, trang bị động cơ AC 3.0Hp đạt đỉnh 6.0Hp, kích thước bàn chạy rộng tới 58cm.', 38000000, 'may-chay-bo', 172000, '{"Mã sản phẩm": "V8", "Màu sắc": "Đen", "Điện áp": "220V, 50-60Hz", "Động cơ": "AC", "Công suất": "3.0Hp đỉnh 6.0Hp", "Tốc độ": "0.8 - 20 km/h", "Nâng độ dốc": "0 đến 18%", "Trọng lượng máy": "172 kg", "Trọng lượng thùng": "188 kg", "Tải trọng tối đa": "150 kg", "Kích thước bàn chạy": "155 x 58 cm", "Kích thước lắp đặt": "200 x 98.2 x 162 cm", "Kích thước gập gọn": "97 x 78 x 151 cm", "Kích thước thùng": "218 x 97 x 45.5 cm", "Màn hình": "LED", "Thảm chạy": "Diamond Running Belt", "Giảm chấn": "Đệm cao su", "Khóa an toàn": "Có", "Gập gọn": "Không", "Bánh xe di chuyển": "Có", "Cổng kết nối/sạc": "USB", "Âm thanh": "Loa Hi-Fi"}'::jsonb, 'https://baoansport.vn/may-chay-bo/may-chay-bo-phong-gym-sakura-v8/'),
  ('ban-bong-ban-ngoai-troi-tt002', 'BAS-1440', 'BBTT-002', 'Bàn bóng bàn ngoài trời TT-002', 'Bàn bóng bàn ngoài trời TT-002 được thiết kế chắc chắn, mặt bàn cho độ nảy chính xác và có khả năng chịu được điều kiện thời tiết nắng mưa khắc nghiệt.', 'Bàn bóng bàn ngoài trời TT-002 được thiết kế chắc chắn, mặt bàn cho độ nảy chính xác và có khả năng chịu được điều kiện thời tiết nắng mưa khắc nghiệt.', 7800000, 'ban-bong-ban', 83000, '{"Mã sản phẩm": "BBTT-002", "Màu sắc": "Xanh - đen", "Chất liệu mặt bàn": "SMC (Composite)", "Độ dày mặt bàn": "14 mm", "Kích thước lắp đặt": "2740 x 1525 x 760 mm", "Trọng lượng bàn": "83 kg", "Trọng lượng đóng thùng": "86 kg", "Gập gọn": "Không"}'::jsonb, 'https://baoansport.vn/ban-bong-ban/ban-bong-ban-ngoai-troi-tt002/'),
  ('xe-dap-tap-the-duc-pro-fitness-pro-216a', 'BAS-1441', 'Pro-216A', 'Xe đạp tập thể dục Pro Fitness Pro-216A', 'Xe đạp tập thể dục Pro Fitness Pro-216A được thiết kế chắc chắn, hỗ trợ cả hai tư thế đứng đạp xe lẫn ngồi đạp xe và phù hợp sử dụng để tập cho gia đình.', 'Xe đạp tập thể dục Pro Fitness Pro-216A được thiết kế chắc chắn, hỗ trợ cả hai tư thế đứng đạp xe lẫn ngồi đạp xe và phù hợp sử dụng để tập cho gia đình.', 6200000, 'xe-dap-tap-the-duc', 46500, '{"Mã sản phẩm": "Pro-216A", "Màu sắc": "Xám - đen", "Chất liệu": "Thép, nhựa", "Trọng lượng bánh đà": "5 kg", "Trọng lượng xe": "46.5 kg", "Trọng lượng thùng": "53.5 kg", "Tải trọng tối đa": "110 kg", "Kích thước lắp đặt": "125 x 65 x 160 cm", "Kích thước thùng": "111 x 37 x 58.5 cm", "Yên xe": "Có", "Chuyển động": "Dây curoa + bánh đà", "Kháng lực": "8 mức", "Đo nhịp tim": "Có"}'::jsonb, 'https://baoansport.vn/xe-dap-tap-the-duc/xe-dap-tap-the-duc-pro-fitness-pro-216a/'),
  ('xe-dap-tap-the-duc-pro-fitness-pro-218a', 'BAS-1442', 'Pro-218A', 'Xe đạp tập thể dục Pro Fitness Pro-218A', 'Xe đạp tập thể dục Pro Fitness Pro-218A thuộc dòng xe đạp toàn thân, hỗ trợ các bài tập giúp giảm cân nhanh chóng và phù hợp để sử dụng cho hộ gia đình.', 'Xe đạp tập thể dục Pro Fitness Pro-218A thuộc dòng xe đạp toàn thân, hỗ trợ các bài tập giúp giảm cân nhanh chóng và phù hợp để sử dụng cho hộ gia đình.', 7600000, 'xe-dap-tap-the-duc', 50500, '{"Mã sản phẩm": "Pro-218A", "Màu sắc": "Xám - đen", "Chất liệu": "Thép, nhựa", "Trọng lượng bánh đà": "7 kg", "Trọng lượng xe": "50.5 kg", "Trọng lượng thùng": "58 kg", "Tải trọng tối đa": "150 kg", "Kích thước lắp đặt": "125 x 65 x 160 cm", "Kích thước thùng": "138 x 37 x 58.5 cm", "Yên xe": "Có", "Chuyển động": "Dây curoa + bánh đà", "Kháng lực": "8 mức", "Đo nhịp tim": "Có"}'::jsonb, 'https://baoansport.vn/xe-dap-tap-the-duc/xe-dap-tap-the-duc-pro-fitness-pro-218a/'),
  ('ban-bong-ban-harito-tt-006', 'BAS-1467', 'TT-006', 'Bàn bóng bàn Harito TT-006', 'Bàn bóng bàn Harito TT-006 được thiết kế đẹp mắt, mặt bàn làm từ chất liệu gỗ MDF cao cấp dày 25mm, chân bàn chắc chắn có khả năng gập gọn khi cần', 'Bàn bóng bàn Harito TT-006 được thiết kế đẹp mắt, mặt bàn làm từ chất liệu gỗ MDF cao cấp dày 25mm, chân bàn chắc chắn có khả năng gập gọn khi cần', 13000000, 'ban-bong-ban', 113000, '{"Mã sản phẩm": "TT-006", "Màu sắc": "Trắng, xanh", "Chất liệu": "Thép, gỗ MDF", "Độ dày mặt bàn": "25mm", "Kích thước lắp đặt": "2740 x 1525 x 760mm", "Kích thước thùng": "1600 x 1480 x 170mm", "Trọng lượng bàn": "113 kg", "Trọng lượng thùng": "117 kg", "Bánh xe di chuyển": "Có", "Khả năng gập gọn": "Có"}'::jsonb, 'https://baoansport.vn/ban-bong-ban/ban-bong-ban-harito-tt-006/'),
  ('ban-bong-ban-harito-tt-008', 'BAS-1468', 'TT-008', 'Bàn bóng bàn Harito TT-008 Plus', 'Bàn bóng bàn Harito TT-008 Plus đạt chuẩn thi đấu, mặt MDF 25mm chống lóa, chân chắc chắn và gập gọn tiện lợi. Chính hãng, giá tốt, bảo hành 12 tháng.', 'Bàn bóng bàn Harito TT-008 Plus đạt chuẩn thi đấu, mặt MDF 25mm chống lóa, chân chắc chắn và gập gọn tiện lợi. Chính hãng, giá tốt, bảo hành 12 tháng.', 10900000, 'ban-bong-ban', 117000, '{"Mã sản phẩm": "TT-008", "Màu sắc": "Trắng, xanh", "Chất liệu": "Thép, gỗ MDF", "Độ dày mặt bàn": "25mm", "Kích thước lắp đặt": "2740 x 1525 x 760mm", "Kích thước thùng": "1600 x 1450 x 170mm", "Trọng lượng bàn": "117 kg", "Trọng lượng thùng": "120 kg", "Bánh xe di chuyển": "Có", "Khả năng gập gọn": "Có"}'::jsonb, 'https://baoansport.vn/ban-bong-ban/ban-bong-ban-harito-tt-008/'),
  ('luoi-tennis-325348c', 'BAS-1469', '325348C', 'Lưới Tennis thi đấu 325348C', 'Lưới Tennis thi đấu 325348C được đan bằng tay theo kỹ thuật cao, không thụng ở giữa và phù hợp sử dụng để lắp đặt cho sân Tennis thi đấu chuyên nghiệp.', 'Lưới Tennis thi đấu 325348C được đan bằng tay theo kỹ thuật cao, không thụng ở giữa và phù hợp sử dụng để lắp đặt cho sân Tennis thi đấu chuyên nghiệp.', 1950000, 'tru-luoi-tennis', 0, '{"Mã sản phẩm": "325348C", "Màu sắc": "Đen", "Chất liệu": "Sợi BR-PE, PVC", "Kích thước lưới": "1.07 x 12.7m", "Cáp căng lưới": "Có", "Trọng lượng": "Đang cập nhật"}'::jsonb, 'https://baoansport.vn/tru-luoi-tennis/luoi-tennis-325348c/'),
  ('tru-bong-tap-phan-xa-cho-tre-em', 'BAS-1491', 'TBTPXTE', 'Trụ bóng tập phản xạ cho trẻ em', 'Trụ bóng tập phản xạ cho trẻ em thiết kế tự đứng bằng hệ thống hút chân không, chiều cao điều chỉnh từ 97 đến 113cm và phù hợp dùng cho bé từ 6-12 tuổi.', 'Trụ bóng tập phản xạ cho trẻ em thiết kế tự đứng bằng hệ thống hút chân không, chiều cao điều chỉnh từ 97 đến 113cm và phù hợp dùng cho bé từ 6-12 tuổi.', 500000, 'bao-cat-dam-boc', 2000, '{"Mã sản phẩm": "TBTPXTE", "Màu sắc": "Đen đỏ", "Chất liệu": "Da PU, EVA, thép", "Chiều cao trụ": "Từ 97 đến 113cm", "Kích thước đế": "18 x 18cm", "Số mút hút": "4 chiếc", "Trọng lượng": "2kg", "Kích thước hộp": "49 x 13 x 12cm"}'::jsonb, 'https://baoansport.vn/bao-cat-dam-boc/tru-bong-tap-phan-xa-cho-tre-em/'),
  ('khung-ganh-ta-da-nang-m-666p', 'BAS-1492', 'M-666P', 'Khung gánh tạ đa năng M-666P', 'Khung gánh tạ đa năng M-666P được thiết kế chắc chắn, hỗ trợ nhiều bài tập thể hình hiệu quả và phù hợp sử dụng lắp cho phòng Gym gia đình hay công ty.', 'Khung gánh tạ đa năng M-666P được thiết kế chắc chắn, hỗ trợ nhiều bài tập thể hình hiệu quả và phù hợp sử dụng lắp cho phòng Gym gia đình hay công ty.', 13300000, 'gian-ta-da-nang', 200000, '{"Mã sản phẩm": "M-666P", "Màu sắc": "Cam - đen", "Chất liệu": "Thép, nệm da", "Trọng lượng tạ": "63 kg", "Trọng lượng cả bộ": "200 kg", "Tải trọng tối đa": "300 kg", "Kích thước lắp đặt": "200 x 150 x 213cm", "Kích thước thùng": "Đang cập nhập", "Số kiện vận chuyển": "5"}'::jsonb, 'https://baoansport.vn/gian-ta-da-nang/khung-ganh-ta-da-nang-m-666p/'),
  ('khung-ganh-ta-da-nang-k9', 'BAS-1493', 'K9', 'Khung gánh tạ đa năng K9', 'Khung gánh tạ đa năng K9 được nâng cấp từ bộ khung K8, thiết kế chắc chắn hơn và hỗ trợ đầy đủ các bài tập như Squat, đẩy ngực, tập xà đơn, tập xà kép,...', 'Khung gánh tạ đa năng K9 được nâng cấp từ bộ khung K8, thiết kế chắc chắn hơn và hỗ trợ đầy đủ các bài tập như Squat, đẩy ngực, tập xà đơn, tập xà kép,...', 16500000, 'gian-ta-da-nang', 166000, '{"Mã sản phẩm": "K9", "Màu sắc": "Cam - đen", "Chất liệu": "Thép, nệm da", "Tạ đi kèm": "Chưa bao gồm", "Trọng lượng cả bộ": "166 kg", "Tải trọng tối đa": "300 kg", "Kích thước lắp đặt": "136 x 210 x 215cm", "Kích thước thùng": "Đang cập nhập", "Số kiện vận chuyển": "4"}'::jsonb, 'https://baoansport.vn/gian-ta-da-nang/khung-ganh-ta-da-nang-k9/'),
