  ('tham-cau-long-alite-a-23145', 'BAS-1497', 'A-23145', 'Thảm cầu lông Alite A-23145', 'Thảm cầu lông Alite A-23145 chính hãng Enlio được làm từ chất liệu PVC, độ dày 4.5mm, bề mặt thảm có độ đàn hồi cao và khả năng chống trơn trượt tốt.', 'Thảm cầu lông Alite A-23145 chính hãng Enlio được làm từ chất liệu PVC, độ dày 4.5mm, bề mặt thảm có độ đàn hồi cao và khả năng chống trơn trượt tốt.', 35500000, 'tham-san-cau-long', 0, '{"Mã sản phẩm": "A-23145", "Màu sắc": "Xanh", "Chất liệu": "PVC", "Độ dày lớp chống mòn": "1.3mm", "Độ dày thảm cầu lông": "4.5mm", "Kích thước cuộn thảm": "15 x 1.8m", "Kích thước sân đấu": "13.4 x 6.1m", "Kích thước toàn sân": "15 x 7.2m", "Diện tích toàn sân": "108m²"}'::jsonb, 'https://baoansport.vn/tham-san-cau-long/tham-cau-long-alite-a-23145/'),
  ('tham-cau-long-enlio-a-22145', 'BAS-1498', 'A-22145', 'Thảm cầu lông Enlio A-22145', 'Thảm cầu lông Enlio A-22145 chính hãng được sản xuất từ chất liệu PVC cao cấp, gồm 5 lớp với độ dày 4.5mm và sử dụng công nghệ hàn nhiệt để thi công.', 'Thảm cầu lông Enlio A-22145 chính hãng được sản xuất từ chất liệu PVC cao cấp, gồm 5 lớp với độ dày 4.5mm và sử dụng công nghệ hàn nhiệt để thi công.', 29000000, 'tham-san-cau-long', 0, '{"Mã sản phẩm": "A-22145", "Màu sắc": "Xanh", "Chất liệu": "PVC", "Độ dày lớp chống mòn": "1.5mm", "Độ dày thảm cầu lông": "4.5mm", "Kích thước cuộn thảm": "15 x 1.8m", "Kích thước sân đấu": "13.4 x 6.1m", "Kích thước toàn sân": "15 x 7.2m", "Diện tích toàn sân": "108m²"}'::jsonb, 'https://baoansport.vn/tham-san-cau-long/tham-cau-long-enlio-a-22145/'),
  ('khung-ganh-ta-impulse-sl7014', 'BAS-1500', 'SL7014', 'Khung gánh tạ Impulse SL7014', 'Khung gánh tạ Impulse SL7014 chính hãng thiết kế chắc chắn, có khả năng chịu được tải trọng tối đa đến 250kg và phù hợp sử dụng để lắp cho phòng Gym', 'Khung gánh tạ Impulse SL7014 chính hãng thiết kế chắc chắn, có khả năng chịu được tải trọng tối đa đến 250kg và phù hợp sử dụng để lắp cho phòng Gym', 20750000, 'gian-ta-da-nang', 167800, '{"Mã sản phẩm": "SL7014", "Màu sắc": "Đen - đỏ", "Chất liệu": "Thép", "Trọng lượng khung": "153 kg", "Trọng lượng thùng": "167.8 kg", "Tải trọng tối đa": "250 kg", "Kích thước lắp đặt": "1390 x 1747 x 2442mm", "Đòn tạ đi kèm": "Chưa bao gồm", "Bánh tạ đi kèm": "Chưa bao gồm"}'::jsonb, 'https://baoansport.vn/gian-ta-da-nang/khung-ganh-ta-impulse-sl7014/'),
  ('khung-ganh-ta-impulse-it7001', 'BAS-1501', 'IT7001', 'Khung gánh tạ Impulse IT7001', 'Khung gánh tạ Impulse IT7001 thuộc dòng khung Smith của hãng Impulse, thiết kế vô cùng chắc chắn, chịu tải tối đa 600kg và bao gồm đòn tạ Squat đi kèm', 'Khung gánh tạ Impulse IT7001 thuộc dòng khung Smith của hãng Impulse, thiết kế vô cùng chắc chắn, chịu tải tối đa 600kg và bao gồm đòn tạ Squat đi kèm', 42000000, 'gian-ta-da-nang', 185000, '{"Mã sản phẩm": "IT7001", "Màu sắc": "Ghi xám", "Chất liệu": "Thép", "Trọng lượng khung": "178 kg", "Trọng lượng thùng": "185 kg", "Tải trọng tối đa": "300 kg", "Kích thước lắp đặt": "2241 x 1326 x 2370mm", "Đòn tạ đi kèm": "Chưa bao gồm"}'::jsonb, 'https://baoansport.vn/gian-ta-da-nang/khung-ganh-ta-impulse-it7001/'),
  ('gian-ta-da-nang-impulse-if1860', 'BAS-1502', 'IF1860', 'Giàn tạ đa năng Impulse IF1860', 'Giàn tạ đa năng Impulse IF1860 thiết kế chắc chắn, trang bị 91kg tạ khối đi kèm và phù hợp sử dụng để lắp cho phòng tập Gym gia đình, cơ quan, khách sạn', 'Giàn tạ đa năng Impulse IF1860 thiết kế chắc chắn, trang bị 91kg tạ khối đi kèm và phù hợp sử dụng để lắp cho phòng tập Gym gia đình, cơ quan, khách sạn', 39000000, 'gian-ta-da-nang', 254000, '{"Mã sản phẩm": "IF1860", "Màu sắc": "Ghi xám, đen", "Chất liệu": "Thép, nệm da", "Trọng lượng tạ": "91 kg", "Trọng lượng cả bộ": "254 kg", "Trọng lượng thùng": "Đang cập nhật", "Tải trọng tối đa": "300 kg", "Kích thước lắp đặt": "1799 x 1207 x 2114mm", "Kích thước thùng": "Đang cập nhật"}'::jsonb, 'https://baoansport.vn/gian-ta-da-nang/gian-ta-da-nang-impulse-if1860/'),
  ('bang-bong-ro-viet-nam', 'BAS-1503', 'BBRVN', 'Bảng bóng rổ Việt Nam', 'Bảng bóng rổ Việt Nam làm từ gỗ ép phủ lớp sợi thủy tinh composite ở ngoài, có khả năng chịu được điều kiện nắng mưa khắc nghiệt và có nhiều kích thước.', 'Bảng bóng rổ Việt Nam làm từ gỗ ép phủ lớp sợi thủy tinh composite ở ngoài, có khả năng chịu được điều kiện nắng mưa khắc nghiệt và có nhiều kích thước.', 1200000, 'phu-kien-bong-ro', 0, '{"Mã sản phẩm": "BBRVN", "Màu sắc": "Trắng - đen", "Vật liệu": "MDF, composite", "Độ dày bảng": "2.2 đến 2.4cm", "Kích thước bảng": "90 x 60cm; 120 x 90cm; 180 x 105cm"}'::jsonb, 'https://baoansport.vn/phu-kien-bong-ro/bang-bong-ro-viet-nam/'),
  ('bong-tennis-dunlop-atp-championship', 'BAS-1504', 'ATP-Championship', 'Bóng Tennis Dunlop ATP Championship', 'Bóng Tennis Dunlop ATP Championship được làm từ cao su kết hợp với nỉ len, khả năng giữ hơi tốt, độ nảy chuẩn và đạt tiêu chuẩn thi đấu chuyên nghiệp.', 'Bóng Tennis Dunlop ATP Championship được làm từ cao su kết hợp với nỉ len, khả năng giữ hơi tốt, độ nảy chuẩn và đạt tiêu chuẩn thi đấu chuyên nghiệp.', 150000, 'bong-tennis', 0, '{"Mã sản phẩm": "ATP-Championship", "Màu sắc": "Xanh, đen", "Chất liệu": "Cao su, nỉ len", "Quy cách đóng hộp": "3 quả/hộp, 4 quả/hộp"}'::jsonb, 'https://baoansport.vn/bong-tennis/bong-tennis-dunlop-atp-championship/'),
  ('tru-dam-boc-goldnova-tj-708-pro', 'BAS-1490', 'TJ-708-Pro', 'Trụ đấm bốc Goldnova TJ-708 Pro', 'Trụ đấm bốc Goldnova TJ‑708 Pro cao 155cm, vỏ da PU dày bền, đế thép hút chân không, phù hợp trẻ 6 đến 15 tuổi. Mua tại Bảo An Sport, bảo hành 3 tháng.', 'Trụ đấm bốc Goldnova TJ‑708 Pro cao 155cm, vỏ da PU dày bền, đế thép hút chân không, phù hợp trẻ 6 đến 15 tuổi. Mua tại Bảo An Sport, bảo hành 3 tháng.', 2150000, 'bao-cat-dam-boc', 18000, '{"Mã sản phẩm": "TJ-708-Pro", "Màu sắc": "Đỏ - Xanh - Vàng", "Chất liệu": "Da PU, EVA, thép", "Chiều cao trụ": "155cm", "Đường kính bao": "26cm", "Kích thước đế": "42 x 42cm", "Kích thước thùng": "27 x 27 x 153cm và 42 x 42 x 4.5cm", "Số mút hút": "16 chiếc", "Trọng lượng": "18kg", "Trọng lượng cả thùng": "19.5kg"}'::jsonb, 'https://baoansport.vn/bao-cat-dam-boc/tru-dam-boc-goldnova-tj-708-pro/'),
  ('tru-dam-boc-tre-em-goldnova-tj-708', 'BAS-1489', 'TJ-708', 'Trụ đấm bốc trẻ em Goldnova TJ-708', 'Trụ đấm bốc trẻ em Goldnova TJ-708 thiết kế dạng tự đứng, chiều cao 115cm, đường kính thân trụ 21cm và phù hợp sử dụng để tập cho bé từ 4 đến 9 tuổi.', 'Trụ đấm bốc trẻ em Goldnova TJ-708 thiết kế dạng tự đứng, chiều cao 115cm, đường kính thân trụ 21cm và phù hợp sử dụng để tập cho bé từ 4 đến 9 tuổi.', 1550000, 'bao-cat-dam-boc', 0, '{"Mã sản phẩm": "TJ-708", "Màu sắc": "Đỏ - Xanh - Vàng", "Chất liệu": "Da PU, EVA, thép", "Chiều cao trụ": "115cm", "Đường kính bao": "21cm", "Kích thước đế": "36 x 36cm", "Kích thước thùng": "23 x 23 x 113cm và 37 x 37 x 4cm", "Số mút hút": "12 chiếc", "Trọng lượng trụ": "12kg", "Trọng lượng cả thùng": "13kg"}'::jsonb, 'https://baoansport.vn/bao-cat-dam-boc/tru-dam-boc-tre-em-goldnova-tj-708/'),
  ('tru-bong-ro-s030', 'BAS-1488', 'S030', 'Trụ bóng rổ S030', 'Trụ bóng rổ S030 nhập khẩu chính hãng từ Trung Quốc, chiều cao có thể điều chỉnh dễ dàng từ 1m45 đến 3m05 và phù hợp dùng lắp đặt cho các trường học.', 'Trụ bóng rổ S030 nhập khẩu chính hãng từ Trung Quốc, chiều cao có thể điều chỉnh dễ dàng từ 1m45 đến 3m05 và phù hợp dùng lắp đặt cho các trường học.', 14500000, 'tru-bong-ro', 0, '{"Mã sản phẩm": "S030", "Màu sắc": "Đen đỏ", "Chất liệu": "Thép, kính cường lực", "Chiều cao rổ": "Từ 1m45 đến 3m05", "Đường kính rổ": "45cm", "Kích thước bảng": "120 x 80 x 1cm", "Kích thước đế": "80 x 130 x 45cm", "Kích thước lắp đặt": "Đang cập nhật", "Kích thước thùng": "140 x 92 x 30cm", "Trọng lượng trụ": "64 kg", "Trọng lượng cả thùng": "68kg"}'::jsonb, 'https://baoansport.vn/tru-bong-ro/tru-bong-ro-s030/'),
  ('tru-bong-ro-di-dong-tt-101', 'BAS-1483', 'TT-101', 'Trụ bóng rổ di động TT-101', 'Trụ bóng rổ di động TT-101 được thiết kế chắc chắn, chiều cao vành rổ điều chỉnh dễ dàng từ 2m6 đến 3m05 và phù hợp lắp đặt chơi trong nhà lẫn ngoài trời.', 'Trụ bóng rổ di động TT-101 được thiết kế chắc chắn, chiều cao vành rổ điều chỉnh dễ dàng từ 2m6 đến 3m05 và phù hợp lắp đặt chơi trong nhà lẫn ngoài trời.', 8400000, 'tru-bong-ro', 0, '{"Mã sản phẩm": "TT-101", "Màu sắc": "Trắng", "Chất liệu": "Thép, composite", "Chiều cao vành rổ": "2m6 đến 3m05", "Kích thước bảng rổ": "1200 x 900 x 20mm", "Đường kính vành rổ": "450mm", "Kích thước đối trọng": "Đang cập nhật", "Trọng lượng trụ": "Đang cập nhật", "Kích thước lắp đặt": "Đang cập nhật", "Bánh xe di chuyển": "Có"}'::jsonb, 'https://baoansport.vn/tru-bong-ro/tru-bong-ro-di-dong-tt-101/'),
  ('vot-bong-ban-729-very-8-sao', 'BAS-1474', 'Very-8-sao', 'Vợt bóng bàn 729 Very 8 sao', 'Vợt bóng bàn 729 Very 8 sao cao cấp thuộc dòng vợt dán sẵn, có độ nảy chuẩn, dễ kiểm soát bóng và phù hợp sử dụng cho người chơi bóng bàn trình độ khá.', 'Vợt bóng bàn 729 Very 8 sao cao cấp thuộc dòng vợt dán sẵn, có độ nảy chuẩn, dễ kiểm soát bóng và phù hợp sử dụng cho người chơi bóng bàn trình độ khá.', 650000, 'vot-bong-ban', 0, '{"Mã sản phẩm": "Very-8-sao", "Màu sắc": "Đỏ, đen", "Chất liệu": "Gỗ, Carbon, mút cao su", "Độ dày mút vợt": "2.1mm", "Kích thước mặt vợt": "Kích thước mặt vợt", "Chiều dài cán vợt": "105mm", "Trọng lượng vợt": "225 gram", "Bao đựng vợt": "Có"}'::jsonb, 'https://baoansport.vn/vot-bong-ban/vot-bong-ban-729-very-8-sao/'),
  ('xe-dap-phuc-hoi-chuc-nang-dual-e-bike', 'BAS-1475', 'T698', 'Xe đạp điện phục hồi chức năng Dual E-Bike', 'Xe đạp phục hồi chức năng Dual E-Bike (T698) thiết kế chắc chắn, chạy tự động bằng điện và phù hợp cho người cao tuổi hoặc bệnh nhân tập vật lý trị liệu', 'Xe đạp phục hồi chức năng Dual E-Bike (T698) thiết kế chắc chắn, chạy tự động bằng điện và phù hợp cho người cao tuổi hoặc bệnh nhân tập vật lý trị liệu', 8250000, 'xe-dap-tap-the-duc', 24000, '{"Mã sản phẩm": "T698", "Màu sắc": "Xám", "Chất liệu": "Thép, nhựa", "Điện áp": "220V / 50 Hz", "Trọng lượng xe": "24 kg", "Trọng lượng thùng": "27 kg", "Tải trọng tối đa": "100 kg", "Tốc độ điều chỉnh": "12 cấp độ", "Chuyển động": "2 chiều", "Kích thước lắp đặt": "1050 x 535 x 1230 mm", "Kích thước thùng": "790 x 330 x 590 mm"}'::jsonb, 'https://baoansport.vn/xe-dap-tap-the-duc/xe-dap-phuc-hoi-chuc-nang-dual-e-bike/'),
  ('may-rung-massage-mhq-300s', 'BAS-1476', 'MHQ-300S', 'Máy rung massage MHQ 300S', 'Máy rung massage MHQ 300S được thiết kế chắc chắn, có 20 cấp độ rung, tích hợp 5 chương trình tập luyện và có chức năng đánh tan mỡ thừa hiệu quả', 'Máy rung massage MHQ 300S được thiết kế chắc chắn, có 20 cấp độ rung, tích hợp 5 chương trình tập luyện và có chức năng đánh tan mỡ thừa hiệu quả', 4650000, 'may-tap-co-bung', 18500, '{"Mã sản phẩm": "MHQ-300S", "Màu sắc": "Đỏ + đen", "Công suất": "100W", "Điện áp sử dụng": "220V - 50Hz", "Trọng lượng máy": "18.5 kg", "Trọng lượng thùng": "20.5 kg", "Tải trọng tối đa": "100 kg", "Kích thước lắp đặt": "69 x 43 x 110 cm", "Kích thước đóng thùng": "97.5 x 49 x 27 cm"}'::jsonb, 'https://baoansport.vn/may-tap-co-bung/may-rung-massage-mhq-300s/'),
  ('dong-ho-thi-dau-co-vua-leap-kk9908', 'BAS-1478', 'KK9908', 'Đồng hồ thi đấu cờ vua Leap KK9908', 'Đồng hồ thi đấu cờ vua Leap KK9908 thiết kế nhỏ gọn, có 36 chế độ cài đặt thời gian được lập trình sẵn phục vụ cho tất cả các hình thức chơi môn cờ vua.', 'Đồng hồ thi đấu cờ vua Leap KK9908 thiết kế nhỏ gọn, có 36 chế độ cài đặt thời gian được lập trình sẵn phục vụ cho tất cả các hình thức chơi môn cờ vua.', 680000, 'thiet-bi-day-hoc-the-duc', 0, '{"Mã sản phẩm": "KK9908", "Màn hình": "LCD", "Chất liệu": "ABS", "Pin sử dụng": "AA", "Kích thước": "17,5 x 10,2 x 58,0mm", "Trọng lượng": "150 gram", "Cài đặt sẵn": "36 chế độ"}'::jsonb, 'https://baoansport.vn/thiet-bi-day-hoc-the-duc/dong-ho-thi-dau-co-vua-leap-kk9908/'),
  ('tru-bong-ro-di-dong-tt-106', 'BAS-1479', 'TT-106', 'Trụ bóng rổ di động TT-106', 'Trụ bóng rổ di động TT-106 thiết kế chắc chắn, thùng đối trọng rỗng và đổ cát hoặc bê tông vào trong, chiều cao có thể điều chỉnh dễ dàng từ 2m1 đến 2m6', 'Trụ bóng rổ di động TT-106 thiết kế chắc chắn, thùng đối trọng rỗng và đổ cát hoặc bê tông vào trong, chiều cao có thể điều chỉnh dễ dàng từ 2m1 đến 2m6', 6850000, 'tru-bong-ro', 0, '{"Mã sản phẩm": "TT-106", "Màu sắc": "Trắng", "Chất liệu": "Thép, composite", "Chiều cao vành rổ": "2m1 đến 2m6", "Kích thước bảng rổ": "1200 x 900mm", "Đường kính vành rổ": "450mm", "Kích thước đối trọng": "40 x 60 x 20cm", "Trọng lượng trụ": "Đang cập nhật", "Kích thước lắp đặt": "Đang cập nhật"}'::jsonb, 'https://baoansport.vn/tru-bong-ro/tru-bong-ro-di-dong-tt-106/'),
  ('tru-bong-ro-di-dong-tt-108', 'BAS-1480', 'TT-108', 'Trụ bóng rổ di động TT-108', 'Trụ bóng rổ di động TT-108 được thiết kế chắc chắn, sử dụng đối trọng rỗng đổ cát hoặc bê tông và chiều cao vành rổ điều chỉnh dễ dàng từ 2m6 đến 3m05.', 'Trụ bóng rổ di động TT-108 được thiết kế chắc chắn, sử dụng đối trọng rỗng đổ cát hoặc bê tông và chiều cao vành rổ điều chỉnh dễ dàng từ 2m6 đến 3m05.', 9900000, 'tru-bong-ro', 0, '{"Mã sản phẩm": "TT-108", "Màu sắc": "Trắng", "Chất liệu": "Thép, composite", "Chiều cao vành rổ": "2m6 đến 3m05", "Kích thước bảng rổ": "1800 x 1050mm", "Đường kính vành rổ": "450mm", "Kích thước đối trọng": "38 x 60 x 40cm", "Trọng lượng trụ": "Đang cập nhật", "Kích thước lắp đặt": "Đang cập nhật"}'::jsonb, 'https://baoansport.vn/tru-bong-ro/tru-bong-ro-di-dong-tt-108/'),
  ('bang-bong-ro-kinh-cuong-luc', 'BAS-1481', 'BRKCL', 'Bảng bóng rổ kính cường lực', 'Bảng bóng rổ kính cường lực làm bằng kính cao cấp, có khả năng chịu lực tốt, cạnh được bo viền nhôm và phù hợp sử dụng để thay cho các bảng rổ bị hỏng.', 'Bảng bóng rổ kính cường lực làm bằng kính cao cấp, có khả năng chịu lực tốt, cạnh được bo viền nhôm và phù hợp sử dụng để thay cho các bảng rổ bị hỏng.', 6200000, 'tru-bong-ro', 50000, '{"Mã sản phẩm": "BRKCL", "Màu sắc": "Trắng", "Chất liệu": "Kính, nhôm, mút EVA", "Trọng lượng": "50kg", "Kích thước bảng": "1800 x 1050 x 10mm"}'::jsonb, 'https://baoansport.vn/tru-bong-ro/bang-bong-ro-kinh-cuong-luc/'),
  ('bang-bong-ro-composite-vifa-sport', 'BAS-1482', '800912(800518)', 'Bảng bóng rổ Composite Vifa Sport', 'Bảng bóng rổ Composite Vifa Sport làm từ chất liệu composite, có khả năng chịu được thời tiết khắc nghiệt và phù hợp sử dụng để thay cho bảng rổ bị hỏng.', 'Bảng bóng rổ Composite Vifa Sport làm từ chất liệu composite, có khả năng chịu được thời tiết khắc nghiệt và phù hợp sử dụng để thay cho bảng rổ bị hỏng.', 5400000, 'tru-bong-ro', 0, '{"Mã sản phẩm": "800912(800518)", "Màu sắc": "Trắng", "Chất liệu": "Gỗ, composite", "Kích thước bảng": "1200 x 900mm và 1800 x 1050mm", "Độ dày bảng": "20mm và 25mm", "Trọng lượng": "Đang cập nhật"}'::jsonb, 'https://baoansport.vn/tru-bong-ro/bang-bong-ro-composite-vifa-sport/'),
  ('hop-bong-ban-100-qua-aurora-3-star', 'BAS-1484', 'Aurora-3Star', 'Hộp bóng bàn 100 quả Aurora 3 Star', 'Hộp bóng bàn 100 quả Aurora 3 Star 40+ chính hãng được làm từ chất liệu nhựa ABS, quả bóng tròn đều, không mối nối và cho độ nảy chuẩn xác khi đánh.', 'Hộp bóng bàn 100 quả Aurora 3 Star 40+ chính hãng được làm từ chất liệu nhựa ABS, quả bóng tròn đều, không mối nối và cho độ nảy chuẩn xác khi đánh.', 600000, 'qua-bong-ban', 0, '{"Mã sản phẩm": "Aurora-3Star", "Màu sắc bóng": "Trắng", "Đường kính bóng": "40 ~ 40.7mm", "Trọng lượng bóng": "27.4-27.6 gram", "Độ nảy bóng": "≥ 235mm", "Quy cách đóng hộp": "100 quả/hộp", "Kích thước hộp": "25 x 20 x 15.5cm", "Trọng lượng hộp": "500 gram"}'::jsonb, 'https://baoansport.vn/qua-bong-ban/hop-bong-ban-100-qua-aurora-3-star/'),
  ('bang-bong-ro-treo-tuong-td-012', 'BAS-1485', 'TD-012', 'Bảng bóng rổ treo tường TD-012', 'Bảng bóng rổ treo tường TD-012 được thiết kế chắc chắn, gắn cố định vào tường bằng hệ thống nở sắt và phù hợp dùng để chơi bóng rổ ở nhà cho cá nhân.', 'Bảng bóng rổ treo tường TD-012 được thiết kế chắc chắn, gắn cố định vào tường bằng hệ thống nở sắt và phù hợp dùng để chơi bóng rổ ở nhà cho cá nhân.', 3850000, 'tru-bong-ro', 0, '{"Mã sản phẩm": "TD-012", "Màu sắc": "Trắng", "Chất liệu": "Thép, composite", "Kích thước bảng": "1200 x 900 x 20mm", "Đường kính vành rổ": "450mm", "Trọng lượng bảng": "Đang cập nhật", "Kích thước lắp đặt": "Đang cập nhật"}'::jsonb, 'https://baoansport.vn/tru-bong-ro/bang-bong-ro-treo-tuong-td-012/'),
  ('tru-bong-chuyen-di-dong-ba-01', 'BAS-1486', 'BA-01', 'Trụ bóng chuyền di động BA-01', 'Trụ bóng chuyền di động BA-01 được thiết kế chắc chắn, sử dụng đối trọng rỗng, có thể di chuyển dễ dàng và điều chỉnh độ cao trong khoảng từ 2m đến 2m45.', 'Trụ bóng chuyền di động BA-01 được thiết kế chắc chắn, sử dụng đối trọng rỗng, có thể di chuyển dễ dàng và điều chỉnh độ cao trong khoảng từ 2m đến 2m45.', 4950000, 'tru-luoi-bong-chuyen', 0, '{"Mã sản phẩm": "BA-01", "Màu sắc": "Xanh", "Chất liệu": "Thép", "Chiều cao điều chỉnh": "200cm đến 245cm", "Kích thước đế": "100 x 60cm", "Kích thước đối trọng": "61 x 25 x 22cm", "Số hộp đối trọng": "4", "Tay quay căng lưới": "Có", "Bánh xe di chuyển": "Có"}'::jsonb, 'https://baoansport.vn/tru-luoi-bong-chuyen/tru-bong-chuyen-di-dong-ba-01/'),
  ('tru-bong-chuyen-di-dong-ba-02', 'BAS-1487', 'BA-02', 'Trụ bóng chuyền di động BA-02', 'Trụ bóng chuyền di động BA-02 được thiết kế chắc chắn từ thép ống D90, sử dụng đối trọng rỗng đổ cát hoặc sỏi và chiều cao điều chỉnh dễ từ 2m2 đến 2m5.', 'Trụ bóng chuyền di động BA-02 được thiết kế chắc chắn từ thép ống D90, sử dụng đối trọng rỗng đổ cát hoặc sỏi và chiều cao điều chỉnh dễ từ 2m2 đến 2m5.', 5950000, 'tru-luoi-bong-chuyen', 0, '{"Mã sản phẩm": "BA-02", "Màu sắc": "Xanh", "Chất liệu": "Thép", "Chiều cao điều chỉnh": "220cm đến 250cm", "Kích thước đế": "100 x 60cm", "Kích thước đối trọng": "61 x 25 x 22cm", "Số hộp đối trọng": "4", "Tay quay căng lưới": "Có", "Bánh xe di chuyển": "Có"}'::jsonb, 'https://baoansport.vn/tru-luoi-bong-chuyen/tru-bong-chuyen-di-dong-ba-02/'),
  ('bong-tennis-wilson-championship-do', 'BAS-1505', 'WCD', 'Bóng Tennis Wilson Championship Đỏ', 'Bóng Tennis Wilson Championship Đỏ được làm từ chất liệu cao su kết hợp với nỉ, độ nảy cực chuẩn khi chơi và đạt tiêu chuẩn thi đấu Tennis chuyên nghiệp.', 'Bóng Tennis Wilson Championship Đỏ được làm từ chất liệu cao su kết hợp với nỉ, độ nảy cực chuẩn khi chơi và đạt tiêu chuẩn thi đấu Tennis chuyên nghiệp.', 210000, 'bong-tennis', 0, '{"Mã sản phẩm": "WCD", "Màu sắc": "Vàng cam", "Chất liệu": "Cao su, nỉ len", "Quy cách đóng hộp": "4 quả/hộp"}'::jsonb, 'https://baoansport.vn/bong-tennis/bong-tennis-wilson-championship-do/'),
  ('tham-trai-san-the-thao-da-nang', 'BAS-1259', 'T-90145', 'Thảm trải sàn thể thao đa năng', 'Thảm trải sàn thể thao đa năng được sản xuất từ chất liệu PVC, bề mặt vân gỗ chống trơn trượt tốt và chuyên sử dụng để thi công sân bóng chuyền, bóng rổ.', 'Thảm trải sàn thể thao đa năng được sản xuất từ chất liệu PVC, bề mặt vân gỗ chống trơn trượt tốt và chuyên sử dụng để thi công sân bóng chuyền, bóng rổ.', 650000, 'phu-kien-bong-chuyen', 0, '{"Mã sản phẩm": "T-90145", "Màu sắc": "Vân gỗ", "Chất liệu": "PVC", "Kích thước 1 cuộn": "15 x 1.8m", "Độ dày thảm": "4.5mm"}'::jsonb, 'https://baoansport.vn/phu-kien-bong-chuyen/tham-trai-san-the-thao-da-nang/'),
  ('tru-bong-chuyen-402442', 'BAS-345', '402442', 'Trụ bóng chuyền 402442', 'Trụ bóng chuyền 402442 (V4442) hãng Vifa Sport được thiết kế chắc chắn từ trụ kẽm D90, đạt chuẩn thi đấu và phù hợp sử dụng lắp đặt tại các trường học.', 'Trụ bóng chuyền 402442 (V4442) hãng Vifa Sport được thiết kế chắc chắn từ trụ kẽm D90, đạt chuẩn thi đấu và phù hợp sử dụng lắp đặt tại các trường học.', 5150000, 'tru-luoi-bong-chuyen', 0, '{"Mã sản phẩm": "402442", "Màu sắc": "Trắng", "Kích thước": "3000 x 90mm", "Nòng trụ đi kèm": "Chưa bao gồm"}'::jsonb, 'https://baoansport.vn/tru-luoi-bong-chuyen/tru-bong-chuyen-402442/'),
  ('tru-cau-long-501522', 'BAS-418', '501522', 'Trụ cầu lông 501522', 'Trụ cầu lông 501522 hãng Vifa Sport được làm chắc chắn + có bánh xe di chuyển, đạt tiêu chuẩn tập luyện và phù hợp dùng để chơi cầu lông tại trường học.', 'Trụ cầu lông 501522 hãng Vifa Sport được làm chắc chắn + có bánh xe di chuyển, đạt tiêu chuẩn tập luyện và phù hợp dùng để chơi cầu lông tại trường học.', 2650000, 'tru-luoi-cau-long', 0, '{"Mã sản phẩm": "501522", "Màu sắc": "Xanh", "Kích thước": "1560 x 800 x 500mm", "Đối trọng": "30 kg/trụ"}'::jsonb, 'https://baoansport.vn/tru-luoi-cau-long/tru-cau-long-501522/'),
  ('tru-cau-long-da-nang', 'BAS-421', 'TDN', 'Trụ cầu lông đa năng', 'Trụ cầu lông đa năng được làm chắc chắn, chuyên cho trường học và phù hợp sử dụng để tập luyện những môn thể thao như cầu lông, đá cầu hay nhảy cao.', 'Trụ cầu lông đa năng được làm chắc chắn, chuyên cho trường học và phù hợp sử dụng để tập luyện những môn thể thao như cầu lông, đá cầu hay nhảy cao.', 1200000, 'tru-luoi-cau-long', 0, '{"Mã sản phẩm": "TDN", "Màu sắc": "Xanh, trắng", "Chất liệu": "Thép", "Đối trọng": "38Kg", "Chiều cao tối đa": "2m"}'::jsonb, 'https://baoansport.vn/tru-luoi-cau-long/tru-cau-long-da-nang/'),
  ('luoi-cau-long-hai-yen', 'BAS-423', 'LCLHY', 'Lưới cầu lông Hải Yến', 'Lưới cầu lông Hải Yến được làm từ sợi tổng hợp, có mắt lưới đều, không bị xô và phù hợp dùng để chơi cầu lông tại nhà hoặc sử dụng cho các trường học.', 'Lưới cầu lông Hải Yến được làm từ sợi tổng hợp, có mắt lưới đều, không bị xô và phù hợp dùng để chơi cầu lông tại nhà hoặc sử dụng cho các trường học.', 100000, 'tru-luoi-cau-long', 0, '{"Mã sản phẩm": "LCLHY", "Màu sắc": "Đỏ đô", "Kích thước lưới": "6 x 0.76m", "Ô lưới": "20mm"}'::jsonb, 'https://baoansport.vn/tru-luoi-cau-long/luoi-cau-long-hai-yen/'),
  ('luoi-cau-long-501506', 'BAS-424', '501506', 'Lưới cầu lông 501506', 'Lưới cầu lông 501506 chính hãng VifaSport được làm bắng sợi Nylon + PP 20mm, ô lưới đều và phù hợp dùng tập luyện cầu lông tại nhà hoặc trường học.', 'Lưới cầu lông 501506 chính hãng VifaSport được làm bắng sợi Nylon + PP 20mm, ô lưới đều và phù hợp dùng tập luyện cầu lông tại nhà hoặc trường học.', 275000, 'tru-luoi-cau-long', 0, '{"Mã sản phẩm": "501506", "Chất liệu": "Sợi tổng hợp", "Kích thước": "6.0 x 0.76m"}'::jsonb, 'https://baoansport.vn/tru-luoi-cau-long/luoi-cau-long-501506/'),
  ('luoi-cau-long-501809', 'BAS-425', '501809', 'Lưới cầu lông 501809', 'Lưới cầu lông 501809 chính hãng Vifasport được đan bằng tay từ sợi PA 0.9mm, đạt tiêu chuẩn BWF và phù hợp sử dụng cho các sân thi đấu môn cầu lông.', 'Lưới cầu lông 501809 chính hãng Vifasport được đan bằng tay từ sợi PA 0.9mm, đạt tiêu chuẩn BWF và phù hợp sử dụng cho các sân thi đấu môn cầu lông.', 340000, 'tru-luoi-cau-long', 0, '{"Mã sản phẩm": "501809", "Màu sắc": "Nâu", "Kích thước lưới": "6.0 x 0.76m", "Ô lưới": "20mm"}'::jsonb, 'https://baoansport.vn/tru-luoi-cau-long/luoi-cau-long-501809/'),
  ('tru-co-goc-san-bong-da-102867', 'BAS-426', '102867', 'Trụ cờ góc sân bóng đá 102867', 'Trụ cờ góc sân bóng đá 102867 chính hãng Vifa Sport được thiết kế theo tiêu chuẩn FIFA, gồm 4 trụ và phù hợp sử dụng cho sân thi đấu bóng đá 11 người.', 'Trụ cờ góc sân bóng đá 102867 chính hãng Vifa Sport được thiết kế theo tiêu chuẩn FIFA, gồm 4 trụ và phù hợp sử dụng cho sân thi đấu bóng đá 11 người.', 2600000, 'phu-kien-bong-da', 0, '{"Mã sản phẩm": "102867", "Chất liệu": "Nhựa", "Chiều cao": "1,5m"}'::jsonb, 'https://baoansport.vn/phu-kien-bong-da/tru-co-goc-san-bong-da-102867/'),
  ('bang-thay-nguoi-bong-da-sa-106', 'BAS-429', 'SA-106', 'Bảng thay người bóng đá SA-106', 'Bảng thay người bóng đá SA-106 được làm chắc chắn từ nhựa ABS, có 2 mặt (IN và OUT) + chữ số lật tay dễ dàng và đạt tiêu chuẩn thi đấu môn bóng đá.', 'Bảng thay người bóng đá SA-106 được làm chắc chắn từ nhựa ABS, có 2 mặt (IN và OUT) + chữ số lật tay dễ dàng và đạt tiêu chuẩn thi đấu môn bóng đá.', 850000, 'phu-kien-bong-da', 1000, '{"Mã sản phẩm": "SA-106", "Chất liệu": "Nhựa", "Kích thước": "440 x 390mm", "Trọng lượng": "1Kg"}'::jsonb, 'https://baoansport.vn/phu-kien-bong-da/bang-thay-nguoi-bong-da-sa-106/'),
  ('bang-thay-nguoi-bong-da-sa-107', 'BAS-430', 'SA-107', 'Bảng thay người bóng đá SA-107', 'Bảng thay người bóng đá SA-107 được làm chắc chắn từ nhựa, chữ số lật tay dễ dàng + hiển thị ở cả hai mặt và đạt tiêu chuẩn thi đấu quốc tế môn bóng đá.', 'Bảng thay người bóng đá SA-107 được làm chắc chắn từ nhựa, chữ số lật tay dễ dàng + hiển thị ở cả hai mặt và đạt tiêu chuẩn thi đấu quốc tế môn bóng đá.', 1400000, 'phu-kien-bong-da', 2000, '{"Mã sản phẩm": "SA-107", "Chất liệu": "Nhựa", "Kích thước": "840 x 390mm", "Trọng lượng": "2Kg"}'::jsonb, 'https://baoansport.vn/phu-kien-bong-da/bang-thay-nguoi-bong-da-sa-107/'),
  ('thang-day-tap-luyen-bong-da', 'BAS-437', 'TDTLBD', 'Thang dây tập luyện bóng đá', 'Thang dây tập luyện bóng đá được thiết kế với khung làm từ nhựa, dây bằng vải và phù hợp dùng cho cầu thủ tập luyện các động tác kỹ thuật môn bóng đá.', 'Thang dây tập luyện bóng đá được thiết kế với khung làm từ nhựa, dây bằng vải và phù hợp dùng cho cầu thủ tập luyện các động tác kỹ thuật môn bóng đá.', 500000, 'phu-kien-bong-da', 0, '{"Mã sản phẩm": "TDTLBD", "Màu sắc": "Xanh trắng", "Chiều dài": "4.5m"}'::jsonb, 'https://baoansport.vn/phu-kien-bong-da/thang-day-tap-luyen-bong-da/'),
  ('khung-tap-ky-thuat-bong-da', 'BAS-438', 'KTKTBD', 'Khung tập kỹ thuật bóng đá', 'Khung tập kỹ thuật bóng đá được làm bằng sắt, sơn tĩnh điện, có nhiều size và chuyên sử dụng để hỗ trợ tập kỹ thuật, tập nhanh nhẹn cho cầu thủ bóng đá.', 'Khung tập kỹ thuật bóng đá được làm bằng sắt, sơn tĩnh điện, có nhiều size và chuyên sử dụng để hỗ trợ tập kỹ thuật, tập nhanh nhẹn cho cầu thủ bóng đá.', 180000, 'phu-kien-bong-da', 0, '{"Mã sản phẩm": "KTKTBD", "Màu sắc": "Cam", "Chất liệu": "Sắt", "Chiều cao": "15, 23, 30cm"}'::jsonb, 'https://baoansport.vn/phu-kien-bong-da/khung-tap-ky-thuat-bong-da/'),
  ('bang-so-do-chien-thuat-bong-da-quan-da', 'BAS-442', 'SDQD', 'Bảng sơ đồ chiến thuật bóng đá quân da', 'Bảng sơ đồ chiến thuật bóng đá quân da được thiết kế nhỏ gọn, có quân bằng da và chuyên dùng cho HLV bóng đá để phân tích + bố trí chiến thuật thi đấu.', 'Bảng sơ đồ chiến thuật bóng đá quân da được thiết kế nhỏ gọn, có quân bằng da và chuyên dùng cho HLV bóng đá để phân tích + bố trí chiến thuật thi đấu.', 320000, 'phu-kien-bong-da', 0, '{"Mã sản phẩm": "SDQD", "Chất liệu": "Nhựa", "Kích thước bảng": "54 x 32cm", "Kích thước gập gọn": "25 x 32cm"}'::jsonb, 'https://baoansport.vn/phu-kien-bong-da/bang-so-do-chien-thuat-bong-da-quan-da/'),
  ('bang-so-do-chien-thuat-bong-da-quan-nhua', 'BAS-443', 'SDQN', 'Bảng sơ đồ chiến thuật bóng đá quân nhựa', 'Bảng sơ đồ chiến thuật bóng đá quân nhựa được làm từ nhựa, có bộ quân xịn đi kèm và chuyên dùng cho HLV để phân tích, bố trí đội hình thi đấu bóng đá.', 'Bảng sơ đồ chiến thuật bóng đá quân nhựa được làm từ nhựa, có bộ quân xịn đi kèm và chuyên dùng cho HLV để phân tích, bố trí đội hình thi đấu bóng đá.', 380000, 'phu-kien-bong-da', 0, '{"Mã sản phẩm": "SDQN", "Kích thước bảng": "540 x 320mm", "Kích thước gập gọn": "250 x 320mm"}'::jsonb, 'https://baoansport.vn/phu-kien-bong-da/bang-so-do-chien-thuat-bong-da-quan-nhua/'),
  ('bang-chien-thuat-bong-da-tu-dung', 'BAS-444', 'BCTBDTD', 'Bảng chiến thuật bóng đá tự đứng', 'Bảng chiến thuật bóng đá tự đứng được thiết kế có chân chắc chắn, bảng mô phỏng sân bóng lớn và phù hợp dùng để tập chiến thuật cho các HLV bóng đá.', 'Bảng chiến thuật bóng đá tự đứng được thiết kế có chân chắc chắn, bảng mô phỏng sân bóng lớn và phù hợp dùng để tập chiến thuật cho các HLV bóng đá.', 930000, 'phu-kien-bong-da', 0, '{"Mã sản phẩm": "BCTBDTD", "Kích thước bảng": "60 x 44 x 2cm", "Kích thước hộp": "70 x 52 x 9cm", "Bút đi kèm": "Có"}'::jsonb, 'https://baoansport.vn/phu-kien-bong-da/bang-chien-thuat-bong-da-tu-dung/'),
  ('nam-chien-thuat-bong-da-co-nho', 'BAS-445', 'NCTCN', 'Nấm chiến thuật bóng đá cỡ nhỏ', 'Nấm chiến thuật bóng đá cỡ nhỏ được làm từ chất liệu nhựa dẻo, có chiều cao 15cm và phù hợp sử dụng để tập kỹ thuật dẫn bóng cho các cầu thủ bóng đá.', 'Nấm chiến thuật bóng đá cỡ nhỏ được làm từ chất liệu nhựa dẻo, có chiều cao 15cm và phù hợp sử dụng để tập kỹ thuật dẫn bóng cho các cầu thủ bóng đá.', 30000, 'phu-kien-bong-da', 0, '{"Mã sản phẩm": "NCTCN", "Màu sắc": "Nhiều màu", "Chất liệu": "Nhựa", "Đường kính chân": "28cm", "Chiều cao nấm": "15cm"}'::jsonb, 'https://baoansport.vn/phu-kien-bong-da/nam-chien-thuat-bong-da-co-nho/'),
  ('nam-chien-thuat-bong-da-co-trung', 'BAS-446', 'NCTCTB', 'Nấm chiến thuật bóng đá cỡ trung', 'Nấm chiến thuật bóng đá cỡ trung được làm từ nhựa dẻo, có chiều cao 30.5cm và phù hợp sử dụng cho tập bóng đá ở các trung tâm đào tạo chuyên nghiệp..', 'Nấm chiến thuật bóng đá cỡ trung được làm từ nhựa dẻo, có chiều cao 30.5cm và phù hợp sử dụng cho tập bóng đá ở các trung tâm đào tạo chuyên nghiệp..', 90000, 'phu-kien-bong-da', 0, '{"Mã sản phẩm": "NCTCTB", "Màu sắc": "Nhiều màu", "Chất liệu": "Nhựa dẻo", "Đường kính đế": "35cm", "Chiều cao nấm": "30.5cm"}'::jsonb, 'https://baoansport.vn/phu-kien-bong-da/nam-chien-thuat-bong-da-co-trung/'),
  ('nam-chien-thuat-bong-da-co-to', 'BAS-447', 'NCTCT', 'Nấm chiến thuật bóng đá cỡ to', 'Nấm chiến thuật bóng đá cỡ to được làm từ nhựa PVC dẻo, chịu lực tốt, có chiều cao 50cm và phù hợp sử dụng để tập kỹ thuật cho cầu thủ chuyên nghiệp.', 'Nấm chiến thuật bóng đá cỡ to được làm từ nhựa PVC dẻo, chịu lực tốt, có chiều cao 50cm và phù hợp sử dụng để tập kỹ thuật cho cầu thủ chuyên nghiệp.', 130000, 'phu-kien-bong-da', 0, '{"Mã sản phẩm": "NCTCT", "Màu sắc": "Nhiều màu", "Chất liệu": "Nhựa", "Chiều cao": "50cm", "Đường kính chân": "40cm"}'::jsonb, 'https://baoansport.vn/phu-kien-bong-da/nam-chien-thuat-bong-da-co-to/'),
  ('tru-cau-long-tap-luyen-501520', 'BAS-417', '501520', 'Trụ cầu lông tập luyện 501520', 'Trụ cầu lông tập luyện 501520 chính hãng VifaSport được làm chắc chắn từ sắt dày, có bánh xe di chuyển dễ dàng và phù hợp sử dụng cho sân tập cầu lông.', 'Trụ cầu lông tập luyện 501520 chính hãng VifaSport được làm chắc chắn từ sắt dày, có bánh xe di chuyển dễ dàng và phù hợp sử dụng cho sân tập cầu lông.', 5750000, 'tru-luoi-cau-long', 0, '{"Mã sản phẩm": "501520", "Màu sắc": "Xanh", "Kích thước": "900 x 500 x 1542mm", "Đối trọng": "30Kg"}'::jsonb, 'https://baoansport.vn/tru-luoi-cau-long/tru-cau-long-tap-luyen-501520/'),
  ('tru-cau-long-thi-dau-502527', 'BAS-416', '502527', 'Trụ cầu lông thi đấu 502527', 'Trụ cầu lông thi đấu 502527 chính hãng Vifa Sport được làm chắc chắn từ thép hộp dày, có bánh xe di chuyển và phù hợp sử dụng cho sân thi đấu cầu lông.', 'Trụ cầu lông thi đấu 502527 chính hãng Vifa Sport được làm chắc chắn từ thép hộp dày, có bánh xe di chuyển và phù hợp sử dụng cho sân thi đấu cầu lông.', 9000000, 'tru-luoi-cau-long', 0, '{"Mã sản phẩm": "502527", "Màu sắc": "Xanh", "Chiều cao": "155cm", "Đối trọng": "50kg"}'::jsonb, 'https://baoansport.vn/tru-luoi-cau-long/tru-cau-long-thi-dau-502527/'),
  ('tru-cau-long-thi-dau-503528', 'BAS-415', '503528', 'Trụ cầu lông thi đấu 503528', 'Trụ cầu lông thi đấu 503528 chính hãng Vifa Sport được làm chắc chắn, có bánh xe di chuyển, đạt chuẩn châu Âu và phù hợp sử dụng cho sân đấu cầu lông.', 'Trụ cầu lông thi đấu 503528 chính hãng Vifa Sport được làm chắc chắn, có bánh xe di chuyển, đạt chuẩn châu Âu và phù hợp sử dụng cho sân đấu cầu lông.', 8150000, 'tru-luoi-cau-long', 0, '{"Mã sản phẩm": "503528", "Màu sắc": "Xanh", "Khung chính": "Ống 40 x 40mm", "Đối trọng": "60Kg"}'::jsonb, 'https://baoansport.vn/tru-luoi-cau-long/tru-cau-long-thi-dau-503528/'),
  ('tru-bong-chuyen-401441', 'BAS-346', '401441', 'Trụ bóng chuyền 401441', 'Trụ bóng chuyền 401441 (V4441) thiết kế theo tiêu chuẩn thi đấu từ ống kẽm D90, có tay quay căng lưới và phù hợp sử dụng cho trường học hoặc cơ quan.', 'Trụ bóng chuyền 401441 (V4441) thiết kế theo tiêu chuẩn thi đấu từ ống kẽm D90, có tay quay căng lưới và phù hợp sử dụng cho trường học hoặc cơ quan.', 4200000, 'tru-luoi-bong-chuyen', 0, '{"Mã sản phẩm": "401441", "Màu sắc": "Trắng", "Trụ chính": "D90", "Kích thước": "90 x 3000mm", "Nòng trụ đi kèm": "Không"}'::jsonb, 'https://baoansport.vn/tru-luoi-bong-chuyen/tru-bong-chuyen-401441/'),
  ('qua-bong-chuyen-bai-bien-dlb-230c', 'BAS-348', 'DLB-230C', 'Quả bóng chuyền bãi biển DLB 230C', 'Quả bóng chuyền bãi biển DLB 230C chính hãng Động Lực được may chắc chắn từ chất liệu da PU, cho độ nảy rất chuẩn và phù hợp sử dụng cho thi đấu.', 'Quả bóng chuyền bãi biển DLB 230C chính hãng Động Lực được may chắc chắn từ chất liệu da PU, cho độ nảy rất chuẩn và phù hợp sử dụng cho thi đấu.', 390000, 'qua-bong-chuyen', 0, '{"Mã sản phẩm": "DLB-230C", "Chất liệu": "Da PU", "Size bóng": "Số 5", "Bơm bóng": "Có"}'::jsonb, 'https://baoansport.vn/qua-bong-chuyen/qua-bong-chuyen-bai-bien-dlb-230c/'),
  ('qua-bong-chuyen-ebete-de-204m3', 'BAS-349', 'DE-204M3', 'Quả bóng chuyền Ebete DE 204M3', 'Quả bóng chuyền Ebete DE 204M3 chính hãng Động Lực được may bằng tay từ chất liệu da PU, giữ hơi tốt + độ nảy chuẩn và phù hợp dùng cho học sinh.', 'Quả bóng chuyền Ebete DE 204M3 chính hãng Động Lực được may bằng tay từ chất liệu da PU, giữ hơi tốt + độ nảy chuẩn và phù hợp dùng cho học sinh.', 310000, 'qua-bong-chuyen', 0, '{"Mã sản phẩm": "DE-204M3", "Size": "Số 5", "Chu vi bóng": "650-670mm", "Trọng lượng": "260-280 gram"}'::jsonb, 'https://baoansport.vn/qua-bong-chuyen/qua-bong-chuyen-ebete-de-204m3/'),
