  ('qua-bong-chuyen-dong-luc-dl-220c', 'BAS-351', 'DL-220C', 'Quả bóng chuyền Động Lực DL 220C', 'Quả bóng chuyền Động Lực DL 220C được may tròn đều từ chất liệu da PU, độ nảy chuẩn và phù hợp dùng cho tập luyện môn bóng chuyền tại trường học.', 'Quả bóng chuyền Động Lực DL 220C được may tròn đều từ chất liệu da PU, độ nảy chuẩn và phù hợp dùng cho tập luyện môn bóng chuyền tại trường học.', 380000, 'qua-bong-chuyen', 0, '{"Mã sản phẩm": "DL-220C", "Size": "Số 5", "Chu vi bóng": "650-670mm", "Trọng lượng": "260-280 gram"}'::jsonb, 'https://baoansport.vn/qua-bong-chuyen/qua-bong-chuyen-dong-luc-dl-220c/'),
  ('qua-bong-chuyen-dong-luc-power-dl-210m3', 'BAS-352', 'DL-210M3', 'Quả bóng chuyền Động Lực Power DL 210M3', 'Quả bóng chuyền Động Lực Power DL 210M3 được may tròn đều bằng tay từ da PU, độ nảy chuẩn và phù hợp dùng để tập luyện tại nhà hoặc trường học.', 'Quả bóng chuyền Động Lực Power DL 210M3 được may tròn đều bằng tay từ da PU, độ nảy chuẩn và phù hợp dùng để tập luyện tại nhà hoặc trường học.', 420000, 'qua-bong-chuyen', 0, '{"Mã sản phẩm": "DL-210M3", "Chất liệu": "Da PU", "Size bóng": "Số 5", "Kim bơm": "Có"}'::jsonb, 'https://baoansport.vn/qua-bong-chuyen/qua-bong-chuyen-dong-luc-power-dl-210m3/'),
  ('qua-bong-chuyen-galaxy-dg-250c', 'BAS-354', 'DG-250C', 'Quả bóng chuyền Galaxy DG 250C', 'Quả bóng chuyền Galaxy DG 250C chính hãng Động Lực được may từ da PU, độ nảy chuẩn và phù hợp cho tập luyện, thi đấu ở các giải đấu cấp quốc gia.', 'Quả bóng chuyền Galaxy DG 250C chính hãng Động Lực được may từ da PU, độ nảy chuẩn và phù hợp cho tập luyện, thi đấu ở các giải đấu cấp quốc gia.', 510000, 'qua-bong-chuyen', 0, '{"Mã sản phẩm": "DG-250C", "Chất liệu": "Da PU", "Size bóng": "Số 5"}'::jsonb, 'https://baoansport.vn/qua-bong-chuyen/qua-bong-chuyen-galaxy-dg-250c/'),
  ('qua-bong-chuyen-thang-long-vb6600', 'BAS-355', 'VB6600', 'Quả bóng chuyền Thăng Long VB6600', 'Quả bóng chuyền Thăng Long VB6600 chính hãng được may bằng tay từ chất liệu da PU, cho độ nảy chuẩn và phù hợp dùng để tập ở nhà hoặc trường học.', 'Quả bóng chuyền Thăng Long VB6600 chính hãng được may bằng tay từ chất liệu da PU, cho độ nảy chuẩn và phù hợp dùng để tập ở nhà hoặc trường học.', 350000, 'qua-bong-chuyen', 0, '{"Mã sản phẩm": "VB6600", "Chất liệu": "Da PU", "Size bóng": "Số 5"}'::jsonb, 'https://baoansport.vn/qua-bong-chuyen/qua-bong-chuyen-thang-long-vb6600/'),
  ('qua-bong-chuyen-thang-long-vb7400', 'BAS-356', 'VB7400', 'Quả bóng chuyền Thăng Long VB7400', 'Quả bóng chuyền Thăng Long VB7400 được may chắc chắn từ chất liệu da PU của Nhật, đạt tiêu chuẩn thi đấu và phù hợp dùng cho giải đấu cấp quốc gia.', 'Quả bóng chuyền Thăng Long VB7400 được may chắc chắn từ chất liệu da PU của Nhật, đạt tiêu chuẩn thi đấu và phù hợp dùng cho giải đấu cấp quốc gia.', 880000, 'qua-bong-chuyen', 0, '{"Mã sản phẩm": "VB7400", "Chất liệu": "Da PU", "Size bóng": "Số 5", "Kim bơm": "Có"}'::jsonb, 'https://baoansport.vn/qua-bong-chuyen/qua-bong-chuyen-thang-long-vb7400/'),
  ('qua-bong-chuyen-thang-long-vb7000', 'BAS-357', 'VB7000', 'Quả bóng chuyền Thăng Long VB7000', 'Quả bóng chuyền Thăng Long VB7000 được may tròn đều bằng tay từ chất liệu da PU, độ nảy chuẩn, giữ hơi tốt và phù hợp dùng cho giải đấu cấp quốc gia.', 'Quả bóng chuyền Thăng Long VB7000 được may tròn đều bằng tay từ chất liệu da PU, độ nảy chuẩn, giữ hơi tốt và phù hợp dùng cho giải đấu cấp quốc gia.', 660000, 'qua-bong-chuyen', 0, '{"Mã sản phẩm": "VB7000", "Chất liệu": "Da PU", "Size bóng": "Số 5"}'::jsonb, 'https://baoansport.vn/qua-bong-chuyen/qua-bong-chuyen-thang-long-vb7000/'),
  ('qua-bong-chuyen-thang-long-vb7700', 'BAS-358', 'VB7700', 'Quả bóng chuyền Thăng Long VB7700', 'Quả bóng chuyền Thăng Long VB7700 chính hãng được làm tròn đều từ chất liệu da PU cao cấp, cho đường bóng chuẩn khi chơi và đạt tiêu chuẩn thi đấu.', 'Quả bóng chuyền Thăng Long VB7700 chính hãng được làm tròn đều từ chất liệu da PU cao cấp, cho đường bóng chuẩn khi chơi và đạt tiêu chuẩn thi đấu.', 990000, 'qua-bong-chuyen', 0, '{"Mã sản phẩm": "VB7700", "Chất liệu": "Da PU", "Size bóng": "Số 5"}'::jsonb, 'https://baoansport.vn/qua-bong-chuyen/qua-bong-chuyen-thang-long-vb7700/'),
  ('ghe-trong-tai-cau-long-s27353', 'BAS-362', 'S27353', 'Ghế trọng tài cầu lông S27353', 'Ghế trọng tài cầu lông S27353 chính hãng Sodex được làm chắc chắn từ thép, đạt tiêu chuẩn và phù hợp dùng cho trọng tài điều khiển thi đấu môn cầu lông.', 'Ghế trọng tài cầu lông S27353 chính hãng Sodex được làm chắc chắn từ thép, đạt tiêu chuẩn và phù hợp dùng cho trọng tài điều khiển thi đấu môn cầu lông.', 4500000, 'phu-kien-cau-long', 0, '{"Mã sản phẩm": "S27353", "Màu sắc": "Trắng", "Chiều cao": "1.5m", "Trọng lượng ghế": "Đang cập nhật", "Tải trọng tối đa": "120kg", "Diện tích lắp đặt": "Đang cập nhật"}'::jsonb, 'https://baoansport.vn/phu-kien-cau-long/ghe-trong-tai-cau-long-s27353/'),
  ('ghe-trong-tai-cau-long-502353', 'BAS-363', '502353', 'Ghế trọng tài cầu lông 502353', 'Ghế trọng tài cầu lông 502353 chính hãng Vifa Sport có khung làm từ ống sắt dày, đạt tiêu chuẩn, phù hợp dùng cho trọng tài điều khiển thi đấu môn cầu lông.', 'Ghế trọng tài cầu lông 502353 chính hãng Vifa Sport có khung làm từ ống sắt dày, đạt tiêu chuẩn, phù hợp dùng cho trọng tài điều khiển thi đấu môn cầu lông.', 3700000, 'phu-kien-cau-long', 0, '{"Mã sản phẩm": "502353", "Màu sắc": "Xanh", "Chiều cao": "1.5m", "Trọng lượng ghế": "Đang cập nhật", "Tải trọng tối đa": "120kg", "Diện tích lắp đặt": "800 x 800 x 1500mm"}'::jsonb, 'https://baoansport.vn/phu-kien-cau-long/ghe-trong-tai-cau-long-502353/'),
  ('qua-cau-long-thanh-cong-do', 'BAS-399', 'TCD', 'Quả cầu lông Thành Công đỏ', 'Quả cầu lông Thành Công đỏ chính hãng có độ nảy tốt khi chơi, đường cầu đi nhanh, chính xác và phù hợp sử dụng cho tập luyện lẫn thi đấu bộ môn cầu lông.', 'Quả cầu lông Thành Công đỏ chính hãng có độ nảy tốt khi chơi, đường cầu đi nhanh, chính xác và phù hợp sử dụng cho tập luyện lẫn thi đấu bộ môn cầu lông.', 210000, 'qua-cau-long', 0, '{"Mã sản phẩm": "TCD", "Màu sắc": "Trắng sứ", "Chất liệu": "Xốp, lông vũ", "Quy cách đóng hộp": "10 quả"}'::jsonb, 'https://baoansport.vn/qua-cau-long/qua-cau-long-thanh-cong-do/'),
  ('qua-cau-long-ba-sao', 'BAS-400', 'Ba-Sao', 'Quả cầu lông Ba Sao', 'Quả cầu lông Ba Sao chính hãng được sản xuất đạt tiêu chuẩn thi đấu, có tốc độ bay nhanh, tiếng nổ to khi đập cầu và phù hợp chơi trong nhà lẫn ngoài trời.', 'Quả cầu lông Ba Sao chính hãng được sản xuất đạt tiêu chuẩn thi đấu, có tốc độ bay nhanh, tiếng nổ to khi đập cầu và phù hợp chơi trong nhà lẫn ngoài trời.', 250000, 'qua-cau-long', 0, '{"Mã sản phẩm": "Ba-Sao", "Màu sắc": "Trắng sứ", "Chất liệu": "Xốp, lông vũ", "Quy cách đóng hộp": "10 quả"}'::jsonb, 'https://baoansport.vn/qua-cau-long/qua-cau-long-ba-sao/'),
  ('qua-cau-long-thanh-cong-xanh', 'BAS-401', 'TCX', 'Quả cầu lông Thành Công xanh', 'Quả cầu lông Thành Công xanh chính hãng có tốc độ bay ổn định, phù hợp cho chơi trong nhà lẫn ngoài trời và chuyên dùng tập luyện, thi đấu môn cầu lông.', 'Quả cầu lông Thành Công xanh chính hãng có tốc độ bay ổn định, phù hợp cho chơi trong nhà lẫn ngoài trời và chuyên dùng tập luyện, thi đấu môn cầu lông.', 350000, 'qua-cau-long', 0, '{"Mã sản phẩm": "TCX", "Màu sắc": "Trắng sứ", "Chất liệu": "Xốp, lông vũ", "Quy cách đóng hộp": "12 quả"}'::jsonb, 'https://baoansport.vn/qua-cau-long/qua-cau-long-thanh-cong-xanh/'),
  ('coi-dong', 'BAS-448', 'CDCA', 'Còi đồng', 'Còi đồng công an hay còi đồng cảnh sát giao thông CSGT được làm từ đồng thau nguyên chất, tiếng kêu to và vang xa. Mua còi đồng giá tốt ở Bảo An Sport.', 'Còi đồng công an hay còi đồng cảnh sát giao thông CSGT được làm từ đồng thau nguyên chất, tiếng kêu to và vang xa. Mua còi đồng giá tốt ở Bảo An Sport.', 120000, 'phu-kien-bong-da', 0, '{"Mã sản phẩm": "CDCA", "Màu sắc": "Vàng đồng", "Chất liệu": "Đồng", "Dây đeo": "Có"}'::jsonb, 'https://baoansport.vn/phu-kien-bong-da/coi-dong/'),
  ('khung-thanh-bong-da-11-nguoi-103667', 'BAS-451', '103667', 'Khung thành bóng đá 11 người 103667', 'Khung thành bóng đá 11 người 103667 được làm từ ống tráng kẽm + sơn tĩnh điện chống rỉ, đạt chuẩn thi đấu FIFA và phù hợp dùng cho sân bóng 11 người.', 'Khung thành bóng đá 11 người 103667 được làm từ ống tráng kẽm + sơn tĩnh điện chống rỉ, đạt chuẩn thi đấu FIFA và phù hợp dùng cho sân bóng 11 người.', 37500000, 'luoi-khung-thanh-bong-da', 320000, '{"Mã sản phẩm": "103667", "Màu sắc": "Trắng", "Thép ống": "Φ114, Φ60, Φ42", "Trọng lượng": "320 Kg/bộ", "Kích thước lắp": "7550 x 2550 x 2160mm"}'::jsonb, 'https://baoansport.vn/luoi-khung-thanh-bong-da/khung-thanh-bong-da-11-nguoi-103667/'),
  ('con-lan-massage-tap-yoga-foam-roller', 'BAS-498', 'Foam-Roller', 'Con lăn massage tập Yoga Foam Roller', 'Con lăn massage tập Yoga Foam Roller thiết kế dạng ống, được làm từ chất liệu EVA và phù hợp sử dụng massage, tập giãn cơ vào cuối buổi tập Yoga, Gym.', 'Con lăn massage tập Yoga Foam Roller thiết kế dạng ống, được làm từ chất liệu EVA và phù hợp sử dụng massage, tập giãn cơ vào cuối buổi tập Yoga, Gym.', 250000, 'phu-kien-yoga', 0, '{"Mã sản phẩm": "Foam-Roller", "Màu sắc": "Xanh", "Chất liệu": "EVA", "Trọng lượng": "950 gram", "Kích thước": "330 x 140 mm"}'::jsonb, 'https://baoansport.vn/phu-kien-yoga/con-lan-massage-tap-yoga-foam-roller/'),
  ('khan-trai-tham-yoga', 'BAS-499', 'KTTY', 'Khăn trải thảm Yoga', 'Khăn trải thảm tập Yoga được làm từ chất liệu sợi cao cấp, có chức năng thấm hút mồ hôi và ở bề mặt phủ hạt cao su giúp tăng độ êm, độ bám khi tập Yoga.', 'Khăn trải thảm tập Yoga được làm từ chất liệu sợi cao cấp, có chức năng thấm hút mồ hôi và ở bề mặt phủ hạt cao su giúp tăng độ êm, độ bám khi tập Yoga.', 200000, 'phu-kien-yoga', 0, '{"Mã sản phẩm": "KTTY", "Màu sắc": "Xanh, tím, hồng, cam", "Chất liệu": "Sợi dệt", "Trọng lượng": "Đang cập nhật", "Kích thước": "1830 x 630 mm"}'::jsonb, 'https://baoansport.vn/phu-kien-yoga/khan-trai-tham-yoga/'),
  ('bong-tap-yoga-adidas-adbl-12247', 'BAS-507', 'ADBL-12247', 'Bóng tập Yoga Adidas ADBL 12247', 'Bóng tập Yoga Adidas ADBL 12247 75cm chính hãng được làm từ cao su có độ đàn hồi tốt, khả năng chống nổ cao và hỗ trợ tập Yoga, tập thể dục hiệu quả.', 'Bóng tập Yoga Adidas ADBL 12247 75cm chính hãng được làm từ cao su có độ đàn hồi tốt, khả năng chống nổ cao và hỗ trợ tập Yoga, tập thể dục hiệu quả.', 790000, 'bong-tap-yoga', 1200, '{"Mã sản phẩm": "ADBL-12247", "Màu sắc": "Đen", "Chất liệu": "Cao su", "Đường kính": "75cm", "Trọng lượng": "1.2kg", "Tải trọng tối đa": "110kg"}'::jsonb, 'https://baoansport.vn/bong-tap-yoga/bong-tap-yoga-adidas-adbl-12247/'),
  ('bong-the-duc-adidas-adbl-14246gr', 'BAS-509', 'ADBL-14246GR', 'Bóng thể dục Adidas ADBL-14246GR', 'Bóng thể dục Adidas ADBL-14246GR 65cm được làm từ chất liệu Polymer có độ đàn hồi cao, chống nổ tốt và hỗ trợ tập Yoga, Gym & tập thể dục hiệu quả.', 'Bóng thể dục Adidas ADBL-14246GR 65cm được làm từ chất liệu Polymer có độ đàn hồi cao, chống nổ tốt và hỗ trợ tập Yoga, Gym & tập thể dục hiệu quả.', 1100000, 'bong-tap-yoga', 1200, '{"Mã sản phẩm": "ADBL-14246GR", "Màu sắc": "Đen - xám", "Chất liệu": "Polymer", "Đường kính": "65cm", "Trọng lượng": "1.2kg", "Tải trọng tối đa": "110kg"}'::jsonb, 'https://baoansport.vn/bong-tap-yoga/bong-the-duc-adidas-adbl-14246gr/'),
  ('bong-the-duc-adidas-adbl-11246gr', 'BAS-511', 'ADBL-11246GR', 'Bóng thể dục Adidas ADBL-11246GR', 'Bóng thể dục Adidas ADBL-11246GR được làm từ chất liệu cao su non, độ đàn hồi cao, khả năng chống nổ tốt và phù hợp dùng để tập Yoga hoặc tập Gym.', 'Bóng thể dục Adidas ADBL-11246GR được làm từ chất liệu cao su non, độ đàn hồi cao, khả năng chống nổ tốt và phù hợp dùng để tập Yoga hoặc tập Gym.', 750000, 'bong-tap-yoga', 1200, '{"Mã sản phẩm": "ADBL-11246GR", "Màu sắc": "Xám", "Chất liệu": "Cao su", "Đường kính": "65cm", "Trọng lượng": "1.2kg", "Tải trọng tối đa": "100kg"}'::jsonb, 'https://baoansport.vn/bong-tap-yoga/bong-the-duc-adidas-adbl-11246gr/'),
  ('bong-tap-thang-bang-bosu', 'BAS-512', 'Bosu', 'Bóng tập thăng bằng Bosu', 'Bóng tập thăng bằng Bosu chính hãng tại Bảo An Sport, giúp rèn luyện sức mạnh, tập thăng bằng, giảm chấn thương và phù hợp cho mọi đối tượng tập luyện.', 'Bóng tập thăng bằng Bosu chính hãng tại Bảo An Sport, giúp rèn luyện sức mạnh, tập thăng bằng, giảm chấn thương và phù hợp cho mọi đối tượng tập luyện.', 1500000, 'bong-tap-yoga', 1500, '{"Mã sản phẩm": "Bosu", "Màu sắc": "Xanh - đen", "Chất liệu": "PVC, nhựa ABS", "Kích thước": "58 x 25 cm", "Trọng lượng": "1.5 kg", "Tải trọng tối đa": "130 kg"}'::jsonb, 'https://baoansport.vn/bong-tap-yoga/bong-tap-thang-bang-bosu/'),
  ('bong-tap-yoga-brosman', 'BAS-513', 'Brosman', 'Bóng tập Yoga Brosman', 'Bóng tập Yoga Brosman được làm từ cao su có độ đàn hồi cao, khả năng chống nổ tốt và phù hợp dùng tập Yoga, Gym hoặc tập thể dục vật lý trị liệu tại nhà.', 'Bóng tập Yoga Brosman được làm từ cao su có độ đàn hồi cao, khả năng chống nổ tốt và phù hợp dùng tập Yoga, Gym hoặc tập thể dục vật lý trị liệu tại nhà.', 350000, 'bong-tap-yoga', 1000, '{"Mã sản phẩm": "Brosman", "Màu sắc": "Xanh, đen, hồng, tím", "Chất liệu": "Cao su tổng hợp", "Đường kính": "65cm và 75cm", "Trọng lượng": "1.0 kg", "Tải trọng tối đa": "100 kg"}'::jsonb, 'https://baoansport.vn/bong-tap-yoga/bong-tap-yoga-brosman/'),
  ('tham-tap-yoga-pido-dinh-tuyen', 'BAS-549', 'PDT', 'Thảm tập Yoga Pido định tuyến', 'Thảm tập Yoga Pido định tuyến cao cấp có mẫu mã đẹp, làm từ cao su tự nhiên kết hợp PU và phù hợp dùng tập Yoga tại nhà hoặc sử dụng cho CLB Yoga.', 'Thảm tập Yoga Pido định tuyến cao cấp có mẫu mã đẹp, làm từ cao su tự nhiên kết hợp PU và phù hợp dùng tập Yoga tại nhà hoặc sử dụng cho CLB Yoga.', 900000, 'tham-tap-yoga', 2700, '{"Mã sản phẩm": "PDT", "Màu sắc": "Đỏ, xanh, hồng, tím", "Chất liệu": "Cao su kết hợp PU", "Độ dày": "5mm", "Kích thước": "185 x 68 cm", "Trọng lượng": "2.7 kg", "Phụ kiện đi kèm": "Túi đựng"}'::jsonb, 'https://baoansport.vn/tham-tap-yoga/tham-tap-yoga-pido-dinh-tuyen/'),
  ('tham-tap-yoga-pido-5d-hoa', 'BAS-550', 'P5H', 'Thảm tập Yoga Pido 5D Hoa', 'Thảm tập Yoga Pido 5D hoa cao cấp được thiết kế đẹp mắt, làm từ chất liệu cao su thiên nhiên kết hợp PU sinh thái và phù hợp sử dụng để tập Yoga tại nhà.', 'Thảm tập Yoga Pido 5D hoa cao cấp được thiết kế đẹp mắt, làm từ chất liệu cao su thiên nhiên kết hợp PU sinh thái và phù hợp sử dụng để tập Yoga tại nhà.', 1350000, 'tham-tap-yoga', 2500, '{"Mã sản phẩm": "P5H", "Màu sắc": "Nhiều màu", "Chất liệu": "Cao su kết hợp PU", "Độ dày": "5mm", "Kích thước": "180 x 64 cm", "Trọng lượng": "2.5 kg", "Phụ kiện đi kèm": "Túi đựng"}'::jsonb, 'https://baoansport.vn/tham-tap-yoga/tham-tap-yoga-pido-5d-hoa/'),
  ('tham-tap-yoga-pido', 'BAS-551', 'Pido', 'Thảm tập Yoga Pido', 'Thảm tập Yoga Pido cao cấp được làm từ cao su thiên nhiên kết hợp PU sinh thái, có độ dày 5mm, chống trơn trượt tốt và phù hợp dùng để tập Yoga tại nhà.', 'Thảm tập Yoga Pido cao cấp được làm từ cao su thiên nhiên kết hợp PU sinh thái, có độ dày 5mm, chống trơn trượt tốt và phù hợp dùng để tập Yoga tại nhà.', 790000, 'tham-tap-yoga', 2700, '{"Mã sản phẩm": "Pido", "Màu sắc": "Nhiều màu", "Chất liệu": "Cao su kết hợp PU", "Độ dày": "5mm", "Kích thước": "183 x 63 cm", "Trọng lượng": "2.7 kg", "Phụ kiện đi kèm": "Túi đựng"}'::jsonb, 'https://baoansport.vn/tham-tap-yoga/tham-tap-yoga-pido/'),
  ('tham-tap-yoga-pido-pvc', 'BAS-552', 'Pido-PVC', 'Thảm tập Yoga Pido PVC', 'Thảm tập Yoga Pido PVC chính hãng được làm từ chất liệu PVC cực êm, bề mặt thảm thiết kế có hoa văn đẹp mắt và phù hợp sử dụng để tập Yoga tại nhà.', 'Thảm tập Yoga Pido PVC chính hãng được làm từ chất liệu PVC cực êm, bề mặt thảm thiết kế có hoa văn đẹp mắt và phù hợp sử dụng để tập Yoga tại nhà.', 480000, 'tham-tap-yoga', 1200, '{"Mã sản phẩm": "Pido-PVC", "Màu sắc": "Hoa văn", "Chất liệu": "PVC", "Độ dày": "5mm", "Kích thước": "183 x 61 cm", "Kích thước hộp": "12 x 12 x 62 cm", "Trọng lượng": "1.2 kg"}'::jsonb, 'https://baoansport.vn/tham-tap-yoga/tham-tap-yoga-pido-pvc/'),
  ('tham-tap-yoga-1009', 'BAS-555', '1009', 'Thảm tập Yoga 1009', 'Thảm tập Yoga 1009 được làm từ chất liệu nhựa PVC cực êm, có khả năng chống trơn trượt tốt và phù hợp dùng để tập ở nhà hoặc sử dụng cho CLB Yoga.', 'Thảm tập Yoga 1009 được làm từ chất liệu nhựa PVC cực êm, có khả năng chống trơn trượt tốt và phù hợp dùng để tập ở nhà hoặc sử dụng cho CLB Yoga.', 150000, 'tham-tap-yoga', 1200, '{"Mã sản phẩm": "1009", "Màu sắc": "Cam, xanh, hồng", "Chất liệu": "PVC", "Độ dày": "6mm", "Kích thước": "173 x 61 cm", "Trọng lượng": "1.2 kg", "Phụ kiện đi kèm": "Túi đựng"}'::jsonb, 'https://baoansport.vn/tham-tap-yoga/tham-tap-yoga-1009/'),
  ('tham-tap-yoga-cao-cap-tpe', 'BAS-556', 'TTYCC', 'Thảm tập Yoga cao cấp TPE', 'Thảm tập Yoga cao cấp TPE được làm từ chất liệu cao su TPE, bề mặt chống trơn trượt và phù hợp dùng để tập Yoga tại nhà hoặc sử dụng cho CLB Yoga.', 'Thảm tập Yoga cao cấp TPE được làm từ chất liệu cao su TPE, bề mặt chống trơn trượt và phù hợp dùng để tập Yoga tại nhà hoặc sử dụng cho CLB Yoga.', 200000, 'tham-tap-yoga', 1000, '{"Mã sản phẩm": "TTYCC", "Màu sắc": "Cam, xanh, hồng, tím", "Chất liệu": "TPE", "Độ dày": "5mm, 6mm và 8mm", "Kích thước": "173 x 61 cm", "Trọng lượng": "1.0 kg", "Phụ kiện đi kèm": "Túi đựng"}'::jsonb, 'https://baoansport.vn/tham-tap-yoga/tham-tap-yoga-cao-cap-tpe/'),
  ('qua-cau-may-thai-lan', 'BAS-570', 'QCMTL', 'Quả cầu mây Thái Lan', 'Quả cầu mây Thái Lan được làm tròn đều từ nhựa cao cấp, có độ nảy chính xác và đạt tiêu chuẩn thi đấu. Đặt mua quả cầu mây giá rẻ nhất gọi 0939 987 456.', 'Quả cầu mây Thái Lan được làm tròn đều từ nhựa cao cấp, có độ nảy chính xác và đạt tiêu chuẩn thi đấu. Đặt mua quả cầu mây giá rẻ nhất gọi 0939 987 456.', 415000, 'thiet-bi-day-hoc-the-duc', 0, '{"Mã sản phẩm": "QCMTL", "Màu sắc": "Nâu", "Chất liệu": "Nhựa", "Chu vi": "16 cm", "Trọng lượng": "170-180 gram"}'::jsonb, 'https://baoansport.vn/thiet-bi-day-hoc-the-duc/qua-cau-may-thai-lan/'),
  ('qua-cau-may-marathon-mt908', 'BAS-572', 'MT908', 'Quả cầu mây Marathon MT908', 'Quả cầu mây Marathon MT908 được làm tròn đều, độ nảy chuẩn, đạt tiêu chuẩn thi đấu cho VĐV nam. Mua cầu mây Marathon giá rẻ ở Bảo An Sport.', 'Quả cầu mây Marathon MT908 được làm tròn đều, độ nảy chuẩn, đạt tiêu chuẩn thi đấu cho VĐV nam. Mua cầu mây Marathon giá rẻ ở Bảo An Sport.', 480000, 'thiet-bi-day-hoc-the-duc', 0, '{"Mã sản phẩm": "MT908", "Màu sắc": "Vàng - nâu", "Chất liệu": "Nhựa", "Đường kính": "13.5 cm", "Trọng lượng": "180 gram"}'::jsonb, 'https://baoansport.vn/thiet-bi-day-hoc-the-duc/qua-cau-may-marathon-mt908/'),
  ('qua-cau-da-thi-dau-tls', 'BAS-583', 'CDTLS', 'Quả cầu đá thi đấu TLS', 'Quả cầu đá thi đấu TLS sản xuất đạt tiêu chuẩn và phù hợp dùng để giảng dạy tại các trường học ở Việt Nam. Đặt mua cầu đá TLS giá rẻ ☎ 0939987456.', 'Quả cầu đá thi đấu TLS sản xuất đạt tiêu chuẩn và phù hợp dùng để giảng dạy tại các trường học ở Việt Nam. Đặt mua cầu đá TLS giá rẻ ☎ 0939987456.', 20000, 'thiet-bi-day-hoc-the-duc', 0, '{"Mã sản phẩm": "CDTLS", "Màu sắc": "Đỏ hồng", "Chất liệu": "Xốp, cao su", "Chiều cao": "13-15cm", "Trọng lượng": "13 gram"}'::jsonb, 'https://baoansport.vn/thiet-bi-day-hoc-the-duc/qua-cau-da-thi-dau-tls/'),
  ('goi-tap-yoga', 'BAS-497', 'Yoga-Block', 'Gối tập Yoga', 'Gối tập Yoga (gạch tập Yoga) được làm từ chất liệu EVA cực êm, có kích thước 23 x 15cm và có chức năng hỗ trợ người sử dụng thực hiện các bài tập Yoga.', 'Gối tập Yoga (gạch tập Yoga) được làm từ chất liệu EVA cực êm, có kích thước 23 x 15cm và có chức năng hỗ trợ người sử dụng thực hiện các bài tập Yoga.', 130000, 'phu-kien-yoga', 0, '{"Mã sản phẩm": "Yoga-Block", "Chất liệu": "EVA", "Màu sắc": "Xanh, tím, đen", "Kích thước": "23 x 15 x 7.6 cm"}'::jsonb, 'https://baoansport.vn/phu-kien-yoga/goi-tap-yoga/'),
  ('bong-da-fifa-quality-uhv-205-galaxy', 'BAS-496', 'UHV-2.05-Galaxy', 'Bóng đá FIFA Quality UHV 2.05 Galaxy', 'Bóng đá FIFA Quality UHV 2.05 Galaxy của Động Lực được may chắc chắn + vỏ ngoài làm từ da PU, đạt tiêu chuẩn và chuyên dùng cho thi đấu bóng đá.', 'Bóng đá FIFA Quality UHV 2.05 Galaxy của Động Lực được may chắc chắn + vỏ ngoài làm từ da PU, đạt tiêu chuẩn và chuyên dùng cho thi đấu bóng đá.', 1250000, 'qua-bong-da', 0, '{"Mã sản phẩm": "UHV-2.05-Galaxy", "Chất liệu": "Da PU", "Size bóng": "Số 5", "Kim bơm": "Có"}'::jsonb, 'https://baoansport.vn/qua-bong-da/bong-da-fifa-quality-uhv-205-galaxy/'),
  ('bong-da-fifa-quality-pro-uhv-207-galaxy', 'BAS-495', 'UHV-2.07-Galaxy', 'Bóng đá FIFA Quality Pro UHV 2.07 Galaxy', 'Bóng đá FIFA Quality Pro UHV 2.07 Galaxy chính hãng Động Lực được may chắc chắn từ da latex, độ nảy chuẩn, chuyên dùng thi đấu cho giải V-League.', 'Bóng đá FIFA Quality Pro UHV 2.07 Galaxy chính hãng Động Lực được may chắc chắn từ da latex, độ nảy chuẩn, chuyên dùng thi đấu cho giải V-League.', 2500000, 'qua-bong-da', 0, '{"Mã sản phẩm": "UHV-2.07-Galaxy", "Chất liệu": "Da Latex", "Size bóng": "Số 5", "Kim bơm": "Có"}'::jsonb, 'https://baoansport.vn/qua-bong-da/bong-da-fifa-quality-pro-uhv-207-galaxy/'),
  ('khung-thanh-bong-da-11-nguoi-103668', 'BAS-452', '103668', 'Khung thành bóng đá 11 người 103668', 'Khung thành bóng đá 11 người 103668 chính hãng Vifa Sport được thiết kế treo lưới hình thang, đạt chuẩn thi đấu và chuyên sử dụng cho sân bóng 11 người.', 'Khung thành bóng đá 11 người 103668 chính hãng Vifa Sport được thiết kế treo lưới hình thang, đạt chuẩn thi đấu và chuyên sử dụng cho sân bóng 11 người.', 33500000, 'luoi-khung-thanh-bong-da', 0, '{"Mã sản phẩm": "103668", "Màu sắc": "Trắng", "Khung chính": "D114", "Kích thước": "7550 x 2550 x 2180mm"}'::jsonb, 'https://baoansport.vn/luoi-khung-thanh-bong-da/khung-thanh-bong-da-11-nguoi-103668/'),
  ('khung-thanh-bong-da-7-nguoi-103630', 'BAS-453', '103630', 'Khung thành bóng đá 7 người 103630', 'Khung thành bóng đá 7 người 103630 được làm chắc chắn bằng ống kẽm sơn tĩnh điện, đạt tiêu chuẩn FIFA và phù hợp dùng cho sân đấu bóng đá 7 người.', 'Khung thành bóng đá 7 người 103630 được làm chắc chắn bằng ống kẽm sơn tĩnh điện, đạt tiêu chuẩn FIFA và phù hợp dùng cho sân đấu bóng đá 7 người.', 20800000, 'luoi-khung-thanh-bong-da', 0, '{"Mã sản phẩm": "103630", "Màu sắc": "Xanh", "Khung chính": "D90", "Kích thước": "6.0 x 2.1 x 1.2m"}'::jsonb, 'https://baoansport.vn/luoi-khung-thanh-bong-da/khung-thanh-bong-da-7-nguoi-103630/'),
  ('khung-thanh-bong-da-futsal-103622', 'BAS-454', '103622', 'Khung thành bóng đá Futsal 103622', 'Khung thành bóng đá Futsal 103622 được làm từ thép hộp vuông 80, thép ống tròn D34, sơn tĩnh điện chống rỉ và đạt tiêu chuẩn thi đấu môn bóng đá Futsal.', 'Khung thành bóng đá Futsal 103622 được làm từ thép hộp vuông 80, thép ống tròn D34, sơn tĩnh điện chống rỉ và đạt tiêu chuẩn thi đấu môn bóng đá Futsal.', 38000000, 'luoi-khung-thanh-bong-da', 0, '{"Mã sản phẩm": "103622", "Màu sắc": "Trắng đỏ", "Khung chính": "Thép hộp 80 x 80mm", "Kích thước": "3 x 2 x 1m"}'::jsonb, 'https://baoansport.vn/luoi-khung-thanh-bong-da/khung-thanh-bong-da-futsal-103622/'),
  ('luoi-bong-da-7-nguoi', 'BAS-460', '162045', 'Lưới bóng đá 7 người', 'Lưới bóng đá 7 người (162045, 163045, 164145, 162245) được may bằng tay, có kích thước 6.1 x 2.1 x 0.5 x 1.5m và phù hợp cho tập luyện, thi đấu bóng đá.', 'Lưới bóng đá 7 người (162045, 163045, 164145, 162245) được may bằng tay, có kích thước 6.1 x 2.1 x 0.5 x 1.5m và phù hợp cho tập luyện, thi đấu bóng đá.', 590000, 'luoi-khung-thanh-bong-da', 0, '{"Mã sản phẩm": "162045", "Màu sắc": "Trắng", "Kích thước lưới": "6.1 x 2.1 x 0.5 x 1.5m", "Ô lưới": "145mm"}'::jsonb, 'https://baoansport.vn/luoi-khung-thanh-bong-da/luoi-bong-da-7-nguoi/'),
  ('may-keo-xo-da-nang-hg-5000c', 'BAS-1560', 'HG-5000C', 'Máy kéo xô đa năng HG-5000C', 'Máy kéo xô đa năng HG-5000C được thiết kế nhỏ gọn, hỗ trợ nhiều bài tập hiệu quả cho nhóm cơ xô và phù hợp sử dụng để lắp đặt cho phòng Gym gia đình.', 'Máy kéo xô đa năng HG-5000C được thiết kế nhỏ gọn, hỗ trợ nhiều bài tập hiệu quả cho nhóm cơ xô và phù hợp sử dụng để lắp đặt cho phòng Gym gia đình.', 3600000, 'gian-ta-da-nang', 30000, '{"Mã sản phẩm": "HG-5000C", "Màu sắc": "Đen", "Chất liệu": "Thép, mút, nhựa", "Trọng lượng máy": "30kg", "Trọng lượng hộp": "32kg", "Tải trọng tập tối đa": "200kg", "Kích thước lắp đặt": "145 x 60 x 186cm", "Kích thước hộp": "190 x 40 x 20cm"}'::jsonb, 'https://baoansport.vn/gian-ta-da-nang/may-keo-xo-da-nang-hg-5000c/'),
  ('khung-thanh-bong-da-5-nguoi', 'BAS-463', 'KTBD5', 'Khung thành bóng đá 5 người', 'Khung thành bóng đá 5 người được thiết kế theo tiêu chuẩn từ thép ống Φ76, sơn tĩnh điện chống rỉ và phù hợp sử dụng làm khung gôn cho sân bóng 5 người.', 'Khung thành bóng đá 5 người được thiết kế theo tiêu chuẩn từ thép ống Φ76, sơn tĩnh điện chống rỉ và phù hợp sử dụng làm khung gôn cho sân bóng 5 người.', 2950000, 'luoi-khung-thanh-bong-da', 0, '{"Mã sản phẩm": "KTBD5", "Màu sắc": "Trắng", "Kích thước": "3 x 2m", "Lưới đi kèm": "Có"}'::jsonb, 'https://baoansport.vn/luoi-khung-thanh-bong-da/khung-thanh-bong-da-5-nguoi/'),
  ('khung-thanh-bong-da-7-nguoi', 'BAS-464', 'KTBD7', 'Khung thành bóng đá 7 người', 'Khung thành bóng đá 7 người được thiết kế chắc chắn từ thép ống Φ90, đã bao gồm lưới đi kèm và đạt tiêu chuẩn thi đấu bóng đá 7 người quốc tế của FIFA', 'Khung thành bóng đá 7 người được thiết kế chắc chắn từ thép ống Φ90, đã bao gồm lưới đi kèm và đạt tiêu chuẩn thi đấu bóng đá 7 người quốc tế của FIFA', 4150000, 'luoi-khung-thanh-bong-da', 0, '{"Mã sản phẩm": "KTBD7", "Màu sắc": "Trắng", "Kích thước": "6 x 2.1m", "Lưới đi kèm": "Có"}'::jsonb, 'https://baoansport.vn/luoi-khung-thanh-bong-da/khung-thanh-bong-da-7-nguoi/'),
  ('khung-thanh-bong-da-11-nguoi', 'BAS-465', 'KTBD11', 'Khung thành bóng đá 11 người', 'Khung thành bóng đá 11 người được thiết kế chắc chắn từ thép ống Φ114 + Φ60, đã bao gồm lưới đi kèm và phù hợp làm khung gôn cho sân bóng 11 người.', 'Khung thành bóng đá 11 người được thiết kế chắc chắn từ thép ống Φ114 + Φ60, đã bao gồm lưới đi kèm và phù hợp làm khung gôn cho sân bóng 11 người.', 7150000, 'luoi-khung-thanh-bong-da', 0, '{"Mã sản phẩm": "KTBD11", "Màu sắc": "Trắng", "Kích thước": "7.32 x 2.44m", "Lưới đi kèm": "Có"}'::jsonb, 'https://baoansport.vn/luoi-khung-thanh-bong-da/khung-thanh-bong-da-11-nguoi/'),
  ('bong-da-co-bap-ucv-305-so-4', 'BAS-484', 'UCV-3.05-size-4', 'Bóng đá cơ bắp UCV 3.05 số 4', 'Bóng đá cơ bắp UCV 3.05 số 4 chính hãng Động Lực được may bằng tay tròn đều từ da PU, độ nảy chuẩn và phù hợp dùng tập đá bóng tại nhà cho trẻ em.', 'Bóng đá cơ bắp UCV 3.05 số 4 chính hãng Động Lực được may bằng tay tròn đều từ da PU, độ nảy chuẩn và phù hợp dùng tập đá bóng tại nhà cho trẻ em.', 335000, 'qua-bong-da', 0, '{"Mã sản phẩm": "UCV-3.05-size-4", "Chất liệu": "Da PU", "Size bóng": "Số 4", "Kim bơm": "Có"}'::jsonb, 'https://baoansport.vn/qua-bong-da/bong-da-co-bap-ucv-305-so-4/'),
  ('bong-da-co-bap-ucv-305-so-5', 'BAS-485', 'UCV-3.05-size-5', 'Bóng đá cơ bắp UCV 3.05 số 5', 'Bóng đá cơ bắp UCV 3.05 số 5 của Động Lực được thiết kế đẹp mắt, may tròn đều từ da PU, có độ nảy chuẩn và phù hợp sử dụng chơi bóng cho học sinh.', 'Bóng đá cơ bắp UCV 3.05 số 5 của Động Lực được thiết kế đẹp mắt, may tròn đều từ da PU, có độ nảy chuẩn và phù hợp sử dụng chơi bóng cho học sinh.', 360000, 'qua-bong-da', 0, '{"Mã sản phẩm": "UCV-3.05-size-5", "Chất liệu": "Da PU", "Size bóng": "Số 5", "Kim bơm": "Có"}'::jsonb, 'https://baoansport.vn/qua-bong-da/bong-da-co-bap-ucv-305-so-5/'),
  ('qua-bong-da-dong-luc-uhv-102-in-d', 'BAS-487', 'UHV-1.02-in-D', 'Quả bóng đá Động Lực UHV 1.02 in D', 'Quả bóng đá Động Lực UHV 1.02 in D﻿ chính hãng được may tròn đều + độ bền cao từ da PU, độ nảy chuẩn và phù hợp cho cả sân cỏ lẫn sân cỏ nhân tạo.', 'Quả bóng đá Động Lực UHV 1.02 in D﻿ chính hãng được may tròn đều + độ bền cao từ da PU, độ nảy chuẩn và phù hợp cho cả sân cỏ lẫn sân cỏ nhân tạo.', 760000, 'qua-bong-da', 0, '{"Mã sản phẩm": "UHV-1.02-in-D", "Chất liệu": "Da PU", "Size bóng": "Số 5", "Kim bơm": "Có"}'::jsonb, 'https://baoansport.vn/qua-bong-da/qua-bong-da-dong-luc-uhv-102-in-d/'),
  ('qua-bong-da-dong-luc-uhv-203', 'BAS-488', 'UHV-2.03', 'Quả bóng đá Động Lực UHV 2.03', 'Quả bóng đá Động Lực UHV 2.03 in sao số 5 được﻿ may tròn đều cực bền từ da PU, cho độ nảy chuẩn và phù hợp dùng cho tập luyện thi đấu môn bóng đá.', 'Quả bóng đá Động Lực UHV 2.03 in sao số 5 được﻿ may tròn đều cực bền từ da PU, cho độ nảy chuẩn và phù hợp dùng cho tập luyện thi đấu môn bóng đá.', 750000, 'qua-bong-da', 0, '{"Mã sản phẩm": "UHV-2.03", "Chất liệu": "Da PU", "Size bóng": "Số 5"}'::jsonb, 'https://baoansport.vn/qua-bong-da/qua-bong-da-dong-luc-uhv-203/'),
  ('bong-da-dong-luc-uhv-205-so-4', 'BAS-489', 'UHV-2.05-size-4', 'Bóng đá Động Lực UHV 2.05 số 4', 'Bóng đá Động Lực UHV 2.05 số 4 chính hãng được may tròn đều từ chất liệu da PU, cho đường bóng chuẩn và phù hợp sử dụng chơi đá bóng cho trẻ em.', 'Bóng đá Động Lực UHV 2.05 số 4 chính hãng được may tròn đều từ chất liệu da PU, cho đường bóng chuẩn và phù hợp sử dụng chơi đá bóng cho trẻ em.', 650000, 'qua-bong-da', 0, '{"Mã sản phẩm": "UHV-2.05-size-4", "Chất liệu": "Da PU", "Size bóng": "Số 4", "Kim bơm": "Có"}'::jsonb, 'https://baoansport.vn/qua-bong-da/bong-da-dong-luc-uhv-205-so-4/'),
  ('bong-da-dong-luc-uhv-205-so-5', 'BAS-490', 'UHV-2.05-size-5', 'Bóng đá Động Lực UHV 2.05 số 5', 'Bóng đá Động Lực UHV 2.05 số 5 chính hãng được may tròn đều, cực bền từ da PU, độ nảy chuẩn và phù hợp sử dụng cho tập luyện thi đấu môn bóng đá.', 'Bóng đá Động Lực UHV 2.05 số 5 chính hãng được may tròn đều, cực bền từ da PU, độ nảy chuẩn và phù hợp sử dụng cho tập luyện thi đấu môn bóng đá.', 1150000, 'qua-bong-da', 0, '{"Mã sản phẩm": "UHV-2.05-size-5", "Chất liệu": "Da PU", "Size bóng": "Số 5", "Kim bơm": "Có"}'::jsonb, 'https://baoansport.vn/qua-bong-da/bong-da-dong-luc-uhv-205-so-5/'),
  ('bong-da-dong-luc-uhv-207', 'BAS-491', 'UHV-2.07', 'Bóng đá Động Lực UHV 2.07', 'Quả bóng đá tiêu chuẩn FIFA UHV 2.07 được may tròn đều từ chất liệu da Latex Hàn Quốc, độ nảy cực chuẩn, phù hợp dùng cho thi đấu bóng đá Quốc tế.', 'Quả bóng đá tiêu chuẩn FIFA UHV 2.07 được may tròn đều từ chất liệu da Latex Hàn Quốc, độ nảy cực chuẩn, phù hợp dùng cho thi đấu bóng đá Quốc tế.', 2500000, 'qua-bong-da', 0, '{"Mã sản phẩm": "UHV-2.07", "Chất liệu": "Da Latex", "Size bóng": "Số 5"}'::jsonb, 'https://baoansport.vn/qua-bong-da/bong-da-dong-luc-uhv-207/'),
  ('bong-da-fifa-spectro-uhv-207', 'BAS-493', 'Spectro-UHV-2.07', 'Bóng đá FIFA Spectro UHV 2.07', 'Bóng đá FIFA Spectro UHV 2.07 hãng Động Lực được may tròn đều + vỏ ngoài làm từ da PU, đạt tiêu chuẩn quốc tế và chuyên dùng cho thi đấu bóng đá.', 'Bóng đá FIFA Spectro UHV 2.07 hãng Động Lực được may tròn đều + vỏ ngoài làm từ da PU, đạt tiêu chuẩn quốc tế và chuyên dùng cho thi đấu bóng đá.', 2500000, 'qua-bong-da', 0, '{"Mã sản phẩm": "Spectro-UHV-2.07", "Chất liệu": "Da PU", "Size bóng": "Số 5", "Kim bơm": "Có"}'::jsonb, 'https://baoansport.vn/qua-bong-da/bong-da-fifa-spectro-uhv-207/'),
  ('dong-ho-bam-giay-pc530', 'BAS-587', 'PC530', 'Đồng hồ bấm giây PC530', 'Đồng hồ bấm giây PC530 bộ nhớ 30 LAP được thiết kế nhỏ gọn, có chức năng đo thời gian chuẩn và chuyên dùng cho trọng tài, giáo viên thể dục, quản đốc.', 'Đồng hồ bấm giây PC530 bộ nhớ 30 LAP được thiết kế nhỏ gọn, có chức năng đo thời gian chuẩn và chuyên dùng cho trọng tài, giáo viên thể dục, quản đốc.', 560000, 'thiet-bi-day-hoc-the-duc', 0, '{"Mã sản phẩm": "PC530", "Màu sắc": "Xám", "Bộ nhớ": "30 LAP", "Trọng lượng": "64 gram", "Kích thước": "87.7 x 59.5 x 21 mm", "Dây đeo": "Có"}'::jsonb, 'https://baoansport.vn/thiet-bi-day-hoc-the-duc/dong-ho-bam-giay-pc530/'),
  ('bang-diem-lat-tay-aosaite', 'BAS-85', 'Aosaite', 'Bảng điểm lật tay Aosaite', 'Bảng điểm lật tay Aosaite được thiết kế nhỏ gọn, chữ số lật tay bằng nhựa và phù hợp dùng cho thi đấu các môn thể thao như cầu lông, bóng bàn hay đá cầu.', 'Bảng điểm lật tay Aosaite được thiết kế nhỏ gọn, chữ số lật tay bằng nhựa và phù hợp dùng cho thi đấu các môn thể thao như cầu lông, bóng bàn hay đá cầu.', 360000, 'phu-kien-bong-ban', 0, '{"Mã sản phẩm": "Aosaite", "Màu sắc": "Xanh + trắng", "Kích thước gấp gọn": "42 x 20cm", "Kích thước khi dùng": "Đang cập nhật", "Kích thước đóng hộp": "Đang cập nhật", "Trọng lượng": "Đang cập nhật"}'::jsonb, 'https://baoansport.vn/phu-kien-bong-ban/bang-diem-lat-tay-aosaite/'),
  ('bong-tennis-dunlop-3-qua', 'BAS-187', 'BTD3Q', 'Bóng Tennis Dunlop 3 quả', 'Bóng Tennis Dunlop 3 quả được làm tròn đều, giữ hơi tốt, cho độ nảy chuẩn và đạt tiêu chuẩn thi đấu môn Tennis. Mua bóng Tennis giá rẻ gọi 0939 987 456.', 'Bóng Tennis Dunlop 3 quả được làm tròn đều, giữ hơi tốt, cho độ nảy chuẩn và đạt tiêu chuẩn thi đấu môn Tennis. Mua bóng Tennis giá rẻ gọi 0939 987 456.', 140000, 'bong-tennis', 0, '{"Mã sản phẩm": "BTD3Q", "Màu sắc": "Xanh", "Chất liệu": "Vải nỉ", "Trọng lượng": "Đang cập nhật", "Đóng hộp": "3 quả/hộp"}'::jsonb, 'https://baoansport.vn/bong-tennis/bong-tennis-dunlop-3-qua/'),
  ('chan-vit-boi-loi', 'BAS-189', 'CVBL', 'Chân vịt bơi lội', 'Chân vịt bơi lội hay chân nhái được thiết kế theo tiêu chuẩn từ chất liệu nhựa cực bền và có độ đàn hồi cao. Đặt mua chân vịt bơi lặn giá rẻ gọi 0939987456.', 'Chân vịt bơi lội hay chân nhái được thiết kế theo tiêu chuẩn từ chất liệu nhựa cực bền và có độ đàn hồi cao. Đặt mua chân vịt bơi lặn giá rẻ gọi 0939987456.', 380000, 'phu-kien-boi-loi', 0, '{"Mã sản phẩm": "CVBL", "Màu sắc": "Xanh - đen", "Chất liệu": "Nhựa", "Size": "36, 37, 38, 39"}'::jsonb, 'https://baoansport.vn/phu-kien-boi-loi/chan-vit-boi-loi/'),
  ('phao-lung-tap-boi-tre-em', 'BAS-192', 'PLTBTE', 'Phao lưng tập bơi trẻ em', 'Phao lưng tập bơi trẻ em chính hãng Thắng Lợi được làm từ xốp chuyên dụng, có dây đeo lưng điều chỉnh dễ dàng và phù hợp dùng để tập bơi cho trẻ nhỏ.', 'Phao lưng tập bơi trẻ em chính hãng Thắng Lợi được làm từ xốp chuyên dụng, có dây đeo lưng điều chỉnh dễ dàng và phù hợp dùng để tập bơi cho trẻ nhỏ.', 85000, 'phu-kien-boi-loi', 0, '{"Mã sản phẩm": "PLTBTE", "Màu sắc": "Xanh - vàng", "Chất liệu": "Xốp", "Kích thước": "Đang cập nhật"}'::jsonb, 'https://baoansport.vn/phu-kien-boi-loi/phao-lung-tap-boi-tre-em/'),
  ('ao-phao-tap-boi', 'BAS-193', 'APTB', 'Áo phao tập bơi', 'Áo phao tập bơi (áo phao cứu hộ) được làm chắc chắn từ chất liệu xốp xịn, đảm bảo an toàn tuyệt đối khi sử dụng và phù hợp dùng cho người lớn lẫn trẻ em.', 'Áo phao tập bơi (áo phao cứu hộ) được làm chắc chắn từ chất liệu xốp xịn, đảm bảo an toàn tuyệt đối khi sử dụng và phù hợp dùng cho người lớn lẫn trẻ em.', 85000, 'phu-kien-boi-loi', 0, '{"Mã sản phẩm": "APTB", "Màu sắc": "Cam - xanh", "Chất liệu": "Xốp", "Kích thước": "Đang cập nhật"}'::jsonb, 'https://baoansport.vn/phu-kien-boi-loi/ao-phao-tap-boi/'),
  ('mu-boi-phoenix', 'BAS-200', 'MBP', 'Mũ bơi Phoenix', 'Mũ bơi Phoenix được thiết kế đẹp mắt, làm từ silicon cao cấp cực mềm và an toàn cho sức khỏe người dùng. Mua online mũ bơi giá rẻ tại Bảo An Sport.', 'Mũ bơi Phoenix được thiết kế đẹp mắt, làm từ silicon cao cấp cực mềm và an toàn cho sức khỏe người dùng. Mua online mũ bơi giá rẻ tại Bảo An Sport.', 130000, 'mu-boi', 0, '{"Mã sản phẩm": "MBP", "Màu sắc": "Nhiều màu", "Chất liệu": "Silicon", "Kích thước": "Đang cập nhật", "Túi đựng": "Có"}'::jsonb, 'https://baoansport.vn/mu-boi/mu-boi-phoenix/'),
  ('bit-tai-boi-view', 'BAS-203', 'BTBV', 'Bịt tai bơi View', 'Bịt tai bơi View được làm từ chất liệu Silicon cao cấp, cực êm và có tác dụng chống nước tràn vào tai khi đi bơi. Đặt mua bịt tai giá rẻ nhất gọi 0939987456.', 'Bịt tai bơi View được làm từ chất liệu Silicon cao cấp, cực êm và có tác dụng chống nước tràn vào tai khi đi bơi. Đặt mua bịt tai giá rẻ nhất gọi 0939987456.', 120000, 'phu-kien-boi-loi', 0, '{"Mã sản phẩm": "BTBV", "Màu sắc": "Vàng", "Chất liệu": "Silicon", "Hộp đựng": "Có", "Số lượng": "3 chiếc"}'::jsonb, 'https://baoansport.vn/phu-kien-boi-loi/bit-tai-boi-view/'),
  ('mu-boi-conquest-co-tai', 'BAS-207', 'MBCCT', 'Mũ bơi Conquest có tai', 'Mũ bơi Conquest có tai được thiết kế đẹp mắt, làm từ chất liệu silicon cao cấp có độ đàn hồi tốt và độ bền cao. Đặt mua mũ bơi giá rẻ nhất gọi 0939987456.', 'Mũ bơi Conquest có tai được thiết kế đẹp mắt, làm từ chất liệu silicon cao cấp có độ đàn hồi tốt và độ bền cao. Đặt mua mũ bơi giá rẻ nhất gọi 0939987456.', 130000, 'mu-boi', 0, '{"Mã sản phẩm": "MBCCT", "Màu sắc": "Nhiều màu", "Chất liệu": "Silicon", "Kích thước": "Đang cập nhật", "Túi đựng": "Có"}'::jsonb, 'https://baoansport.vn/mu-boi/mu-boi-conquest-co-tai/'),
  ('mu-boi-view', 'BAS-208', 'MBVi', 'Mũ bơi View', 'Mũ bơi View nhập khẩu từ Nhật Bản được làm bằng chất liệu silicon cực mềm, êm và thân thiện với da đầu. Mua online mũ bơi giá rẻ nhất gọi 0939987456.', 'Mũ bơi View nhập khẩu từ Nhật Bản được làm bằng chất liệu silicon cực mềm, êm và thân thiện với da đầu. Mua online mũ bơi giá rẻ nhất gọi 0939987456.', 165000, 'mu-boi', 0, '{"Mã sản phẩm": "MBVi", "Màu sắc": "Nhiều màu", "Chất liệu": "Silicon", "Kích thước": "Đang cập nhật", "Túi đựng": "Có"}'::jsonb, 'https://baoansport.vn/mu-boi/mu-boi-view/'),
  ('kinh-boi-phoenix-pn-401', 'BAS-219', 'PN-401', 'Kính bơi Phoenix PN 401', 'Kính bơi Phoenix PN 401 được làm từ chất liệu cao cấp, đảm bảo an toàn cho sức khỏe + có góc nhìn rộng khi bơi và phù hợp sử dụng cho người lớn đi bơi.', 'Kính bơi Phoenix PN 401 được làm từ chất liệu cao cấp, đảm bảo an toàn cho sức khỏe + có góc nhìn rộng khi bơi và phù hợp sử dụng cho người lớn đi bơi.', 165000, 'kinh-boi', 0, '{"Mã sản phẩm": "PN-401", "Màu sắc": "Đen, xanh", "Chất liệu": "Polycarbonate, Silicone", "Hộp đựng": "Có", "Kích thước hộp": "20 x 6 x 4.5cm", "Trọng lượng kính": "145 gram"}'::jsonb, 'https://baoansport.vn/kinh-boi/kinh-boi-phoenix-pn-401/'),
  ('kinh-boi-phoenix-pn-203', 'BAS-220', 'PN-203', 'Kính bơi Phoenix PN 203', 'Kính bơi Phoenix PN 203 nhập khẩu Hàn Quốc được làm từ polycacbonat + silicon, đảm bảo an toàn cho sức khỏe và phù hợp dùng để đi bơi cho người lớn.', 'Kính bơi Phoenix PN 203 nhập khẩu Hàn Quốc được làm từ polycacbonat + silicon, đảm bảo an toàn cho sức khỏe và phù hợp dùng để đi bơi cho người lớn.', 140000, 'kinh-boi', 0, '{"Mã sản phẩm": "PN-203", "Màu sắc": "Đen, xanh, hồng", "Hộp đựng": "Có"}'::jsonb, 'https://baoansport.vn/kinh-boi/kinh-boi-phoenix-pn-203/'),
  ('con-lan-tap-bung-ab-2023-new', 'BAS-1470', 'AB-2023-New', 'Con lăn tập bụng AB 2023 New', 'Con lăn tập bụng AB 2023 New được thiết kế chắc chắn, chuyển động trơn tru, có lò xo trợ lực và phù hợp sử dụng cho người có nhu cầu tập giảm mỡ bụng', 'Con lăn tập bụng AB 2023 New được thiết kế chắc chắn, chuyển động trơn tru, có lò xo trợ lực và phù hợp sử dụng cho người có nhu cầu tập giảm mỡ bụng', 300000, 'may-tap-co-bung', 1500, '{"Mã sản phẩm": "AB-2023-New", "Màu sắc": "Xanh, đỏ, cam", "Chất liệu": "Nhựa TPR, ABS, thép", "Trọng lượng": "1.5 kg", "Trọng lượng hộp": "1.8 kg", "Tải trọng tối đa": "150 kg", "Kích thước lắp": "370 x 350 x 245mm", "Kích thước hộp": "25 x 16 x 16.5cm"}'::jsonb, 'https://baoansport.vn/may-tap-co-bung/con-lan-tap-bung-ab-2023-new/'),
  ('kinh-boi-phoenix-pn-204', 'BAS-221', 'PN-204', 'Kính bơi Phoenix PN 204', 'Kính bơi Phoenix PN 204 được nhập khẩu từ Hàn Quốc, có thiết kế đẹp mắt và phù hợp dùng cho người lớn. Cần mua kính bơi giá rẻ nhất gọi 0939 987 456.', 'Kính bơi Phoenix PN 204 được nhập khẩu từ Hàn Quốc, có thiết kế đẹp mắt và phù hợp dùng cho người lớn. Cần mua kính bơi giá rẻ nhất gọi 0939 987 456.', 150000, 'kinh-boi', 0, '{"Mã sản phẩm": "PN-204", "Màu sắc": "Xanh, đen, hồng", "Hộp đựng": "Có"}'::jsonb, 'https://baoansport.vn/kinh-boi/kinh-boi-phoenix-pn-204/'),
  ('kinh-boi-phoenix-pn-207', 'BAS-222', 'PN-207', 'Kính bơi Phoenix PN 207', 'Kính bơi Phoenix PN 207 được thiết kế đẹp từ chất liệu Polycarbonate kết hợp Silicon, đảm bảo an toàn cho sức khỏe và phù hợp dùng đi bơi cho người lớn.', 'Kính bơi Phoenix PN 207 được thiết kế đẹp từ chất liệu Polycarbonate kết hợp Silicon, đảm bảo an toàn cho sức khỏe và phù hợp dùng đi bơi cho người lớn.', 150000, 'kinh-boi', 0, '{"Mã sản phẩm": "PN-207", "Màu sắc": "Đen, xanh", "Chất liệu": "Polycarbonate, Silicone", "Hộp đựng": "Có", "Kích thước hộp": "21 x 4.7 x 5.5cm", "Trọng lượng kính": "135 gram"}'::jsonb, 'https://baoansport.vn/kinh-boi/kinh-boi-phoenix-pn-207/'),
  ('kinh-boi-phan-quang-view-v610mr', 'BAS-232', 'V610MR', 'Kính bơi phản quang View V610MR', 'Kính bơi phản quang View V610MR nhập khẩu từ Nhật được thiết kế đẹp mắt, làm từ chất liệu cao cấp giúp chống lóa mắt và phù hợp dùng đi bơi ngoài trời.', 'Kính bơi phản quang View V610MR nhập khẩu từ Nhật được thiết kế đẹp mắt, làm từ chất liệu cao cấp giúp chống lóa mắt và phù hợp dùng đi bơi ngoài trời.', 540000, 'kinh-boi', 0, '{"Mã sản phẩm": "V610MR", "Màu sắc": "Nhiều màu", "Chất liệu": "Polycarbonate, Silicone", "Hộp đựng": "Có", "Kích thước hộp": "22 x 5 x 5.5cm", "Trọng lượng kính": "150 gram"}'::jsonb, 'https://baoansport.vn/kinh-boi/kinh-boi-phan-quang-view-v610mr/'),
  ('kinh-boi-phan-quang-view-v220amr', 'BAS-233', 'V220AMR', 'Kính bơi phản quang View V220AMR', 'Kính bơi phản quang View V220AMR được thiết kế với phong cách thể thao mạnh mẽ, mắt kính tráng gương chống lóa và phù hợp cho người bơi ngoài trời.', 'Kính bơi phản quang View V220AMR được thiết kế với phong cách thể thao mạnh mẽ, mắt kính tráng gương chống lóa và phù hợp cho người bơi ngoài trời.', 460000, 'kinh-boi', 0, '{"Mã sản phẩm": "V220AMR", "Màu sắc": "Nhiều màu", "Chất liệu": "Polycarbonate, Silicone", "Hộp đựng": "Có", "Kích thước hộp": "19 x 6 x 4.6cm", "Trọng lượng kính": "120 gram"}'::jsonb, 'https://baoansport.vn/kinh-boi/kinh-boi-phan-quang-view-v220amr/'),
  ('kinh-boi-view-v610', 'BAS-236', 'V610', 'Kính bơi View V610', 'Kính bơi View V610 chính hãng từ Nhật Bản được thiết kế đẹp, sử dụng chất liệu cao cấp cho góc nhìn rõ khi bơi dưới nước và phù hợp dùng cho người lớn.', 'Kính bơi View V610 chính hãng từ Nhật Bản được thiết kế đẹp, sử dụng chất liệu cao cấp cho góc nhìn rõ khi bơi dưới nước và phù hợp dùng cho người lớn.', 350000, 'kinh-boi', 0, '{"Mã sản phẩm": "V610", "Màu sắc": "Nhiều màu", "Chất liệu": "Polycarbonate, Silicone", "Hộp đựng": "Có", "Kích thước hộp": "21 x 5.6 x 5cm", "Trọng lượng kính": "130 gram"}'::jsonb, 'https://baoansport.vn/kinh-boi/kinh-boi-view-v610/'),
  ('bong-tennis-dunlop-fort', 'BAS-186', 'Fort', 'Bóng Tennis Dunlop Fort', 'Bóng Tennis Dunlop Fort được sản xuất tròn đều, có độ nảy cực chuẩn và giữ hơi rất tốt khi sử dụng. Đặt mua bóng Tennis giá rẻ nhất tại Bảo An Sport.', 'Bóng Tennis Dunlop Fort được sản xuất tròn đều, có độ nảy cực chuẩn và giữ hơi rất tốt khi sử dụng. Đặt mua bóng Tennis giá rẻ nhất tại Bảo An Sport.', 140000, 'bong-tennis', 0, '{"Mã sản phẩm": "Fort", "Màu sắc": "Xanh", "Chất liệu": "Vải nỉ", "Trọng lượng": "Đang cập nhật", "Đóng hộp": "4 quả/hộp"}'::jsonb, 'https://baoansport.vn/bong-tennis/bong-tennis-dunlop-fort/'),
  ('bong-tennis-dunlop-4-qua', 'BAS-188', 'BTD4Q', 'Bóng Tennis Dunlop 4 quả', 'Bóng Tennis Dunlop 4 quả dùng thi đấu Tennis được làm tròn đều, giữ hơi tốt và cho độ nảy chính xác. Mua online bóng Tennis giá rẻ nhất tại Bảo An Sport.', 'Bóng Tennis Dunlop 4 quả dùng thi đấu Tennis được làm tròn đều, giữ hơi tốt và cho độ nảy chính xác. Mua online bóng Tennis giá rẻ nhất tại Bảo An Sport.', 160000, 'bong-tennis', 0, '{"Mã sản phẩm": "BTD4Q", "Màu sắc": "Xanh", "Chất liệu": "Vải nỉ", "Trọng lượng": "Đang cập nhật", "Đóng hộp": "4 quả/hộp"}'::jsonb, 'https://baoansport.vn/bong-tennis/bong-tennis-dunlop-4-qua/'),
  ('tru-tennis-di-dong-303344', 'BAS-181', '303344', 'Trụ Tennis di động 303344', 'Trụ Tennis di động 303344 chính hãng Vifasport được làm chắc chắn từ sắt D90 tráng kẽm nung nóng, sơn tĩnh điện và phù hợp dùng cho sân thi đấu Tennis.', 'Trụ Tennis di động 303344 chính hãng Vifasport được làm chắc chắn từ sắt D90 tráng kẽm nung nóng, sơn tĩnh điện và phù hợp dùng cho sân thi đấu Tennis.', 3900000, 'tru-luoi-tennis', 0, '{"Mã sản phẩm": "303344", "Màu sắc": "Trắng", "Trụ chính": "Trụ sắt D90", "Trọng lượng": "Đang cập nhật", "Kích thước": "1420 x 90 mm", "Tay quay căng lưới": "Có"}'::jsonb, 'https://baoansport.vn/tru-luoi-tennis/tru-tennis-di-dong-303344/'),
  ('bang-diem-lat-tay-cima', 'BAS-87', 'BDLTC', 'Bảng điểm lật tay Cima', 'Bảng điểm lật tay Cima được làm bằng nhựa, có chức năng gập gọn và sử dụng để báo điểm cho các cuộc thi thể thao như bóng bàn, cầu lông, bóng chuyền.', 'Bảng điểm lật tay Cima được làm bằng nhựa, có chức năng gập gọn và sử dụng để báo điểm cho các cuộc thi thể thao như bóng bàn, cầu lông, bóng chuyền.', 300000, 'phu-kien-bong-ban', 0, '{"Mã sản phẩm": "BDLTC", "Màu sắc": "Xanh đen", "Chất liệu": "Nhựa", "Trọng lượng": "Đang cập nhật", "Kích thước": "Đang cập nhật"}'::jsonb, 'https://baoansport.vn/phu-kien-bong-ban/bang-diem-lat-tay-cima/'),
  ('qua-bong-chay', 'BAS-150', 'QBC', 'Quả bóng chày', 'Quả bóng chày được thiết kế đạt chuẩn, may chắc chắn từ da và cho đường bóng chính xác khi sử dụng. Mua quả bóng chày giá rẻ nhất liên hệ 0939987456.', 'Quả bóng chày được thiết kế đạt chuẩn, may chắc chắn từ da và cho đường bóng chính xác khi sử dụng. Mua quả bóng chày giá rẻ nhất liên hệ 0939987456.', 45000, 'dung-cu-bong-chay', 0, '{"Mã sản phẩm": "QBC", "Màu sắc": "Trắng - đỏ", "Chất liệu": "Da PU", "Đường kính": "5cm", "Trọng lượng": "100 gram"}'::jsonb, 'https://baoansport.vn/dung-cu-bong-chay/qua-bong-chay/'),
  ('gang-tay-bong-chay', 'BAS-151', 'GTBC', 'Găng tay bóng chày', 'Găng tay bóng chày được thiết kế theo tiêu chuẩn thi đấu, làm từ chất liệu da PU và có đường may chắc chắn. Mua găng bóng chày giá rẻ ☎ 0939987456.', 'Găng tay bóng chày được thiết kế theo tiêu chuẩn thi đấu, làm từ chất liệu da PU và có đường may chắc chắn. Mua găng bóng chày giá rẻ ☎ 0939987456.', 480000, 'dung-cu-bong-chay', 0, '{"Mã sản phẩm": "GTBC", "Màu sắc": "Vàng cam", "Chất liệu": "Da PU", "Trọng lượng": "400 gram", "Đối tượng sử dụng": "Người lớn"}'::jsonb, 'https://baoansport.vn/dung-cu-bong-chay/gang-tay-bong-chay/'),
  ('bo-bong-chay-mini', 'BAS-152', 'BBCM', 'Bộ bóng chày Mini', 'Bộ bóng chày Mini được thiết kế phù hợp dùng cho trẻ em và học sinh tập chơi bóng chày ở nhà hoặc trường học. Mua bộ bóng chày giá rẻ gọi 0939 987 456.', 'Bộ bóng chày Mini được thiết kế phù hợp dùng cho trẻ em và học sinh tập chơi bóng chày ở nhà hoặc trường học. Mua bộ bóng chày giá rẻ gọi 0939 987 456.', 640000, 'dung-cu-bong-chay', 0, '{"Mã sản phẩm": "BBCM", "Màu sắc": "Nhiều màu", "Bộ sản phẩm": "Gậy, găng và bóng", "Trọng lượng": "Đang cập nhật", "Kích thước hộp": "Đang cập nhật", "Đối tượng sử dụng": "Trẻ em"}'::jsonb, 'https://baoansport.vn/dung-cu-bong-chay/bo-bong-chay-mini/'),
  ('gay-bong-chay-nhom', 'BAS-153', 'GBCN', 'Gậy bóng chày nhôm', 'Gậy bóng chày nhôm được làm theo tiêu chuẩn thi đấu từ chất liệu hợp kim nhôm, có độ cứng cao và phù hợp sử dụng cho tập luyện, thi đấu môn bóng chày.', 'Gậy bóng chày nhôm được làm theo tiêu chuẩn thi đấu từ chất liệu hợp kim nhôm, có độ cứng cao và phù hợp sử dụng cho tập luyện, thi đấu môn bóng chày.', 200000, 'dung-cu-bong-chay', 0, '{"Mã sản phẩm": "GBCN", "Màu sắc": "Xanh, đỏ, đen", "Chất liệu": "Hợp kim nhôm", "Size": "28, 30 inches", "Trọng lượng": "250-300 gram", "Đối tượng sử dụng": "Người lớn và trẻ em"}'::jsonb, 'https://baoansport.vn/dung-cu-bong-chay/gay-bong-chay-nhom/'),
  ('gay-bong-chay-go', 'BAS-154', 'GBCG', 'Gậy bóng chày gỗ', 'Gậy bóng chày gỗ được làm cứng cáp, đẹp mắt từ gỗ tự nhiên, tạo lực đánh mạnh. Dành cho luyện tập, thi đấu. Giao hàng toàn quốc, giá tốt ở Bảo An Sport.', 'Gậy bóng chày gỗ được làm cứng cáp, đẹp mắt từ gỗ tự nhiên, tạo lực đánh mạnh. Dành cho luyện tập, thi đấu. Giao hàng toàn quốc, giá tốt ở Bảo An Sport.', 190000, 'dung-cu-bong-chay', 1000, '{"Mã sản phẩm": "GBCG", "Màu sắc": "Nâu", "Chất liệu": "Gỗ", "Trọng lượng": "1 kg", "Size": "29, 30 inches", "Đối tượng sử dụng": "Người lớn và trẻ em"}'::jsonb, 'https://baoansport.vn/dung-cu-bong-chay/gay-bong-chay-go/');
INSERT INTO seed_product VALUES
  ('ghe-trong-tai-tennis-s25335', 'BAS-158', 'S25335', 'Ghế trọng tài Tennis S25335', 'Ghế trọng tài Tennis S25335 của hãng Sodex được thiết kế chắc chắn, đạt chuẩn thi đấu và phù hợp dùng làm ghế ngồi cho trọng tài điều khiển thi đấu Tennis.', 'Ghế trọng tài Tennis S25335 của hãng Sodex được thiết kế chắc chắn, đạt chuẩn thi đấu và phù hợp dùng làm ghế ngồi cho trọng tài điều khiển thi đấu Tennis.', 7050000, 'phu-kien-tennis', 0, '{"Mã sản phẩm": "S25335", "Màu sắc": "Trắng", "Khung chính": "Sắt ống D34", "Trọng lượng": "Đang cập nhật", "Kích thước lắp đặt": "80 x 92.5 x 272 cm", "Chiều cao ghế ngồi": "1.5m"}'::jsonb, 'https://baoansport.vn/phu-kien-tennis/ghe-trong-tai-tennis-s25335/'),
  ('ghe-trong-tai-tennis-302351', 'BAS-159', '302351', 'Ghế trọng tài Tennis 302351', 'Ghế trọng tài Tennis 302351 chính hãng Vifa Sport được thiết kế chắc chắn, có mái che, đạt tiêu chuẩn thi đấu và phù hợp lắp đặt cho sân thi đấu môn Tennis.', 'Ghế trọng tài Tennis 302351 chính hãng Vifa Sport được thiết kế chắc chắn, có mái che, đạt tiêu chuẩn thi đấu và phù hợp lắp đặt cho sân thi đấu môn Tennis.', 6600000, 'phu-kien-tennis', 0, '{"Mã sản phẩm": "302351", "Màu sắc": "Trắng", "Khung chính": "Thép ống D34", "Trọng lượng": "Đang cập nhật", "Kích thước lắp đặt": "80 x 92.5 x 272 cm", "Chiều cao ghế ngồi": "1.5m và 1.8m"}'::jsonb, 'https://baoansport.vn/phu-kien-tennis/ghe-trong-tai-tennis-302351/'),
  ('luoi-cao-su-gat-nuoc-san-tennis', 'BAS-160', 'LGNST', 'Lưỡi cao su gạt nước sân Tennis', 'Lưỡi cao su gạt nước sân Tennis của Vifasport được làm từ cao su non, có tính năng chống mài mòn và phù hợp dùng để thay thế cho lưỡi gạt sân Tennis cũ.', 'Lưỡi cao su gạt nước sân Tennis của Vifasport được làm từ cao su non, có tính năng chống mài mòn và phù hợp dùng để thay thế cho lưỡi gạt sân Tennis cũ.', 130000, 'phu-kien-tennis', 0, '{"Mã sản phẩm": "LGNST", "Màu sắc": "Xám", "Chất liệu": "Cao su", "Chiều dài": "140 cm"}'::jsonb, 'https://baoansport.vn/phu-kien-tennis/luoi-cao-su-gat-nuoc-san-tennis/'),
  ('gat-nuoc-san-tennis-301361', 'BAS-163', '301361', 'Gạt nước sân Tennis 301361', 'Gạt nước sân Tennis 301361 của Vifasport được thiết kế chắc chắn với phần khung làm từ inox, lưỡi bằng cao su và chuyên dùng để vệ sinh cho sân Tennis.', 'Gạt nước sân Tennis 301361 của Vifasport được thiết kế chắc chắn với phần khung làm từ inox, lưỡi bằng cao su và chuyên dùng để vệ sinh cho sân Tennis.', 2050000, 'phu-kien-tennis', 0, '{"Mã sản phẩm": "301361", "Màu sắc": "Trắng", "Khung chính": "Inox D21", "Trọng lượng": "Đang cập nhật", "Kích thước lắp đặt": "140 x 160 cm"}'::jsonb, 'https://baoansport.vn/phu-kien-tennis/gat-nuoc-san-tennis-301361/'),
  ('xe-gat-nuoc-san-tennis-301360', 'BAS-164', '301360', 'Xe gạt nước sân Tennis 301360', 'Xe gạt nước sân Tennis 301360 thiết kế chắc chắn từ sắt D21, lưỡi gạt bằng cao su và có bánh xe di chuyển. Hàng chính hãng Vifa Sport, giá tốt tại Bảo An Sport.', 'Xe gạt nước sân Tennis 301360 thiết kế chắc chắn từ sắt D21, lưỡi gạt bằng cao su và có bánh xe di chuyển. Hàng chính hãng Vifa Sport, giá tốt tại Bảo An Sport.', 1650000, 'phu-kien-tennis', 6500, '{"Mã sản phẩm": "301360", "Màu sắc": "Trắng", "Khung chính": "Sắt ống D21", "Trọng lượng": "6.5 kg", "Kích thước lắp đặt": "140 x 160cm"}'::jsonb, 'https://baoansport.vn/phu-kien-tennis/xe-gat-nuoc-san-tennis-301360/'),
  ('luoi-tennis-302648', 'BAS-172', '302648', 'Lưới Tennis 302648', 'Lưới Tennis 302648 chính hãng Vifa Sport được đan đều bằng tay từ chất liệu sợi TW-PE, viền trên PVC với 4 đường chỉ, xung quanh vắt sổ rất chắc chắn.', 'Lưới Tennis 302648 chính hãng Vifa Sport được đan đều bằng tay từ chất liệu sợi TW-PE, viền trên PVC với 4 đường chỉ, xung quanh vắt sổ rất chắc chắn.', 1650000, 'tru-luoi-tennis', 0, '{"Mã sản phẩm": "302648", "Màu sắc": "Đen", "Chất liệu": "Sợi tổng hợp", "Trọng lượng": "Đang cập nhật", "Kích thước": "12.7 x 1.07 m"}'::jsonb, 'https://baoansport.vn/tru-luoi-tennis/luoi-tennis-302648/'),
  ('gian-ta-da-nang-m-718p', 'BAS-1547', 'M-718P', 'Giàn tạ đa năng M-718P', 'Giàn tạ đa năng M-718P được thiết kế chắc chắn, đẹp mắt, trang bị nhiều bài tập thể hình hiệu quả và phù hợp dùng cho anh em đang có nhu cầu tập tại nhà.', 'Giàn tạ đa năng M-718P được thiết kế chắc chắn, đẹp mắt, trang bị nhiều bài tập thể hình hiệu quả và phù hợp dùng cho anh em đang có nhu cầu tập tại nhà.', 9600000, 'gian-ta-da-nang', 158000, '{"Mã sản phẩm": "M-718P", "Màu sắc": "Đen + nâu", "Chất liệu": "Thép, nhựa, da PU", "Trọng lượng tạ": "73 kg", "Trọng lượng cả bộ": "158 kg", "Trọng lượng thùng": "165 kg", "Tải trọng tối đa": "260 kg", "Kích thước lắp đặt": "150 x 100 x 205cm", "Số kiện vận chuyển": "4 kiện"}'::jsonb, 'https://baoansport.vn/gian-ta-da-nang/gian-ta-da-nang-m-718p/'),
  ('luoi-tennis-322648c', 'BAS-174', '322648C', 'Lưới Tennis 322648C', 'Lưới Tennis 322648C chính hãng Vifasport được đan bằng tay từ sợi TW-PE, theo kỹ thuật mới không thụng giữa và phù hợp lắp đặt cho sân Tennis thi đấu.', 'Lưới Tennis 322648C chính hãng Vifasport được đan bằng tay từ sợi TW-PE, theo kỹ thuật mới không thụng giữa và phù hợp lắp đặt cho sân Tennis thi đấu.', 2180000, 'tru-luoi-tennis', 0, '{"Mã sản phẩm": "322648C", "Màu sắc": "Đen", "Chất liệu": "Sợi tổng hợp", "Trọng lượng": "Đang cập nhật", "Kích thước": "12.7 x 1.07 m"}'::jsonb, 'https://baoansport.vn/tru-luoi-tennis/luoi-tennis-322648c/'),
  ('luoi-tennis-thi-dau-323348c', 'BAS-175', '323348C', 'Lưới Tennis thi đấu 323348C', 'Lưới Tennis thi đấu 323348C hãng Vifa Sport được đan bằng tay từ chất liệu sợi BR-PE cao cấp, có khả năng chống tia UV và phù hợp lắp cho sân thi đấu.', 'Lưới Tennis thi đấu 323348C hãng Vifa Sport được đan bằng tay từ chất liệu sợi BR-PE cao cấp, có khả năng chống tia UV và phù hợp lắp cho sân thi đấu.', 2640000, 'tru-luoi-tennis', 0, '{"Mã sản phẩm": "323348C", "Màu sắc": "Đen", "Chất liệu": "Sợi tổng hợp", "Trọng lượng": "Đang cập nhật", "Kích thước": "12.7 x 1.07 m"}'::jsonb, 'https://baoansport.vn/tru-luoi-tennis/luoi-tennis-thi-dau-323348c/'),
  ('nong-tru-tennis-d90-s25362', 'BAS-176', 'S25362', 'Nòng trụ Tennis D90 S25362', 'Nòng trụ Tennis D90 S25362 được thiết kế theo tiêu chuẩn từ ống thép dày sơn tĩnh điện, có nắp đậy và phù hợp sử dụng để thi công sân cho Tennis thi đấu.', 'Nòng trụ Tennis D90 S25362 được thiết kế theo tiêu chuẩn từ ống thép dày sơn tĩnh điện, có nắp đậy và phù hợp sử dụng để thi công sân cho Tennis thi đấu.', 700000, 'tru-luoi-tennis', 0, '{"Mã sản phẩm": "S25362", "Màu sắc": "Xám", "Trụ chính": "Ống thép D90", "Trọng lượng": "Đang cập nhật", "Kích thước": "400 x 90 mm"}'::jsonb, 'https://baoansport.vn/tru-luoi-tennis/nong-tru-tennis-d90-s25362/'),
  ('kinh-boi-view-v-730j', 'BAS-239', 'V-730J', 'Kính bơi View V-730J', 'Kính bơi View V-730J chính hãng từ Nhật Bản được thiết kế đẹp mắt, bảo vệ mắt cực tốt khi bơi dưới nước và phù hợp sử dụng cho trẻ em từ 4 đến 9 tuổi.', 'Kính bơi View V-730J chính hãng từ Nhật Bản được thiết kế đẹp mắt, bảo vệ mắt cực tốt khi bơi dưới nước và phù hợp sử dụng cho trẻ em từ 4 đến 9 tuổi.', 340000, 'kinh-boi', 0, '{"Mã sản phẩm": "V-730J", "Màu sắc": "Nhiều màu", "Chất liệu": "Polycarbonate, Silicone", "Hộp đựng": "Có", "Kích thước hộp": "19 x 6 x 4.5cm", "Trọng lượng kính": "110 gram"}'::jsonb, 'https://baoansport.vn/kinh-boi/kinh-boi-view-v-730j/'),
