  ('bang-thay-nguoi-bong-chuyen-401457', 'BAS-313', '401457', 'Bảng thay người bóng chuyền 401457', 'Bảng thay người bóng chuyền 401457 chính hãng Vifa Sport được thiết kế theo chuẩn FIVB, có túi đựng và phù hợp sử dụng cho thi đấu môn bóng chuyền.', 'Bảng thay người bóng chuyền 401457 chính hãng Vifa Sport được thiết kế theo chuẩn FIVB, có túi đựng và phù hợp sử dụng cho thi đấu môn bóng chuyền.', 3500000, 'phu-kien-bong-chuyen', 0, '{"Mã sản phẩm": "401457", "Chiều cao số": "13cm", "Túi đựng đi kèm": "Có"}'::jsonb, 'https://baoansport.vn/phu-kien-bong-chuyen/bang-thay-nguoi-bong-chuyen-401457/'),
  ('ghe-trong-tai-bong-chuyen-402670', 'BAS-318', '402670', 'Ghế trọng tài bóng chuyền 402670', 'Ghế trọng tài bóng chuyền 402670 chân tam giác được thiết kế chắc chắn, đạt tiêu chuẩn và phù hợp dùng cho trọng tài điều khiển thi đấu môn bóng chuyền.', 'Ghế trọng tài bóng chuyền 402670 chân tam giác được thiết kế chắc chắn, đạt tiêu chuẩn và phù hợp dùng cho trọng tài điều khiển thi đấu môn bóng chuyền.', 5500000, 'phu-kien-bong-chuyen', 20000, '{"Mã sản phẩm": "402670", "Màu sắc": "Trắng", "Kích thước": "800 x 1000 x 2400mm", "Trọng lượng": "20Kg"}'::jsonb, 'https://baoansport.vn/phu-kien-bong-chuyen/ghe-trong-tai-bong-chuyen-402670/'),
